/// Old logic for aborting shard transfers on shard drop, had a bug: it dropped all transfers
/// regardless of the shard id. In order to keep consensus consistent, we can only
/// enable new fixed logic once cluster fully switched to this version.
/// Otherwise, some node might follow old logic and some - new logic.
///
/// See: <https://github.com/qdrant/qdrant/pull/7792>
pub static ABORT_TRANSFERS_ON_SHARD_DROP_FIX_FROM_VERSION: LazyLock<Version> =
    LazyLock::new(|| Version::parse("1.16.3-dev").expect("valid version string"));

impl Collection {
    /// Updates collection params:
    /// Saves new params on disk
    ///
    /// After this, `recreate_optimizers_background` must be called to create new optimizers using
    /// the updated configuration.
    pub async fn update_params_from_diff(
        &self,
        params_diff: CollectionParamsDiff,
    ) -> CollectionResult<()> {
        {
            let mut config = self.collection_config.write().await;
            config.params = config.params.update(&params_diff);
        }
        self.collection_config.read().await.save(&self.path)?;
        Ok(())
    }

    /// Updates HNSW config:
    /// Saves new params on disk
    ///
    /// After this, `recreate_optimizers_background` must be called to create new optimizers using
    /// the updated configuration.
    pub async fn update_hnsw_config_from_diff(
        &self,
        hnsw_config_diff: HnswConfigDiff,
    ) -> CollectionResult<()> {
        {
            let mut config = self.collection_config.write().await;
            config.hnsw_config = config.hnsw_config.update(&hnsw_config_diff);
        }
        self.collection_config.read().await.save(&self.path)?;
        Ok(())
    }

    /// Updates vectors config:
    /// Saves new params on disk
    ///
    /// After this, `recreate_optimizers_background` must be called to create new optimizers using
    /// the updated configuration.
    pub async fn update_vectors_from_diff(
        &self,
        update_vectors_diff: &VectorsConfigDiff,
    ) -> CollectionResult<()> {
        let mut config = self.collection_config.write().await;
        update_vectors_diff.check_vector_names(&config.params)?;
        config
            .params
            .update_vectors_from_diff(update_vectors_diff)?;
        config.save(&self.path)?;
        Ok(())
    }

    /// Updates sparse vectors config:
    /// Saves new params on disk
    ///
    /// After this, `recreate_optimizers_background` must be called to create new optimizers using
    /// the updated configuration.
    pub async fn update_sparse_vectors_from_other(
        &self,
        update_vectors_diff: &SparseVectorsConfig,
    ) -> CollectionResult<()> {
        let mut config = self.collection_config.write().await;
        update_vectors_diff.check_vector_names(&config.params)?;
        config
            .params
            .update_sparse_vectors_from_other(update_vectors_diff)?;
        config.save(&self.path)?;
        Ok(())
    }

    /// Updates shard optimization params:
    /// Saves new params on disk
    ///
    /// After this, `recreate_optimizers_background` must be called to create new optimizers using
    /// the updated configuration.
    pub async fn update_optimizer_params_from_diff(
        &self,
        optimizer_config_diff: OptimizersConfigDiff,
    ) -> CollectionResult<()> {
        {
            let mut config = self.collection_config.write().await;
            config.optimizer_config = config.optimizer_config.update(&optimizer_config_diff);
        }
        self.collection_config.read().await.save(&self.path)?;
        Ok(())
    }

    /// Updates quantization config:
    /// Saves new params on disk
    ///
    /// After this, `recreate_optimizers_background` must be called to create new optimizers using
    /// the updated configuration.
    pub async fn update_quantization_config_from_diff(
        &self,
        quantization_config_diff: QuantizationConfigDiff,
    ) -> CollectionResult<()> {
        {
            let mut config = self.collection_config.write().await;
            match quantization_config_diff {
                QuantizationConfigDiff::Scalar(scalar) => {
                    config
                        .quantization_config
                        .replace(QuantizationConfig::Scalar(scalar));
                }
                QuantizationConfigDiff::Product(product) => {
                    config
                        .quantization_config
                        .replace(QuantizationConfig::Product(product));
                }
                QuantizationConfigDiff::Binary(binary) => {
                    config
                        .quantization_config
                        .replace(QuantizationConfig::Binary(binary));
                }
                QuantizationConfigDiff::Turbo(turbo) => {
                    config
                        .quantization_config
                        .replace(QuantizationConfig::Turbo(turbo));
                }
                QuantizationConfigDiff::Disabled(_) => {
                    config.quantization_config = None;
                }
            }
        }
        self.collection_config.read().await.save(&self.path)?;
        Ok(())
    }

    pub async fn update_metadata(&self, metadata: Payload) -> CollectionResult<()> {
        let mut collection_config_guard: tokio::sync::RwLockWriteGuard<
            '_,
            crate::config::CollectionConfigInternal,
        > = self.collection_config.write().await;

        if let Some(current_metadata) = collection_config_guard.metadata.as_mut() {
            current_metadata.merge(&metadata);
        } else {
            collection_config_guard.metadata = Some(metadata);
        }
        drop(collection_config_guard);
        self.collection_config.read().await.save(&self.path)?;
        Ok(())
    }

    /// Updates the strict mode configuration and saves it to disk.
    ///
    /// Order matters: rate limiters on each shard are updated *before* the new
    /// `strict_mode_config` is published to `self.collection_config`. Otherwise
    /// readers of `info()` could observe `enabled=false` while a search arriving
    /// on the same peer is still rejected by a not-yet-cleared rate limiter
    /// (or vice versa for an enable).
    pub async fn update_strict_mode_config(
        &self,
        strict_mode_diff: StrictModeConfig,
    ) -> CollectionResult<()> {
        // Compute the new strict-mode config without yet exposing it.
        let new_strict_mode_config = {
            let config = self.collection_config.read().await;
            if let Some(current) = config.strict_mode_config.as_ref() {
                current.update(&strict_mode_diff)
            } else {
                strict_mode_diff
            }
        };

        // Apply rate-limiter changes to every shard first, so the visible config
        // never lies about the active rate limit.
        {
            let shard_holder = self.shards_holder.write().await;
            let updates = shard_holder.all_shards().map(|replica_set| {
                replica_set.on_strict_mode_config_update(&new_strict_mode_config)
            });
            future::try_join_all(updates).await?;
        }

        // Publish the new config and persist it.
        {
            let mut config = self.collection_config.write().await;
            config.strict_mode_config = Some(new_strict_mode_config);
        }
        self.collection_config.read().await.save(&self.path)?;
        Ok(())
    }

    /// Handle replica changes
    ///
    /// Remove replicas from replica set
    pub async fn handle_replica_changes(
        &self,
        replica_changes: Vec<Change>,
    ) -> CollectionResult<()> {
        if replica_changes.is_empty() {
            return Ok(());
        }

        let shard_holder = self.shards_holder.read().await;
        let mut to_remove = Vec::with_capacity(replica_changes.len());

        for change in replica_changes {
            let (shard_id, peer_id) = match change {
                Change::Remove(shard_id, peer_id) => (shard_id, peer_id),
            };

            let Some(replica_set) = shard_holder.get_shard(shard_id).cloned() else {
                return Err(CollectionError::bad_request(format!(
                    "Shard {shard_id} of {} not found",
                    self.name(),
                )));
            };

            let peers = replica_set.peers();

            if !peers.contains_key(&peer_id) {
                return Err(CollectionError::bad_request(format!(
                    "Peer {peer_id} has no replica of shard {shard_id}"
                )));
            }

            // Check that we are not removing the *last* replica or the last *active* replica
            //
            // `is_last_active_replica` counts both `Active` and `ReshardingScaleDown` replicas!
            if peers.len() == 1 || replica_set.is_last_source_of_truth_replica(peer_id) {
                return Err(CollectionError::bad_request(format!(
                    "Shard {shard_id} must have at least one active replica after removing {peer_id}",
                )));
            }

            let all_nodes_fixed_cancellation = self
                .channel_service
                .all_peers_at_version(&ABORT_TRANSFERS_ON_SHARD_DROP_FIX_FROM_VERSION);

            // Collect shard transfers related to removed shard...
            let transfers = if all_nodes_fixed_cancellation {
                shard_holder.get_related_transfers(peer_id, shard_id)
            } else {
                // This is the old buggy logic, but we have to keep it
                // for maintaining consistency in a cluster with mixed versions.
                shard_holder
                    .get_transfers(|transfer| transfer.from == peer_id || transfer.to == peer_id)
            };

            to_remove.push((replica_set, peer_id, transfers));
        }

        // Must release shard holder lock for abort_shard_transfer_and_resharding
        drop(shard_holder);

        for (replica_set, peer_id, transfers) in to_remove {
            for transfer in transfers {
                self.abort_shard_transfer_and_resharding(transfer.key())
                    .await?;
            }

            replica_set.remove_peer(peer_id).await?;

            // We can't remove the last repilca of a shard, so this should prevent removing
            // resharding shard, because it's always the *only* replica.
            //
            // And if we remove some other shard, that is currently doing resharding transfer,
            // the transfer should be cancelled (see the block right above this comment),
            // so no special handling is needed.
        }

        Ok(())
    }

    /// Recreate the optimizers on all shards for this collection, in the background.
    ///
    /// Returns immediately and performs all the work - stopping the existing workers and starting
    /// new ones - in a detached task. Stopping the existing workers waits for in-flight
    /// optimizations to finish, which can take a long time. This is why it runs in the background:
    /// it is reached from paths that go through consensus, where blocking the caller stalls the
    /// whole consensus loop and can take down a cluster.
    ///
    /// At most one recreation runs at a time. If one is already running, this records that another
    /// run is needed and returns; the running task then runs once more when it finishes, picking up
    /// the latest config. Any number of requests that arrive while a task is running collapse into a
    /// single additional run (recreation always rebuilds from the current config, so coalescing is
    /// safe - the last run reflects the latest state).
    ///
    /// Errors are logged rather than returned: the configuration change that triggers the
    /// recreation has already been applied and persisted by the time we get here, so there is no
    /// caller left to propagate them to. Failures are also surfaced as optimizer errors per shard
    /// (see `LocalShard::on_optimizer_config_update`).
    pub fn recreate_optimizers_background(&self) {
        // Single-flight: only spawn a task if none is running. Otherwise the request is coalesced
        // into a queued re-run handled by the task that is already running.
        if !self.recreate_optimizers_state.request() {
            return;
        }

        let shards_holder = self.shards_holder.clone();
        let collection_id = self.id.clone();
        let recreate_state = self.recreate_optimizers_state.clone();
        tokio::task::spawn(async move {
            loop {
                // Run the recreation as a child task, so a panic is contained (surfaced as a
                // `JoinError`) and never unwinds the coordinator loop below - which would otherwise
                // leave `running` stuck and wedge all future recreations.
                match tokio::task::spawn(Self::recreate_optimizers(shards_holder.clone())).await {
                    Ok(Ok(())) => {}
                    Ok(Err(err)) => log::error!(
                        "Failed to recreate optimizers for collection {collection_id} in background: {err}",
                    ),
                    Err(err) => log::error!(
                        "Optimizer recreation task for collection {collection_id} failed: {err}",
                    ),
                }

                // Run again if a request arrived while we were running, otherwise stop. The
                // decision is a single atomic compare-and-swap (in `finish_run`), so a request
                // arriving exactly now is never lost: it either still sees us running (and queues a
                // re-run, handled by the next iteration) or sees us idle (and spawns a fresh task).
                if !recreate_state.finish_run() {
                    break;
                }
            }
        });
    }

    /// Stop the existing optimizers on all shards and start new ones using the current config.
    ///
    /// Implementation behind [`Collection::recreate_optimizers_background`]. Takes an owned
    /// [`SharedShardHolder`] so the returned future is `'static` and can be spawned as a task.
    async fn recreate_optimizers(shards_holder: SharedShardHolder) -> CollectionResult<()> {
        let shard_holder = shards_holder.read().await;
        let updates = shard_holder
            .all_shards()
            .map(|replica_set| replica_set.on_optimizer_config_update());
        future::try_join_all(updates).await?;
        Ok(())
    }

    pub async fn strict_mode_config(&self) -> Option<StrictModeConfig> {
        self.collection_config
            .read()
            .await
            .strict_mode_config
            .clone()
    }

    pub async fn vectors_config(&self) -> VectorsConfig {
        self.collection_config.read().await.params.vectors.clone()
    }

    pub async fn info(
        &self,
        shard_selection: &ShardSelectorInternal,
    ) -> CollectionResult<CollectionInfo> {
        let shards_holder = self.shards_holder.read().await;
        let shards = shards_holder.select_shards(shard_selection)?;
        let mut requests: futures::stream::FuturesUnordered<_> = shards
            .into_iter()
            // `info` requests received through internal gRPC *always* have `shard_selection`
            .map(|(shard, _shard_key)| shard.info(shard_selection.is_shard_id()))
            .collect();

        let mut info = match requests.try_next().await? {
            Some(info) => info,
            None => CollectionInfo::empty(
                self.collection_config.read().await.clone(),
                self.payload_index_schema.read().clone(),
            ),
        };

        while let Some(response) = requests.try_next().await? {
            let CollectionInfo {
                status,
                optimizer_status,
                warnings,
                indexed_vectors_count,
                points_count,
                segments_count,
                config: _,
                payload_schema,
                update_queue,
            } = response;
            info.status = cmp::max(info.status, status);
            info.optimizer_status = cmp::max(info.optimizer_status, optimizer_status);
            info.indexed_vectors_count = info
                .indexed_vectors_count
                .zip(indexed_vectors_count)
                .map(|(a, b)| a + b);
            info.points_count = info.points_count.zip(points_count).map(|(a, b)| a + b);
            info.segments_count += segments_count;
            info.warnings.extend(warnings);

            if let Some(UpdateQueueInfo {
                length,
                deferred_points,
            }) = &mut info.update_queue
            {
                *length += update_queue.as_ref().map(|q| q.length).unwrap_or(0);

                if let Some(response_deferred_count) = update_queue.and_then(|i| i.deferred_points)
                    && response_deferred_count > 0
                {
                    *deferred_points.get_or_insert_default() += response_deferred_count;
                }
            } else {
                info.update_queue = update_queue;
            }

            for (key, response_schema) in payload_schema {
                info.payload_schema
                    .entry(key)
                    .and_modify(|info_schema| info_schema.points += response_schema.points)
                    .or_insert(response_schema);
            }
        }

        Ok(info)
    }

    pub async fn cluster_info(&self, peer_id: PeerId) -> CollectionResult<CollectionClusterInfo> {
        let shards_holder = self.shards_holder.read().await;
        let shard_count = shards_holder.len();
        let mut local_shards = Vec::new();
        let mut remote_shards = Vec::new();
        let count_request = Arc::new(CountRequestInternal {
            filter: None,
            exact: false, // Don't need exact count of unique ids here, only size estimation
        });
        let shard_to_key = shards_holder.get_shard_id_to_key_mapping();

        // extract shards info
        for (shard_id, replica_set) in shards_holder.get_shards() {
            let peers = replica_set.peers();

            if replica_set.has_local_shard().await {
                let state = peers
                    .get(&replica_set.this_peer_id())
                    .copied()
                    .unwrap_or(ReplicaState::Dead);

                // Cluster info is explicitly excluded from hardware measurements
                // So that we can monitor hardware usage without interference
                let hw_acc = HwMeasurementAcc::disposable();
                let count_result = replica_set
                    .count_local(
                        count_request.clone(),
                        None,
                        hw_acc,
                        DeferredBehavior::Exclude,
                    )
                    .await
                    .unwrap_or_default();

                let points_count = count_result.map(|x| x.count).unwrap_or(0);
                local_shards.push(LocalShardInfo {
                    shard_id,
                    points_count,
                    state,
                    shard_key: shard_to_key.get(&shard_id).cloned(),
                })
            }
            for (peer_id, state) in replica_set.peers() {
                if peer_id == replica_set.this_peer_id() {
                    continue;
                }
                remote_shards.push(RemoteShardInfo {
                    shard_id,
                    peer_id,
                    state,
                    shard_key: shard_to_key.get(&shard_id).cloned(),
                });
            }
        }
        let shard_transfers =
            shards_holder.get_shard_transfer_info(&*self.transfer_tasks.lock().await);
        let resharding_operations = shards_holder.get_resharding_operations_info();

        // sort by shard_id
        local_shards.sort_by_key(|k| k.shard_id);
        remote_shards.sort_by_key(|k| k.shard_id);

        let info = CollectionClusterInfo {
            peer_id,
            shard_count,
            local_shards,
            remote_shards,
            shard_transfers,
            resharding_operations,
        };
        Ok(info)
    }

    pub async fn optimizations(
        &self,
        options: OptimizationsRequestOptions,
    ) -> CollectionResult<OptimizationsResponse> {
        let shards_holder = self.shards_holder.read().await;

        let futures: Vec<_> = shards_holder
            .all_shards()
            .map(|shard| shard.optimizations(options))
            .collect();

        let shard_responses = future::try_join_all(futures).await?;

        let mut merged = OptimizationsResponse::default();
        for shard_response in shard_responses {
            merged.merge(shard_response);
        }

        // Sort from newest to oldest
        merged
            .running
            .sort_by_key(|v| cmp::Reverse(v.progress.started_at));

        if let Some(completed) = &mut merged.completed {
            completed.sort_by_key(|v| cmp::Reverse(v.progress.started_at));
            if let Some(limit) = options.completed_limit {
                completed.truncate(limit);
            }
        }

        Ok(merged)
    }

    pub async fn print_warnings(&self) {
        let warnings = self.collection_config.read().await.get_warnings();
        for warning in warnings {
            log::warn!("Collection {}: {}", self.name(), warning.message);
        }
    }
}use std::time::Duration;

use ahash::AHashSet;
use api::rest::{
    SearchMatrixOffsetsResponse, SearchMatrixPair, SearchMatrixPairsResponse,
    SearchMatrixRequestInternal,
};
use common::counter::hardware_accumulator::HwMeasurementAcc;
use segment::data_types::vectors::DEFAULT_VECTOR_NAME;
use segment::types::{
    Condition, Filter, HasIdCondition, HasVectorCondition, PointIdType, ScoredPoint, VectorNameBuf,
    WithPayloadInterface, WithVector,
};

use crate::collection::Collection;
use crate::operations::consistency_params::ReadConsistency;
use crate::operations::shard_selector_internal::ShardSelectorInternal;
use crate::operations::types::CollectionResult;
use crate::operations::universal_query::collection_query::{
    CollectionQueryRequest, Query, VectorInputInternal, VectorQuery,
};
use crate::operations::universal_query::shard_query::{
    SampleInternal, ScoringQuery, ShardQueryRequest,
};

#[derive(Debug, Default)]
pub struct CollectionSearchMatrixResponse {
    pub sample_ids: Vec<PointIdType>,    // sampled point ids
    pub nearests: Vec<Vec<ScoredPoint>>, // nearest points for each sampled point
}

/// Internal representation of the distance matrix request, used to convert from REST and gRPC.
pub struct CollectionSearchMatrixRequest {
    pub sample_size: usize,
    pub limit_per_sample: usize,
    pub filter: Option<Filter>,
    pub using: VectorNameBuf,
}

impl CollectionSearchMatrixRequest {
    pub const DEFAULT_LIMIT_PER_SAMPLE: usize = 3;
    pub const DEFAULT_SAMPLE: usize = 10;
}

impl From<SearchMatrixRequestInternal> for CollectionSearchMatrixRequest {
    fn from(request: SearchMatrixRequestInternal) -> Self {
        let SearchMatrixRequestInternal {
            sample,
            limit,
            filter,
            using,
        } = request;
        Self {
            sample_size: sample.unwrap_or(CollectionSearchMatrixRequest::DEFAULT_SAMPLE),
            limit_per_sample: limit
                .unwrap_or(CollectionSearchMatrixRequest::DEFAULT_LIMIT_PER_SAMPLE),
            filter,
            using: using.unwrap_or_else(|| DEFAULT_VECTOR_NAME.to_owned()),
        }
    }
}

impl From<CollectionSearchMatrixResponse> for SearchMatrixOffsetsResponse {
    fn from(response: CollectionSearchMatrixResponse) -> Self {
        let CollectionSearchMatrixResponse {
            sample_ids,
            nearests,
        } = response;
        let offset_by_id = sample_ids
            .iter()
            .enumerate()
            .map(|(i, id)| (id, i))
            .collect::<std::collections::HashMap<_, _>>();
        let mut offsets_row = Vec::with_capacity(sample_ids.len());
        let mut offsets_col = Vec::with_capacity(sample_ids.len());
        for (row_offset, scored_points) in nearests.iter().enumerate() {
            for p in scored_points {
                offsets_row.push(row_offset as u64);
                offsets_col.push(offset_by_id[&p.id] as u64);
            }
        }
        let scores = nearests
            .into_iter()
            .flat_map(|row| row.into_iter().map(|p| p.score))
            .collect();
        Self {
            offsets_row,
            offsets_col,
            scores,
            ids: sample_ids,
        }
    }
}

impl From<CollectionSearchMatrixResponse> for SearchMatrixPairsResponse {
    fn from(response: CollectionSearchMatrixResponse) -> Self {
        let CollectionSearchMatrixResponse {
            sample_ids,
            nearests,
        } = response;

        let pairs_len = nearests.iter().map(|n| n.len()).sum();
        let mut pairs = Vec::with_capacity(pairs_len);

        for (a, scored_points) in sample_ids.into_iter().zip(nearests) {
            for scored_point in scored_points {
                pairs.push(SearchMatrixPair {
                    a,
                    b: scored_point.id,
                    score: scored_point.score,
                });
            }
        }

        Self { pairs }
    }
}

impl From<CollectionSearchMatrixResponse> for api::grpc::qdrant::SearchMatrixPairs {
    fn from(response: CollectionSearchMatrixResponse) -> Self {
        let rest_result = SearchMatrixPairsResponse::from(response);
        let pairs = rest_result.pairs.into_iter().map(From::from).collect();
        Self { pairs }
    }
}

impl From<CollectionSearchMatrixResponse> for api::grpc::qdrant::SearchMatrixOffsets {
    fn from(response: CollectionSearchMatrixResponse) -> Self {
        let rest_result = SearchMatrixOffsetsResponse::from(response);
        Self {
            offsets_row: rest_result.offsets_row,
            offsets_col: rest_result.offsets_col,
            scores: rest_result.scores,
            ids: rest_result.ids.into_iter().map(From::from).collect(),
        }
    }
}

impl Collection {
    pub async fn search_points_matrix(
        &self,
        request: CollectionSearchMatrixRequest,
        shard_selection: ShardSelectorInternal,
        read_consistency: Option<ReadConsistency>,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<CollectionSearchMatrixResponse> {
        let start = std::time::Instant::now();
        let CollectionSearchMatrixRequest {
            sample_size,
            limit_per_sample,
            filter,
            using,
        } = request;
        if limit_per_sample == 0 || sample_size == 0 {
            return Ok(Default::default());
        }

        self.collection_config
            .read()
            .await
            .params
            .check_vector_exists(&using)?;

        // make sure the vector is present in the point
        let has_vector = Filter::new_must(Condition::HasVector(HasVectorCondition::from(
            using.clone(),
        )));

        // merge user's filter with the has_vector filter
        let filter = Some(
            filter
                .map(|filter| filter.merge(&has_vector))
                .unwrap_or(has_vector),
        );

        // sample random points
        let sampling_query = ShardQueryRequest {
            prefetches: vec![],
            query: Some(ScoringQuery::Sample(SampleInternal::Random)),
            filter,
            score_threshold: None,
            limit: sample_size,
            offset: 0,
            params: None,
            with_vector: WithVector::Selector(vec![using.clone()]), // retrieve the vector
            with_payload: Default::default(),
        };

        let mut sampled_points = self
            .query(
                sampling_query,
                read_consistency,
                shard_selection.clone(),
                timeout,
                hw_measurement_acc.clone(),
            )
            .await?;

        // if we have less than 2 points, we can't build a matrix
        if sampled_points.len() < 2 {
            return Ok(CollectionSearchMatrixResponse::default());
        }

        sampled_points.truncate(sample_size);
        // sort by id for a deterministic order
        sampled_points.sort_unstable_by_key(|p| p.id);

        // collect the sampled point ids in the same order
        let sampled_point_ids: Vec<_> = sampled_points.iter().map(|p| p.id).collect();

        // filter to only include the sampled points in the search
        // use the same filter for all requests to leverage batch search
        let filter = Filter::new_must(Condition::HasId(HasIdCondition::from(
            sampled_point_ids.iter().copied().collect::<AHashSet<_>>(),
        )));

        // Perform nearest neighbor search for each sampled point
        let mut queries = Vec::with_capacity(sampled_points.len());

        for point in sampled_points {
            let vector = point
                .vector
                .as_ref()
                .and_then(|v| v.get(&using))
                .map(|v| v.to_owned())
                .expect("Vector not found in the point");

            // nearest query on the sample vector
            let query = Query::Vector(VectorQuery::Nearest(VectorInputInternal::Vector(vector)));

            let query_request = CollectionQueryRequest {
                prefetch: vec![],
                query: Some(query),
                using: using.clone(),
                filter: Some(filter.clone()),
                score_threshold: None,
                limit: limit_per_sample + 1, // +1 to exclude the point itself afterward
                offset: 0,
                params: None,
                with_vector: WithVector::Bool(false),
                with_payload: WithPayloadInterface::Bool(false),
                lookup_from: None,
            };

            queries.push((query_request, shard_selection.clone()));
        }

        // update timeout
        let timeout = timeout.map(|timeout| timeout.saturating_sub(start.elapsed()));

        // We know by construction that lookup_from is not used in the queries
        // so can use placeholder closure here
        let collection_by_name = |_name: String| async move { None };

        // run batch search request
        let mut nearest = self
            .query_batch(
                queries,
                collection_by_name,
                read_consistency,
                timeout,
                hw_measurement_acc,
            )
            .await?;

        // postprocess the results to account for overlapping samples
        for (scores, sample_id) in nearest.iter_mut().zip(sampled_point_ids.iter()) {
            // need to remove the sample_id from the results
            if let Some(sample_pos) = scores.iter().position(|p| p.id == *sample_id) {
                scores.remove(sample_pos);
            } else {
                // if not found pop lowest score
                if scores.len() == limit_per_sample + 1 {
                    // if we have enough results, remove the last one
                    scores.pop();
                }
            }
        }

        Ok(CollectionSearchMatrixResponse {
            sample_ids: sampled_point_ids,
            nearests: nearest,
        })
    }
}

#[cfg(test)]
mod tests {
    use segment::types::ScoredPoint;

    use super::*;

    fn make_scored_point(id: u64, score: f32) -> ScoredPoint {
        ScoredPoint {
            id: id.into(),
            version: 0,
            score,
            payload: None,
            vector: None,
            shard_key: None,
            order_value: None,
        }
    }

    // 3 samples, 2 results per sample
    fn fixture_response() -> CollectionSearchMatrixResponse {
        CollectionSearchMatrixResponse {
            sample_ids: vec![1.into(), 2.into(), 3.into()],
            nearests: vec![
                vec![make_scored_point(1, 0.2), make_scored_point(2, 0.1)],
                vec![make_scored_point(2, 0.4), make_scored_point(3, 0.3)],
                vec![make_scored_point(1, 0.6), make_scored_point(3, 0.5)],
            ],
        }
    }

    #[test]
    fn test_matrix_pairs_response_conversion() {
        let response = fixture_response();
        let expected = SearchMatrixPairsResponse {
            pairs: vec![
                SearchMatrixPair::new(1, 1, 0.2),
                SearchMatrixPair::new(1, 2, 0.1),
                SearchMatrixPair::new(2, 2, 0.4),
                SearchMatrixPair::new(2, 3, 0.3),
                SearchMatrixPair::new(3, 1, 0.6),
                SearchMatrixPair::new(3, 3, 0.5),
            ],
        };

        let actual = SearchMatrixPairsResponse::from(response);
        assert_eq!(actual, expected);
    }

    #[test]
    fn test_matrix_offsets_response_conversion() {
        let response = fixture_response();
        let expected = SearchMatrixOffsetsResponse {
            offsets_row: vec![0, 0, 1, 1, 2, 2],
            offsets_col: vec![0, 1, 1, 2, 0, 2],
            scores: vec![0.2, 0.1, 0.4, 0.3, 0.6, 0.5],
            ids: vec![1.into(), 2.into(), 3.into()],
        };

        let actual = SearchMatrixOffsetsResponse::from(response);
        assert_eq!(actual, expected);
    }
}use std::collections::HashMap;
use std::sync::Arc;
use std::time::Duration;

use common::counter::hardware_accumulator::HwMeasurementAcc;
use futures::TryStreamExt;
use futures::stream::FuturesUnordered;
use segment::data_types::facets::{FacetParams, FacetResponse, FacetValue};

use super::Collection;
use crate::operations::consistency_params::ReadConsistency;
use crate::operations::shard_selector_internal::ShardSelectorInternal;
use crate::operations::types::CollectionResult;

/// Multiplier applied to the user-facing `limit` to derive the per-shard
/// over-fetch cap when running approximate facet queries. With unique-per-point
/// values (e.g. UUIDs), every distinct value has count = 1, so the practical
/// accuracy of approximate top-k is bounded by what each shard returns; the
/// factor is a trade-off between per-shard payload/work and result accuracy.
const FACET_OVERSAMPLE_FACTOR: usize = 4;

/// Lower bound for the per-shard over-fetch cap, so small `limit` values still
/// have enough headroom to absorb cross-shard rank differences.
const FACET_MIN_OVERSAMPLE: usize = 128;

impl Collection {
    /// Entry point for a facet request. Applies oversampling (for approximate
    /// queries) before fanning out to shards. This runs *once*, on the node
    /// that received the client request; peer nodes enter through
    /// [`Collection::facet_internal`] instead and never re-oversample.
    ///
    /// How `limit` flows through a distributed cluster for an approximate query.
    /// `L` is the user limit (here `L = 10`); `N` is the oversampled per-shard
    /// limit `N = max(L * 4, 128) = 128`:
    ///
    /// ```text
    ///                            Client  (limit = L = 10)
    ///                               │
    ///                               ▼
    ///   ┌── Node A: Collection::facet ───────────────────────────────────┐
    ///   │     request.limit:   L  ──oversample──▶  N = 128               │
    ///   │     response_limit:  L = 10  (kept for the final truncation)   │
    ///   │                              │                                 │
    ///   │                              ▼                                 │
    ///   │     Collection::facet_internal(limit = N, response_limit = L)  │
    ///   │              ┌───────────────┴────────────────┐                │
    ///   │              ▼ local shard                    ▼ remote shard   │
    ///   │     approx_facet(limit = N)          gRPC FacetCountsInternal  │
    ///   │     returns ≤ N hits                       { limit = N }       │
    ///   │              │                                 │               │
    ///   └──────────────┼─────────────────────────────────┼───────────────┘
    ///                  │                                 ▼
    ///                  │     ┌── Node B: facet_counts_internal ──────────┐
    ///                  │     │     toc.facet_internal: peer_limit = N    │
    ///                  │     │     (NOT re-oversampled)                  │
    ///                  │     │              │                            │
    ///                  │     │              ▼                            │
    ///                  │     │     Collection::facet_internal(           │
    ///                  │     │         limit = N, response_limit = N)    │
    ///                  │     │     approx_facet(limit = N)               │
    ///                  │     │     top_hits(.., N)  ──▶  ≤ N hits        │
    ///                  │     └──────────────┬────────────────────────────┘
    ///                  │                    │
    ///                  └─────────┬──────────┘
    ///                            ▼
    ///   Node A:  aggregate all shard hits (sum counts per value)
    ///            top_hits(aggregated, response_limit = L)  ──▶  L = 10 hits
    ///                            │
    ///                            ▼
    ///                          Client  (L = 10 results)
    /// ```
    ///
    /// Key points:
    /// - Oversampling (`L` → `N`) happens only here, on the entry node. Each
    ///   shard — local or remote — returns up to `N` values, giving the final
    ///   aggregation enough headroom to absorb cross-shard rank differences.
    /// - Remote peers are reached via the internal gRPC path, which calls
    ///   `facet_internal` directly with `peer_limit = N`, so the limit is *not*
    ///   multiplied a second time.
    /// - Only the final aggregation on the entry node truncates back to the
    ///   user-facing `response_limit = L`.
    pub async fn facet(
        &self,
        mut request: FacetParams,
        shard_selection: ShardSelectorInternal,
        read_consistency: Option<ReadConsistency>,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<FacetResponse> {
        let response_limit = request.limit;
        if response_limit == 0 {
            return Ok(FacetResponse::default());
        }
        if !request.exact {
            // Approximate facet sends only the established limit between shards.
            //
            // Oversample to preserve accuracy.
            request.limit = request
                .limit
                .saturating_mul(FACET_OVERSAMPLE_FACTOR)
                .max(FACET_MIN_OVERSAMPLE);
        };

        self.facet_internal(
            request,
            response_limit,
            shard_selection,
            read_consistency,
            timeout,
            hw_measurement_acc,
        )
        .await
    }

    pub async fn facet_internal(
        &self,
        request: FacetParams,
        response_limit: usize,
        shard_selection: ShardSelectorInternal,
        read_consistency: Option<ReadConsistency>,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<FacetResponse> {
        if request.limit == 0 {
            return Ok(FacetResponse::default());
        }

        let request = Arc::new(request);

        let shard_holder = self.shards_holder.read().await;
        let target_shards = shard_holder.select_shards(&shard_selection)?;

        let mut shards_reads_f = target_shards
            .iter()
            .map(|(shard, _shard_key)| {
                shard.facet(
                    request.clone(),
                    read_consistency,
                    shard_selection.is_shard_id(),
                    timeout,
                    hw_measurement_acc.clone(),
                )
            })
            .collect::<FuturesUnordered<_>>();

        // Collect results from all shards into a single map
        let mut aggregated_results: HashMap<FacetValue, usize> = HashMap::new();
        while let Some(response) = shards_reads_f.try_next().await? {
            for hit in response.hits {
                *aggregated_results.entry(hit.value).or_insert(0) += hit.count;
            }
        }

        Ok(FacetResponse::top_hits(aggregated_results, response_limit))
    }
}use std::time::Duration;

use common::counter::hardware_accumulator::HwMeasurementAcc;
use segment::types::ScoredPoint;
use shard::query::MmrInternal;
use shard::query::mmr::mmr_from_points_with_vector as mmr_from_points_with_vector_impl;
use tokio_util::task::AbortOnDropHandle;

use crate::common::adaptive_handle::AdaptiveSearchHandle;
use crate::config::CollectionParams;
use crate::operations::types::{CollectionError, CollectionResult};

pub async fn mmr_from_points_with_vector(
    collection_params: &CollectionParams,
    points_with_vector: impl IntoIterator<Item = ScoredPoint> + Send + 'static,
    mmr: MmrInternal,
    limit: usize,
    search_runtime_handle: &AdaptiveSearchHandle,
    timeout: Duration,
    hw_measurement_acc: HwMeasurementAcc,
) -> CollectionResult<Vec<ScoredPoint>> {
    let distance = collection_params.get_distance(&mmr.using)?;
    let multivector_config = collection_params
        .vectors
        .get_params(&mmr.using)
        .and_then(|vector_params| vector_params.multivector_config);

    let cpu_utilization = hw_measurement_acc.cpu_utilization();
    let handle = search_runtime_handle.spawn_blocking(move || {
        cpu_utilization.measure(|| {
            mmr_from_points_with_vector_impl(
                points_with_vector,
                mmr,
                distance,
                multivector_config,
                limit,
                hw_measurement_acc,
            )
        })
    });
    let task = AbortOnDropHandle::new(handle);

    let result = tokio::time::timeout(timeout, task)
        .await
        .map_err(|_| CollectionError::timeout(timeout, "mmr"))???;

    Ok(result)
