impl Collection {
    pub fn get_snapshots_storage_manager(&self) -> CollectionResult<SnapshotStorageManager> {
        SnapshotStorageManager::new(&self.shared_storage_config.snapshots_config)
    }

    pub async fn list_snapshots(&self) -> CollectionResult<Vec<SnapshotDescription>> {
        let snapshot_manager = self.get_snapshots_storage_manager()?;
        snapshot_manager.list_snapshots(&self.snapshots_path).await
    }

    /// Creates a snapshot of the collection.
    ///
    /// The snapshot is created in three steps:
    /// 1. Create a temporary directory and create a snapshot of each shard in it.
    /// 2. Archive the temporary directory into a single file.
    /// 3. Move the archive to the final location.
    ///
    /// # Arguments
    ///
    /// * `global_temp_dir`: directory used to host snapshots while they are being created
    /// * `this_peer_id`: current peer id
    ///
    /// returns: Result<SnapshotDescription, CollectionError>
    pub async fn create_snapshot(
        &self,
        global_temp_dir: &Path,
        this_peer_id: PeerId,
    ) -> CollectionResult<SnapshotDescription> {
        let snapshot_name = format!(
            "{}-{this_peer_id}-{}.snapshot",
            self.name(),
            chrono::Utc::now().format("%Y-%m-%d-%H-%M-%S"),
        );

        // Final location of snapshot
        let snapshot_path = self.snapshots_path.join(&snapshot_name);
        log::info!("Creating collection snapshot {snapshot_name} into {snapshot_path:?}");

        // Dedicated temporary file for archiving this snapshot (deleted on drop)
        let snapshot_temp_arc_file = tempfile::Builder::new()
            .prefix(&format!("{snapshot_name}-arc-"))
            .tempfile_in(global_temp_dir)
            .map_err(|err| {
                CollectionError::service_error(format!(
                    "failed to create temporary snapshot directory {}/{snapshot_name}-arc-XXXX: \
                     {err}",
                    global_temp_dir.display(),
                ))
            })?;

        let tar = BuilderExt::new_seekable_owned(File::create(snapshot_temp_arc_file.path())?);

        // Create snapshot of each shard
        {
            let snapshot_temp_temp_dir = tempfile::Builder::new()
                .prefix(&format!("{snapshot_name}-temp-"))
                .tempdir_in(global_temp_dir)
                .map_err(|err| {
                    CollectionError::service_error(format!(
                        "failed to create temporary snapshot directory {}/{snapshot_name}-temp-XXXX: \
                         {err}",
                        global_temp_dir.display(),
                    ))
                })?;

            let mut futures = Vec::new();
            {
                let shards_holder = self.shards_holder.read().await;

                // Create snapshot of each shard
                for (shard_id, replica_set) in shards_holder.get_shards() {
                    let shard_snapshot_path = shard_path(Path::new(""), shard_id);

                    // If node is listener, we can save whatever currently is in the storage
                    let save_wal = self.shared_storage_config.node_type != NodeType::Listener;
                    let future = replica_set
                        .create_snapshot(
                            snapshot_temp_temp_dir.path(),
                            tar.descend(&shard_snapshot_path)?,
                            SnapshotFormat::Regular,
                            None,
                            save_wal,
                        )
                        .await?;
                    futures.push(future);
                }
            }

            for future in futures {
                future.await.map_err(|err| {
                    CollectionError::service_error(format!("failed to create snapshot: {err}"))
                })?;
            }
        }

        // Save collection config and version
        tar.append_data(
            CollectionVersion::current_raw().as_bytes().to_vec(),
            Path::new(common::storage_version::VERSION_FILE),
        )
        .await?;

        tar.append_data(
            self.collection_config.read().await.to_bytes()?,
            Path::new(COLLECTION_CONFIG_FILE),
        )
        .await?;

        self.shards_holder
            .read()
            .await
            .save_key_mapping_to_tar(&tar)
            .await?;

        self.payload_index_schema
            .save_to_tar(&tar, Path::new(PAYLOAD_INDEX_CONFIG_FILE))
            .await?;

        tar.finish().await.map_err(|err| {
            CollectionError::service_error(format!("failed to create snapshot archive: {err}"))
        })?;

        let snapshot_manager = self.get_snapshots_storage_manager()?;
        snapshot_manager
            .store_file(snapshot_temp_arc_file.path(), snapshot_path.as_path())
            .await
            .map_err(|err| {
                CollectionError::service_error(format!(
                    "failed to store snapshot archive to {}: {err}",
                    snapshot_temp_arc_file.path().display()
                ))
            })
    }

    /// Restore collection from snapshot
    ///
    /// This method performs blocking IO.
    pub fn restore_snapshot(
        snapshot_data: SnapshotData,
        target_dir: &Path,
        this_peer_id: PeerId,
        is_distributed: bool,
    ) -> CollectionResult<()> {
        match snapshot_data {
            SnapshotData::Packed(snapshot_path) => {
                tar_unpack_file(&snapshot_path, target_dir)?;
                snapshot_path.close()?;
            }
            SnapshotData::Unpacked(snapshot_dir) => {
                // already unpacked snapshot, validate files and move to target dir
                let snapshot_dir_path = snapshot_dir.path();
                move_all(snapshot_dir_path, target_dir)?;
            }
        }

        let config = CollectionConfigInternal::load(target_dir)?;
        config.validate_and_warn();
        let configured_shards = config.params.shard_number.get();

        let shard_ids_list: Vec<_> = match config.params.sharding_method.unwrap_or_default() {
            ShardingMethod::Auto => (0..configured_shards).collect(),
            ShardingMethod::Custom => {
                // Load shard mapping from disk
                let mapping_path = target_dir.join(SHARD_KEY_MAPPING_FILE);
                debug_assert!(
                    mapping_path.exists(),
                    "Shard mapping file must exist once custom sharding is used"
                );
                if !mapping_path.exists() {
                    Vec::new()
                } else {
                    let shard_key_mapping: ShardKeyMapping = read_json(&mapping_path)?;
                    shard_key_mapping.shard_ids()
                }
            }
        };

        // Check that all shard ids are unique
        debug_assert_eq!(
            shard_ids_list.len(),
            shard_ids_list.iter().collect::<HashSet<_>>().len(),
            "Shard mapping must contain all shards",
        );

        for shard_id in shard_ids_list {
            let shard_path = shard_path(target_dir, shard_id);
            let shard_config_opt = ShardConfig::load(&shard_path)?;
            if let Some(shard_config) = shard_config_opt {
                match shard_config.r#type {
                    shard_config::ShardType::Local => LocalShard::restore_snapshot(&shard_path)?,
                    shard_config::ShardType::Remote { .. } => {
                        RemoteShard::restore_snapshot(&shard_path)
                    }
                    shard_config::ShardType::Temporary => {}
                    shard_config::ShardType::ReplicaSet => ShardReplicaSet::restore_snapshot(
                        &shard_path,
                        this_peer_id,
                        is_distributed,
                    )?,
                }
            } else {
                return Err(CollectionError::service_error(format!(
                    "Can't read shard config at {}",
                    shard_path.display()
                )));
            }
        }

        Ok(())
    }

    /// # Cancel safety
    ///
    /// This method is *not* cancel safe.
    pub async fn recover_local_shard_from(
        &self,
        snapshot_shard_path: &Path,
        recovery_type: RecoveryType,
        shard_id: ShardId,
        cancel: cancel::CancellationToken,
    ) -> CollectionResult<bool> {
        // TODO:
        //   Check that shard snapshot is compatible with the collection
        //   (see `VectorsConfig::check_compatible_with_segment_config`)

        // `ShardHolder::recover_local_shard_from` is *not* cancel safe
        // (see `ShardReplicaSet::restore_local_replica_from`)
        let res = self
            .shards_holder
            .read()
            .await
            .recover_local_shard_from(
                snapshot_shard_path,
                recovery_type,
                &self.path,
                shard_id,
                cancel,
            )
            .await?;

        Ok(res)
    }

    pub async fn list_shard_snapshots(
        &self,
        shard_id: ShardId,
    ) -> CollectionResult<Vec<SnapshotDescription>> {
        self.shards_holder
            .read()
            .await
            .list_shard_snapshots(&self.snapshots_path, shard_id)
            .await
    }

    pub async fn create_shard_snapshot(
        &self,
        shard_id: ShardId,
        temp_dir: &Path,
    ) -> CollectionResult<SnapshotDescription> {
        let snapshot_creator = self
            .shards_holder
            .read()
            .await
            .create_shard_snapshot(&self.snapshots_path, self.name(), shard_id, temp_dir)
            .await?;
        // We don't hold shards_holder lock here on purpose,
        // because snapshot creation may take a long time,
        // and we don't want to block other operations on the collection.
        snapshot_creator.await
    }

    pub async fn stream_shard_snapshot(
        &self,
        shard_id: ShardId,
        manifest: Option<SnapshotManifest>,
        temp_dir: &Path,
    ) -> CollectionResult<SnapshotStream> {
        let shard = OwnedRwLockReadGuard::try_map(
            self.shards_holder.clone().read_owned().await,
            |shard_holder| shard_holder.get_shard(shard_id),
        )
        .map_err(|_| shard_not_found_error(shard_id))?;

        ShardHolder::stream_shard_snapshot(shard, self.name(), shard_id, manifest, temp_dir).await
    }

    /// # Cancel safety
    ///
    /// This method is cancel safe.
    #[expect(clippy::too_many_arguments)]
    pub async fn restore_shard_snapshot(
        &self,
        shard_id: ShardId,
        snapshot_data: SnapshotData,
        recovery_type: RecoveryType,
        this_peer_id: PeerId,
        is_distributed: bool,
        temp_dir: &Path,
        recovery_progress: Option<RecoveryProgressHandle>,
        cancel: cancel::CancellationToken,
    ) -> CollectionResult<impl Future<Output = CollectionResult<()>> + 'static> {
        // `ShardHolder::validate_shard_snapshot` is cancel safe, so we explicitly cancel it
        // when token is triggered
        let shard_holder = self.shards_holder.clone().read_owned().await;

        let collection_path = self.path.clone();
        let collection_name = self.name().to_string();

        let temp_dir = temp_dir.to_path_buf();

        // `ShardHolder::restore_shard_snapshot` is *not* cancel safe, so we spawn it onto runtime,
        // so that it won't be cancelled if current future is dropped
        let restore = self.update_runtime.spawn(async move {
            shard_holder
                .restore_shard_snapshot(
                    snapshot_data,
                    recovery_type,
                    &collection_path,
                    &collection_name,
                    shard_id,
                    this_peer_id,
                    is_distributed,
                    &temp_dir,
                    recovery_progress,
                    cancel,
                )
                .await?;

            CollectionResult::Ok(())
        });

        // Flatten nested `Result<Result<()>>` into `Result<()>`
        let restore = async move {
            restore.await.map_err(CollectionError::from)??;
            Ok(())
        };

        Ok(restore)
    }

    pub async fn assert_shard_exists(&self, shard_id: ShardId) -> CollectionResult<()> {
        self.shards_holder
            .read()
            .await
            .assert_shard_exists(shard_id)
    }

    /// Drop the local shard and clear its on-disk data, before a shard snapshot
    /// transfer downloads a replacement snapshot. See
    /// [`ShardReplicaSet::clear_local_for_snapshot_recovery`] for details and safety
    /// constraints.
    pub async fn clear_local_shard_for_snapshot_recovery(
        &self,
        shard_id: ShardId,
    ) -> CollectionResult<()> {
        self.shards_holder
            .read()
            .await
            .get_shard(shard_id)
            .ok_or_else(|| shard_not_found_error(shard_id))?
            .clear_local_for_snapshot_recovery(&self.path)
            .await
    }

    pub async fn try_take_partial_snapshot_recovery_lock(
        &self,
        shard_id: ShardId,
        recovery_type: RecoveryType,
    ) -> CollectionResult<Option<tokio::sync::OwnedRwLockWriteGuard<()>>> {
        self.shards_holder
            .read()
            .await
            .try_take_partial_snapshot_recovery_lock(shard_id, recovery_type)
    }

    pub async fn get_partial_snapshot_manifest(
        &self,
        shard_id: ShardId,
    ) -> CollectionResult<SnapshotManifest> {
        self.shards_holder
            .read()
            .await
            .get_shard(shard_id)
            .ok_or_else(|| shard_not_found_error(shard_id))?
            .get_partial_snapshot_manifest()
            .await
    }
}use std::collections::HashSet;

use ahash::AHashMap;
use common::counter::hardware_accumulator::HwMeasurementAcc;
use futures::StreamExt as _;
use futures::stream::FuturesUnordered;

use crate::collection::Collection;
use crate::collection::payload_index_schema::PayloadIndexSchema;
use crate::collection_state::{ShardInfo, State};
use crate::config::{CollectionConfigInternal, CollectionParams};
use crate::operations::types::{CollectionError, CollectionResult};
use crate::shards::replica_set::ShardReplicaSet;
use crate::shards::resharding::ReshardState;
use crate::shards::shard::{PeerId, ShardId};
use crate::shards::shard_holder::ShardTransferChange;
use crate::shards::shard_holder::shard_mapping::ShardKeyMapping;
use crate::shards::transfer::ShardTransfer;

impl Collection {
    pub async fn check_config_compatible(
        &self,
        config: &CollectionConfigInternal,
    ) -> CollectionResult<()> {
        self.collection_config
            .read()
            .await
            .params
            .check_compatible(&config.params)
    }

    pub async fn apply_state(
        &self,
        state: State,
        this_peer_id: PeerId,
        abort_transfer: impl FnMut(ShardTransfer),
    ) -> CollectionResult<()> {
        let State {
            config,
            shards,
            resharding,
            transfers,
            shards_key_mapping,
            payload_index_schema,
        } = state;

        // Used to detect which named vectors have changed after applying new config
        let old_collection_config = self.collection_config.read().await.params.clone();

        // Apply config first — this updates the collection-level vector definitions
        let new_config = config.clone();
        self.apply_config(config).await?;
        self.apply_shard_transfers(transfers, this_peer_id, abort_transfer)
            .await?;
        self.apply_reshard_state(resharding).await?;
        self.apply_shard_info(shards, shards_key_mapping).await?;
        self.apply_payload_index_schema(payload_index_schema)
            .await?;
        // Reconcile named vectors at the segment level to match the new config.
        // This ensures segments have the correct vector storages after a Raft snapshot.
        self.apply_vector_name_schema(old_collection_config, &new_config)
            .await?;
        Ok(())
    }

    async fn apply_shard_transfers(
        &self,
        shard_transfers: HashSet<ShardTransfer>,
        this_peer_id: PeerId,
        mut abort_transfer: impl FnMut(ShardTransfer),
    ) -> CollectionResult<()> {
        let old_transfers = self
            .shards_holder
            .read()
            .await
            .shard_transfers
            .read()
            .clone();
        for transfer in shard_transfers.intersection(&old_transfers) {
            log::debug!("Aborting shard transfer: {transfer:?}");
        }
        for transfer in old_transfers.difference(&shard_transfers) {
            log::debug!("Aborting shard transfer: {transfer:?}");
        }
        for transfer in shard_transfers.difference(&old_transfers) {
            if transfer.from == this_peer_id {
                // Abort transfer as sender should not learn about the transfer from snapshot
                // If this happens it mean the sender is probably outdated and it is safer to abort
                abort_transfer(transfer.clone());
                // Since we remove the transfer from our list below, we don't invoke regular abort logic on this node
                // Do it here explicitly so we don't miss a silent abort change
                let _ = self
                    .shards_holder
                    .read()
                    .await
                    .shard_transfer_changes
                    .send(ShardTransferChange::Abort(transfer.key()));
            }
        }
        self.shards_holder
            .write()
            .await
            .shard_transfers
            .write(|transfers| *transfers = shard_transfers)?;
        Ok(())
    }

    async fn apply_reshard_state(&self, resharding: Option<ReshardState>) -> CollectionResult<()> {
        // We don't have to explicitly abort resharding or bump shard replica states, because:
        // - peers are not driving resharding themselves
        // - ongoing (resharding) shard transfers are explicitly updated
        // - shard replica set states are explicitly updated
        self.shards_holder
            .write()
            .await
            .resharding_state
            .write(|state| *state = resharding)?;
        Ok(())
    }

    async fn apply_config(&self, new_config: CollectionConfigInternal) -> CollectionResult<()> {
        let recreate_optimizers;

        {
            let mut config = self.collection_config.write().await;

            if config.uuid != new_config.uuid {
                return Err(CollectionError::service_error(format!(
                    "collection {} UUID mismatch: \
                     UUID of existing collection is different from UUID of collection in Raft snapshot: \
                     existing collection UUID: {:?}, Raft snapshot collection UUID: {:?}",
                    self.id, config.uuid, new_config.uuid,
                )));
            }

            if let Err(err) = config.params.check_compatible(&new_config.params) {
                // Stop consensus with a service error, if new config is incompatible with current one.
                //
                // We expect that `apply_config` is only called when configs are compatible, otherwise
                // collection have to be *recreated*.
                return Err(CollectionError::service_error(err.to_string()));
            }

            // Destructure `new_config`, to ensure we compare all config fields. Compiler would
            // complain, if new field is added to `CollectionConfig` struct, but not destructured
            // explicitly. We have to explicitly compare config fields, because we want to compare
            // `wal_config` and `strict_mode_config` independently of other fields.
            let CollectionConfigInternal {
                params,
                hnsw_config,
                optimizer_config,
                wal_config,
                quantization_config,
                strict_mode_config,
                uuid: _,
                metadata,
            } = &new_config;

            let is_core_config_updated = params != &config.params
                || hnsw_config != &config.hnsw_config
                || optimizer_config != &config.optimizer_config
                || quantization_config != &config.quantization_config;

            let is_metadata_updated = metadata != &config.metadata;

            let is_wal_config_updated = wal_config != &config.wal_config;
            let is_strict_mode_config_updated = strict_mode_config != &config.strict_mode_config;

            let is_config_updated = is_core_config_updated
                || is_wal_config_updated
                || is_strict_mode_config_updated
                || is_metadata_updated;

            if !is_config_updated {
                return Ok(());
            }

            if is_wal_config_updated {
                log::warn!(
                    "WAL config of collection {} updated when applying Raft snapshot, \
                     but updated WAL config will only be applied on Qdrant restart",
                    self.id,
                );
            }

            *config = new_config;

            // We need to recreate optimizers, if "core" config was updated
            recreate_optimizers = is_core_config_updated;
        }

        self.collection_config.read().await.save(&self.path)?;

        self.print_warnings().await;

        // Recreate optimizers in the background: this path is reached from consensus (Raft snapshot
        // application), and stopping the existing optimizers can take a long time, which would
        // otherwise stall the consensus loop.
        if recreate_optimizers {
            self.recreate_optimizers_background();
        }

        Ok(())
    }

    async fn apply_shard_info(
        &self,
        shards: AHashMap<ShardId, ShardInfo>,
        shards_key_mapping: ShardKeyMapping,
    ) -> CollectionResult<()> {
        let mut extra_shards: AHashMap<ShardId, ShardReplicaSet> = AHashMap::new();

        let shard_ids = shards.keys().copied().collect::<HashSet<_>>();

        // There are two components, where shard-related info is stored:
        // Shard objects themselves and shard_holder, that maps shard_keys to shards.

        // On the first state of the update, we update state of shards themselves
        // and create new shards if needed

        let mut shards_holder = self.shards_holder.write().await;

        for (shard_id, shard_info) in shards {
            let shard_key = shards_key_mapping.shard_key(shard_id);
            match shards_holder.get_shard(shard_id) {
                Some(replica_set) => {
                    replica_set
                        .apply_state(shard_info.replicas, shard_key)
                        .await?;
                }
                None => {
                    let mut shard_replicas: Vec<_> = shard_info.replicas.keys().copied().collect();
                    shard_replicas.sort_unstable();
                    let replica_set = self
                        .create_replica_set(shard_id, shard_key.clone(), &shard_replicas, None)
                        .await?;
                    replica_set
                        .apply_state(shard_info.replicas, shard_key)
                        .await?;
                    extra_shards.insert(shard_id, replica_set);
                }
            }
        }

        // On the second step, we register missing shards and remove extra shards
        shards_holder
            .apply_shards_state(shard_ids, shards_key_mapping, extra_shards)
            .await
    }

    async fn apply_payload_index_schema(
        &self,
        payload_index_schema: PayloadIndexSchema,
    ) -> CollectionResult<()> {
        let state = self.state().await;

        for field_name in state.payload_index_schema.schema.keys() {
            if !payload_index_schema.schema.contains_key(field_name) {
                self.drop_payload_index(field_name.clone()).await?;
            }
        }

        for (field_name, field_schema) in payload_index_schema.schema {
            // This function is only used in collection state recovery and thus an unmeasured internal operation.
            self.create_payload_index(field_name, field_schema, HwMeasurementAcc::disposable())
                .await?;
        }
        Ok(())
    }

    /// Reconcile named vectors at the segment level to match the given config.
    ///
    /// This is called during state application (Raft snapshot recovery) to ensure
    /// that segments have the correct vector storages, even if the node missed the
    /// original create/delete vector name operations.
    async fn apply_vector_name_schema(
        &self,
        old_collection_params: CollectionParams,
        target_config: &CollectionConfigInternal,
    ) -> CollectionResult<()> {
        use segment::data_types::vector_name_config::{
            DenseVectorConfig, SparseVectorConfig, VectorNameConfig,
        };
        use segment::types::VectorStorageDatatype;

        let mut to_create: Vec<(segment::types::VectorNameBuf, VectorNameConfig)> = Vec::new();
        let mut to_delete: Vec<segment::types::VectorNameBuf> = Vec::new();

        // Dense vectors: compare target vs current
        for (vector_name, target_params) in target_config.params.vectors.params_iter() {
            let target_dense = DenseVectorConfig {
                size: target_params.size.get() as usize,
                distance: target_params.distance,
                multivector_config: target_params.multivector_config,
                datatype: target_params.datatype.map(VectorStorageDatatype::from),
            };

            match old_collection_params.vectors.get_params(vector_name) {
                None => {
                    // New vector — create it
                    to_create.push((
                        vector_name.to_owned(),
                        VectorNameConfig::dense(target_dense),
                    ));
                }
                Some(current_params) => {
                    // Exists in both — check if parameters changed (delete+recreate)
                    let current_dense = DenseVectorConfig {
                        size: current_params.size.get() as usize,
                        distance: current_params.distance,
                        multivector_config: current_params.multivector_config,
                        datatype: current_params.datatype.map(VectorStorageDatatype::from),
                    };
                    if current_dense != target_dense {
                        to_delete.push(vector_name.to_owned());
                        to_create.push((
                            vector_name.to_owned(),
                            VectorNameConfig::dense(target_dense),
                        ));
                    }
                }
            }
        }

        // Dense vectors: delete those in current but not in target
        for (vector_name, _) in old_collection_params.vectors.params_iter() {
            if target_config
                .params
                .vectors
                .get_params(vector_name)
                .is_none()
            {
                to_delete.push(vector_name.to_owned());
            }
        }

        // Sparse vectors: compare target vs current
        if let Some(target_sparse) = &target_config.params.sparse_vectors {
            let current_sparse = old_collection_params.sparse_vectors.as_ref();
            for (vector_name, target_params) in target_sparse {
                let target_sparse_cfg = SparseVectorConfig {
                    modifier: target_params.modifier,
                    datatype: target_params
                        .index
                        .as_ref()
                        .and_then(|idx| idx.datatype)
                        .map(VectorStorageDatatype::from),
                };

                let current_exists = current_sparse.and_then(|c| c.get(vector_name));
                match current_exists {
                    None => {
                        to_create.push((
                            vector_name.clone(),
                            VectorNameConfig::sparse(target_sparse_cfg),
                        ));
                    }
                    Some(current_params) => {
                        let current_sparse_cfg = SparseVectorConfig {
                            modifier: current_params.modifier,
                            datatype: current_params
                                .index
                                .as_ref()
                                .and_then(|idx| idx.datatype)
                                .map(VectorStorageDatatype::from),
                        };
                        if current_sparse_cfg != target_sparse_cfg {
                            to_delete.push(vector_name.clone());
                            to_create.push((
                                vector_name.clone(),
                                VectorNameConfig::sparse(target_sparse_cfg),
                            ));
                        }
                    }
                }
            }
        }

        // Sparse vectors: delete those in current but not in target
        if let Some(current_sparse) = &old_collection_params.sparse_vectors {
            let target_sparse = target_config.params.sparse_vectors.as_ref();
            for vector_name in current_sparse.keys() {
                if !target_sparse.is_some_and(|t| t.contains_key(vector_name)) {
                    to_delete.push(vector_name.clone());
                }
            }
        }

        // Delete first (includes changed vectors), then create
        for vector_name in to_delete {
            self.delete_named_vector(vector_name).await?;
        }

        for (vector_name, config) in to_create {
            self.create_named_vector(vector_name, config, HwMeasurementAcc::disposable())
                .await?;
        }

        Ok(())
    }

    /// Truncate unapplied WAL records for all local shards in the collection.
    /// Returns amount of removed records.
    pub async fn truncate_unapplied_wal(&self) -> CollectionResult<usize> {
        let shard_holder = self.shards_holder.clone().read_owned().await;

        let results = self
            .update_runtime
            .spawn(async move {
                let local_updates: FuturesUnordered<_> = shard_holder
                    .all_shards()
                    .map(|shard| shard.truncate_unapplied_wal())
                    .collect();

                let results: Vec<_> = local_updates.collect().await;

                results
            })
            .await?;

        results.into_iter().sum()
    }
}use std::time::Duration;

use common::types::{DetailsLevel, TelemetryDetail};

use crate::collection::Collection;
use crate::operations::types::CollectionResult;
use crate::telemetry::{CollectionConfigTelemetry, CollectionTelemetry};

impl Collection {
    pub async fn get_telemetry_data(
        &self,
        detail: TelemetryDetail,
        timeout: Duration,
    ) -> CollectionResult<CollectionTelemetry> {
        let (shards_telemetry, transfers, resharding) = {
            if detail.level >= DetailsLevel::Level3 {
                let shards_holder = self.shards_holder.read().await;
                let mut shards_telemetry = Vec::new();
                for shard in shards_holder.all_shards() {
                    shards_telemetry.push(shard.get_telemetry_data(detail, timeout).await?)
                }
                (
                    Some(shards_telemetry),
                    Some(shards_holder.get_shard_transfer_info(&*self.transfer_tasks.lock().await)),
                    Some(
                        shards_holder
                            .get_resharding_operations_info()
                            .unwrap_or_default(),
                    ),
                )
            } else {
                (None, None, None)
            }
        };

        let shard_clean_tasks = self.clean_local_shards_statuses();

        Ok(CollectionTelemetry {
            id: self.name().to_string(),
            init_time_ms: Some(self.init_time.as_millis() as u64),
            config: Some(CollectionConfigTelemetry::from(
                self.collection_config.read().await.clone(),
            )),
            shards: shards_telemetry,
            transfers,
            resharding,
            shard_clean_tasks: (!shard_clean_tasks.is_empty()).then_some(shard_clean_tasks),
        })
    }
}use std::num::NonZeroU64;

use common::counter::hardware_accumulator::HwMeasurementAcc;
use segment::data_types::vector_name_config::{
    DenseVectorConfig, SparseVectorConfig, VectorNameConfig,
};
use segment::types::VectorNameBuf;
use shard::operations::{
    CollectionUpdateOperations, CreateVectorName, DeleteVectorName, VectorNameOperations,
};

use crate::collection::Collection;
use crate::operations::types::{
    CollectionError, CollectionResult, SparseVectorParams, VectorParams,
};
use crate::shards::shard_trait::WaitUntil;

impl Collection {
    pub async fn create_named_vector(
        &self,
        vector_name: VectorNameBuf,
        config: VectorNameConfig,
        hw_acc: HwMeasurementAcc,
    ) -> CollectionResult<()> {
        self.update_collection_vector_config(|params| {
            add_vector_to_config(params, &vector_name, &config)
        })
        .await?;

        let operation = CollectionUpdateOperations::VectorNameOperation(
            VectorNameOperations::CreateVectorName(CreateVectorName {
                vector_name,
                config,
            }),
        );

        self.update_all_local(operation, WaitUntil::from(false), hw_acc, true)
            .await?;

        // Refresh shard optimizers so the cached `SegmentOptimizerConfig` picks up the
        // new vector schema. Otherwise optimization-built destination segments use the
        // stale dim and panic on dim mismatch when copying from sources with the new dim.
        //
        // Done in the background: this path is reached from consensus, where blocking can stall the
        // whole cluster. The refresh itself is unchanged - it already ran on a spawned task either
        // way - so this does not widen the window in which the stale config is in effect.
        self.recreate_optimizers_background();

        Ok(())
    }

    pub async fn delete_named_vector(&self, vector_name: VectorNameBuf) -> CollectionResult<()> {
        self.update_collection_vector_config(|params| {
            remove_vector_from_config(params, &vector_name);
            Ok(())
        })
        .await?;

        let operation = CollectionUpdateOperations::VectorNameOperation(
            VectorNameOperations::DeleteVectorName(DeleteVectorName { vector_name }),
        );

        self.update_all_local(
            operation,
            WaitUntil::from(true),
            HwMeasurementAcc::disposable(),
            true, // Delete even in dead shards
        )
        .await?;

        // Refresh shard optimizers so the cached `SegmentOptimizerConfig` drops the
        // removed vector. Without this, optimization keeps allocating storage for it
        // using the old config.
        //
        // Done in the background: this path is reached from consensus, where blocking can stall the
        // whole cluster.
        self.recreate_optimizers_background();

        Ok(())
    }

    /// Apply a mutation to collection params and persist.
    async fn update_collection_vector_config(
        &self,
        mutate: impl FnOnce(&mut crate::config::CollectionParams) -> CollectionResult<()>,
    ) -> CollectionResult<()> {
        let mut config = self.collection_config.write().await;
        mutate(&mut config.params)?;
        config.save(&self.path)?;
        Ok(())
    }
}

fn dense_config_to_params(config: &DenseVectorConfig) -> VectorParams {
    let DenseVectorConfig {
        size,
        distance,
        multivector_config,
        datatype,
    } = config;

    VectorParams {
        size: NonZeroU64::new(*size as u64).unwrap_or(NonZeroU64::MIN),
        distance: *distance,
        hnsw_config: None,
        quantization_config: None,
        on_disk: None,
        datatype: datatype.map(storage_datatype_to_collection),
        multivector_config: *multivector_config,
    }
}

fn sparse_config_to_params(config: &SparseVectorConfig) -> SparseVectorParams {
    let SparseVectorConfig { modifier, datatype } = config;

    SparseVectorParams {
        index: datatype.map(|dt| crate::operations::types::SparseIndexParams {
            full_scan_threshold: None,
            on_disk: None,
            datatype: Some(storage_datatype_to_collection(dt)),
        }),
        modifier: *modifier,
    }
}

/// Insert a new named vector into the stored collection params.
///
/// Returns `Ok(true)` if the vector was newly added, `Ok(false)` if a vector with the
/// same name and an identical config already exists (idempotent no-op), or
/// `Err(BadInput)` if a vector with the same name exists with a conflicting config or
/// a conflicting kind (dense vs. sparse). This guards against silently overwriting the
/// stored schema with a different one while shards keep the old one — shard-level
/// `CreateVectorName` is idempotent and will not re-apply the new config.
fn add_vector_to_config(
    params: &mut crate::config::CollectionParams,
    vector_name: &VectorNameBuf,
    config: &VectorNameConfig,
) -> CollectionResult<()> {
    match config {
        VectorNameConfig::Dense(wrapper) => {
            if let Some(existing) = params.vectors.get_params(vector_name.as_str()) {
                if !dense_schema_matches(existing, &wrapper.dense) {
                    return Err(CollectionError::bad_input(format!(
                        "Vector `{vector_name}` already exists with a different configuration",
                    )));
                }
                return Ok(());
            }
            if params
                .sparse_vectors
                .as_ref()
                .is_some_and(|sv| sv.contains_key(vector_name))
            {
                return Err(CollectionError::bad_input(format!(
                    "Vector `{vector_name}` already exists as a sparse vector",
                )));
            }
            params
                .vectors
                .insert(vector_name.clone(), dense_config_to_params(&wrapper.dense));
            Ok(())
        }
        VectorNameConfig::Sparse(wrapper) => {
            if let Some(existing) = params
                .sparse_vectors
                .as_ref()
                .and_then(|sv| sv.get(vector_name))
            {
                if !sparse_schema_matches(existing, &wrapper.sparse) {
                    return Err(CollectionError::bad_input(format!(
                        "Sparse vector `{vector_name}` already exists with a different configuration",
                    )));
                }
                return Ok(());
            }
            if params.vectors.get_params(vector_name.as_str()).is_some() {
                return Err(CollectionError::bad_input(format!(
                    "Vector `{vector_name}` already exists as a dense vector",
                )));
            }
            params
                .sparse_vectors
                .get_or_insert_with(Default::default)
                .insert(
                    vector_name.clone(),
                    sparse_config_to_params(&wrapper.sparse),
                );
            Ok(())
        }
    }
}

/// Compare the schema-defining subset of `VectorParams` against a `DenseVectorConfig`.
///
/// `VectorParams` carries fields that can be tuned independently after creation
/// (`hnsw_config`, `quantization_config`, `on_disk`); those must be ignored here so
/// repeated `create_named_vector` calls don't spuriously conflict with a vector whose
/// HNSW/quantization/on_disk settings were updated since.
fn dense_schema_matches(existing: &VectorParams, config: &DenseVectorConfig) -> bool {
    let DenseVectorConfig {
        size,
        distance,
        multivector_config,
        datatype,
    } = config;

    existing.size.get() == *size as u64
        && existing.distance == *distance
        && existing.multivector_config == *multivector_config
        && existing.datatype == datatype.map(storage_datatype_to_collection)
}

/// Compare the schema-defining subset of `SparseVectorParams` against a
/// `SparseVectorConfig`. Index tuning fields (`full_scan_threshold`, `on_disk`) are
/// ignored for the same reason as in [`dense_schema_matches`].
fn sparse_schema_matches(existing: &SparseVectorParams, config: &SparseVectorConfig) -> bool {
    let SparseVectorConfig { modifier, datatype } = config;

    let existing_datatype = existing.index.as_ref().and_then(|index| index.datatype);
    existing.modifier == *modifier
        && existing_datatype == datatype.map(storage_datatype_to_collection)
}

fn remove_vector_from_config(
    params: &mut crate::config::CollectionParams,
    vector_name: &VectorNameBuf,
) {
    params.vectors.remove(vector_name);

    if let Some(sparse) = &mut params.sparse_vectors {
        sparse.remove(vector_name);
    }
}

fn storage_datatype_to_collection(
    dt: segment::types::VectorStorageDatatype,
) -> crate::operations::types::Datatype {
    match dt {
        segment::types::VectorStorageDatatype::Float32 => {
            crate::operations::types::Datatype::Float32
        }
        segment::types::VectorStorageDatatype::Float16 => {
            crate::operations::types::Datatype::Float16
        }
        segment::types::VectorStorageDatatype::Uint8 => crate::operations::types::Datatype::Uint8,
        segment::types::VectorStorageDatatype::Turbo4 => crate::operations::types::Datatype::Turbo4,
    }
}/// Looks for segments having a mismatch between configured and actual parameters
///
/// For example, a user may change the HNSW parameters for a collection. A segment that was already
/// indexed with different parameters now has a mismatch. This segment should be optimized (and
/// indexed) again in order to update the effective configuration.
pub use shard::optimizers::config_mismatch_optimizer::ConfigMismatchOptimizer;

#[cfg(test)]
mod tests {
    use std::collections::HashMap;

    use itertools::Itertools;
    use segment::data_types::vectors::DEFAULT_VECTOR_NAME;
    use segment::entry::ReadSegmentEntry;
    use segment::segment_constructor::simple_segment_constructor::{VECTOR1_NAME, VECTOR2_NAME};
    use segment::types::{
        CompressionRatio, HnswConfig, HnswGlobalConfig, Indexes, ProductQuantization,
        ProductQuantizationConfig, QuantizationConfig, ScalarQuantizationConfig, ScalarType,
        SegmentConfig, VectorNameBuf, VectorStorageType,
    };
    use shard::operations::optimization::OptimizerThresholds;
    use shard::optimizers::config::{
        DenseVectorOptimizerConfig, SegmentOptimizerConfig, SparseVectorOptimizerConfig,
    };
    use shard::optimizers::segment_optimizer::SegmentOptimizer;
    use shard::segment_holder::locked::LockedSegmentHolder;
    use tempfile::Builder;

    use super::*;
    use crate::collection_manager::fixtures::{random_multi_vec_segment, random_segment};
    use crate::collection_manager::holders::segment_holder::SegmentHolder;
    use crate::collection_manager::optimizers::indexing_optimizer::IndexingOptimizer;

    fn dense_map_from_segment(
        segment_config: &SegmentConfig,
        overrides: &HashMap<VectorNameBuf, DenseVectorOptimizerConfig>,
    ) -> HashMap<VectorNameBuf, DenseVectorOptimizerConfig> {
        segment_config
            .vector_data
            .keys()
            .map(|name| {
                let cfg = overrides
                    .get(name)
                    .cloned()
                    .unwrap_or(DenseVectorOptimizerConfig {
                        on_disk: None,
                        hnsw_config: HnswConfig::default(),
                        quantization_config: None,
                    });
                (name.clone(), cfg)
            })
            .collect()
    }

    fn segment_optimizer_config(
        segment_config: &SegmentConfig,
        dense_overrides: &HashMap<VectorNameBuf, DenseVectorOptimizerConfig>,
    ) -> SegmentOptimizerConfig {
        let dense_vector = dense_map_from_segment(segment_config, dense_overrides);
        let mut base_vector_data = segment_config.vector_data.clone();
        for (name, cfg) in &dense_vector {
            if let Some(vector_data) = base_vector_data.get_mut(name)
                && let Some(on_disk) = cfg.on_disk
            {
                vector_data.storage_type = if on_disk {
                    VectorStorageType::Mmap
                } else {
                    VectorStorageType::Memory
                };
            }
        }

        SegmentOptimizerConfig {
            payload_storage_type: segment_config.payload_storage_type,
            plain_dense_vector_config: base_vector_data,
            plain_sparse_vector_config: segment_config.sparse_vector_data.clone(),
            dense_vector,
            sparse_vector: segment_config
                .sparse_vector_data
                .keys()
                .map(|name| (name.clone(), SparseVectorOptimizerConfig { on_disk: None }))
                .collect(),
        }
    }

    /// This test the config mismatch optimizer for a changed HNSW config
    ///
    /// It tests whether:
    /// - the condition check for HNSW mismatches works
    /// - optimized segments (and vector storages) use the updated configuration
    ///
    /// In short, this is what happens in this test:
    /// - create randomized segment as base
    /// - use indexing optimizer to build index for our segment
    /// - test config mismatch condition: should not trigger yet
    /// - change collection HNSW config
    /// - test config mismatch condition: should trigger due to HNSW change
    /// - optimize segment with config mismatch optimizer
    /// - assert segment uses changed configuration
    #[test]
    fn test_hnsw_config_mismatch() {
        // Collection configuration
        let (point_count, dim) = (1000, 10);
        let thresholds_config = OptimizerThresholds {
            max_segment_size_kb: usize::MAX,
            memmap_threshold_kb: usize::MAX,
            indexing_threshold_kb: 10,
            deferred_internal_id: None,
        };

        // Base segment
        let temp_dir = Builder::new().prefix("segment_temp_dir").tempdir().unwrap();
        let dir = Builder::new().prefix("segment_dir").tempdir().unwrap();
        let mut holder = SegmentHolder::default();

        let segment = random_segment(dir.path(), 100, point_count, dim as usize);
        let base_segment_config = segment.segment_config.clone();

        let segment_id = holder.add_new(segment);
        let locked_holder = LockedSegmentHolder::new(holder);

        let hnsw_config = HnswConfig {
            m: 16,
            ef_construct: 100,
            full_scan_threshold: 10,
            max_indexing_threads: 0,
            on_disk: None,
            payload_m: None,
            inline_storage: None,
        };

        let mut dense_overrides = HashMap::new();
        dense_overrides.insert(
            VectorNameBuf::from(DEFAULT_VECTOR_NAME),
            DenseVectorOptimizerConfig {
                on_disk: None,
                hnsw_config,
                quantization_config: None,
            },
        );
        let optimizer_config = segment_optimizer_config(&base_segment_config, &dense_overrides);

        // Optimizers used in test
        let index_optimizer = IndexingOptimizer::new(
            2,
            thresholds_config,
            dir.path().to_owned(),
            temp_dir.path().to_owned(),
            optimizer_config.clone(),
            HnswGlobalConfig::default(),
        );
        let config_mismatch_optimizer = ConfigMismatchOptimizer::new(
            thresholds_config,
            dir.path().to_owned(),
            temp_dir.path().to_owned(),
            optimizer_config,
            hnsw_config,
            HnswGlobalConfig::default(),
        );

        // Use indexing optimizer to build index for HNSW mismatch test
        let changed = index_optimizer.optimize_for_test(locked_holder.clone(), vec![segment_id]);
        assert!(changed > 0, "optimizer should have rebuilt this segment");
        assert!(
            locked_holder.read().get(segment_id).is_none(),
            "optimized segment should be gone",
        );
        assert_eq!(locked_holder.read().len(), 2, "index must be built");

        // Mismatch optimizer should not optimize yet, HNSW config is not changed yet
        let suggested_to_optimize =
            config_mismatch_optimizer.plan_optimizations_for_test(&locked_holder);
        assert_eq!(suggested_to_optimize.len(), 0);

        // Create changed HNSW config with other m/ef_construct value, update it in the optimizer
        let mut changed_hnsw_config = hnsw_config;
        changed_hnsw_config.m /= 2;
        changed_hnsw_config.ef_construct /= 5;

        dense_overrides.insert(
            VectorNameBuf::from(DEFAULT_VECTOR_NAME),
            DenseVectorOptimizerConfig {
                on_disk: None,
                hnsw_config: changed_hnsw_config,
                quantization_config: None,
            },
        );
        let changed_optimizer_config =
            segment_optimizer_config(&base_segment_config, &dense_overrides);
        let config_mismatch_optimizer = ConfigMismatchOptimizer::new(
            thresholds_config,
            dir.path().to_owned(),
            temp_dir.path().to_owned(),
            changed_optimizer_config,
            changed_hnsw_config,
            HnswGlobalConfig::default(),
        );

        // Run mismatch optimizer again, make sure it optimizes now
        let suggested_to_optimize =
            config_mismatch_optimizer.plan_optimizations_for_test(&locked_holder);
        let suggested_to_optimize = suggested_to_optimize.into_iter().exactly_one().unwrap();
        assert_eq!(suggested_to_optimize.len(), 1);
        let changed = config_mismatch_optimizer
            .optimize_for_test(locked_holder.clone(), suggested_to_optimize);
        assert!(changed > 0, "optimizer should have rebuilt this segment");

        // Ensure new segment has changed HNSW config
        locked_holder
            .read()
            .iter_original()
            .map(|(_, segment)| segment.read())
            .filter(|segment| segment.total_point_count() > 0)
            .for_each(|segment| {
                assert_eq!(
                    segment.config().vector_data[DEFAULT_VECTOR_NAME].index,
                    Indexes::Hnsw(changed_hnsw_config),
                    "segment must be optimized with changed HNSW config",
                );
            });
    }

    /// This test the config mismatch optimizer for a changed vector specific HNSW config
    ///
    /// Similar to `test_hnsw_config_mismatch` but for multi vector segment with a vector specific
    /// change.
    ///
    /// It tests whether:
    /// - the condition check for HNSW mismatches works for a vector specific change
    /// - optimized segments (and vector storages) use the updated configuration
    ///
    /// In short, this is what happens in this test:
    /// - create randomized multi segment as base
    /// - use indexing optimizer to build index for our segment
    /// - test config mismatch condition: should not trigger yet
    /// - change HNSW config for vector2
    /// - test config mismatch condition: should trigger due to HNSW change
    /// - optimize segment with config mismatch optimizer
    /// - assert segment uses changed configuration
    #[test]
    fn test_hnsw_config_mismatch_vector_specific() {
        // Collection configuration
        let (point_count, vector1_dim, vector2_dim) = (1000, 10, 20);
        let thresholds_config = OptimizerThresholds {
            max_segment_size_kb: usize::MAX,
            memmap_threshold_kb: usize::MAX,
            indexing_threshold_kb: 10,
            deferred_internal_id: None,
        };

        // Base segment
        let temp_dir = Builder::new().prefix("segment_temp_dir").tempdir().unwrap();
        let dir = Builder::new().prefix("segment_dir").tempdir().unwrap();
        let mut holder = SegmentHolder::default();

        let segment = random_multi_vec_segment(
            dir.path(),
            100,
            point_count,
            vector1_dim as usize,
            vector2_dim as usize,
        );
        let base_segment_config = segment.segment_config.clone();

        let segment_id = holder.add_new(segment);
        let locked_holder = LockedSegmentHolder::new(holder);

        let hnsw_config_collection = HnswConfig {
            m: 16,
            ef_construct: 100,
            full_scan_threshold: 10,
            max_indexing_threads: 0,
            on_disk: None,
            payload_m: None,
            inline_storage: None,
        };

        let mut hnsw_config_vector1 = hnsw_config_collection;
        hnsw_config_vector1.m = 10;
        hnsw_config_vector1.ef_construct = 40;
        hnsw_config_vector1.on_disk = Some(true);

        let hnsw_config_vector2 = hnsw_config_collection;

        let mut dense_overrides = HashMap::new();
        dense_overrides.insert(
            VectorNameBuf::from(VECTOR1_NAME),
            DenseVectorOptimizerConfig {
                on_disk: Some(true),
                hnsw_config: hnsw_config_vector1,
                quantization_config: None,
            },
        );
        dense_overrides.insert(
            VectorNameBuf::from(VECTOR2_NAME),
            DenseVectorOptimizerConfig {
                on_disk: None,
                hnsw_config: hnsw_config_vector2,
                quantization_config: None,
            },
        );
        let optimizer_config = segment_optimizer_config(&base_segment_config, &dense_overrides);

        // Optimizers used in test
        let index_optimizer = IndexingOptimizer::new(
            2,
            thresholds_config,
            dir.path().to_owned(),
            temp_dir.path().to_owned(),
            optimizer_config.clone(),
            HnswGlobalConfig::default(),
        );
        let config_mismatch_optimizer = ConfigMismatchOptimizer::new(
            thresholds_config,
            dir.path().to_owned(),
            temp_dir.path().to_owned(),
            optimizer_config,
            hnsw_config_collection,
            HnswGlobalConfig::default(),
        );

        // Use indexing optimizer to build index for HNSW mismatch test
        let changed = index_optimizer.optimize_for_test(locked_holder.clone(), vec![segment_id]);
        assert!(changed > 0, "optimizer should have rebuilt this segment");
        assert!(
            locked_holder.read().get(segment_id).is_none(),
            "optimized segment should be gone",
        );
        assert_eq!(locked_holder.read().len(), 2, "index must be built");

        // Mismatch optimizer should not optimize yet, HNSW config is not changed yet
        let suggested_to_optimize =
            config_mismatch_optimizer.plan_optimizations_for_test(&locked_holder);
        assert_eq!(suggested_to_optimize.len(), 0);

        let mut hnsw_config_vector2_changed = hnsw_config_collection;
        hnsw_config_vector2_changed.m = hnsw_config_vector1.m / 2;
        hnsw_config_vector2_changed.on_disk = Some(true);

        dense_overrides.insert(
            VectorNameBuf::from(VECTOR2_NAME),
            DenseVectorOptimizerConfig {
                on_disk: None,
                hnsw_config: hnsw_config_vector2_changed,
                quantization_config: None,
            },
        );
        let changed_optimizer_config =
            segment_optimizer_config(&base_segment_config, &dense_overrides);
        let config_mismatch_optimizer = ConfigMismatchOptimizer::new(
            thresholds_config,
            dir.path().to_owned(),
            temp_dir.path().to_owned(),
            changed_optimizer_config,
            hnsw_config_collection,
            HnswGlobalConfig::default(),
        );

        // Run mismatch optimizer again, make sure it optimizes now
        let suggested_to_optimize =
            config_mismatch_optimizer.plan_optimizations_for_test(&locked_holder);
        let suggested_to_optimize = suggested_to_optimize.into_iter().exactly_one().unwrap();
        assert_eq!(suggested_to_optimize.len(), 1);
        let changed = config_mismatch_optimizer
            .optimize_for_test(locked_holder.clone(), suggested_to_optimize);
        assert!(changed > 0, "optimizer should have rebuilt this segment");

        // Ensure new segment has changed HNSW config
        locked_holder
            .read()
            .iter_original()
            .map(|(_, segment)| segment.read())
            .filter(|segment| segment.total_point_count() > 0)
            .for_each(|segment| {
                assert_eq!(
                    segment.config().vector_data[VECTOR1_NAME].index,
                    Indexes::Hnsw(hnsw_config_vector1),
                    "HNSW config of vector1 is not what we expect",
                );
                assert_eq!(
                    segment.config().vector_data[VECTOR2_NAME].index,
                    Indexes::Hnsw(hnsw_config_vector2_changed),
                    "HNSW config of vector2 is not what we expect",
                );
            });
    }

    /// This test the config mismatch optimizer for a changed vector specific HNSW config
    ///
    /// Similar to `test_hnsw_config_mismatch` but for multi vector segment with a vector specific
    /// change.
    ///
    /// It tests whether:
    /// - the condition check for HNSW mismatches works for a vector specific change
    /// - optimized segments (and vector storages) use the updated configuration
    ///
    /// In short, this is what happens in this test:
    /// - create randomized multi segment as base
    /// - use indexing optimizer to build index for our segment
    /// - test config mismatch condition: should not trigger yet
    /// - change HNSW config for vector2
    /// - test config mismatch condition: should trigger due to HNSW change
    /// - optimize segment with config mismatch optimizer
    /// - assert segment uses changed configuration
    #[test]
    fn test_quantization_config_mismatch_vector_specific() {
        // Collection configuration
        let (point_count, vector1_dim, vector2_dim) = (1000, 10, 20);
        let thresholds_config = OptimizerThresholds {
            max_segment_size_kb: usize::MAX,
            memmap_threshold_kb: usize::MAX,
            indexing_threshold_kb: 10,
            deferred_internal_id: None,
        };
        let quantization_config_vector1 =
            QuantizationConfig::Scalar(segment::types::ScalarQuantization {
                scalar: ScalarQuantizationConfig {
                    r#type: ScalarType::Int8,
                    quantile: Some(0.99),
                    always_ram: Some(true),
                },
            });

        // Base segment
        let temp_dir = Builder::new().prefix("segment_temp_dir").tempdir().unwrap();
        let dir = Builder::new().prefix("segment_dir").tempdir().unwrap();
        let mut holder = SegmentHolder::default();

        let segment = random_multi_vec_segment(
            dir.path(),
            100,
            point_count,
            vector1_dim as usize,
            vector2_dim as usize,
        );
        let base_segment_config = segment.segment_config.clone();

        let segment_id = holder.add_new(segment);
        let locked_holder = LockedSegmentHolder::new(holder);

        let quantization_config_collection =
            QuantizationConfig::Scalar(segment::types::ScalarQuantization {
                scalar: ScalarQuantizationConfig {
                    r#type: ScalarType::Int8,
                    quantile: Some(0.91),
                    always_ram: None,
                },
            });

        let mut dense_overrides = HashMap::new();
        dense_overrides.insert(
            VectorNameBuf::from(VECTOR1_NAME),
            DenseVectorOptimizerConfig {
                on_disk: None,
                hnsw_config: HnswConfig::default(),
                quantization_config: Some(quantization_config_vector1.clone()),
            },
        );
        dense_overrides.insert(
            VectorNameBuf::from(VECTOR2_NAME),
            DenseVectorOptimizerConfig {
                on_disk: None,
                hnsw_config: HnswConfig::default(),
                quantization_config: Some(quantization_config_collection.clone()),
            },
        );
        let optimizer_config = segment_optimizer_config(&base_segment_config, &dense_overrides);

        // Optimizers used in test
        let index_optimizer = IndexingOptimizer::new(
            2,
            thresholds_config,
            dir.path().to_owned(),
            temp_dir.path().to_owned(),
            optimizer_config.clone(),
            HnswGlobalConfig::default(),
        );
        let config_mismatch_optimizer = ConfigMismatchOptimizer::new(
            thresholds_config,
            dir.path().to_owned(),
            temp_dir.path().to_owned(),
            optimizer_config,
            Default::default(),
            HnswGlobalConfig::default(),
        );

        // Use indexing optimizer to build index for quantization mismatch test
        let changed = index_optimizer.optimize_for_test(locked_holder.clone(), vec![segment_id]);
        assert!(changed > 0, "optimizer should have rebuilt this segment");
        assert!(
            locked_holder.read().get(segment_id).is_none(),
            "optimized segment should be gone",
        );
        assert_eq!(locked_holder.read().len(), 2, "index must be built");

        // Mismatch optimizer should not optimize yet, quantization config is not changed yet
        let suggested_to_optimize =
            config_mismatch_optimizer.plan_optimizations_for_test(&locked_holder);
        assert_eq!(suggested_to_optimize.len(), 0);

        // Create changed quantization config for vector2, update it in the optimizer
        let quantization_config_vector2 = QuantizationConfig::Product(ProductQuantization {
            product: ProductQuantizationConfig {
                compression: CompressionRatio::X32,
                always_ram: Some(true),
            },
        });
        dense_overrides.insert(
            VectorNameBuf::from(VECTOR2_NAME),
            DenseVectorOptimizerConfig {
                on_disk: None,
                hnsw_config: HnswConfig::default(),
                quantization_config: Some(quantization_config_vector2.clone()),
            },
        );
        let changed_optimizer_config =
            segment_optimizer_config(&base_segment_config, &dense_overrides);
        let config_mismatch_optimizer = ConfigMismatchOptimizer::new(
            thresholds_config,
            dir.path().to_owned(),
            temp_dir.path().to_owned(),
            changed_optimizer_config,
            Default::default(),
            HnswGlobalConfig::default(),
        );

        // Run mismatch optimizer again, make sure it optimizes now
        let suggested_to_optimize =
            config_mismatch_optimizer.plan_optimizations_for_test(&locked_holder);
        let suggested_to_optimize = suggested_to_optimize.into_iter().exactly_one().unwrap();
        assert_eq!(suggested_to_optimize.len(), 1);
        let changed = config_mismatch_optimizer
            .optimize_for_test(locked_holder.clone(), suggested_to_optimize);
        assert!(changed > 0, "optimizer should have rebuilt this segment");

        // Ensure new segment has changed quantization config
        locked_holder
            .read()
            .iter_original()
            .map(|(_, segment)| segment.read())
            .filter(|segment| segment.total_point_count() > 0)
            .for_each(|segment| {
                assert_eq!(
                    segment.config().vector_data[VECTOR1_NAME].quantization_config,
                    Some(quantization_config_vector1.clone()),
                    "Quantization config of vector1 is not what we expect",
                );
                assert_eq!(
                    segment.config().vector_data[VECTOR2_NAME].quantization_config,
                    Some(quantization_config_vector2.clone()),
                    "Quantization config of vector2 is not what we expect",
                );
            });
    }
}/// Looks for the segments, which require to be indexed.
///
/// If segment is too large, but still does not have indexes - it is time to create some indexes.
/// The process of index creation is slow and CPU-bounded, so it is convenient to perform
/// index building in a same way as segment re-creation.
pub use shard::optimizers::indexing_optimizer::IndexingOptimizer;

#[cfg(test)]
mod tests {
