impl TryFrom<api::grpc::qdrant::RecommendPoints> for RecommendRequestInternal {
    type Error = Status;

    fn try_from(value: api::grpc::qdrant::RecommendPoints) -> Result<Self, Self::Error> {
        let api::grpc::qdrant::RecommendPoints {
            positive,
            negative,
            strategy,
            using,
            lookup_from,
            filter,
            params,
            with_payload,
            with_vectors,
            score_threshold,
            read_consistency: _,
            limit,
            offset,
            collection_name: _,
            positive_vectors,
            negative_vectors,
            timeout: _,
            shard_key_selector: _,
        } = value;
        let positive_ids = positive
            .into_iter()
            .map(RecommendExample::try_from)
            .collect::<Result<Vec<RecommendExample>, Self::Error>>()?;

        let positive_vectors = positive_vectors
            .into_iter()
            .map(RecommendExample::try_from)
            .collect::<Result<_, _>>()?;
        let positive = [positive_ids, positive_vectors].concat();

        let negative_ids = negative
            .into_iter()
            .map(RecommendExample::try_from)
            .collect::<Result<Vec<RecommendExample>, Self::Error>>()?;

        let negative_vectors = negative_vectors
            .into_iter()
            .map(RecommendExample::try_from)
            .collect::<Result<_, _>>()?;
        let negative = [negative_ids, negative_vectors].concat();

        Ok(RecommendRequestInternal {
            positive,
            negative,
            strategy: strategy.map(|s| s.try_into()).transpose()?,
            filter: filter.map(|f| f.try_into()).transpose()?,
            params: params.map(Into::into),
            limit: limit as usize,
            offset: offset.map(|x| x as usize),
            with_payload: with_payload.map(|wp| wp.try_into()).transpose()?,
            with_vector: Some(with_vectors.map(Into::into).unwrap_or_default()),
            score_threshold,
            using: using.map(String::into),
            lookup_from: lookup_from.map(LookupLocation::try_from).transpose()?,
        })
    }
}

impl TryFrom<api::grpc::qdrant::RecommendPointGroups> for RecommendGroupsRequestInternal {
    type Error = Status;

    fn try_from(value: api::grpc::qdrant::RecommendPointGroups) -> Result<Self, Self::Error> {
        let api::grpc::qdrant::RecommendPointGroups {
            collection_name: _,
            positive,
            negative,
            filter,
            limit,
            with_payload,
            params,
            score_threshold,
            using,
            with_vectors,
            lookup_from,
            group_by,
            group_size,
            read_consistency: _,
            with_lookup,
            strategy,
            positive_vectors,
            negative_vectors,
            timeout: _,
            shard_key_selector: _,
        } = value;

        let recommend_points = api::grpc::qdrant::RecommendPoints {
            positive,
            negative,
            strategy,
            using,
            lookup_from,
            filter,
            params,
            with_payload,
            with_vectors,
            score_threshold,
            read_consistency: None,
            limit: 0,     // Will be calculated from group_size
            offset: None, // Not enabled for groups
            collection_name: String::new(),
            positive_vectors,
            negative_vectors,
            timeout: None, // Passed as query param
            shard_key_selector: None,
        };

        let RecommendRequestInternal {
            positive,
            negative,
            strategy,
            using,
            lookup_from,
            filter,
            params,
            with_payload,
            with_vector,
            score_threshold,
            limit: _,
            offset: _,
        } = recommend_points.try_into()?;

        Ok(RecommendGroupsRequestInternal {
            positive,
            negative,
            strategy,
            using,
            lookup_from,
            filter,
            params,
            with_payload,
            with_vector,
            score_threshold,
            group_request: BaseGroupRequest {
                group_by: json_path_from_proto(&group_by)?,
                limit,
                group_size,
                with_lookup: with_lookup.map(|l| l.try_into()).transpose()?,
            },
        })
    }
}

