/// Outcome of submitting an update to the worker queue.
pub enum SubmitOutcome {
    /// Operation was written to the WAL and dispatched to the update worker.
    /// Awaiting the embedded receiver yields the operation's result.
    Submitted {
        operation_id: segment::types::SeqNumberType,
        receiver: Option<oneshot::Receiver<CollectionResult<InternalUpdateResult>>>,
        clock_tag: Option<crate::operations::ClockTag>,
    },
    /// Operation was rejected because of an outdated clock; nothing was queued.
    ClockRejected {
        clock_tag: Option<crate::operations::ClockTag>,
    },
}

impl LocalShard {
    /// Submit an update to the worker queue without waiting for completion.
    ///
    /// Holds locks only for the brief WAL write + channel send. The returned
    /// [`SubmitOutcome::Submitted`] carries an owned `oneshot::Receiver` that
    /// can be awaited via [`await_update_result`] after dropping any outer
    /// read guards on the replica set.
    pub async fn submit_update(
        &self,
        mut operation: OperationWithClockTag,
        wait: WaitUntil,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<SubmitOutcome> {
        let (callback_sender, callback_receiver) = if wait.needs_callback() {
            let (tx, rx) = oneshot::channel();
            (Some(tx), Some(rx))
        } else {
            (None, None)
        };

        if self
            .disk_usage_watcher
            .is_disk_full()
            .await?
            .unwrap_or(false)
        {
            return Err(CollectionError::service_error(
                "No space left on device: WAL buffer size exceeds available disk space".to_string(),
            ));
        }

        let _update_lock = self.update_lock.read().await;
        let pending_operations_count = self.update_queue_length();

        let update_sender = self.update_sender.load();
        let channel_permit = update_sender.reserve().await?;

        // It is *critical* to hold `_wal_lock` while sending operation to the update handler!
        //
        // TODO: Refactor `lock_and_write`, so this is less terrible? :/
        let (operation_id, _wal_lock) = match self.wal.lock_and_write(&mut operation).await {
            Ok(id_and_lock) => id_and_lock,

            Err(shard::wal::WalError::ClockRejected) => {
                // Propagate clock rejection to operation sender
                return Ok(SubmitOutcome::ClockRejected {
                    clock_tag: operation.clock_tag,
                });
            }

            Err(err) => return Err(err.into()),
        };

        // If there are too many pending operations, don't keep operation data in RAM.
        // Instead, read operation data from the WAL when processing the operation.
        let keep_operation_in_ram = pending_operations_count < DEFAULT_UPDATE_QUEUE_RAM_BUFFER;
        let clock_tag = operation.clock_tag;
        let operation_in_ram = keep_operation_in_ram.then_some(Box::new(operation.operation));

        channel_permit.send(UpdateSignal::Operation(OperationData {
            op_num: operation_id,
            operation: operation_in_ram,
            sender: callback_sender,
            wait_for_deferred: wait.wait_for_deferred(),
            hw_measurements: hw_measurement_acc,
        }));

        Ok(SubmitOutcome::Submitted {
            operation_id,
            receiver: callback_receiver,
            clock_tag,
        })
    }
}

/// Wait for an update previously dispatched via [`LocalShard::submit_update`].
///
/// The future is `'static` on its inputs (no borrow on the originating shard),
/// so the caller can drop replica-set read guards before awaiting it.
pub async fn await_update_result(
    outcome: SubmitOutcome,
    timeout: Option<Duration>,
) -> CollectionResult<UpdateResult> {
    let (operation_id, receiver, clock_tag) = match outcome {
        SubmitOutcome::Submitted {
            operation_id,
            receiver,
            clock_tag,
        } => (operation_id, receiver, clock_tag),
        SubmitOutcome::ClockRejected { clock_tag } => {
            return Ok(UpdateResult {
                operation_id: None,
                status: UpdateStatus::ClockRejected,
                clock_tag,
            });
        }
    };

    match (receiver, timeout) {
        // Wait indefinitely
        (Some(receiver), None) => {
            let _ = receiver.await??;
            Ok(UpdateResult {
                operation_id: Some(operation_id),
                status: UpdateStatus::Completed,
                clock_tag,
            })
        }
        // Wait for timeout
        (Some(receiver), Some(timeout)) => match tokio::time::timeout(timeout, receiver).await {
            Ok(res) => {
                let InternalUpdateResult { op_num, status } = res??;
                debug_assert_eq!(
                    op_num, operation_id,
                    "Operation ID from WAL should match the one received from update worker"
                );
                Ok(UpdateResult {
                    operation_id: Some(op_num),
                    status,
                    clock_tag,
                })
            }
            Err(elapsed) => {
                let _elapsed: Elapsed = elapsed;
                Ok(UpdateResult {
                    operation_id: Some(operation_id),
                    status: UpdateStatus::WaitTimeout,
                    clock_tag,
                })
            }
        },
        // Don't wait at all
        (None, _) => Ok(UpdateResult {
            operation_id: Some(operation_id),
            status: UpdateStatus::Acknowledged,
            clock_tag,
        }),
    }
}

#[async_trait]
impl ShardOperation for LocalShard {
    /// Imply interior mutability.
    /// Performs update operation on this collection asynchronously.
    /// Explicitly waits for result to be updated.
    ///
    /// # Cancel safety
    ///
    /// This method is cancel safe.
    async fn update(
        &self,
        operation: OperationWithClockTag,
        wait: WaitUntil,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<UpdateResult> {
        // `LocalShard::update` only has a single cancel safe `await`, WAL operations are blocking,
        // and update is applied by a separate task, so, surprisingly, this method is cancel safe. :D
        let outcome = self
            .submit_update(operation, wait, hw_measurement_acc)
            .await?;
        await_update_result(outcome, timeout).await
    }

    /// This call is rate limited by the read rate limiter.
    async fn scroll_by(
        &self,
        request: Arc<ScrollRequestInternal>,
        search_runtime_handle: &AdaptiveSearchHandle,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<Vec<RecordInternal>> {
        let ScrollRequestInternal {
            offset,
            limit,
            filter,
            with_payload,
            with_vector,
            order_by,
        } = request.as_ref();

        let default_with_payload = ScrollRequestInternal::default_with_payload();

        // Validate user did not try to use an id offset with order_by
        if order_by.is_some() && offset.is_some() {
            return Err(CollectionError::bad_input("Cannot use an `offset` when using `order_by`. The alternative for paging is to use `order_by.start_from` and a filter to exclude the IDs that you've already seen for the `order_by.start_from` value".to_string()));
        };

        // Check read rate limiter before proceeding
        self.check_read_rate_limiter(&hw_measurement_acc, "scroll_by", || {
            let mut cost = BASE_COST;
            if let Some(filter) = &filter {
                cost += filter_rate_cost(filter);
            }
            cost
        })?;
        let start_time = Instant::now();
        let cpu_utilization = hw_measurement_acc.cpu_utilization();

        let limit = limit.unwrap_or(ScrollRequestInternal::default_limit());
        let order_by = order_by.clone().map(OrderBy::from);
        let timeout = self.timeout_or_default_search_timeout(timeout);
        let result = match order_by {
            None => {
                self.internal_scroll_by_id(
                    *offset,
                    limit,
                    with_payload.as_ref().unwrap_or(&default_with_payload),
                    with_vector,
                    filter.as_ref(),
                    search_runtime_handle,
                    timeout,
                    hw_measurement_acc,
                    DeferredBehavior::Exclude,
                )
                .await
            }
            Some(order_by) => {
                self.internal_scroll_by_field(
                    limit,
                    with_payload.as_ref().unwrap_or(&default_with_payload),
                    with_vector,
                    filter.as_ref(),
                    search_runtime_handle,
                    &order_by,
                    timeout,
                    hw_measurement_acc,
                    DeferredBehavior::Exclude,
                )
                .await
            }
        };

        let elapsed = start_time.elapsed();
        let cpu_ratio = cpu_utilization.ratio();
        let cpu_usage_ratio = if cpu_ratio > 0.0 {
            Some(cpu_ratio)
        } else {
            None
        };
        log_request_to_collector(&self.collection_name, elapsed, cpu_usage_ratio, || request);
        result
    }

    async fn local_scroll_by_id(
        &self,
        offset: Option<ExtendedPointId>,
        limit: usize,
        with_payload_interface: &WithPayloadInterface,
        with_vector: &WithVector,
        filter: Option<&Filter>,
        search_runtime_handle: &AdaptiveSearchHandle,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
        deferred_behavior: DeferredBehavior,
    ) -> CollectionResult<Vec<RecordInternal>> {
        let timeout = self.timeout_or_default_search_timeout(timeout);
        self.internal_scroll_by_id(
            offset,
            limit,
            with_payload_interface,
            with_vector,
            filter,
            search_runtime_handle,
            timeout,
            hw_measurement_acc,
            deferred_behavior,
        )
        .await
    }

    /// Collect overview information about the shard
    async fn info(&self) -> CollectionResult<CollectionInfo> {
        Ok(CollectionInfo::from(self.local_shard_info().await))
    }

    /// This call is rate limited by the read rate limiter.
    async fn core_search(
        &self,
        request: Arc<CoreSearchRequestBatch>,
        search_runtime_handle: &AdaptiveSearchHandle,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<Vec<Vec<ScoredPoint>>> {
        // Check read rate limiter before proceeding
        self.check_read_rate_limiter(&hw_measurement_acc, "core_search", || {
            request.searches.iter().map(|s| s.search_rate_cost()).sum()
        })?;
        let timeout = self.timeout_or_default_search_timeout(timeout);
        self.do_search(request, search_runtime_handle, timeout, hw_measurement_acc)
            .await
    }

    /// This call is rate limited by the read rate limiter.
    async fn count(
        &self,
        request: Arc<CountRequestInternal>,
        search_runtime_handle: &AdaptiveSearchHandle,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
        deferred_behavior: DeferredBehavior,
    ) -> CollectionResult<CountResult> {
        // Check read rate limiter before proceeding
        self.check_read_rate_limiter(&hw_measurement_acc, "count", || {
            let mut cost = BASE_COST;
            if let Some(filter) = &request.filter {
                cost += filter_rate_cost(filter);
            }
            cost
        })?;
        let start_time = Instant::now();
        let cpu_utilization = hw_measurement_acc.cpu_utilization();
        let result: CollectionResult<usize> = if request.exact {
            let timeout = self.timeout_or_default_search_timeout(timeout);
            match tokio::time::timeout(
                timeout,
                self.read_filtered(
                    request.filter.as_ref(),
                    search_runtime_handle,
                    hw_measurement_acc,
                    Some(timeout),
                    deferred_behavior,
                ),
            )
            .await
            {
                Ok(Ok(all_points)) => Ok(all_points.len()),
                Ok(Err(err)) => Err(err),
                Err(_elapsed) => Err(CollectionError::timeout(timeout, "count")),
            }
        } else {
            self.estimate_cardinality(request.filter.as_ref(), &hw_measurement_acc)
                .await
                .map(|cardinality| cardinality.exp)
        };
        let elapsed = start_time.elapsed();
        let cpu_ratio = cpu_utilization.ratio();
        let cpu_usage_ratio = if cpu_ratio > 0.0 {
            Some(cpu_ratio)
        } else {
            None
        };
        log_request_to_collector(&self.collection_name, elapsed, cpu_usage_ratio, || request);
        result.map(|total_count| CountResult { count: total_count })
    }

    /// This call is rate limited by the read rate limiter.
    async fn retrieve(
        &self,
        request: Arc<PointRequestInternal>,
        with_payload: &WithPayload,
        with_vector: &WithVector,
        search_runtime_handle: &AdaptiveSearchHandle,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
        deferred_behavior: DeferredBehavior,
    ) -> CollectionResult<Vec<RecordInternal>> {
        // Check read rate limiter before proceeding
        self.check_read_rate_limiter(&hw_measurement_acc, "retrieve", || request.ids.len())?;
        let timeout = self.timeout_or_default_search_timeout(timeout);

        let start_time = Instant::now();
        let cpu_utilization = hw_measurement_acc.cpu_utilization();
        let result = match tokio::time::timeout(
            timeout,
            SegmentsSearcher::retrieve(
                self.segments.clone(),
                &request.ids,
                with_payload,
                with_vector,
                search_runtime_handle,
                timeout,
                hw_measurement_acc,
                deferred_behavior,
            ),
        )
        .await
        {
            Ok(Ok(records_map)) => {
                let ordered_records = request
                    .ids
                    .iter()
                    .filter_map(|point| records_map.get(point).cloned())
                    .collect();

                Ok(ordered_records)
            }
            Ok(Err(err)) => Err(err),
            Err(_elapsed) => Err(CollectionError::timeout(timeout, "retrieve")),
        };

        let elapsed = start_time.elapsed();
        let cpu_ratio = cpu_utilization.ratio();
        let cpu_usage_ratio = if cpu_ratio > 0.0 {
            Some(cpu_ratio)
        } else {
            None
        };
        log_request_to_collector(&self.collection_name, elapsed, cpu_usage_ratio, || request);

        result
    }

    /// This call is rate limited by the read rate limiter.
    async fn query_batch(
        &self,
        requests: Arc<Vec<ShardQueryRequest>>,
        search_runtime_handle: &AdaptiveSearchHandle,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<Vec<ShardQueryResponse>> {
        let start_time = Instant::now();
        let planned_query = PlannedQuery::try_from(requests.as_ref().to_owned())?;

        // Check read rate limiter before proceeding
        self.check_read_rate_limiter(&hw_measurement_acc, "query_batch", || {
            planned_query
                .searches
                .iter()
                .map(|s| s.search_rate_cost())
                .chain(planned_query.scrolls.iter().map(|s| s.scroll_rate_cost()))
                .sum()
        })?;
        let timeout = self.timeout_or_default_search_timeout(timeout);
        let cpu_utilization = hw_measurement_acc.cpu_utilization();
        let result = self
            .do_planned_query(
                planned_query,
                search_runtime_handle,
                timeout,
                hw_measurement_acc,
            )
            .await;

        let elapsed = start_time.elapsed();
        let cpu_ratio = cpu_utilization.ratio();
        let cpu_usage_ratio = if cpu_ratio > 0.0 {
            Some(cpu_ratio)
        } else {
            None
        };
        log_request_to_collector(&self.collection_name, elapsed, cpu_usage_ratio, || {
            requests.remove_details()
        });

        result
    }

    /// This call is rate limited by the read rate limiter.
    async fn facet(
        &self,
        request: Arc<FacetParams>,
        search_runtime_handle: &AdaptiveSearchHandle,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<FacetResponse> {
        // Check read rate limiter before proceeding
        self.check_read_rate_limiter(&hw_measurement_acc, "facet", || {
            let mut cost = BASE_COST;
            if let Some(filter) = &request.filter {
                cost += filter_rate_cost(filter);
            }
            cost
        })?;

        let start_time = Instant::now();
        let timeout = self.timeout_or_default_search_timeout(timeout);
        let cpu_utilization = hw_measurement_acc.cpu_utilization();
        let result = if request.exact {
            self.exact_facet(
                request.clone(),
                search_runtime_handle,
                timeout,
                hw_measurement_acc,
            )
            .await
        } else {
            self.approx_facet(
                request.clone(),
                search_runtime_handle,
                timeout,
                hw_measurement_acc,
            )
            .await
        };
        let elapsed = start_time.elapsed();
        let cpu_ratio = cpu_utilization.ratio();
        let cpu_usage_ratio = if cpu_ratio > 0.0 {
            Some(cpu_ratio)
        } else {
            None
        };
        log_request_to_collector(&self.collection_name, elapsed, cpu_usage_ratio, || request);
        result.map(|hits| FacetResponse { hits })
    }

    /// Finishes ongoing update tasks
    async fn stop_gracefully(mut self) {
        {
            // Send stop signals to workers
            let mut update_handler = self.update_handler.lock().await;
            update_handler.stop_flush_worker();
            update_handler.stop_update_worker();
        }

        match self.wait_update_workers_stop().await {
            Ok(pending_receiver) => {
                if let Some(receiver) = pending_receiver {
                    // Log number of pending operations that were not processed
                    let pending_count = receiver.len();
                    if pending_count > 0 {
                        log::debug!(
                            "Shard stopped with {pending_count} pending update operations in channel"
                        );
                    }
                }
            }
            Err(err) => {
                log::warn!("Update workers failed with: {err}");
            }
        }

        self.is_gracefully_stopped = true;

        drop(self);
    }
}use std::collections::HashSet;
use std::sync::Arc;

use common::save_on_disk::SaveOnDisk;
use common::tar_ext;
use fs_err::File;
use segment::types::SnapshotFormat;
use shard::fixtures::{build_segment_1, build_segment_2};
use shard::payload_index_schema::PayloadIndexSchema;
use shard::segment_holder::SegmentHolder;
use shard::segment_holder::locked::LockedSegmentHolder;
use tempfile::Builder;

use crate::shards::local_shard::snapshot::snapshot_all_segments;

#[test]
fn test_snapshot_all() {
    let dir = Builder::new().prefix("segment_dir").tempdir().unwrap();
    let segment1 = build_segment_1(dir.path());
    let segment2 = build_segment_2(dir.path());

    let mut holder = SegmentHolder::default();

    let sid1 = holder.add_new(segment1);
    let sid2 = holder.add_new(segment2);
    assert_ne!(sid1, sid2);

    let holder = LockedSegmentHolder::new(holder);

    let before_ids = holder
        .read()
        .iter()
        .map(|(id, _)| id)
        .collect::<HashSet<_>>();

    let segments_dir = Builder::new().prefix("segments_dir").tempdir().unwrap();
    let temp_dir = Builder::new().prefix("temp_dir").tempdir().unwrap();
    let snapshot_file = Builder::new().suffix(".snapshot.tar").tempfile().unwrap();
    let tar = tar_ext::BuilderExt::new_seekable_owned(File::create(snapshot_file.path()).unwrap());

    let payload_schema_file = dir.path().join("payload.schema");
    let schema: Arc<SaveOnDisk<PayloadIndexSchema>> =
        Arc::new(SaveOnDisk::load_or_init_default(payload_schema_file).unwrap());

    snapshot_all_segments(
        holder.clone(),
        segments_dir.path(),
        None,
        schema,
        None,
        temp_dir.path(),
        &tar,
        SnapshotFormat::Regular,
        None,
    )
    .unwrap();

    let after_ids = holder
        .read()
        .iter()
        .map(|(id, _)| id)
        .collect::<HashSet<_>>();

    assert_eq!(
        before_ids, after_ids,
        "segment holder IDs before and after snapshotting must be equal",
    );

    let mut tar = tar::Archive::new(File::open(snapshot_file.path()).unwrap());
    let archive_count = tar.entries_with_seek().unwrap().count();
    // one archive produced per concrete segment in the SegmentHolder
    assert_eq!(archive_count, 2);
}use std::borrow::Cow;
use std::num::NonZeroUsize;
use std::path::{Path, PathBuf};
use std::sync::Arc;

use common::save_on_disk::SaveOnDisk;
use common::tar_ext;
use common::types::PointOffsetType;
use fs_err as fs;
use parking_lot::RwLock;
use segment::common::operation_error::{OperationError, OperationResult};
use segment::data_types::manifest::SegmentManifest;
use segment::entry::StorageSegmentEntry;
use segment::types::{SegmentConfig, SnapshotFormat};
use shard::files::{APPLIED_SEQ_FILE, SEGMENTS_PATH, WAL_PATH};
use shard::locked_segment::LockedSegment;
use shard::operations::OperationWithClockTag;
use shard::payload_index_schema::PayloadIndexSchema;
use shard::segment_holder::SegmentHolder;
use shard::segment_holder::locked::LockedSegmentHolder;
use shard::snapshots::snapshot_manifest::SnapshotManifest;
use shard::snapshots::snapshot_utils::SnapshotUtils;
use shard::wal::SerdeWal;
use tokio::sync::OwnedMutexGuard;
use tokio_util::task::AbortOnDropHandle;
use wal::{Wal, WalOptions};

use crate::operations::types::{CollectionError, CollectionResult};
use crate::shards::local_shard::{LocalShard, LocalShardClocks};

impl LocalShard {
    pub async fn snapshot_manifest(&self) -> CollectionResult<SnapshotManifest> {
        let task = {
            let _runtime = self.search_runtime.tokio_handle().enter();

            let segments = self.segments.clone();
            cancel::blocking::spawn_cancel_on_drop(move |_| segments.read().snapshot_manifest())
        };

        Ok(task.await??)
    }

    pub fn restore_snapshot(snapshot_path: &Path) -> CollectionResult<()> {
        log::info!("Restoring shard snapshot {}", snapshot_path.display());
        SnapshotUtils::restore_unpacked_snapshot(snapshot_path)?;
        Ok(())
    }

    /// Create snapshot for local shard into `target_path`
    pub async fn get_snapshot_creator(
        &self,
        temp_path: &Path,
        tar: &tar_ext::BuilderExt,
        format: SnapshotFormat,
        manifest: Option<SnapshotManifest>,
        save_wal: bool,
    ) -> CollectionResult<impl Future<Output = CollectionResult<()>> + use<>> {
        let segments = self.segments.clone();
        let wal = self.wal.wal.clone();
        let payload_index_schema = self.payload_index_schema.clone();

        let shard_path = self.path.clone();

        let segments_path = Self::segments_path(&self.path);
        let (segment_config, deferred_internal_id) = {
            let collection_config = self.collection_config.read().await;
            (
                collection_config.to_base_segment_config(),
                collection_config.params.get_deferred_point_id(
                    &collection_config.hnsw_config,
                    collection_config
                        .optimizer_config
                        .get_deferred_points_threshold_bytes(),
                ),
            )
        };

        let applied_seq_path = self.applied_seq_handler.path().to_path_buf();

        let tar = tar.clone();
        let temp_path = temp_path.to_path_buf();

        let plunger_notify = if !save_wal {
            // If we are not saving WAL, we still need to make sure that all submitted by this point
            // updates have made it to the segments. So we use the Plunger to achieve that.
            // It will notify us when all submitted updates so far have been processed.
            Some(self.plunge_async().await?)
        } else {
            None
        };

        let future = async move {
            if let Some(plunger_notify) = plunger_notify {
                plunger_notify.await?;
            }

            let handle = tokio::task::spawn_blocking(move || {
                // Do not change segments while snapshotting
                snapshot_all_segments(
                    segments.clone(),
                    &segments_path,
                    Some(segment_config),
                    payload_index_schema,
                    deferred_internal_id,
                    &temp_path,
                    &tar.descend(Path::new(SEGMENTS_PATH))?,
                    format,
                    manifest.as_ref(),
                )?;

                let wal_guard = wal.blocking_lock_owned();

                LocalShardClocks::archive_data(&shard_path, &tar)?;

                // Staging delay
                #[cfg(feature = "staging")]
                {
                    let delay_secs: f64 =
                        std::env::var("QDRANT__STAGING__SNAPSHOT_SHARD_CLOCKS_DELAY")
                            .ok()
                            .and_then(|str| str.parse().ok())
                            .unwrap_or(0.0);

                    if delay_secs > 0.0 {
                        log::debug!("Staging: Delaying snapshotting WAL for {delay_secs}s");
                        std::thread::sleep(std::time::Duration::from_secs_f64(delay_secs));
                        log::debug!("Staging: Delay complete, snapshotting WAL");
                    }
                }

                if save_wal {
                    // snapshot all shard's WAL
                    Self::snapshot_wal(wal_guard, &tar)?;
                    // snapshot applied_seq, it is preferred to save applied_seq later,
                    // as higher applied_seq means more updates will be processed on restore,
                    // which is more safe than having applied_seq too old.
                    Self::snapshot_applied_seq(applied_seq_path, &tar)?;
                } else {
                    Self::snapshot_empty_wal(wal_guard, &temp_path, &tar)?;
                }

                CollectionResult::Ok(())
            });

            AbortOnDropHandle::new(handle).await??;

            Ok(())
        };

        Ok(future)
    }

    /// Create empty WAL which is compatible with currently stored data
    ///
    /// # Panics
    ///
    /// This function panics if called within an asynchronous execution context.
    fn snapshot_empty_wal(
        wal_guard: OwnedMutexGuard<SerdeWal<OperationWithClockTag>>,
        temp_path: &Path,
        tar: &tar_ext::BuilderExt,
    ) -> CollectionResult<()> {
        let wal_segment_capacity = wal_guard.segment_capacity();
        let wal_last_index = wal_guard.last_index();

        // Empty snapshot only need indexes to be correct
        drop(wal_guard);

        let temp_dir = tempfile::tempdir_in(temp_path).map_err(|err| {
            CollectionError::service_error(format!(
                "Can not create temporary directory for WAL: {err}",
            ))
        })?;

        Wal::generate_empty_wal_starting_at_index(
            temp_dir.path(),
            &WalOptions {
                segment_capacity: wal_segment_capacity,
                segment_queue_len: 0,
                retain_closed: NonZeroUsize::new(1).unwrap(),
            },
            wal_last_index,
        )
        .map_err(|err| {
            CollectionError::service_error(format!("Error while create empty WAL: {err}"))
        })?;

        tar.blocking_append_dir_all(temp_dir.path(), Path::new(WAL_PATH))
            .map_err(|err| {
                CollectionError::service_error(format!("Error while archiving WAL: {err}"))
            })
    }

    /// snapshot WAL
    ///
    /// # Panics
    ///
    /// This function panics if called within an asynchronous execution context.
    fn snapshot_wal(
        mut wal_guard: OwnedMutexGuard<SerdeWal<OperationWithClockTag>>,
        tar: &tar_ext::BuilderExt,
    ) -> CollectionResult<()> {
        wal_guard.flush()?;
        let source_wal_path = wal_guard.path();

        let tar = tar.descend(Path::new(WAL_PATH))?;
        for entry in fs::read_dir(source_wal_path).map_err(|err| {
            CollectionError::service_error(format!("Can't read WAL directory: {err}",))
        })? {
            let entry = entry.map_err(|err| {
                CollectionError::service_error(format!("Can't read WAL directory: {err}",))
            })?;

            if entry.file_name() == ".wal" {
                // This sentinel file is used for WAL locking. Trying to archive
                // or open it will cause the following error on Windows:
                // > The process cannot access the file because another process
                // > has locked a portion of the file. (os error 33)
                // https://github.com/qdrant/wal/blob/7c9202d0874/src/lib.rs#L125-L145
                continue;
            }

            tar.blocking_append_file(&entry.path(), Path::new(&entry.file_name()))
                .map_err(|err| {
                    CollectionError::service_error(format!("Error while archiving WAL: {err}"))
                })?;
        }
        Ok(())
    }

    /// snapshot the applied_seq file
    fn snapshot_applied_seq(
        applied_seq_path: PathBuf,
        tar: &tar_ext::BuilderExt,
    ) -> CollectionResult<()> {
        if applied_seq_path.exists() {
            tar.blocking_append_file(applied_seq_path.as_path(), Path::new(APPLIED_SEQ_FILE))
                .map_err(|err| {
                    CollectionError::service_error(format!(
                        "Error while archiving applied_seq: {err}"
                    ))
                })?;
        }
        Ok(())
    }
}

/// Take a snapshot of all segments into `snapshot_dir_path`
///
/// It is recommended to provide collection parameters. This function internally creates a
/// temporary segment, which will source the configuration from it.
///
/// Shortcuts at the first failing segment snapshot.
#[expect(clippy::too_many_arguments)]
pub fn snapshot_all_segments(
    segments: LockedSegmentHolder,
    segments_path: &Path,
    segment_config: Option<SegmentConfig>,
    payload_index_schema: Arc<SaveOnDisk<PayloadIndexSchema>>,
    deferred_internal_id: Option<PointOffsetType>,
    temp_dir: &Path,
    tar: &tar_ext::BuilderExt,
    format: SnapshotFormat,
    manifest: Option<&SnapshotManifest>,
) -> OperationResult<()> {
    // Snapshotting may take long-running read locks on segments blocking incoming writes, do
    // this through proxied segments to allow writes to continue.

    proxy_all_segments_and_apply(
        segments,
        segments_path,
        segment_config,
        payload_index_schema,
        deferred_internal_id,
        |segment| {
            let read_segment = segment.read();
            let request_segment_manifest = if let Some(manifest) = manifest {
                let segment_id = read_segment.segment_id()?;
                Some(
                    manifest
                        .get(&segment_id)
                        .map(Cow::Borrowed)
                        .unwrap_or_else(|| Cow::Owned(SegmentManifest::empty(segment_id))),
                )
            } else {
                None
            };
            let segment_manifest_ref = request_segment_manifest.as_deref();
            read_segment.take_snapshot(temp_dir, tar, format, segment_manifest_ref)?;
            Ok(())
        },
    )
}

/// Temporarily proxify all segments and apply function `f` to it.
///
/// Intended to smoothly accept writes while performing long-running read operations on each
/// segment, such as during snapshotting. It should prevent blocking reads on segments for any
/// significant amount of time.
///
/// This calls function `f` on all segments, but each segment is temporarily proxified while
/// the function is called.
///
/// All segments are proxified at the same time on start. That ensures each wrapped (proxied)
/// segment is kept at the same point in time. Each segment is unproxied one by one, right
/// after function `f` has been applied. That helps keeping proxies as shortlived as possible.
///
/// A read lock is kept during the whole process to prevent external actors from messing with
/// the segment holder while segments are in proxified state. That means no other actors can
/// take a write lock while this operation is running.
///
/// As part of this process, a new segment is created. All proxies direct their writes to this
/// segment. The segment is added to the collection if it has any operations, otherwise it is
/// deleted when all segments are unproxied again.
///
/// It is recommended to provide collection parameters. The segment configuration will be
/// sourced from it.
///
/// Before snapshotting all segments are forcefully flushed to ensure all data is persisted.
pub fn proxy_all_segments_and_apply<F>(
    segments: LockedSegmentHolder,
    segments_path: &Path,
    segment_config: Option<SegmentConfig>,
    payload_index_schema: Arc<SaveOnDisk<PayloadIndexSchema>>,
    deferred_internal_id: Option<PointOffsetType>,
    mut operation: F,
) -> OperationResult<()>
where
    F: FnMut(&RwLock<dyn StorageSegmentEntry>) -> OperationResult<()>,
{
    let segments_lock = segments.upgradable_read();

    // Proxy all segments
    // Proxied segments are sorted by flush ordering
    log::trace!("Proxying all shard segments to apply function");
    let (mut proxies, tmp_segment_id, mut segments_lock) = SegmentHolder::proxy_all_segments(
        segments_lock,
        segments_path,
        segment_config,
        payload_index_schema,
        deferred_internal_id,
    )?;

    // Flush all pending changes of each segment, now wrapped segments won't change anymore
    segments_lock.flush_all(true, true)?;

    // Apply provided function
    log::trace!("Applying function on all proxied shard segments");
    let mut result = Ok(());
    let mut unproxied_segment_ids = Vec::with_capacity(proxies.len());

    // Proxied segments are sorted by flush ordering, important because the operation we apply
    // might explicitly flush segments
    for (segment_id, proxy_segment) in &proxies {
        // Get segment to snapshot
        let op_result = match proxy_segment {
            LockedSegment::Proxy(proxy_segment) => {
                let wrapped_segment = proxy_segment.read().wrapped_segment.clone();
                let segment = wrapped_segment.get();
                operation(segment)
            }
            // All segments to snapshot should be proxy, warn if this is not the case
            LockedSegment::Original(segment) => {
                debug_assert!(
                    false,
                    "Reached non-proxy segment while applying function to proxies, this should not happen, ignoring",
                );
                // Call provided function on segment
                operation(segment.as_ref())
            }
        };

        if let Err(err) = op_result {
            result = Err(OperationError::service_error(format!(
                "Applying function to a proxied shard segment {segment_id} failed: {err}"
            )));
            break;
        }

        // Try to unproxy/release this segment since we don't use it anymore
        // Unproxying now lets us release the segment earlier, prevent unnecessary writes to the temporary segment.
        // Make sure to keep at least one proxy segment to maintain access to the points in the shared write segment.
        // The last proxy and the shared write segment will be promoted into the segment_holder atomically
        // by `Self::unproxy_all_segments` afterwards to maintain the read consistency.
        let remaining = proxies.len() - unproxied_segment_ids.len();
        if remaining > 1 {
            match SegmentHolder::try_unproxy_segment(
                segments_lock,
                *segment_id,
                proxy_segment.clone(),
                segments.acquire_updates_lock(),
            ) {
                Ok(lock) => {
                    segments_lock = lock;
                    unproxied_segment_ids.push(*segment_id);
                }
                Err(lock) => segments_lock = lock,
            }
        }
    }
    proxies.retain(|(id, _)| !unproxied_segment_ids.contains(id));

    // Unproxy all segments
    // Always do this to prevent leaving proxy segments behind
    log::trace!("Unproxying all shard segments after function is applied");
    SegmentHolder::unproxy_all_segments(
        segments_lock,
        proxies,
        tmp_segment_id,
        segments.acquire_updates_lock(),
    )?;

    result
}use std::collections::HashMap;
use std::sync::atomic::Ordering;
use std::time::Duration;

use common::types::{DetailsLevel, TelemetryDetail};
use segment::common::operation_time_statistics::OperationDurationStatistics;
use segment::types::SizeStats;
use segment::vector_storage::common::get_async_scorer;
use shard::common::stopping_guard::StoppingGuard;
use tokio_util::task::AbortOnDropHandle;

use crate::operations::types::{CollectionError, CollectionResult, OptimizersStatus};
use crate::shards::local_shard::{LocalShard, indexed_only};
use crate::shards::telemetry::{LocalShardTelemetry, OptimizerTelemetry};

impl LocalShard {
    pub async fn get_telemetry_data(
        &self,
        detail: TelemetryDetail,
        timeout: Duration,
    ) -> CollectionResult<LocalShardTelemetry> {
        let start = std::time::Instant::now();
        let segments = self.segments.clone();
        let segments_data = if detail.level < DetailsLevel::Level4 {
            Ok((vec![], HashMap::default()))
        } else {
            let locked_collection_config = self.collection_config.clone();
            let is_stopped_guard = StoppingGuard::new();
            let is_stopped = is_stopped_guard.get_is_stopped();
            let handle = tokio::task::spawn_blocking(move || {
                // blocking sync lock
                let segments: Vec<_> = {
                    let Some(holder_guard) = segments.try_read_for(timeout) else {
                        return Err(CollectionError::timeout(timeout, "shard telemetry"));
                    };
                    holder_guard
                        .iter()
                        .map(|(_id, segment)| segment.clone())
                        .collect()
                };

                let mut segments_telemetry = Vec::with_capacity(segments.len());
                for segment in segments.iter() {
                    if is_stopped.load(Ordering::Relaxed) {
                        return Ok((vec![], HashMap::default()));
                    }

                    // blocking sync lock
                    let Some(segment_guard) = segment.get().try_read_for(timeout) else {
                        return Err(CollectionError::timeout(timeout, "shard telemetry"));
                    };

                    segments_telemetry.push(segment_guard.get_telemetry_data(detail))
                }

                let collection_config = locked_collection_config.blocking_read();
                let indexed_only_excluded_vectors =
                    indexed_only::get_index_only_excluded_vectors(&segments, &collection_config);

                Ok((segments_telemetry, indexed_only_excluded_vectors))
            });
            AbortOnDropHandle::new(handle).await?
        };

        let (segments, index_only_excluded_vectors) = segments_data?;
        let total_optimized_points = self.total_optimized_points.load(Ordering::Relaxed);

        let optimizations: OperationDurationStatistics = self
            .optimizers
            .load()
            .iter()
            .map(|optimizer| {
                optimizer
                    .get_telemetry_counter()
                    .lock()
                    .get_statistics(detail)
            })
            .fold(Default::default(), |total, stats| total + stats);

        let status = self
            .get_optimization_status(timeout.saturating_sub(start.elapsed()))
            .await?;
        let SizeStats {
            num_vectors,
            num_vectors_by_name,
            vectors_size_bytes,
            payloads_size_bytes,
            num_points,
        } = self
            .get_size_stats(timeout.saturating_sub(start.elapsed()))
            .await?;

        Ok(LocalShardTelemetry {
            variant_name: None,
            status: None,
            total_optimized_points,
            vectors_size_bytes: Some(vectors_size_bytes),
            payloads_size_bytes: Some(payloads_size_bytes),
            num_points: Some(num_points),
            num_vectors: Some(num_vectors),
            num_vectors_by_name: Some(HashMap::from(num_vectors_by_name)),
            segments: if segments.is_empty() {
                None
            } else {
                Some(segments)
            },
            optimizations: Some(OptimizerTelemetry {
                status,
                optimizations,
                log: (detail.level >= DetailsLevel::Level4)
                    .then(|| self.optimizers_log.lock().to_telemetry()),
            }),
            async_scorer: Some(get_async_scorer()),
            indexed_only_excluded_vectors: (!index_only_excluded_vectors.is_empty())
                .then_some(index_only_excluded_vectors),
            update_queue: Some(self.local_update_queue_info().await),
        })
    }

    pub async fn get_optimization_status(
        &self,
        timeout: Duration,
    ) -> CollectionResult<OptimizersStatus> {
        let segments = self.segments.clone();

        let status = tokio::task::spawn_blocking(move || {
            // blocking sync lock
            let Some(segments) = segments.try_read_for(timeout) else {
                return Err(CollectionError::timeout(timeout, "optimization status"));
            };

            match &segments.optimizer_errors {
                None => Ok(OptimizersStatus::Ok),
                Some(err) => Ok(OptimizersStatus::Error(err.clone())),
            }
        });
        AbortOnDropHandle::new(status).await?
    }

    pub async fn get_size_stats(&self, timeout: Duration) -> CollectionResult<SizeStats> {
        let segments = self.segments.clone();

        let stats = tokio::task::spawn_blocking(move || {
            // blocking sync lock
            let Some(segments) = segments.try_read_for(timeout) else {
                return Err(CollectionError::timeout(timeout, "get size stats"));
            };

            let SizeStats {
                mut num_points,
                mut num_vectors,
                mut num_vectors_by_name,
                mut vectors_size_bytes,
                mut payloads_size_bytes,
            } = SizeStats::default();

            for (_, segment) in segments.iter() {
                let info = segment.get().read().info();
                num_points += info.num_points;
                num_vectors += info.num_vectors;
                vectors_size_bytes += info.vectors_size_bytes;
                payloads_size_bytes += info.payloads_size_bytes;

                for (vector_name, vector_data) in info.vector_data.iter() {
                    *num_vectors_by_name.get_or_insert_default(vector_name) +=
                        vector_data.num_vectors;
                }
            }

            Ok(SizeStats {
                num_vectors,
                num_vectors_by_name,
                vectors_size_bytes,
                payloads_size_bytes,
                num_points,
            })
        });
        AbortOnDropHandle::new(stats).await?
    }
}use segment::id_tracker::IdTracker;

use crate::shards::local_shard::LocalShard;

impl LocalShard {
    // Testing helper: performs partial flush of the segments
    pub fn partial_flush(&self) {
        let segments = self.segments.read();

        for (_segment_id, segment) in segments.iter_original() {
            let segment = segment.read();
            segment.id_tracker.borrow().mapping_flusher()().unwrap();
        }
    }

    pub fn full_flush(&self) {
        let segments = self.segments.read();
        segments.flush_all(true, true).unwrap();
    }
}use std::sync::Arc;

use tokio::sync::mpsc::{self, Receiver};

use crate::operations::types::CollectionResult;
use crate::optimizers_builder::build_optimizers;
use crate::shards::local_shard::LocalShard;
use crate::update_handler::UpdateSignal;

impl LocalShard {
    pub fn trigger_optimizers(&self) {
        // Send a trigger signal and ignore errors because all error cases are acceptable:
        // - If receiver is already dead - we do not care
        // - If channel is full - optimization will be triggered by some other signal
        let _ = self.update_sender.load().try_send(UpdateSignal::Nop);
    }

    /// Stops flush worker only.
    /// This is useful for testing purposes to prevent background flushes.
    #[cfg(feature = "testing")]
    pub async fn stop_flush_worker(&self) {
        let mut update_handler = self.update_handler.lock().await;
        update_handler.stop_flush_worker()
    }

    pub async fn wait_update_workers_stop(
        &self,
    ) -> CollectionResult<Option<Receiver<UpdateSignal>>> {
        let mut update_handler = self.update_handler.lock().await;
        update_handler.wait_workers_stops().await
    }

    /// Handles updates to the optimizer configuration by rebuilding optimizers
    /// and restarting the update handler's workers with the new configuration.
    ///
    /// On failure, the error is recorded as an optimizer error on this shard, so it is exposed in
    /// the collection's optimizer status. This matters especially for background recreation, where
    /// the error would otherwise only be logged with no caller left to propagate it to.
    ///
    /// ## Cancel safety
    ///
    /// This function is **not** cancel safe.
    pub async fn on_optimizer_config_update(&self) -> CollectionResult<()> {
        let result = self.on_optimizer_config_update_impl().await;

        // Surface a failed recreation as an optimizer error, so it shows up in the optimizer status
        // instead of being silently lost on the background recreation path.
        if let Err(err) = &result {
            self.segments
                .write()
                .report_optimizer_error(format!("Failed to recreate optimizers: {err}"));
        }

        result
    }

    async fn on_optimizer_config_update_impl(&self) -> CollectionResult<()> {
        let mut update_handler = self.update_handler.lock().await;

        // Signal all workers to stop
        update_handler.stop_flush_worker();
        update_handler.stop_update_worker();

        // Wait for workers to finish and get pending operations from the old channel.
        //
        // This can take a long time, because in-flight optimizations are awaited before they stop.
        // We deliberately do not hold the `collection_config` read lock across this wait, so a
        // concurrent collection config update is not blocked on acquiring the config write lock.
        let update_receiver = update_handler.wait_workers_stops().await?;

        let update_receiver = match update_receiver {
            Some(receiver) => receiver,
            None => {
                // Receiver is destroyed, create a new channel.
                // It's not expected to happen in normal operation,
                // Because it means that there were no update workers running.
                // Just in case, we create a new channel to avoid panics in update handler.
                debug_assert!(
                    false,
                    "Update receiver was None during optimizer config update"
                );
                let (update_sender, update_receiver) =
                    mpsc::channel(self.shared_storage_config.update_queue_size);
                let _old_sender = self.update_sender.swap(Arc::new(update_sender));
                update_receiver
            }
        };

        // Read the latest config now that the workers have stopped, and build new optimizers from
        // it. Reading it here (rather than before the wait) also ensures we pick up the most recent
        // config if it changed again while we were waiting.
        let config = self.collection_config.read().await;

        let new_optimizers = build_optimizers(
            &self.path,
            &config.params,
            &config.optimizer_config,
            &config.hnsw_config,
            &self.shared_storage_config.hnsw_global_config,
            &config.quantization_config,
        );

        update_handler.optimizers = new_optimizers.clone();
        update_handler.flush_interval_sec = config.optimizer_config.flush_interval_sec;
        update_handler.max_optimization_threads = config.optimizer_config.max_optimization_threads;
        update_handler.prevent_unoptimized = config
            .optimizer_config
            .prevent_unoptimized
            .unwrap_or_default();

        drop(config);

        update_handler.run_workers(update_receiver);

        self.optimizers.store(new_optimizers);

        self.segments.write().optimizer_errors = None;

        self.update_sender.load().send(UpdateSignal::Nop).await?;

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use std::sync::Arc;

    use common::budget::ResourceBudget;
    use common::save_on_disk::SaveOnDisk;
    use tempfile::Builder;
    use tokio::runtime::Handle;
    use tokio::sync::RwLock;

    use super::LocalShard;
    use crate::common::adaptive_handle::AdaptiveSearchHandle;
    use crate::shards::shard_trait::ShardOperation;
    use crate::tests::fixtures::create_collection_config;

    #[tokio::test(flavor = "multi_thread")]
    async fn optimizer_config_update_refreshes_prevent_unoptimized_flag() {
        let collection_dir = Builder::new().prefix("test_collection").tempdir().unwrap();
        let payload_index_schema_dir = Builder::new().prefix("qdrant-test").tempdir().unwrap();
        let payload_index_schema_file = payload_index_schema_dir.path().join("payload-schema.json");
        let payload_index_schema =
            Arc::new(SaveOnDisk::load_or_init_default(payload_index_schema_file).unwrap());

        let mut config = create_collection_config();
        config.optimizer_config.prevent_unoptimized = Some(false);

        let update_runtime = Handle::current();
        let search_runtime = AdaptiveSearchHandle::current_for_tests();
        let shard = LocalShard::build(
            0,
            "test".to_string(),
            collection_dir.path(),
            Arc::new(RwLock::new(config.clone())),
            Arc::new(Default::default()),
            payload_index_schema,
            update_runtime.clone(),
            search_runtime.clone(),
            ResourceBudget::default(),
            config.optimizer_config.clone(),
        )
        .await
        .unwrap();

        assert!(!shard.update_handler.lock().await.prevent_unoptimized);

        {
            let mut shard_config = shard.collection_config.write().await;
            shard_config.optimizer_config.prevent_unoptimized = Some(true);
        }

        shard.on_optimizer_config_update().await.unwrap();

        assert!(shard.update_handler.lock().await.prevent_unoptimized);

        {
            let mut shard_config = shard.collection_config.write().await;
            shard_config.optimizer_config.prevent_unoptimized = Some(false);
        }

        shard.on_optimizer_config_update().await.unwrap();

        assert!(!shard.update_handler.lock().await.prevent_unoptimized);

        shard.stop_gracefully().await;
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn optimizer_config_update_clears_optimizer_errors() {
        let collection_dir = Builder::new().prefix("test_collection").tempdir().unwrap();
        let payload_index_schema_dir = Builder::new().prefix("qdrant-test").tempdir().unwrap();
        let payload_index_schema_file = payload_index_schema_dir.path().join("payload-schema.json");
        let payload_index_schema =
            Arc::new(SaveOnDisk::load_or_init_default(payload_index_schema_file).unwrap());

        let config = create_collection_config();

        let update_runtime = Handle::current();
        let search_runtime = AdaptiveSearchHandle::current_for_tests();
        let shard = LocalShard::build(
            0,
            "test".to_string(),
            collection_dir.path(),
            Arc::new(RwLock::new(config.clone())),
            Arc::new(Default::default()),
            payload_index_schema,
            update_runtime.clone(),
            search_runtime.clone(),
            ResourceBudget::default(),
            config.optimizer_config.clone(),
        )
        .await
        .unwrap();

        assert!(shard.segments.read().optimizer_errors.is_none());

        shard
            .segments
            .write()
            .report_optimizer_error("test optimizer error");
        assert!(shard.segments.read().optimizer_errors.is_some());

        shard.on_optimizer_config_update().await.unwrap();

        assert!(
            shard.segments.read().optimizer_errors.is_none(),
            "optimizer errors should be cleared after config update"
        );

        shard.stop_gracefully().await;
    }
}use std::sync::Arc;

use tokio::sync::{Mutex, mpsc};

use crate::operations::types::CollectionResult;
use crate::shards::local_shard::LocalShard;
use crate::update_handler::UpdateSignal;

impl LocalShard {
    /// WAL is keeping more data, even if truncated.
    /// Useful if we expect to read old WAL records soon.
    pub async fn set_extended_wal_retention(&self) {
        self.wal.set_extended_retention().await;
    }

    /// WAL is keeping normal amount of data after truncation.
    pub async fn set_normal_wal_retention(&self) {
        self.wal.set_normal_retention().await;
    }

    /// Truncate unapplied WAL records.
    /// Returns amount of removed records.
    pub async fn truncate_unapplied_wal(&self) -> CollectionResult<usize> {
        // First, lock the `update_lock` to prevent new updates while dropping WAL.
        let _update_lock = self.update_lock.write().await;
        let mut update_handler = self.update_handler.lock().await;

        // Create new channel - new operations will go to the new channel
        let (update_sender, update_receiver) =
            mpsc::channel(self.shared_storage_config.update_queue_size);
        let _old_sender = self.update_sender.swap(Arc::new(update_sender));

        // Signal all workers to stop
        update_handler.stop_flush_worker();
        update_handler.stop_update_worker();

        // Wait for workers to finish and get pending operations from the old channel
        let pending_receiver = update_handler.wait_workers_stops().await?;

        // Find first pending operation's op_num - this is where we truncate from
        let truncate_from_op_num = pending_receiver.and_then(|mut receiver| {
            std::iter::from_fn(|| receiver.try_recv().ok()).find_map(|signal| match signal {
                UpdateSignal::Operation(op_data) => Some(op_data.op_num),
                UpdateSignal::Nop | UpdateSignal::Plunger(_) => None,
            })
        });

        // Lock WAL and perform truncation
        let mut wal_lock = Mutex::lock_owned(self.wal.wal.clone()).await;
        let last_wal_op_num = wal_lock.last_index();

        let truncation_result: CollectionResult<usize> =
            if let Some(truncate_from_op_num) = truncate_from_op_num {
                debug_assert!(truncate_from_op_num <= last_wal_op_num);

                wal_lock.drop_from(truncate_from_op_num)?;
                wal_lock.flush()?;

                // To calculate removed records, add 1 because both are inclusive
                Ok((last_wal_op_num + 1 - truncate_from_op_num) as usize)
            } else {
                Ok(0)
            };

        // Release WAL lock before restarting workers
        drop(wal_lock);

        // Restart workers with new channel (pending operations are intentionally not forwarded)
        update_handler.run_workers(update_receiver);

        // Trigger optimizers
        let _ = self.update_sender.load().try_send(UpdateSignal::Nop);

        truncation_result
    }
}use std::sync::Arc;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};

/// We want to have limited amount of clocks, because all the clocks we create during
/// qdrant operations are preserved for the entire live-span of the cluster.
///
/// Limiting number of clocks essentially means that we are limiting number of parallel
/// update operations which can happen on the cluster, but this number should be high enough
/// for all reasonable use cases.
const DEFAULT_MAX_CLOCKS: usize = 64;

#[derive(Clone, Debug)]
pub struct ClockSet {
    clocks: Vec<Arc<Clock>>,
    max_clocks: usize,
}

impl Default for ClockSet {
    fn default() -> Self {
        Self::new()
    }
}

impl ClockSet {
    pub fn new() -> Self {
        Self::with_max_clocks(DEFAULT_MAX_CLOCKS)
    }

    pub fn with_max_clocks(max_clocks: usize) -> Self {
        Self {
            clocks: Vec::new(),
            max_clocks,
        }
    }

    /// Get the first available clock from the set, or create a new one.
    pub fn get_clock(&mut self) -> Option<ClockGuard> {
        for (id, clock) in self.clocks.iter().enumerate() {
            if clock.try_lock() {
                return Some(ClockGuard::new(id as u32, clock.clone()));
            }
        }

        let id = self.clocks.len();
        if id >= self.max_clocks {
            return None;
        }

        let clock = Arc::new(Clock::new_locked());

        self.clocks.push(clock.clone());

        Some(ClockGuard::new(id as u32, clock))
    }
}

#[derive(Debug)]
#[must_use = "dropping this guard immediately marks the clock as inactive"]
pub struct ClockGuard {
    id: u32,
    clock: Arc<Clock>,
}

impl ClockGuard {
    fn new(id: u32, clock: Arc<Clock>) -> Self {
        Self { id, clock }
    }

    pub fn id(&self) -> u32 {
        self.id
    }

    /// Return current clock tick.
    pub fn current_tick(&self) -> Option<u64> {
        self.clock.current_tick()
    }

    /// Advance clock by a single tick and return current tick.
    #[must_use = "new clock value must be used"]
    pub fn tick_once(&mut self) -> u64 {
        self.clock.tick_once()
    }

    /// Advance clock to `new_tick`, if `new_tick` is newer than current tick.
    pub fn advance_to(&mut self, new_tick: u64) {
        self.clock.advance_to(new_tick)
    }
}

impl Drop for ClockGuard {
    fn drop(&mut self) {
        self.clock.release();
    }
}

#[derive(Debug)]
struct Clock {
    /// Tracks the *next* clock tick
    next_tick: AtomicU64,
    available: AtomicBool,
}

impl Clock {
    fn new_locked() -> Self {
        Self {
            next_tick: 0.into(),
            available: false.into(),
        }
    }

    /// Return current clock tick.
    fn current_tick(&self) -> Option<u64> {
        let next_tick = self.next_tick.load(Ordering::Relaxed);
        next_tick.checked_sub(1)
    }

    /// Advance clock by a single tick and return current tick.
    ///
    /// # Thread safety
    ///
    /// Clock *has to* be locked (using [`Clock::try_lock`]) before calling [`Clock::tick_once`]!
    #[must_use = "new clock tick value must be used"]
    fn tick_once(&self) -> u64 {
        // `Clock` tracks *next* tick, so we increment `next_tick` by 1 and return *previous* value
        // of `next_tick` (which is *exactly* what `fetch_add(1)` does)
        let current_tick = self.next_tick.fetch_add(1, Ordering::Relaxed);

        // If `current_tick` is `0`, then "revert" `next_tick` back to `0`.
        // We expect that `advance_to` would be used to advance "past" the initial `0`.
        //
        // Executing multiple atomic operations sequentially is not strictly thread-safe,
        // but we expect that `Clock` would be "locked" before calling `tick_once`.
        if current_tick == 0 {
            self.next_tick.store(0, Ordering::Relaxed);
        }

        current_tick
    }

    /// Advance clock to `new_tick`, if `new_tick` is newer than current tick.
    fn advance_to(&self, new_tick: u64) {
        // `Clock` tracks *next* tick, so if we want to advance *current* tick to `new_tick`,
        // we have to advance `next_tick` to `new_tick + 1`
        self.next_tick.fetch_max(new_tick + 1, Ordering::Relaxed);
    }

    /// Try to acquire exclusive lock over this clock.
    ///
    /// Returns `true` if the lock was successfully acquired, or `false` if the clock is already
    /// locked.
    fn try_lock(&self) -> bool {
        self.available.swap(false, Ordering::Relaxed)
    }

    /// Release the exclusive lock over this clock.
    ///
    /// No-op if the clock is not locked.
    fn release(&self) {
        self.available.store(true, Ordering::Relaxed);
    }
}

#[cfg(test)]
mod tests {
    use std::iter;

    use rand::prelude::*;

    use super::*;

    /// Tick a single clock, it should increment after we advance it from 0 (or higher).
    #[test]
    fn test_clock_set_single_tick() {
        let mut clock_set = ClockSet::new();

        // Don't tick from 0 unless we explicitly advance
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 0);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 0);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 0);

        clock_set.get_clock().unwrap().advance_to(0);

        // Following ticks should increment
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 1);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 2);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 3);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 4);
    }

    /// Test a single clock, but tick it multiple times on the same guard.
    #[test]
    fn test_clock_set_single_tick_twice() {
        let mut clock_set = ClockSet::new();

        // Don't tick from 0 unless we explicitly advance
        {
            let mut clock = clock_set.get_clock().unwrap();
            assert_eq!(clock.tick_once(), 0);
            assert_eq!(clock.tick_once(), 0);
            clock.advance_to(0);
        }

        // Following ticks should increment
        {
            let mut clock = clock_set.get_clock().unwrap();
            assert_eq!(clock.tick_once(), 1);
            assert_eq!(clock.tick_once(), 2);
            assert_eq!(clock.tick_once(), 3);
            assert_eq!(clock.tick_once(), 4);
        }
    }

    /// Advance a clock to a higher number, which should increase it.
    #[test]
    fn test_clock_set_single_advance_high() {
        let mut clock_set = ClockSet::new();

        // Bring the clock up to 4
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 0);
        clock_set.get_clock().unwrap().advance_to(0);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 1);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 2);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 3);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 4);

        // If we advance to 100, we should continue from 101
        clock_set.get_clock().unwrap().advance_to(100);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 101);
    }

    /// Advance a clock to a lower number, which should not do anything.
    #[test]
    fn test_clock_set_single_advance_low() {
        let mut clock_set = ClockSet::new();

        // Bring the clock up to 4
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 0);
        clock_set.get_clock().unwrap().advance_to(0);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 1);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 2);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 3);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 4);

        // If we advance to a low number, just continue
        clock_set.get_clock().unwrap().advance_to(0);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 5);

        clock_set.get_clock().unwrap().advance_to(1);
        assert_eq!(clock_set.get_clock().unwrap().tick_once(), 6);
    }

    /// Test multiple clocks in various configurations.
    #[test]
    fn test_clock_multi_tick() {
        let mut clock_set = ClockSet::new();

        // 2 parallel operations, that fails and doesn't advance
        {
            let mut clock1 = clock_set.get_clock().unwrap();
            let mut clock2 = clock_set.get_clock().unwrap();
            assert_eq!(clock1.tick_once(), 0);
            assert_eq!(clock2.tick_once(), 0);
        }

        // 2 parallel operations
        {
            let mut clock1 = clock_set.get_clock().unwrap();
            let mut clock2 = clock_set.get_clock().unwrap();
            assert_eq!(clock1.tick_once(), 0);
            assert_eq!(clock2.tick_once(), 0);
            clock1.advance_to(0);
            clock2.advance_to(0);
        }

        // 1 operation
        {
            let mut clock1 = clock_set.get_clock().unwrap();
            assert_eq!(clock1.tick_once(), 1);
            clock1.advance_to(1);
        }

        // 1 operation, without advancing should still tick
        {
            let mut clock1 = clock_set.get_clock().unwrap();
            assert_eq!(clock1.tick_once(), 2);
        }

        // 2 parallel operations
        {
            let mut clock1 = clock_set.get_clock().unwrap();
            let mut clock2 = clock_set.get_clock().unwrap();
            assert_eq!(clock1.tick_once(), 3);
            assert_eq!(clock2.tick_once(), 1);
            clock1.advance_to(3);
            clock2.advance_to(1);
        }

        // 3 parallel operations, but clock 2 was much newer on some node
        {
            let mut clock1 = clock_set.get_clock().unwrap();
            let mut clock2 = clock_set.get_clock().unwrap();
            let mut clock3 = clock_set.get_clock().unwrap();
            assert_eq!(clock1.tick_once(), 4);
            assert_eq!(clock2.tick_once(), 2);
            assert_eq!(clock3.tick_once(), 0);
            clock1.advance_to(4);
            clock2.advance_to(10);
            clock3.advance_to(0);
        }

        // 3 parallel operations, advancing in a different order should not matter
        {
            let mut clock1 = clock_set.get_clock().unwrap();
            let mut clock2 = clock_set.get_clock().unwrap();
            let mut clock3 = clock_set.get_clock().unwrap();
            assert_eq!(clock1.tick_once(), 5);
            assert_eq!(clock2.tick_once(), 11);
            assert_eq!(clock3.tick_once(), 1);
            clock3.advance_to(1);
            clock2.advance_to(11);
            clock1.advance_to(5);
        }

        // 3 parallel operations, advancing just some should still tick all
        {
            let mut clock1 = clock_set.get_clock().unwrap();
            let mut clock2 = clock_set.get_clock().unwrap();
            let mut clock3 = clock_set.get_clock().unwrap();
            assert_eq!(clock1.tick_once(), 6);
            assert_eq!(clock2.tick_once(), 12);
            assert_eq!(clock3.tick_once(), 2);
            clock2.advance_to(12);
        }

        // 1 operation
        {
            let mut clock1 = clock_set.get_clock().unwrap();
            assert_eq!(clock1.tick_once(), 7);
        }

        // Test final state of all clocks
        {
            let mut clock1 = clock_set.get_clock().unwrap();
            let mut clock2 = clock_set.get_clock().unwrap();
            let mut clock3 = clock_set.get_clock().unwrap();
            let mut clock4 = clock_set.get_clock().unwrap();
            assert_eq!(clock1.tick_once(), 8);
            assert_eq!(clock2.tick_once(), 13);
            assert_eq!(clock3.tick_once(), 3);
            assert_eq!(clock4.tick_once(), 0);
        }
    }

    /// Test a number of parallel operations with some running for a long time. Clocks are resolved
    /// unordered.
    #[test]
    fn test_clock_set_long_running_unordered() {
        let mut clock_set = ClockSet::new();

        // Clock 1 runs for a long while
        let mut clock1 = clock_set.get_clock().unwrap();
        assert_eq!(clock1.tick_once(), 0);

        // 2 quick parallel operations
        {
            let mut clock2 = clock_set.get_clock().unwrap();
            let mut clock3 = clock_set.get_clock().unwrap();
            assert_eq!(clock2.tick_once(), 0);
            assert_eq!(clock3.tick_once(), 0);
            clock2.advance_to(0);
            clock3.advance_to(0);
        }

        // Clock 2 runs for a long while
        let clock2 = clock_set.get_clock().unwrap();
        assert_eq!(clock1.tick_once(), 0);

        // 2 quick parallel operations
        {
            let mut clock3 = clock_set.get_clock().unwrap();
            let mut clock4 = clock_set.get_clock().unwrap();
            assert_eq!(clock3.tick_once(), 1);
            assert_eq!(clock4.tick_once(), 0);
            clock4.advance_to(0);
        }

        // Clock 1 finally resolves
        clock1.advance_to(0);
        drop(clock1);

        // 3 quick parallel operations
        {
            let mut clock1 = clock_set.get_clock().unwrap();
            let mut clock3 = clock_set.get_clock().unwrap();
            let mut clock4 = clock_set.get_clock().unwrap();
            assert_eq!(clock1.tick_once(), 1);
            assert_eq!(clock3.tick_once(), 2);
            assert_eq!(clock4.tick_once(), 1);
        }

        // Clock 2 finally resolves
        drop(clock2);

        // Test final state of all clocks
        {
            let mut clock1 = clock_set.get_clock().unwrap();
            let mut clock2 = clock_set.get_clock().unwrap();
            let mut clock3 = clock_set.get_clock().unwrap();
            let mut clock4 = clock_set.get_clock().unwrap();
            let mut clock5 = clock_set.get_clock().unwrap();
            assert_eq!(clock1.tick_once(), 2);
            assert_eq!(clock2.tick_once(), 1);
            assert_eq!(clock3.tick_once(), 3);
            assert_eq!(clock4.tick_once(), 2);
            assert_eq!(clock5.tick_once(), 0);
        }
    }

    /// Test and increment a lot of clocks, but at some point 10% of the clocks gets stuck.
    #[test]
    fn test_clock_set_many() {
        const N: usize = 5000;

        let mut clock_set = ClockSet::with_max_clocks(N);

        // Tick all clocks past 0
        {
            let mut clocks = iter::repeat_with(|| clock_set.get_clock().unwrap())
                .take(N)
                .collect::<Vec<_>>();
            clocks.shuffle(&mut rand::rng());

            for clock in &mut clocks {
                assert_eq!(clock.tick_once(), 0);
                clock.advance_to(0);
            }
        }

        // Tick all clocks 10 times
        {
            for tick in 0..10 {
                let mut clocks = iter::repeat_with(|| clock_set.get_clock().unwrap())
                    .take(N)
                    .collect::<Vec<_>>();
                clocks.shuffle(&mut rand::rng());

                for clock in &mut clocks {
                    assert_eq!(clock.tick_once(), 1 + tick);
                }
            }
        }

        // Now the first 10% gets stuck
        let mut stuck_clocks = iter::repeat_with(|| clock_set.get_clock().unwrap())
            .take(N / 10)
            .collect::<Vec<_>>();
        for clock in stuck_clocks.iter_mut() {
            assert_eq!(clock.tick_once(), 11);
        }

        // Tick all other clocks 10 times
        {
            for tick in 0..10 {
                let mut clocks = iter::repeat_with(|| clock_set.get_clock().unwrap())
                    .take(N - (N / 10))
                    .collect::<Vec<_>>();
                clocks.shuffle(&mut rand::rng());

                for clock in clocks.iter_mut() {
                    assert_eq!(clock.tick_once(), 11 + tick);
                }
            }
        }

        // All stuck clocks resolve
        drop(stuck_clocks);

        // Test all clocks
        {
            let mut stuck_clocks = iter::repeat_with(|| clock_set.get_clock().unwrap())
                .take(N / 10)
                .collect::<Vec<_>>();
            let mut clocks = iter::repeat_with(|| clock_set.get_clock().unwrap())
                .take(N - (N / 10))
                .collect::<Vec<_>>();

            for clock in stuck_clocks.iter_mut() {
                assert_eq!(clock.tick_once(), 12);
            }
            for clock in clocks.iter_mut() {
                assert_eq!(clock.tick_once(), 21);
            }
        }
    }

    /// Test and increment a lot of clocks, but each iteration, we get on more clock stuck.
    #[test]
    fn test_clock_set_many_staggered_stuck() {
        const N: usize = 500;

        let mut clock_set = ClockSet::with_max_clocks(N);

        let mut stuck_clocks = Vec::new();

        for i in 0..N {
            let mut clock_to_stuck = clock_set.get_clock().unwrap();
            let mut clocks = iter::repeat_with(|| clock_set.get_clock().unwrap())
                .take(N - i - 1)
                .collect::<Vec<_>>();

            if clock_to_stuck.tick_once() == 0 {
                clock_to_stuck.advance_to(0);
            }

            for clock in clocks.iter_mut() {
                if clock.tick_once() == 0 {
                    clock.advance_to(0);
                }
            }

            stuck_clocks.push(clock_to_stuck);
        }

        // All stuck clocks resolve now
        drop(stuck_clocks);

        // Test all clocks
        {
            let mut clocks = iter::repeat_with(|| clock_set.get_clock().unwrap())
                .take(N)
                .enumerate()
                .collect::<Vec<_>>();

            for (i, clock) in clocks.iter_mut() {
                assert_eq!(clock.tick_once(), *i as u64 + 1);
            }
        }
    }
}use std::cmp;
use std::fmt::Write as _;
use std::ops::Deref as _;

use futures::future::{self, BoxFuture};
use futures::stream::FuturesUnordered;
use futures::{FutureExt as _, StreamExt as _};
use rand::seq::SliceRandom as _;

use super::ShardReplicaSet;
use crate::operations::consistency_params::{ReadConsistency, ReadConsistencyType};
use crate::operations::types::{CollectionError, CollectionResult};
use crate::shards::remote_shard::RemoteShard;
use crate::shards::resolve::{Resolve, ResolveCondition};
use crate::shards::shard_trait::ShardOperation;

impl ShardReplicaSet {
    /// Execute read op. on replica set:
    /// 1 - Prefer local replica
    /// 2 - Otherwise uses `read_fan_out_ratio` to compute list of active remote shards.
    /// 3 - Falls back to all remaining shards if the optimization fails.
    /// It does not report failing peer_ids to the consensus.
    pub async fn execute_read_operation<Res, F>(
        &self,
        read_operation: F,
        local_only: bool,
    ) -> CollectionResult<Res>
    where
        F: Fn(&(dyn ShardOperation + Send + Sync)) -> BoxFuture<'_, CollectionResult<Res>>,
    {
        if local_only {
            return self.execute_local_read_operation(read_operation).await;
        }

        let mut responses = self
            .execute_cluster_read_operation(read_operation, 1, None)
            .await?;

        Ok(responses.pop().unwrap())
    }

    pub async fn execute_and_resolve_read_operation<Res, F>(
        &self,
        read_operation: F,
        read_consistency: Option<ReadConsistency>,
        local_only: bool,
    ) -> CollectionResult<Res>
    where
        F: Fn(&(dyn ShardOperation + Send + Sync)) -> BoxFuture<'_, CollectionResult<Res>>,
        Res: Resolve,
    {
        if local_only {
            return self.execute_local_read_operation(read_operation).await;
        }

        let read_consistency = read_consistency.unwrap_or_default();

        let local_count = usize::from(self.peer_state(self.this_peer_id()).is_some());
        let active_local_count = usize::from(self.peer_is_readable(self.this_peer_id()));
        let initializing_local_count = usize::from(self.peer_is_initializing(self.this_peer_id()));

        let remotes = self.remotes.read().await;

        let remotes_count = remotes.len();

        // TODO(resharding): Handle resharded shard?
        let active_remotes_count = remotes
            .iter()
            .filter(|remote| self.peer_is_readable(remote.peer_id))
            .count();
        let initializing_remotes_count = remotes
            .iter()
            .filter(|remote| self.peer_is_initializing(remote.peer_id))
            .count();

        let total_count = local_count + remotes_count;
        let active_count = active_local_count + active_remotes_count;
        let initializing_count = initializing_local_count + initializing_remotes_count;

        let (mut required_successful_results, condition) = match read_consistency {
            ReadConsistency::Type(ReadConsistencyType::All) => (total_count, ResolveCondition::All),

            ReadConsistency::Type(ReadConsistencyType::Majority) => {
                (total_count, ResolveCondition::Majority)
            }

            ReadConsistency::Type(ReadConsistencyType::Quorum) => {
                (total_count / 2 + 1, ResolveCondition::All)
            }

            ReadConsistency::Factor(factor) => {
                (factor.clamp(1, total_count), ResolveCondition::All)
            }
        };

        if active_count + initializing_count < required_successful_results {
            return Err(CollectionError::service_error(format!(
                "The replica set for shard {} on peer {} does not have enough active replicas",
                self.shard_id,
                self.this_peer_id(),
            )));
        }

        if active_count < required_successful_results {
            required_successful_results = cmp::max(
                required_successful_results.saturating_sub(initializing_count),
                active_count,
            );
        }

        let mut responses = self
            .execute_cluster_read_operation(
                read_operation,
                required_successful_results,
                Some(remotes),
            )
            .await?;

        if responses.is_empty() {
            Ok(Res::default())
        } else if responses.len() == 1 {
            Ok(responses.pop().unwrap())
        } else {
            Ok(Res::resolve(responses, condition))
        }
    }

    async fn execute_local_read_operation<Res, F>(&self, read_operation: F) -> CollectionResult<Res>
    where
        F: Fn(&(dyn ShardOperation + Send + Sync)) -> BoxFuture<'_, CollectionResult<Res>>,
    {
        let _partial_snapshot_search_lock =
            self.partial_snapshot_meta.try_take_search_read_lock()?;

        let local = self.local.read().await;

        let Some(local) = local.deref() else {
            return Err(CollectionError::service_error(format!(
                "Local shard {} not found",
                self.shard_id
            )));
        };

        read_operation(local.get()).await
    }

    async fn execute_cluster_read_operation<Res, F>(
        &self,
        read_operation: F,
        required_successful_results: usize,
        remotes: Option<tokio::sync::RwLockReadGuard<'_, Vec<RemoteShard>>>,
    ) -> CollectionResult<Vec<Res>>
    where
        F: Fn(&(dyn ShardOperation + Send + Sync)) -> BoxFuture<'_, CollectionResult<Res>>,
    {
        let remotes = match remotes {
            Some(remotes) => remotes,
            None => self.remotes.read().await,
        };

        // We don't need to explicitly check partial snapshot recovery lock, because
        // - partial snapshot recovery *write-locks* `local` shard when applying partial snapshot
        // - this method *tries* to read-lock `local` shard, and if it's unavailable, fan-out
        //   request to other replicas

        let local_read = self.local.try_read().ok();
        let local_read = local_read.as_ref().and_then(|local| local.as_ref());

        let (local, is_local_ready, update_watcher) = match local_read {
            Some(local) => {
                let update_watcher = local.watch_for_update();
                let is_local_ready = !local.is_update_in_progress();

                (Some(local), is_local_ready, Some(update_watcher))
            }

            None => (None, false, None),
        };

        let local_is_readable = self.peer_is_readable(self.this_peer_id());

        let local_operation = if local_is_readable {
            let local_operation = async {
                let Some(local) = local else {
                    return Err(CollectionError::service_error(format!(
                        "Local shard {} not found",
                        self.shard_id,
                    )));
                };

                read_operation(local.get()).await
            };

            Some(local_operation.map(|result| (result, true)).left_future())
        } else {
            None
        };

        // TODO(resharding): Handle resharded shard?
        let mut readable_remotes: Vec<_> = remotes
            .iter()
            .filter(|remote| self.peer_is_readable(remote.peer_id))
            .collect();

        readable_remotes.shuffle(&mut rand::rng());

        let remote_operations = readable_remotes.into_iter().map(|remote| {
            read_operation(remote)
                .map(|result| (result, false))
                .right_future()
        });

        let mut operations = local_operation.into_iter().chain(remote_operations);

        // Possible scenarios:
        //
        // - Local is available: default fan-out is 0 (no fan-out, unless explicitly requested)
        // - Local is not available: default fan-out is 1
        // - There is no local: default fan-out is 1

        let default_fan_out = if is_local_ready && local_is_readable {
            0
        } else {
            1
        };

        let (read_fan_out_factor, fan_out_delay) = {
            let guard = self.collection_config.read().await;
            let params = &guard.params;

            let read_fan_out_factor =
                params.read_fan_out_factor.unwrap_or(default_fan_out) as usize;
            let read_fan_out_delay = params.read_fan_out_delay_ms.and_then(|delay| {
                if delay == 0 {
                    None
                } else {
                    Some(tokio::time::Duration::from_millis(delay))
                }
            });
            (read_fan_out_factor, read_fan_out_delay)
        };

        let initial_concurrent_operations = required_successful_results + read_fan_out_factor;

        let mut pending_operations: FuturesUnordered<_> = operations
            .by_ref()
            .take(initial_concurrent_operations)
            .collect();

        let mut responses = Vec::new();
        let mut errors = Vec::new();

        let mut is_local_operation_resolved = false;

        let update_watcher = async move {
            match update_watcher {
                Some(update_watcher) => update_watcher.await,
                None => future::pending().await,
            }
        };

        let update_watcher = update_watcher.fuse();

        tokio::pin!(update_watcher);

        let fan_out_delay_sleep = async move {
            match fan_out_delay {
                Some(delay) => tokio::time::sleep(delay).await,
                None => future::pending().await,
            }
        };

        let fan_out_delay_sleep = fan_out_delay_sleep.fuse();

        tokio::pin!(fan_out_delay_sleep);

        let mut is_fan_out_delay_resolved = false;

        loop {
            let result;

            tokio::select! {
                operation_result = pending_operations.next() => {
                    let Some(operation_result) = operation_result else {
                        break;
                    };

                    let (operation_result, is_local_operation) = operation_result;

                    result = operation_result;

                    if is_local_operation {
                        is_local_operation_resolved = true;
                    }
                }

                _ = &mut update_watcher, if local_is_readable && !is_local_operation_resolved => {
                    pending_operations.extend(operations.next());
                    continue;
                }

                _ = &mut fan_out_delay_sleep, if !is_fan_out_delay_resolved => {
                    is_fan_out_delay_resolved = true;
                    pending_operations.extend(operations.next());
                    continue;
                }
            }

            match result {
                Ok(response) => {
                    responses.push(response);

                    if responses.len() >= required_successful_results {
                        break;
                    }
                }

                Err(error) => {
                    if error.is_transient() {
                        log::debug!("Read operation failed: {error}");
                        errors.push(error);
                    } else {
                        return Err(error);
                    }

                    pending_operations.extend(operations.next());

                    if responses.len() + pending_operations.len() < required_successful_results {
                        break;
                    }
                }
            }
        }

        if responses.len() >= required_successful_results {
            Ok(responses)
        } else {
            let errors_count = errors.len();
            let operations_count = responses.len() + errors.len();
            let errors_separator = if !errors.is_empty() { ":" } else { "" };

            let mut message = format!(
                "{errors_count} of {operations_count} read operations failed{errors_separator}"
            );

            for error in errors {
                write!(&mut message, "\n  {error}").expect("writing into String always succeeds");
            }

            Err(CollectionError::service_error(message))
        }
    }
}use std::cmp;
use std::collections::HashMap;
use std::time::{Duration, Instant};

use crate::shards::replica_set::replica_set_state::ReplicaState;
use crate::shards::shard::PeerId;

#[derive(Clone, Debug, Default)]
pub struct Registry {
    /// List of disabled peer IDs and a backoff to prevent spamming consensus.
    ///
    /// Each peer optionally specifies what state it was in when it was disabled. They're send
    /// along with the consensus proposal and prevents accidentally killing replicas if the current
    /// peer is slow to catch up with consensus.
    /// See: <https://github.com/qdrant/qdrant/pull/5343>
    locally_disabled_peers: HashMap<PeerId, (Backoff, Option<ReplicaState>)>,
}

impl Registry {
    pub fn is_disabled(&self, peer_id: PeerId) -> bool {
        self.locally_disabled_peers.contains_key(&peer_id)
    }

    pub fn is_all_disabled(&self, peer_ids: impl IntoIterator<Item = PeerId>) -> bool {
        peer_ids
            .into_iter()
            .all(|peer_id| self.is_disabled(peer_id))
    }

    pub fn disable_peer(&mut self, peer_id: PeerId) {
        self.locally_disabled_peers.entry(peer_id).or_default();
    }

    pub fn disable_peer_and_notify_if_elapsed(
        &mut self,
        peer_id: PeerId,
        from_state: Option<ReplicaState>,
    ) -> bool {
        let (backoff, _from_state) = self
            .locally_disabled_peers
            .entry(peer_id)
            // Update from state if changed on already disabled peers
            .and_modify(|(_backoff, value_from_state)| {
                *value_from_state = from_state;
            })
            .or_insert_with(|| (Backoff::default(), from_state));
        backoff.retry_if_elapsed()
    }

    pub fn enable_peer(&mut self, peer_id: PeerId) {
        let _ = self.locally_disabled_peers.remove(&peer_id);
    }

    pub fn clear(&mut self) {
        self.locally_disabled_peers.clear();
    }

    pub fn notify_elapsed(&mut self) -> impl Iterator<Item = (PeerId, Option<ReplicaState>)> + '_ {
        self.locally_disabled_peers
            .iter_mut()
            .filter_map(|(&peer_id, (backoff, from_state))| {
                backoff.retry_if_elapsed().then_some((peer_id, *from_state))
            })
    }
}

#[derive(Copy, Clone, Debug)]
struct Backoff {
    last_attempt: Instant,
    delay: Duration,
}

impl Default for Backoff {
    fn default() -> Self {
        Self {
            last_attempt: Instant::now(),
            delay: Duration::ZERO,
        }
    }
}

impl Backoff {
    const MAX_DELAY: Duration = Duration::from_secs(10);

    pub fn retry_if_elapsed(&mut self) -> bool {
        let is_elapsed = self.is_elapsed();

        if is_elapsed {
            self.retry();
        }

        is_elapsed
    }

    fn is_elapsed(&self) -> bool {
        self.last_attempt.elapsed() >= self.delay
    }

    fn retry(&mut self) {
        self.last_attempt = Instant::now();

        self.delay = if self.delay.is_zero() {
            Duration::from_secs(1)
        } else {
            cmp::min(self.delay * 2, Self::MAX_DELAY)
        }
    }
