/// Service version, starting from which `ManualRecovery` state is supported.
pub static MANUAL_RECOVERY_SHARD_STATE_VERSION: LazyLock<Version> =
    LazyLock::new(|| Version::parse("1.16.4-dev").expect("valid version string"));

/// Represents a replica set state
#[derive(Debug, Deserialize, Serialize, Default, PartialEq, Eq, Clone)]
pub struct ReplicaSetState {
    pub is_local: bool,
    pub this_peer_id: PeerId,
    peers: HashMap<PeerId, ReplicaState>,
}

impl ReplicaSetState {
    pub fn get_peer_state(&self, peer_id: PeerId) -> Option<ReplicaState> {
        self.peers.get(&peer_id).copied()
    }

    /// Returns previous state if any
    pub fn set_peer_state(&mut self, peer_id: PeerId, state: ReplicaState) -> Option<ReplicaState> {
        self.peers.insert(peer_id, state)
    }

    pub fn remove_peer_state(&mut self, peer_id: PeerId) -> Option<ReplicaState> {
        self.peers.remove(&peer_id)
    }

    pub fn peers(&self) -> &HashMap<PeerId, ReplicaState> {
        &self.peers
    }

    pub fn check_peers_state_all<F>(&self, check: F) -> bool
    where
        F: Fn(ReplicaState) -> bool,
    {
        self.peers.values().all(|state| check(*state))
    }

    pub fn active_peers(&self) -> Vec<PeerId> {
        self.peers
            .iter()
            .filter_map(|(peer_id, state)| {
                // We consider `ReshardingScaleDown` to be `Active`!
                state.is_active().then_some(*peer_id)
            })
            .collect()
    }

    pub fn readable_peers(&self) -> Vec<PeerId> {
        self.peers
            .iter()
            .filter_map(|(peer_id, state)| state.is_readable().then_some(*peer_id))
            .collect()
    }

    pub fn active_or_resharding_peers(&self) -> impl Iterator<Item = PeerId> + '_ {
        self.peers.iter().filter_map(|(peer_id, state)| {
            matches!(
                state,
                ReplicaState::Active | ReplicaState::Resharding | ReplicaState::ReshardingScaleDown
            )
            .then_some(*peer_id)
        })
    }

    pub fn set_peers(&mut self, peers: HashMap<PeerId, ReplicaState>) {
        self.peers = peers;
    }

    /// Change current `this_peer_id` to a new one.
    pub fn switch_peer_id(&mut self, new_peer_id: PeerId) {
        let old_peer_id = self.this_peer_id;
        self.this_peer_id = new_peer_id;

        self.peers
            .remove(&old_peer_id)
            .and_then(|replica_state| self.peers.insert(new_peer_id, replica_state));
    }

    /// Remove all remote peers from the replica set state and activate local peer.
    pub fn force_local_active(&mut self) {
        self.peers.clear();
        self.peers.insert(self.this_peer_id, ReplicaState::Active);
    }
}

/// State of the single shard within a replica set.
#[derive(
    Debug, Deserialize, Serialize, JsonSchema, Default, PartialEq, Eq, Hash, Clone, Copy, Anonymize,
)]
pub enum ReplicaState {
    // Active and sound
    #[default]
    Active,
    // Failed for some reason
    Dead,
    // The shard is partially loaded and is currently receiving data from other shards
    Partial,
    // Collection is being created
    Initializing,
    // A shard which receives data, but is not used for search
    // Useful for backup shards
    Listener,
    // Deprecated since Qdrant 1.9.0, used in Qdrant 1.7.0 and 1.8.0
    //
    // Snapshot shard transfer is in progress, updates aren't sent to the shard
    // Normally rejects updates. Since 1.8 it allows updates if force is true.
    PartialSnapshot,
    // Shard is undergoing recovery by an external node
    // Normally rejects updates, accepts updates if force is true
    Recovery,
    // Points are being migrated to this shard as part of resharding up
    Resharding,
    // Points are being migrated to this shard as part of resharding down
    ReshardingScaleDown,
    // Active for readers, Partial for writers
    ActiveRead,
    // State for manually creation/recovery of a shard.
    // Usually when snapshot is uploaded.
    // This state is equivalent to `Partial`, except:
    // - it can't receive updates
    // - it is not treated as broken on startup
    ManualRecovery,
}

impl ReplicaState {
    /// Check if replica state is active
    /// Used to define if this replica can be used as a source of truth.
    pub fn is_active(self) -> bool {
        match self {
            ReplicaState::Active => true,
            ReplicaState::ReshardingScaleDown => true,

            ReplicaState::Dead
            | ReplicaState::Partial
            | ReplicaState::ManualRecovery
            | ReplicaState::Initializing
            | ReplicaState::Listener
            | ReplicaState::PartialSnapshot
            | ReplicaState::Recovery
            | ReplicaState::Resharding
            | ReplicaState::ActiveRead => false,
        }
    }

    /// Check that replica has full dataset, so it can be used for read operations.
    pub fn is_readable(self) -> bool {
        match self {
            ReplicaState::Active => true,
            ReplicaState::ReshardingScaleDown => true,
            ReplicaState::ActiveRead => true,
            // False from here on
            ReplicaState::Dead => false,
            ReplicaState::Partial => false,
            ReplicaState::ManualRecovery => false,
            ReplicaState::Initializing => false,
            ReplicaState::Listener => false,
            ReplicaState::PartialSnapshot => false,
            ReplicaState::Recovery => false,
            ReplicaState::Resharding => false,
        }
    }

    pub fn is_updatable(self) -> bool {
        match self {
            ReplicaState::Active => true,
            ReplicaState::Partial => true,
            ReplicaState::Initializing => true,
            ReplicaState::Listener => true,
            ReplicaState::Recovery | ReplicaState::PartialSnapshot => false,
            ReplicaState::Resharding | ReplicaState::ReshardingScaleDown => true,
            ReplicaState::Dead => false,
            ReplicaState::ActiveRead => true,
            ReplicaState::ManualRecovery => false,
        }
    }

    /// Check if this peer can be used as a source of truth within a shard_id.
    /// For instance:
    /// - It can be the only receiver of updates
    /// - It can be a primary replica for ordered writes
    pub fn can_be_source_of_truth(self) -> bool {
        match self {
            ReplicaState::Active => true,
            ReplicaState::ActiveRead => true, // Can be only one replica per shard_id
            ReplicaState::Resharding => true, // Can be only one replica per shard_id
            ReplicaState::ReshardingScaleDown => true, // Acts like Active, until resharding is committed
            // false from here on
            ReplicaState::Partial => false,
            ReplicaState::ManualRecovery => false,
            ReplicaState::Initializing => false,
            ReplicaState::Listener => false,
            ReplicaState::PartialSnapshot => false,
            ReplicaState::Recovery => false,
            ReplicaState::Dead => false,
        }
    }

    /// Check whether the replica state is active or listener or resharding.
    /// Healthy state means that replica does not require **automatic** recovery.
    pub fn is_healthy(self) -> bool {
        match self {
            ReplicaState::Active
            | ReplicaState::Listener
            | ReplicaState::Resharding
            | ReplicaState::ManualRecovery
            | ReplicaState::ReshardingScaleDown => true,

            ReplicaState::Dead
            | ReplicaState::Initializing
            | ReplicaState::Partial
            | ReplicaState::PartialSnapshot
            | ReplicaState::Recovery
            | ReplicaState::ActiveRead => false,
        }
    }

    /// Check if the replica state requires automatic recovery to be scheduled.
    pub fn requires_recovery(self) -> bool {
        match self {
            ReplicaState::Dead => true,
            ReplicaState::Active
            | ReplicaState::Partial
            | ReplicaState::Initializing
            | ReplicaState::Listener
            | ReplicaState::PartialSnapshot
            | ReplicaState::Recovery
            | ReplicaState::ManualRecovery
            | ReplicaState::Resharding
            | ReplicaState::ReshardingScaleDown
            | ReplicaState::ActiveRead => false,
        }
    }

    /// Check whether the replica state is partial or partial-like.
    ///
    /// In other words: is the state related to shard transfers?
    //
    // TODO(resharding): What's the best way to handle `ReshardingScaleDown` properly!?
    pub fn is_partial_or_recovery(self) -> bool {
        match self {
            ReplicaState::Partial
            | ReplicaState::ManualRecovery
            | ReplicaState::PartialSnapshot
            | ReplicaState::Recovery
            | ReplicaState::Resharding
            | ReplicaState::ReshardingScaleDown
            | ReplicaState::ActiveRead => true,

            ReplicaState::Active
            | ReplicaState::Dead
            | ReplicaState::Initializing
            | ReplicaState::Listener => false,
        }
    }

    /// Returns `true` if the replica state is resharding, either up or down.
    pub fn is_resharding(&self) -> bool {
        match self {
            ReplicaState::Resharding | ReplicaState::ReshardingScaleDown => true,

            ReplicaState::Partial
            | ReplicaState::ManualRecovery
            | ReplicaState::PartialSnapshot
            | ReplicaState::Recovery
            | ReplicaState::Active
            | ReplicaState::Dead
            | ReplicaState::Initializing
            | ReplicaState::Listener
            | ReplicaState::ActiveRead => false,
        }
    }

    pub fn is_listener(self) -> bool {
        match self {
            ReplicaState::Listener => true,
            ReplicaState::Active
            | ReplicaState::Dead
            | ReplicaState::Partial
            | ReplicaState::Initializing
            | ReplicaState::PartialSnapshot
            | ReplicaState::Recovery
            | ReplicaState::Resharding
            | ReplicaState::ReshardingScaleDown
            | ReplicaState::ActiveRead
            | ReplicaState::ManualRecovery => false,
        }
    }

    /// Does write rate limiting applicable for this state?
    /// E.g. during resharding we expect more internal ops, so
    /// we can't write rate limit the shard.
    pub fn is_write_rate_limitable(self) -> bool {
        match self {
            ReplicaState::Active => true,
            ReplicaState::Dead
            | ReplicaState::Partial
            | ReplicaState::Initializing
            | ReplicaState::Listener
            | ReplicaState::PartialSnapshot
            | ReplicaState::Recovery
            | ReplicaState::Resharding
            | ReplicaState::ReshardingScaleDown
            | ReplicaState::ActiveRead
            | ReplicaState::ManualRecovery => false,
        }
    }
}use std::ops::Deref as _;
use std::sync::Arc;

use parking_lot::Mutex;
use segment::types::{Filter, PointIdType};

use super::ShardReplicaSet;
use crate::hash_ring::HashRingRouter;
use crate::operations::types::{CollectionError, CollectionResult};
use crate::shards::forward_proxy_shard::{ForwardProxyShard, PreparedTransferBatch};
use crate::shards::local_shard::clock_map::RecoveryPoint;
use crate::shards::queue_proxy_shard::QueueProxyShard;
use crate::shards::remote_shard::RemoteShard;
use crate::shards::shard::Shard;
use crate::shards::transfer::transfer_tasks_pool::TransferTaskProgress;

impl ShardReplicaSet {
    /// Convert `Local` shard into `ForwardProxy`.
    ///
    /// # Cancel safety
    ///
    /// This method is cancel safe.
    pub async fn proxify_local(
        &self,
        remote_shard: RemoteShard,
        resharding_hash_ring: Option<HashRingRouter>,
        filter: Option<Filter>,
    ) -> CollectionResult<()> {
        let mut local = self.local.write().await;

        match local.deref() {
            // Expected state, continue
            Some(Shard::Local(_)) => {}

            // If a forward proxy to same remote, return early
            Some(Shard::ForwardProxy(proxy))
                if proxy.remote_shard.peer_id == remote_shard.peer_id =>
            {
                return Ok(());
            }

            // Unexpected states, error
            Some(Shard::ForwardProxy(proxy)) => {
                return Err(CollectionError::service_error(format!(
                    "Cannot proxify local shard {} to peer {} because it is already proxified to peer {}",
                    self.shard_id, remote_shard.peer_id, proxy.remote_shard.peer_id
                )));
            }
            Some(Shard::QueueProxy(_)) => {
                return Err(CollectionError::service_error(format!(
                    "Cannot proxify local shard {} to peer {} because it is already queue proxified",
                    self.shard_id, remote_shard.peer_id,
                )));
            }
            Some(Shard::Proxy(_)) => {
                return Err(CollectionError::service_error(format!(
                    "Cannot queue proxify local shard {} to peer {} because it already is a proxy",
                    self.shard_id, remote_shard.peer_id,
                )));
            }
            Some(Shard::Dummy(_)) => {
                return Err(CollectionError::service_error(format!(
                    "Cannot proxify local dummy shard {} to peer {}",
                    self.shard_id, remote_shard.peer_id,
                )));
            }
            None => {
                return Err(CollectionError::service_error(format!(
                    "Cannot proxify local shard {} on peer {} because it is not active",
                    self.shard_id,
                    self.this_peer_id()
                )));
            }
        };

        // Explicit `match` instead of `if-let` to catch `unreachable` condition if top `match` is
        // changed
        let Some(Shard::Local(local_shard)) = local.take() else {
            unreachable!()
        };

        let proxy_shard_res = ForwardProxyShard::new(
            self.shard_id,
            local_shard,
            remote_shard,
            resharding_hash_ring,
            filter,
        );

        match proxy_shard_res {
            Ok(proxy_shard) => {
                let _ = local.insert(Shard::ForwardProxy(proxy_shard));
                Ok(())
            }
            Err((err, local_shard)) => {
                log::warn!("Failed to proxify shard, reverting to local shard: {err}");
                let _ = local.insert(Shard::Local(local_shard));
                Err(err)
            }
        }
    }

    /// Queue proxy our local shard, pointing to the remote shard.
    ///
    /// A `from_version` may be provided to start queueing the WAL from a specific version. The
    /// point may be in the past, but can never be outside the range of what we currently have in
    /// WAL. If `None` is provided, it'll queue from the latest available WAL version at this time.
    ///
    /// For snapshot transfer we queue from the latest version, so we can send all new updates once
    /// the remote shard has been recovered. For WAL delta transfer we queue from a specific
    /// version based on our recovery point.
    ///
    /// # Cancel safety
    ///
    /// This method is cancel safe.
    pub async fn queue_proxify_local(
        &self,
        remote_shard: RemoteShard,
        from_version: Option<u64>,
        progress: Arc<Mutex<TransferTaskProgress>>,
    ) -> CollectionResult<()> {
        let mut local = self.local.write().await;

        match local.deref() {
            // Expected state, continue
            Some(Shard::Local(_)) => {}

            // If a forward proxy to same remote, continue and change into queue proxy
            Some(Shard::ForwardProxy(proxy))
                if proxy.remote_shard.peer_id == remote_shard.peer_id => {}

            // Unexpected states, error
            Some(Shard::QueueProxy(_)) => {
                return Err(CollectionError::service_error(format!(
                    "Cannot queue proxify local shard {} to peer {} because it is already queue proxified",
                    self.shard_id, remote_shard.peer_id,
                )));
            }
            Some(Shard::ForwardProxy(proxy)) => {
                return Err(CollectionError::service_error(format!(
                    "Cannot queue proxify local shard {} to peer {} because it is already proxified to peer {}",
                    self.shard_id, remote_shard.peer_id, proxy.remote_shard.peer_id
                )));
            }
            Some(Shard::Proxy(_)) => {
                return Err(CollectionError::service_error(format!(
                    "Cannot queue proxify local shard {} to peer {} because it already is a proxy",
                    self.shard_id, remote_shard.peer_id,
                )));
            }
            Some(Shard::Dummy(_)) => {
                return Err(CollectionError::service_error(format!(
                    "Cannot proxify local dummy shard {} to peer {}",
                    self.shard_id, remote_shard.peer_id,
                )));
            }
            None => {
                return Err(CollectionError::service_error(format!(
                    "Cannot queue proxify local shard {} on peer {} because it is not active",
                    self.shard_id,
                    self.this_peer_id()
                )));
            }
        };

        // Get `max_ack_version` without "taking" local shard (to maintain cancel safety)
        let local_shard = match local.deref() {
            Some(Shard::Local(local)) => local,
            Some(Shard::ForwardProxy(proxy)) => &proxy.wrapped_shard,
            _ => unreachable!(),
        };

        let wal_keep_from = local_shard
            .update_handler
            .lock()
            .await
            .wal_keep_from
            .clone();

        // Proxify local shard
        //
        // Making `await` calls between `local.take()` and `local.insert(...)` is *not* cancel safe!
        let local_shard = match local.take() {
            Some(Shard::Local(local)) => local,
            Some(Shard::ForwardProxy(proxy)) => proxy.wrapped_shard,
            _ => unreachable!(),
        };

        // Try to queue proxify with or without version
        let proxy_shard = match from_version {
            None => {
                Ok(QueueProxyShard::new(local_shard, remote_shard, wal_keep_from, progress).await)
            }
            Some(from_version) => {
                QueueProxyShard::new_from_version(
                    local_shard,
                    remote_shard,
                    wal_keep_from,
                    from_version,
                    progress,
                )
                .await
            }
        };

        // Insert queue proxy shard on success or revert to local shard on failure
        match proxy_shard {
            // All good, insert queue proxy shard
            Ok(proxy_shard) => {
                let _ = local.insert(Shard::QueueProxy(proxy_shard));
                Ok(())
            }
            Err((local_shard, err)) => {
                log::warn!("Failed to queue proxify shard, reverting to local shard: {err}");
                let _ = local.insert(Shard::Local(local_shard));
                Err(err)
            }
        }
    }

    /// Un-proxify local shard wrapped as `ForwardProxy` or `QueueProxy`.
    ///
    /// # Cancel safety
    ///
    /// This method is cancel safe.
    pub async fn un_proxify_local(&self) -> CollectionResult<()> {
        let mut local = self.local.write().await;

        match local.deref() {
            // Expected states, continue
            Some(Shard::Local(_)) => return Ok(()),
            Some(Shard::ForwardProxy(_) | Shard::QueueProxy(_)) => {}

            // Unexpected states, error
            Some(shard @ (Shard::Proxy(_) | Shard::Dummy(_))) => {
                return Err(CollectionError::service_error(format!(
                    "Cannot un-proxify local shard {} because it has unexpected type - {}",
                    self.shard_id,
                    shard.variant_name(),
                )));
            }

            None => {
                return Err(CollectionError::service_error(format!(
                    "Cannot un-proxify local shard {} on peer {} because it is not active",
                    self.shard_id,
                    self.this_peer_id(),
                )));
            }
        };

        // Perform async finalization without "taking" local shard (to maintain cancel safety)
        //
        // Explicit `match` instead of `if-let` on `Shard::QueueProxy` to catch `unreachable`
        // condition if top `match` is changed
        let result = match local.deref() {
            Some(Shard::ForwardProxy(_)) => Ok(()),

            Some(Shard::QueueProxy(proxy)) => {
                // We should not unproxify a queue proxy shard directly because it can fail if it
                // fails to send all updates to the remote shard.
                // Instead we should transform it into a forward proxy shard before unproxify is
                // called to handle errors at an earlier time.
                // Also, we're holding a write lock here which could block other accessors for a
                // long time if transferring updates takes a long time.
                // See `Self::queue_proxy_into_forward_proxy()` for more details.

                log::warn!(
                    "Directly unproxifying queue proxy shard, this should not happen normally"
                );

                let result = proxy.transfer_all_missed_updates().await;

                if let Err(err) = &result {
                    log::error!(
                        "Failed to un-proxify local shard because transferring remaining queue \
                         items to remote failed: {err}"
                    );
                }

                result
            }

            _ => unreachable!(),
        };

        // Un-proxify local shard
        //
        // Making `await` calls between `local.take()` and `local.insert(...)` is *not* cancel safe!
        let local_shard = match local.take() {
            Some(Shard::ForwardProxy(proxy)) => proxy.wrapped_shard,

            Some(Shard::QueueProxy(proxy)) => {
                let (local_shard, _) = proxy.forget_updates_and_finalize();
                local_shard
            }

            _ => unreachable!(),
        };

        let _ = local.insert(Shard::Local(local_shard));

        result
    }

    /// Revert usage of a `QueueProxy` shard and forget all updates, then un-proxify to local
    ///
    /// This can be used to intentionally forget all updates that are collected by the queue proxy
    /// shard and revert back to a local shard. This is useful if a shard transfer operation using
    /// a queue proxy must be aborted.
    ///
    /// Does nothing if the local shard is not a queue proxy shard.
    /// This method cannot fail.
    ///
    /// # Warning
    ///
    /// This intentionally forgets and drops updates pending to be transferred to the remote shard.
    /// The remote shard may therefore therefore be left in an inconsistent state, which should be
    /// resolved separately.
    ///
    /// # Cancel safety
    ///
    /// This method is cancel safe.
    ///
    /// If cancelled - the queue proxy may not be reverted to a local proxy.
    pub async fn revert_queue_proxy_local(&self) {
        let mut local = self.local.write().await;

        // Take out queue proxy shard or return
        if !matches!(local.deref(), Some(Shard::QueueProxy(_))) {
            return;
        };

        log::debug!("Forgetting queue proxy updates and reverting to local shard");

        // Making `await` calls between `local.take()` and `local.insert(...)` is *not* cancel safe!
        let Some(Shard::QueueProxy(queue_proxy)) = local.take() else {
            unreachable!();
        };

        let (local_shard, _) = queue_proxy.forget_updates_and_finalize();
        let _ = local.insert(Shard::Local(local_shard));
    }

    /// Read a transfer batch without sending it yet.
    ///
    /// Returns a [`PreparedTransferBatch`] that holds the update lock. The caller can then drop
    /// other locks (e.g. the shard holder lock) before calling [`PreparedTransferBatch::send`].
    ///
    /// # Cancel safety
    ///
    /// This method is cancel safe.
    pub async fn read_transfer_batch(
        &self,
        offset: Option<PointIdType>,
        batch_size: usize,
        hashring_filter: Option<&HashRingRouter>,
        merge_points: bool,
    ) -> CollectionResult<PreparedTransferBatch> {
        let local = self.local.read().await;

        let Some(Shard::ForwardProxy(proxy)) = local.deref() else {
            return Err(CollectionError::service_error(format!(
                "Cannot transfer batch from shard {} because it is not proxified",
                self.shard_id
            )));
        };

        proxy
            .read_transfer_batch(
                offset,
                batch_size,
                hashring_filter,
                merge_points,
                &self.search_runtime,
            )
            .await
    }

    /// Custom operation for transferring indexes from one shard to another during transfer
    ///
    /// # Cancel safety
    ///
    /// This method is cancel safe.
    pub async fn transfer_indexes(&self) -> CollectionResult<()> {
        let local = self.local.read().await;

        let Some(Shard::ForwardProxy(proxy)) = local.deref() else {
            return Err(CollectionError::service_error(format!(
                "Cannot transfer indexes from shard {} because it is not proxified",
                self.shard_id,
            )));
        };

        log::trace!(
            "Transferring indexes to shard {}",
            proxy.remote_shard.peer_id,
        );

        proxy.transfer_indexes().await
    }

    /// Send all queue proxy updates to remote
    ///
    /// This method allows to transfer queued updates at any point, before the shard is
    /// unproxified for example. This allows for proper error handling at the time this method is
    /// called. Because the shard is transformed into a forward proxy after this operation it will
    /// not error again when the shard is eventually unproxified again.
    ///
    /// Does nothing if the local shard is not a queue proxy.
    ///
    /// # Errors
    ///
    /// Returns an error if transferring all updates to the remote failed.
    ///
    /// # Cancel safety
    ///
    /// This function is cancel safe.
    ///
    /// If cancelled - transforming the queue proxy into a forward proxy may not actually complete.
    /// None, some or all queued operations may be transmitted to the remote.
    pub async fn queue_proxy_flush(&self) -> CollectionResult<()> {
        let local = self.local.read().await;

        let Some(Shard::QueueProxy(proxy)) = local.deref() else {
            return Ok(());
        };

        proxy.transfer_all_missed_updates().await?;

        Ok(())
    }

    /// Send all queue proxy updates to remote and transform into forward proxy
    ///
    /// When a queue or forward proxy shard needs to be unproxified into a local shard again we
    /// typically don't have room to handle errors. A queue proxy shard may error if it fails to
    /// send updates to the remote shard, while a forward proxy does not fail at all when
    /// transforming.
    ///
    /// This method allows to transfer queued updates before the shard is unproxified. This allows
    /// for proper error handling at the time this method is called. Because the shard is
    /// transformed into a forward proxy after this operation it will not error again when the
    /// shard is eventually unproxified again.
    ///
    /// If the local shard is a queue proxy:
    /// - Transfers all missed updates to remote
    /// - Transforms queue proxy into forward proxy
    ///
    /// Does nothing if the local shard is not a queue proxy.
    ///
    /// # Errors
    ///
    /// Returns an error if transferring all updates to the remote failed.
    ///
    /// # Cancel safety
    ///
    /// This function is cancel safe.
    ///
    /// If cancelled - transforming the queue proxy into a forward proxy may not actually complete.
    /// None, some or all queued operations may be transmitted to the remote.
    pub async fn queue_proxy_into_forward_proxy(&self) -> CollectionResult<()> {
        // First pass: transfer all missed updates with shared read lock
        self.queue_proxy_flush().await?;

        // Second pass: transfer new updates
        let mut local = self.local.write().await;

        let Some(Shard::QueueProxy(proxy)) = local.deref() else {
            return Ok(());
        };

        proxy.transfer_all_missed_updates().await?;

        // Transform `QueueProxyShard` into `ForwardProxyShard`
        log::trace!("Transferred all queue proxy operations, transforming into forward proxy now");

        // Making `await` calls between `local.take()` and `local.insert(...)` is *not* cancel safe!
        let Some(Shard::QueueProxy(queue_proxy)) = local.take() else {
            unreachable!();
        };

        let (local_shard, remote_shard) = queue_proxy.forget_updates_and_finalize();
        let forward_proxy_res =
            ForwardProxyShard::new(self.shard_id, local_shard, remote_shard, None, None);

        match forward_proxy_res {
            Ok(forward_proxy) => {
                let _ = local.insert(Shard::ForwardProxy(forward_proxy));
                Ok(())
            }
            Err((err, local_shard)) => {
                log::warn!(
                    "Failed to transform queue proxy shard into forward proxy, reverting to local shard: {err}"
                );
                let _ = local.insert(Shard::Local(local_shard));
                Err(err)
            }
        }
    }

    pub async fn resolve_wal_delta(
        &self,
        recovery_point: RecoveryPoint,
    ) -> CollectionResult<Option<u64>> {
        let local_shard_read = self.local.read().await;
        let Some(local_shard) = local_shard_read.deref() else {
            return Err(CollectionError::service_error(
                "Cannot resolve WAL delta, shard replica set does not have local shard",
            ));
        };

        local_shard.resolve_wal_delta(recovery_point).await
    }

    pub async fn wal_version(&self) -> CollectionResult<Option<u64>> {
        let local_shard_read = self.local.read().await;
        let Some(local_shard) = local_shard_read.deref() else {
            return Err(CollectionError::service_error(
                "Cannot get WAL version, shard replica set does not have local shard",
            ));
        };

        local_shard.wal_version().await
    }
}use std::path::Path;

use common::fs::{safe_delete_with_suffix, sync_parent_dir_async};
use common::save_on_disk::SaveOnDisk;
use common::tar_ext;
use fs_err::tokio as tokio_fs;
use segment::types::SnapshotFormat;
use shard::snapshots::snapshot_manifest::{RecoveryType, SnapshotManifest};
use shard::snapshots::snapshot_utils::{SnapshotMergePlan, SnapshotUtils};

use super::{REPLICA_STATE_FILE, ShardReplicaSet};
use crate::common::file_utils::{move_dir, move_file};
use crate::operations::types::{CollectionError, CollectionResult};
use crate::shards::dummy_shard::DummyShard;
use crate::shards::local_shard::LocalShard;
use crate::shards::replica_set::replica_set_state::ReplicaSetState;
use crate::shards::shard::{PeerId, Shard};
use crate::shards::shard_config::ShardConfig;
use crate::shards::shard_initializing_flag_path;

impl ShardReplicaSet {
    pub async fn create_snapshot(
        &self,
        temp_path: &Path,
        tar: tar_ext::BuilderExt,
        format: SnapshotFormat,
        manifest: Option<SnapshotManifest>,
        save_wal: bool,
    ) -> CollectionResult<impl Future<Output = CollectionResult<()>> + use<>> {
        // Track concurrent `create_partial_snapshot` requests, so that cluster manager can load-balance them
        let partial_snapshot_create_request_guard = if manifest.is_some() {
            Some(self.partial_snapshot_meta.track_create_snapshot_request())
        } else {
            None
        };

        let replica_state = self.replica_state.clone();
        let temp_path = temp_path.to_path_buf();

        let local_read = self.local.read().await;

        let maybe_local_snapshot_future = if let Some(local) = &*local_read {
            Some(
                local
                    .get_snapshot_creator(&temp_path, &tar, format, manifest, save_wal)
                    .await?,
            )
        } else {
            None
        };

        drop(local_read);

        let future = async move {
            let _partial_snapshot_create_request_guard = partial_snapshot_create_request_guard;

            if let Some(local_snapshot_future) = maybe_local_snapshot_future {
                local_snapshot_future.await?;
            }

            replica_state.save_to_tar(&tar, REPLICA_STATE_FILE).await?;

            let shard_config = ShardConfig::new_replica_set();
            shard_config.save_to_tar(&tar).await?;
            Ok(())
        };

        Ok(future)
    }

    pub fn try_take_partial_snapshot_recovery_lock(
        &self,
    ) -> CollectionResult<tokio::sync::OwnedRwLockWriteGuard<()>> {
        self.partial_snapshot_meta.try_take_recovery_lock()
    }

    pub fn restore_snapshot(
        snapshot_path: &Path,
        this_peer_id: PeerId,
        is_distributed: bool,
    ) -> CollectionResult<()> {
        let replica_state: SaveOnDisk<ReplicaSetState> =
            SaveOnDisk::load_or_init_default(snapshot_path.join(REPLICA_STATE_FILE))?;

        // If this shard have local data
        let is_snapshot_local = replica_state.read().is_local;

        if !is_distributed && !is_snapshot_local {
            return Err(CollectionError::service_error(format!(
                "Can't restore snapshot in local mode with missing data at shard: {}",
                snapshot_path.display()
            )));
        }

        replica_state.write(|state| {
            state.switch_peer_id(this_peer_id);
            if !is_distributed {
                state.force_local_active()
            }
        })?;

        if replica_state.read().is_local {
            LocalShard::restore_snapshot(snapshot_path)?;
        }
        Ok(())
    }

    /// # Cancel safety
    ///
    /// This method is *not* cancel safe.
    pub async fn restore_local_replica_from(
        &self,
        replica_path: &Path,
        recovery_type: RecoveryType,
        collection_path: &Path,
        cancel: cancel::CancellationToken,
    ) -> CollectionResult<bool> {
        // `local.take()` call and `restore` task have to be executed as a single transaction

        if !LocalShard::check_data(replica_path) {
            return Ok(false);
        }

        let snapshot_manifest =
            SnapshotManifest::load_from_snapshot(replica_path, Some(recovery_type))?;

        // TODO:
        //   Check that shard snapshot is compatible with the collection
        //   (see `VectorsConfig::check_compatible_with_segment_config`)

        let _partial_snapshot_search_lock = match recovery_type {
            RecoveryType::Full => None,
            RecoveryType::Partial => {
                Some(self.partial_snapshot_meta.take_search_write_lock().await)
            }
        };

        let mut local = cancel::future::cancel_on_token(cancel.clone(), self.local.write()).await?;

        // set shard_id initialization flag
        // the file is removed after full recovery to indicate a well-formed shard
        // for example: some of the files may go missing if node gets killed during shard directory move/replace
        let shard_flag = shard_initializing_flag_path(collection_path, self.shard_id);
        let flag_file = tokio_fs::File::create(&shard_flag).await?;
        flag_file.sync_all().await?;
        sync_parent_dir_async(&shard_flag).await?;

        // Check `cancel` token one last time before starting non-cancellable section
        if cancel.is_cancelled() {
            return Err(cancel::Error::Cancelled.into());
        }

        let local_manifest = match local.take() {
            Some(shard) if snapshot_manifest.is_empty() => {
                // Shard is no longer needed and can be dropped
                shard.stop_gracefully().await;

                None
            }
            Some(shard) => {
                let local_manifest = shard.snapshot_manifest().await;

                // If local shard produces a valid manifest, it can be replaced and no longer needed
                // If it fails, we return it back.

                match local_manifest {
                    Ok(local_manifest) => {
                        local_manifest.validate().map_err(|err| {
                            CollectionError::service_error(format!(
                                "failed to restore partial shard snapshot for shard {}:{}: \
                                 local shard produces invalid snapshot manifest: \
                                 {err}",
                                self.collection_id, self.shard_id,
                            ))
                        })?;

                        // Shard is no longer needed and can be dropped
                        shard.stop_gracefully().await;

                        Some(local_manifest)
                    }

                    Err(err) => {
                        let _ = local.insert(shard);

                        return Err(CollectionError::service_error(format!(
                            "failed to restore partial shard snapshot for shard {}:{}: \
                             failed to collect snapshot manifest: \
                             {err}",
                            self.collection_id, self.shard_id,
                        )));
                    }
                }
            }
            None => None,
        };

        // Try to restore local replica from specified shard snapshot directory
        let restore = async {
            if let Some(local_manifest) = local_manifest {
                // ToDo: Replace with `partial_snapshot_merge_plan` when rocksdb is removed
                let merge_plan = SnapshotUtils::partial_snapshot_merge_plan(
                    &self.shard_path,
                    &local_manifest,
                    replica_path,
                    &snapshot_manifest,
                );

                let SnapshotMergePlan {
                    move_files,
                    replace_directories,
                    merge_directories,
                    delete_files,
                    delete_directories,
                } = merge_plan;

                // Clean up files and directories according to merge plan
                for path in delete_files {
                    if !path.exists() {
                        continue;
                    }
                    log::debug!("Deleting file {}", path.display());
                    tokio_fs::remove_file(&path).await?;
                }

                for path in delete_directories {
                    if !path.exists() {
                        continue;
                    }
                    log::debug!("Deleting directory {}", path.display());
                    tokio::task::spawn_blocking({
                        let path = path.clone();
                        move || safe_delete_with_suffix(&path)
                    })
                    .await??;
                }

                // Execute merge plan
                for (from, to) in move_files {
                    log::debug!("Moving file from {} to {}", from.display(), to.display());
                    move_file(&from, &to).await?;
                }

                for (from, to) in replace_directories {
                    log::debug!(
                        "Replacing directory {} with {}",
                        to.display(),
                        from.display()
                    );
                    if to.exists() {
                        tokio::task::spawn_blocking({
                            let to = to.clone();
                            move || safe_delete_with_suffix(&to)
                        })
                        .await??;
                    }
                    move_dir(from, to).await?;
                }

                for (from, to) in merge_directories {
                    log::debug!(
                        "Merging directory from {} to {}",
                        from.display(),
                        to.display()
                    );
                    move_dir(from, to).await?;
                }
            } else {
                // Remove shard data but not configuration files
                LocalShard::clear(&self.shard_path).await?;
                LocalShard::move_data(replica_path, &self.shard_path).await?;
            }

            LocalShard::load(
                self.shard_id,
                self.collection_id.clone(),
                &self.shard_path,
                self.collection_config.clone(),
                self.optimizers_config.clone(),
                self.shared_storage_config.clone(),
                self.payload_index_schema.clone(),
                recovery_type.is_full(),
                self.update_runtime.clone(),
                self.search_runtime.clone(),
                self.optimizer_resource_budget.clone(),
            )
            .await
        };

        match restore.await {
            Ok(new_local) => {
                local.replace(Shard::Local(new_local));
                // remove shard_id initialization flag because shard is fully recovered
                tokio_fs::remove_file(&shard_flag).await?;

                if recovery_type.is_partial() {
                    self.partial_snapshot_meta.snapshot_recovered();
                }

                Ok(true)
            }

            Err(restore_err) => {
                // Initialize "dummy" replica
                local.replace(Shard::Dummy(DummyShard::new(
                    "Failed to restore local replica",
                )));

                // Mark local replica as Dead since it's dummy and dirty
                self.add_locally_disabled(None, self.this_peer_id(), None);

                // Remove inner shard data but keep the shard folder with its configuration files.
                // This way the shard can be read on startup and the user can decide what to do next.
                match LocalShard::clear(&self.shard_path).await {
                    Ok(()) => Err(restore_err),

                    Err(cleanup_err) => {
                        log::error!(
                            "Failed to cleanup shard {} directory ({}) after restore failed: \
                             {cleanup_err}",
                            self.shard_id,
                            self.shard_path.display(),
                        );

                        // TODO: Contextualize `restore_err` with `cleanup_err` details!?
                        Err(restore_err)
                    }
                }
            }
        }
    }

    /// Replace the in-memory local shard (if any) with a dummy and remove its on-disk
    /// data files.
    ///
    /// Used by shard snapshot transfers to free disk space before the receiving node
    /// downloads the new snapshot, avoiding having both the old data and the incoming
    /// snapshot on disk at the same time. The configuration files and replica state
    /// are preserved, so the shard directory remains a valid (empty) shard.
    ///
    /// A dummy shard is left in place of the real one so that APIs still report a local
    /// shard while the data is being cleared and recovered, rather than reporting none.
    /// The subsequent `restore_local_replica_from` call drops this dummy and installs
    /// the recovered shard.
    ///
    /// Only safe to call while the shard is in a state that prevents user requests
    /// (`PartialSnapshot` during a shard transfer). Do NOT call this from a
    /// user-triggered URL recovery path, where the shard may still be serving queries.
    ///
    /// Writes the shard initializing flag before clearing, so that a crash between
    /// here and the end of the subsequent `restore_local_replica_from` call causes
    /// the shard to be loaded as a dummy on startup and re-recovered.
    pub async fn clear_local_for_snapshot_recovery(
        &self,
        collection_path: &Path,
    ) -> CollectionResult<()> {
        // Callers must only invoke this while the shard is in a state that cannot
        // be a source of truth (e.g. `PartialSnapshot` during a shard transfer).
        // Clearing a source-of-truth replica would silently drop data that may
        // still be serving queries.
        if self
            .peer_state(self.this_peer_id())
            .is_some_and(|s| s.can_be_source_of_truth())
        {
            return Err(CollectionError::service_error(format!(
                "clear_local_for_snapshot_recovery called on a peer that can be source-of-truth {}:{}",
                self.collection_id, self.shard_id,
            )));
        }

        let mut local = self.local.write().await;

        // Mark the shard as initializing before touching disk, so a crash during or
        // after clearing is detected on next startup and the shard is reloaded as a
        // dummy that triggers recovery.
        let shard_flag = shard_initializing_flag_path(collection_path, self.shard_id);
        let flag_file = tokio_fs::File::create(&shard_flag).await?;
        flag_file.sync_all().await?;
        sync_parent_dir_async(&shard_flag).await?;

        // Replace the local shard with a dummy rather than removing it entirely, so APIs
        // keep reporting a local shard while the data is cleared and the replacement
        // snapshot is recovered. `restore_local_replica_from` drops this dummy afterwards.
        let dummy = Shard::Dummy(DummyShard::new(
            "Local shard is being cleared for snapshot recovery",
        ));
        if let Some(shard) = local.replace(dummy) {
            shard.stop_gracefully().await;
        }

        LocalShard::clear(&self.shard_path).await?;

        Ok(())
    }

    pub async fn get_partial_snapshot_manifest(&self) -> CollectionResult<SnapshotManifest> {
        self.local
            .read()
            .await
            .as_ref()
            .ok_or_else(|| {
                CollectionError::not_found(format!(
                    "local shard {}:{} does not exist on peer {}",
                    self.collection_id,
                    self.shard_id,
                    self.this_peer_id(),
                ))
            })?
            .snapshot_manifest()
            .await
    }
}use std::ops::Deref as _;
use std::time::Duration;

use common::types::TelemetryDetail;
use segment::types::SizeStats;

use crate::operations::types::{CollectionResult, OptimizersStatus};
use crate::shards::replica_set::ShardReplicaSet;
use crate::shards::telemetry::{PartialSnapshotTelemetry, ReplicaSetTelemetry};

impl ShardReplicaSet {
    pub(crate) async fn get_telemetry_data(
        &self,
        detail: TelemetryDetail,
        timeout: Duration,
    ) -> CollectionResult<ReplicaSetTelemetry> {
        let local_shard = self.local.read().await;
        let local = local_shard.as_ref();

        let local_telemetry = match local {
            Some(local_shard) => Some(local_shard.get_telemetry_data(detail, timeout).await?),
            None => None,
        };

        Ok(ReplicaSetTelemetry {
            id: self.shard_id,
            key: self.shard_key(),
            local: local_telemetry,
            remote: self
                .remotes
                .read()
                .await
                .iter()
                .map(|remote| remote.get_telemetry_data(detail))
                .collect(),
            replicate_states: self.replica_state.read().peers().clone(),
            partial_snapshot: Some(PartialSnapshotTelemetry {
                ongoing_create_snapshot_requests: self
                    .partial_snapshot_meta
                    .ongoing_create_snapshot_requests(),
                is_recovering: self.partial_snapshot_meta.is_recovery_lock_taken(),
                recovery_timestamp: self.partial_snapshot_meta.recovery_timestamp(),
            }),
        })
    }

    pub(crate) async fn get_optimization_status(
        &self,
        timeout: Duration,
    ) -> Option<CollectionResult<OptimizersStatus>> {
        let local_shard = self.local.read().await;

        let Some(local) = local_shard.deref() else {
            return None;
        };

        Some(local.get_optimization_status(timeout).await)
    }

    pub(crate) async fn get_size_stats(&self, timeout: Duration) -> CollectionResult<SizeStats> {
        let local_shard = self.local.read().await;

        let Some(local) = local_shard.deref() else {
            return Ok(SizeStats::default());
        };

        local.get_size_stats(timeout).await
    }
}use std::future::Future;
use std::num::NonZeroUsize;
use std::ops::Deref as _;
use std::time::Duration;

use common::counter::hardware_accumulator::HwMeasurementAcc;
use futures::stream::FuturesUnordered;
use futures::{FutureExt as _, StreamExt as _};
use itertools::Itertools as _;
use tokio::sync::oneshot;
use tokio::task::yield_now;
use tokio_util::task::AbortOnDropHandle;

use super::{RemoteShard, ShardReplicaSet, clock_set};
use crate::operations::point_ops::WriteOrdering;
use crate::operations::types::{CollectionError, CollectionResult, UpdateResult, UpdateStatus};
use crate::operations::{ClockTag, CollectionUpdateOperations, OperationWithClockTag};
use crate::shards::local_shard::shard_ops::await_update_result;
use crate::shards::replica_set::clock_set::ClockGuard;
use crate::shards::replica_set::replica_set_state::{ReplicaSetState, ReplicaState};
use crate::shards::shard::{PeerId, Shard};
use crate::shards::shard_trait::{ShardOperation as _, WaitUntil};

/// Maximum number of attempts for applying an update with a new clock.
///
/// If an update is rejected because of an old clock, we will try again with a new clock. This
/// describes the maximum number of times we try the update.
const UPDATE_MAX_CLOCK_REJECTED_RETRIES: usize = 3;

const DEFAULT_SHARD_DEACTIVATION_TIMEOUT: Duration = Duration::from_secs(30);

impl ShardReplicaSet {
    /// Update local shard if any without forwarding to remote shards
    ///
    /// If `force` is true, the operation will be applied unconditionally no matter the replica
    /// state. Must only be used internally.
    ///
    /// # Cancel safety
    ///
    /// This method is *not* cancel safe.
    pub async fn update_local(
        &self,
        operation: OperationWithClockTag,
        wait: WaitUntil,
        timeout: Option<Duration>,
        mut hw_measurement: HwMeasurementAcc,
        force: bool,
    ) -> CollectionResult<Option<UpdateResult>> {
        // `ShardOperations::update` is not guaranteed to be cancel safe, so this method is not
        // cancel safe.

        let local = self.local.read().await;

        let Some(shard) = local.deref() else {
            return Ok(None);
        };

        let Some(state) = self.peer_state(self.this_peer_id()) else {
            return Ok(None);
        };

        // Don't measure hw when resharding
        if state.is_resharding() && !hw_measurement.is_disposable() {
            hw_measurement = HwMeasurementAcc::disposable();
        }

        // Decide whether to apply the operation in the current replica state.
        // `force` and a force-tagged clock both bypass the recovery-state guard.
        let accepts_operation = match state {
            ReplicaState::Active
            | ReplicaState::Partial
            | ReplicaState::Initializing
            | ReplicaState::Listener
            | ReplicaState::Resharding
            | ReplicaState::ReshardingScaleDown
            | ReplicaState::ActiveRead => true,
            // Recovery states only accept updates with an explicit force flag.
            ReplicaState::PartialSnapshot | ReplicaState::Recovery => {
                force || operation.clock_tag.is_some_and(|tag| tag.force)
            }
            // Dead/ManualRecovery only accept updates when the caller forces.
            ReplicaState::Dead | ReplicaState::ManualRecovery => force,
        };

        if !accepts_operation {
            if matches!(
                state,
                ReplicaState::PartialSnapshot | ReplicaState::Recovery
            ) && log::log_enabled!(log::Level::Debug)
            {
                if let Some(ids) = operation.operation.point_ids() {
                    log::debug!(
                        "Operation affecting point IDs {ids:?} rejected on this peer, force flag required in recovery state",
                    );
                } else {
                    log::debug!(
                        "Operation {operation:?} rejected on this peer, force flag required in recovery state",
                    );
                }
            }
            return Ok(None);
        }

        // Listener replicas only durably ack to WAL; everything else honours
        // the caller-supplied wait/timeout.
        let (effective_wait, effective_timeout) = if state.is_listener() {
            (WaitUntil::Wal, None)
        } else {
            (wait, timeout)
        };

        // Rate limit update operations on Active replica.
        if state.is_write_rate_limitable() {
            self.check_operation_write_rate_limiter(&hw_measurement, shard, &operation)
                .await?;
        }

        // For a plain `Shard::Local`, submit the operation while the read
        // guard is held (brief), then drop the guard before awaiting
        // completion. Holding the guard across a deferred-points wait would
        // deadlock concurrent shard transfers that need `local.write()`.
        // Proxy variants are transient and keep the inline-await path.
        let result = match shard {
            Shard::Local(local_shard) => {
                let outcome = local_shard
                    .submit_update(operation, effective_wait, hw_measurement)
                    .await?;
                drop(local);
                await_update_result(outcome, effective_timeout).await?
            }
            Shard::Proxy(_) | Shard::ForwardProxy(_) | Shard::QueueProxy(_) | Shard::Dummy(_) => {
                shard
                    .get()
                    .update(operation, effective_wait, effective_timeout, hw_measurement)
                    .await?
            }
        };

        Ok(Some(result))
    }

    /// # Cancel safety
    ///
    /// This method is *not* cancel safe.
    pub async fn update_with_consistency(
        &self,
        operation: CollectionUpdateOperations,
        wait: WaitUntil,
        timeout: Option<Duration>,
        ordering: WriteOrdering,
        update_only_existing: bool,
        mut hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<UpdateResult> {
        // `ShardReplicaSet::update` is not cancel safe, so this method is not cancel safe.

        let Some(leader_peer) = self.leader_peer_for_update(ordering) else {
            return Err(CollectionError::service_error(format!(
                "Cannot update shard {}:{} with {ordering:?} ordering because no leader could be selected",
                self.collection_id, self.shard_id
            )));
        };

        // Don't measure hw when resharding
        let peer_state = self.peer_state(leader_peer);
        if peer_state.is_some_and(|state| state.is_resharding()) {
            hw_measurement_acc = HwMeasurementAcc::disposable();
        }

        // If we are the leader, run the update from this replica set
        if leader_peer == self.this_peer_id() {
            // Lock updates if ordering is strong or medium
            let _write_ordering_lock = match ordering {
                WriteOrdering::Strong | WriteOrdering::Medium => {
                    Some(self.write_ordering_lock.lock().await)
                }
                WriteOrdering::Weak => None,
            };

            self.update(
                operation,
                wait,
                timeout,
                update_only_existing,
                hw_measurement_acc,
            )
            .await
        } else {
            // Forward the update to the designated leader
            self.forward_update(leader_peer, operation, wait, timeout, ordering, hw_measurement_acc)
                .await
                .map_err(|err| {
                    if err.is_transient() {
                        // Deactivate the peer if forwarding failed with transient error
                        let replica_state = self.replica_state.read();
                        let from_state = replica_state.get_peer_state(leader_peer);
                        self.add_locally_disabled(Some(&replica_state), leader_peer, from_state);

                        // Return service error
                        CollectionError::service_error(format!(
                            "Failed to apply update with {ordering:?} ordering via leader peer {leader_peer}: {err}"
                        ))
                    } else {
                        err
                    }
                })
        }
    }

    /// Designated a leader replica for the update based on the WriteOrdering
    fn leader_peer_for_update(&self, ordering: WriteOrdering) -> Option<PeerId> {
        match ordering {
            WriteOrdering::Weak => Some(self.this_peer_id()), // no requirement for consistency
            WriteOrdering::Medium => self.highest_alive_replica_peer_id(), // consistency with highest alive replica
            WriteOrdering::Strong => self.highest_replica_peer_id(), // consistency with highest replica
        }
    }

    fn highest_alive_replica_peer_id(&self) -> Option<PeerId> {
        let read_lock = self.replica_state.read();
        let peer_ids = read_lock.peers().keys().cloned().collect::<Vec<_>>();
        drop(read_lock);

        peer_ids
            .into_iter()
            .filter(|&peer_id| self.peer_can_be_source_of_truth(peer_id)) // re-acquire replica_state read lock
            .max()
    }

    fn highest_replica_peer_id(&self) -> Option<PeerId> {
        self.replica_state.read().peers().keys().max().cloned()
    }

    pub async fn get_clock(&self) -> ClockGuard {
        loop {
            match self.clock_set.lock().await.get_clock() {
                Some(clock) => return clock,
                // Prevent blocking async runtime with spinlock
                None => yield_now().await,
            }
        }
    }

    /// # Cancel safety
    ///
    /// This method is *not* cancel safe.
    async fn update(
        &self,
        operation: CollectionUpdateOperations,
        wait: WaitUntil,
        timeout: Option<Duration>,
        update_only_existing: bool,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<UpdateResult> {
        // `ShardRepilcaSet::update_impl` is not cancel safe, so this method is not cancel safe.

        // TODO: Optimize `remotes`/`local`/`clock` locking for the "happy path"?
        //
        // E.g., refactor `update`/`update_impl`, so that it would be possible to:
        // - lock `remotes`, `local`, `clock` (in specified order!) on the *first* iteration of the loop
        // - then release and lock `remotes` and `local` *only* for all next iterations
        // - but keep initial `clock` for the whole duration of `update`
        let clock_timeout = timeout.unwrap_or(Duration::MAX);
        let mut clock = tokio::time::timeout(clock_timeout, self.get_clock())
            .await
            .map_err(|_| {
                CollectionError::timeout(
                    clock_timeout,
                    format!("Failed to acquire clock for update operation within {timeout:?}"),
                )
            })?;

        for attempt in 1..=UPDATE_MAX_CLOCK_REJECTED_RETRIES {
            let is_non_zero_tick = clock.current_tick().is_some();

            let res = self
                .update_impl(
                    operation.clone(),
                    wait,
                    timeout,
                    &mut clock,
                    update_only_existing,
                    hw_measurement_acc.clone(),
                )
                .await?;

            if let Some(res) = res {
                return Ok(res);
            }

            // Log a warning, if operation was rejected... but only if operation had a non-0 tick,
            // because operations with tick 0 should *always* be rejected and rejection is *expected*.
            if is_non_zero_tick && log::log_enabled!(log::Level::Warn) {
                if let Some(ids) = operation.point_ids() {
                    log::warn!(
                        "Operation affecting point IDs {ids:?} was rejected by some node(s), retrying... \
                         (attempt {attempt}/{UPDATE_MAX_CLOCK_REJECTED_RETRIES})"
                    );
                } else {
                    log::warn!(
                        "Operation {operation:?} was rejected by some node(s), retrying... \
                         (attempt {attempt}/{UPDATE_MAX_CLOCK_REJECTED_RETRIES})"
                    );
                }
            }
        }

        Err(CollectionError::service_error(format!(
            "Failed to apply operation {operation:?} \
             after {UPDATE_MAX_CLOCK_REJECTED_RETRIES} attempts, \
             all attempts were rejected",
        )))
    }

    /// # Cancel safety
    ///
    /// This method is *not* cancel safe.
    async fn update_impl(
        &self,
        operation: CollectionUpdateOperations,
        wait: WaitUntil,
        timeout: Option<Duration>,
        clock: &mut clock_set::ClockGuard,
        update_only_existing: bool,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<Option<UpdateResult>> {
        // `LocalShard::update` is not guaranteed to be cancel safe and it's impossible to cancel
        // multiple parallel updates in a way that is *guaranteed* not to introduce inconsistencies
        // between nodes, so this method is not cancel safe.

        // Snapshot the remote shards into owned values, then drop the read guard so
        // we don't hold `remotes.read()` across the long update await. Holding it
        // would deadlock with `add_remote`'s `remotes.write()` on the consensus
        // apply path (e.g. when starting a shard transfer concurrently with a
        // wait=true update that's parked on a deferred-points wait).
        let (updatable_remote_shards, total_remotes) = {
            let remotes = self.remotes.read().await;
            let updatable: Vec<RemoteShard> = remotes
                .iter()
                .filter(|rs| self.is_peer_updatable(rs.peer_id))
                .cloned()
                .collect();
            (updatable, remotes.len())
        };

        let local = self.local.read().await;
        let replica_count = usize::from(local.is_some()) + total_remotes;

        let this_peer_id = self.this_peer_id();

        // Local is defined and can receive updates
        let local_is_updatable = local.is_some() && self.is_peer_updatable(this_peer_id);

        if updatable_remote_shards.is_empty() && !local_is_updatable {
            return Err(CollectionError::service_error(format!(
                "The replica set for shard {} on peer {this_peer_id} has no active replica",
                self.shard_id,
            )));
        }

        let current_clock_tick = clock.tick_once();
        let clock_tag = ClockTag::new(this_peer_id, clock.id() as _, current_clock_tick);
        let operation = OperationWithClockTag::new(operation, Some(clock_tag));
        let is_listener = self
            .peer_state(this_peer_id)
            .is_some_and(ReplicaState::is_listener);

        let local_wait = if is_listener { WaitUntil::Wal } else { wait };

        // Rate-limit local writes on Active replica, while we still hold the read guard.
        if local_is_updatable
            && self.peer_is_write_rate_limitable(this_peer_id)
            && let Some(shard) = local.deref()
        {
            self.check_operation_write_rate_limiter(&hw_measurement_acc, shard, &operation)
                .await?;
        }

        let update_concurrency = self.shared_storage_config.update_concurrency;

        // Build remote update futures up front; they're identical between the
        // two local-dispatch paths and don't borrow from the local read guard.
        let remote_futures: Vec<_> = updatable_remote_shards
            .into_iter()
            .map(|remote| {
                let operation = operation.clone();
                let hw_acc = hw_measurement_acc.clone();
                async move {
                    let peer_id = remote.peer_id;
                    remote
                        .update(operation, wait, timeout, hw_acc)
                        .await
                        .map(|ok| (peer_id, ok))
                        .map_err(|err| (peer_id, err))
                }
            })
            .collect();

        // For a plain `Shard::Local`, submit the operation while the read
        // guard is held (brief), then drop the guard before awaiting
        // completion. Holding the guard across a deferred-points wait would
        // deadlock concurrent shard transfers that need `local.write()`.
        // Proxy variants are transient and keep the inline-await path.
        let all_res: Vec<Result<(PeerId, UpdateResult), (PeerId, CollectionError)>> =
            match local.deref() {
                Some(Shard::Local(local_shard)) if local_is_updatable => {
                    let outcome = local_shard
                        .submit_update(operation, local_wait, hw_measurement_acc)
                        .await?;
                    drop(local);

                    let mut update_futures = Vec::with_capacity(remote_futures.len() + 1);
                    let local_update = async move {
                        await_update_result(outcome, timeout)
                            .await
                            .map(|ok| (this_peer_id, ok))
                            .map_err(|err| (this_peer_id, err))
                    };
                    update_futures.push(local_update.left_future());
                    update_futures.extend(remote_futures.into_iter().map(|f| f.right_future()));

                    run_update_futures(update_futures, update_concurrency).await
                }
                None
                | Some(Shard::Local(_))
                | Some(Shard::Proxy(_))
                | Some(Shard::ForwardProxy(_))
                | Some(Shard::QueueProxy(_))
                | Some(Shard::Dummy(_)) => {
                    let mut update_futures = Vec::with_capacity(remote_futures.len() + 1);

                    if let Some(shard) = local.deref()
                        && local_is_updatable
                    {
                        let local_update = async move {
                            shard
                                .get()
                                .update(operation, local_wait, timeout, hw_measurement_acc)
                                .await
                                .map(|ok| (this_peer_id, ok))
                                .map_err(|err| (this_peer_id, err))
                        };
                        update_futures.push(local_update.left_future());
                    }
                    update_futures.extend(remote_futures.into_iter().map(|f| f.right_future()));

                    let res = run_update_futures(update_futures, update_concurrency).await;
                    drop(local);
                    res
                }
            };

        let write_consistency_factor = self
            .collection_config
            .read()
            .await
            .params
            .write_consistency_factor
            .get() as usize;

        let minimal_success_count = write_consistency_factor.min(replica_count);

        let (successes, failures): (Vec<_>, Vec<_>) = all_res.into_iter().partition_result();

        // Advance clock if some replica echoed *newer* tick

        let new_clock_tick = successes
            .iter()
            .filter_map(|(_, result)| {
                let echo_tag = result.clock_tag?;

                if echo_tag.peer_id != clock_tag.peer_id {
                    debug_assert!(
                        false,
                        "Echoed clock tag peer_id does not match the original",
                    );
                    return None;
                }

                if echo_tag.clock_id != clock_tag.clock_id {
                    debug_assert!(
                        false,
                        "Echoed clock tag clock_id does not match the original",
                    );
                    return None;
                }

                Some(echo_tag.clock_tick)
            })
            .max();

        if let Some(new_clock_tick) = new_clock_tick {
            clock.advance_to(new_clock_tick);
        }

        // Notify consensus about replica failures if:
        // 1. there are some failures, but enough successes for the operation to be accepted
        // 2. a resharding replica failed, and there are not enough successes for the operation to be accepted
        //
        // Notify user about potential consistency problems if:
        // 1. there are some failures and enough successes, but we fail to deactivate the failed replicas
        // 2. successes were not applied to any Active or Resharding replica
        //
        // Notify user with operation error if:
        // 1. there are not enough successes for the operation to be accepted

        let failure_error = if let Some((peer_id, collection_error)) = failures.first() {
            format!("Failed peer: {peer_id}, error: {collection_error}")
        } else {
            String::new()
        };

        if !failures.is_empty() {
            for (peer_id, err) in &failures {
                log::warn!(
                    "Failed to update shard {}:{} on peer {peer_id}, error: {err}",
                    self.collection_id,
                    self.shard_id,
                );
            }

            // If there is at least one full-complete operation, we can't ignore non-transient errors (4xx)
            // And we must deactivate failed replicas to ensure consistency
            let has_full_completed_updates = successes.iter().any(|(_, res)| match res.status {
                UpdateStatus::Completed => true,
                UpdateStatus::Acknowledged => false,
                UpdateStatus::ClockRejected => false,
                UpdateStatus::WaitTimeout => false,
            });

            if successes.len() >= minimal_success_count {
                // If there are enough successes, deactivate failed replicas
                // Failed replicas will automatically recover from another replica ensuring consistency

                let failures_to_handle: Vec<_> = if !has_full_completed_updates {
                    // We can only deactivate transient errors
                    failures
                        .into_iter()
                        .filter(|(_, err)| err.is_transient())
                        .collect()
                } else {
                    failures
                };

                let wait_for_deactivation = self.handle_failed_replicas(
                    &failures_to_handle,
                    &self.replica_state.read(),
                    update_only_existing,
                );

                // Wait for replica failures to be accepted, otherwise return consistency error
                if wait.needs_callback() && wait_for_deactivation {
                    // ToDo: allow timeout configuration in API
                    let timeout = DEFAULT_SHARD_DEACTIVATION_TIMEOUT;

                    let replica_state = self.replica_state.clone();
                    let peer_ids: Vec<_> = failures_to_handle
                        .iter()
                        .map(|(peer_id, _)| *peer_id)
                        .collect();

                    let shards_disabled =
                        AbortOnDropHandle::new(tokio::task::spawn_blocking(move || {
                            replica_state.wait_for(
                                |state| {
                                    peer_ids.iter().all(|peer_id| {
                                        // Not found means that peer is dead

                                        // Wait for replica deactivation.
                                        let is_active = state
                                            .peers()
                                            .get(peer_id)
                                            .map(|state| state.can_be_source_of_truth())
                                            .unwrap_or(false);

                                        !is_active
                                    })
                                },
                                timeout,
                            )
                        }))
                        .await?;

                    if !shards_disabled {
                        return Err(CollectionError::service_error(format!(
                            "Some replica of shard {} failed to apply operation and deactivation \
                            timed out after {timeout:?}. Consistency of this update is not guaranteed. Please retry. {failure_error}",
                            self.shard_id,
                        )));
                    }
                }
            } else {
                // If there aren't enough successes, report error to user

                // TODO(resharding): reconsider how we count/deactivate resharding replicas.
                self.handle_failed_replicas(
                    failures
                        .iter()
                        .filter(|(peer_id, _)| self.peer_is_resharding(*peer_id)),
                    &self.replica_state.read(),
                    update_only_existing,
                );

                let (_peer_id, err) = failures.into_iter().next().unwrap();
                return Err(err);
            }
        }

        // Successes must have applied to at least one active replica
        if !successes
            .iter()
            .any(|&(peer_id, _)| self.peer_can_be_source_of_truth(peer_id))
        {
            return Err(CollectionError::service_error(format!(
                "Failed to apply operation to at least one `Active` replica. \
                 Consistency of this update is not guaranteed. Please retry. {failure_error}",
            )));
        }

        let is_any_operation_rejected = successes
            .iter()
            .any(|(_, res)| matches!(res.status, UpdateStatus::ClockRejected));

        if is_any_operation_rejected {
            return Ok(None);
        }

        let res = Self::merge_successful_update_results(&successes);

        Ok(Some(res))
    }

    /// Check write rate limiter for the operation
    ///
    /// Lazily compute the cost of the operation and check against the write
    /// rate limiter. The limiter lives on `LocalShard`; proxy wrappers forward
    /// writes to that same local shard, so we resolve the wrapped local shard
    /// uniformly via [`Shard::local_shard`]. `Dummy` shards have no limiter.
    async fn check_operation_write_rate_limiter(
        &self,
        hw_measurement: &HwMeasurementAcc,
        local: &Shard,
        operation: &OperationWithClockTag,
    ) -> CollectionResult<()> {
        let Some(local_shard) = local.local_shard() else {
            return Ok(());
        };
        local_shard
            .check_write_rate_limiter(hw_measurement, async || {
                let mut ratelimiter_cost = 1;

                // Estimate the cost based on affected points if filter is available.
                match local
                    .estimate_request_cardinality(&operation.operation, hw_measurement)
                    .await
                {
                    Ok(est) => ratelimiter_cost = 1.max(est.exp),
                    Err(err) => log::error!("Estimating cardinality: {err:?}"),
                }

                ratelimiter_cost
            })
            .await?;
        Ok(())
    }

    /// Whether to send updates to the given peer
    ///
    /// A peer in dead state, or a locally disabled peer, will not accept updates.
    fn is_peer_updatable(&self, peer_id: PeerId) -> bool {
        let Some(state) = self.peer_state(peer_id) else {
            return false;
        };

        state.is_updatable() && !self.is_locally_disabled(peer_id)
    }

    fn peer_is_resharding(&self, peer_id: PeerId) -> bool {
        let is_resharding = matches!(
            self.peer_state(peer_id),
            Some(ReplicaState::Resharding | ReplicaState::ReshardingScaleDown)
        );

        is_resharding && !self.is_locally_disabled(peer_id)
    }

    fn handle_failed_replicas<'a>(
        &self,
        failures: impl IntoIterator<Item = &'a (PeerId, CollectionError)>,
        state: &ReplicaSetState,
        update_only_existing: bool,
    ) -> bool {
        let mut wait_for_deactivation = false;

        for (peer_id, err) in failures {
            let Some(peer_state) = state.get_peer_state(*peer_id) else {
                continue;
            };

            // Ignore errors entirely for dead and listener replicas
            match peer_state {
                ReplicaState::Dead | ReplicaState::Listener | ReplicaState::ManualRecovery => {
                    continue;
                }
                ReplicaState::Active
                | ReplicaState::Initializing
                | ReplicaState::Partial
                | ReplicaState::Recovery
                | ReplicaState::PartialSnapshot
                | ReplicaState::Resharding
                | ReplicaState::ReshardingScaleDown
                | ReplicaState::ActiveRead => (),
            }

            // Handle a special case where transfer receiver is not in the expected replica state yet.
            // Data consistency will be handled by the shard transfer and the associated proxies.
            if peer_state.is_partial_or_recovery() && err.is_pre_condition_failed() {
                continue;
            }

            // Ignore missing point errors if replica is in partial or recovery state
            // Partial or recovery state indicates that the replica is receiving a shard transfer,
            // it might not have received all the points yet
            // See: <https://github.com/qdrant/qdrant/pull/5991>
            if peer_state.is_partial_or_recovery() && err.is_missing_point() {
                continue;
            }

            if update_only_existing && err.is_missing_point() {
                continue;
            }

            if err.is_transient() || peer_state == ReplicaState::Initializing {
                // If the error is transient, we should not deactivate the peer
                // before allowing other operations to continue.
                // Otherwise, the failed node can become responsive again, before
                // the other nodes deactivate it, so the storage might be inconsistent.
                wait_for_deactivation = true;
            }

            log::debug!(
                "Deactivating peer {peer_id} because of failed update of shard {}:{}",
                self.collection_id,
                self.shard_id,
            );

            // Deactivate replica in consensus if it matches the state we expect.
            // We filter out transient transfer states (Partial, Recovery, etc.)
            // because those can change rapidly between proposal and apply, and
            // we want the deactivation to go through even if the state has
            // moved on. Resharding/ReshardingScaleDown are stable through the
            // resharding lifecycle (only flipped by finish_migrating_points
            // → Active or by this same deactivation flow → Dead), so we keep
            // them populated. Carrying the captured pre-state in the consensus
            // log entry is what lets the local `abort_resharding` side-effect
            // in `Collection::set_shard_replica_state` re-fire correctly on
            // replay — without it, replay reads `current_state` as Dead from
            // disk and silently skips the side-effect, leaving
            // resharding_state stale.
            let from_state = Some(peer_state)
                .filter(|state| !state.is_partial_or_recovery() || state.is_resharding());

            self.add_locally_disabled(Some(state), *peer_id, from_state);
        }

        wait_for_deactivation
    }

    /// Forward update to the leader replica
    ///
    /// # Cancel safety
    ///
    /// This method is cancel safe.
    async fn forward_update(
        &self,
        leader_peer: PeerId,
        operation: CollectionUpdateOperations,
        wait: WaitUntil,
        timeout: Option<Duration>,
        ordering: WriteOrdering,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<UpdateResult> {
        // `RemoteShard::forward_update` is cancel safe, so this method is cancel safe.

        let remotes_guard = self.remotes.read().await;

        let Some(remote_leader) = remotes_guard.iter().find(|r| r.peer_id == leader_peer) else {
            return Err(CollectionError::service_error(format!(
                "Cannot forward update to shard {} because was removed from the replica set",
                self.shard_id
            )));
        };

        remote_leader
            .forward_update(
                OperationWithClockTag::from(operation),
                wait,
                timeout,
                ordering,
                hw_measurement_acc,
            ) // `clock_tag` *has to* be `None`!
            .await
    }

    /// Pick a successful update result to return from a replica set.
    ///
    /// We pick the reply from the highest peer ID. This makes the returned response deterministic.
    fn merge_successful_update_results(successes: &[(PeerId, UpdateResult)]) -> UpdateResult {
        debug_assert!(!successes.is_empty());
        debug_assert!(
            !successes
                .iter()
                .any(|(_, r)| r.status == UpdateStatus::ClockRejected),
            "ClockRejected must be handled before merging successful results",
        );

        // Aggregate status: WaitTimeout > .. > ClockRejected
        let status = successes
            .iter()
            .map(|(_, res)| res.status)
            .max_by_key(|s| s.priority())
            .unwrap_or(UpdateStatus::Acknowledged);

        let mut result = successes
            .iter()
            .max_by_key(|(peer_id, _)| *peer_id)
            .map(|(_, res)| *res)
            .expect("successes is not empty");

        result.status = status;
        result
    }

    /// Send plunger operation
    ///
    /// Returns oneshot channel receiver that will be notified once the plunger operation is
    /// processed. Returns `None` if local shard is not present.
    ///
    /// # Cancel safety
    ///
    /// This method is cancel safe.
    pub async fn plunge_local_async(&self) -> CollectionResult<Option<oneshot::Receiver<()>>> {
        match self.local.read().await.deref() {
            Some(local) => local.plunge_async().await.map(Some),
            None => Ok(None),
        }
    }
}

/// Drive a batch of update futures, optionally limiting concurrency.
async fn run_update_futures<F>(
    update_futures: Vec<F>,
    update_concurrency: Option<NonZeroUsize>,
) -> Vec<Result<(PeerId, UpdateResult), (PeerId, CollectionError)>>
where
    F: Future<Output = Result<(PeerId, UpdateResult), (PeerId, CollectionError)>>,
{
    match update_concurrency {
        Some(concurrency) => {
            futures::stream::iter(update_futures)
                .buffer_unordered(concurrency.get())
                .collect()
                .await
        }
        None => FuturesUnordered::from_iter(update_futures).collect().await,
    }
}

#[cfg(test)]
mod tests {
    use std::collections::HashSet;
    use std::num::NonZeroU32;
    use std::sync::Arc;

    use common::budget::ResourceBudget;
    use common::save_on_disk::SaveOnDisk;
    use segment::types::Distance;
    use tempfile::{Builder, TempDir};
    use tokio::runtime::Handle;
    use tokio::sync::RwLock;

    use super::*;
    use crate::common::adaptive_handle::AdaptiveSearchHandle;
    use crate::config::*;
    use crate::operations::types::VectorsConfig;
    use crate::operations::vector_params_builder::VectorParamsBuilder;
    use crate::optimizers_builder::OptimizersConfig;
    use crate::shards::replica_set::{AbortShardTransfer, ChangePeerFromState};

    #[test]
    fn test_merge_successful_update_results_wait_timeout_dominates() {
        let this_peer_id: PeerId = 1;

        let local_tag = ClockTag::new_with_token(this_peer_id, 7, 10, 0);
        let remote_tag = ClockTag::new_with_token(this_peer_id, 7, 12, 0);

        let successes = vec![
            (
                this_peer_id,
                UpdateResult {
                    operation_id: Some(10),
                    status: UpdateStatus::Completed,
                    clock_tag: Some(local_tag),
                },
            ),
            (
                2,
                UpdateResult {
                    operation_id: Some(20),
                    status: UpdateStatus::WaitTimeout,
                    clock_tag: Some(remote_tag),
                },
            ),
        ];

        let merged = ShardReplicaSet::merge_successful_update_results(&successes);

        assert_eq!(merged.status, UpdateStatus::WaitTimeout);
        assert_eq!(merged.operation_id, Some(20));
        assert_eq!(merged.clock_tag.unwrap().clock_tick, 12);
    }

    #[test]
    fn test_merge_successful_update_results_prefers_highest_peer_id() {
        let this_peer_id: PeerId = 1;

        let local_tag = ClockTag::new_with_token(this_peer_id, 7, 10, 0);
        let remote_tag = ClockTag::new_with_token(this_peer_id, 7, 11, 0);

        let successes = vec![
            (
                this_peer_id,
                UpdateResult {
                    operation_id: Some(10),
                    status: UpdateStatus::Acknowledged,
                    clock_tag: Some(local_tag),
                },
            ),
            (
                2,
                UpdateResult {
                    operation_id: Some(20),
                    status: UpdateStatus::Completed,
                    clock_tag: Some(remote_tag),
                },
            ),
        ];

        let merged = ShardReplicaSet::merge_successful_update_results(&successes);

        assert_eq!(merged.status, UpdateStatus::Completed);
        assert_eq!(merged.operation_id, Some(20));
        assert_eq!(merged.clock_tag.unwrap().clock_tick, 11);
    }

    #[tokio::test]
    async fn test_highest_replica_peer_id() {
        let collection_dir = Builder::new().prefix("test_collection").tempdir().unwrap();
        let rs = new_shard_replica_set(&collection_dir).await;

        assert_eq!(rs.highest_replica_peer_id(), Some(5));
        // at build time the replicas are all dead, they need to be activated
        assert_eq!(rs.highest_alive_replica_peer_id(), None);

        rs.set_replica_state(1, ReplicaState::Active).await.unwrap();
        rs.set_replica_state(3, ReplicaState::Active).await.unwrap();
        rs.set_replica_state(4, ReplicaState::Active).await.unwrap();
        rs.set_replica_state(5, ReplicaState::Partial)
            .await
            .unwrap();

        assert_eq!(rs.highest_replica_peer_id(), Some(5));
        assert_eq!(rs.highest_alive_replica_peer_id(), Some(4));
    }

    const TEST_OPTIMIZERS_CONFIG: OptimizersConfig = OptimizersConfig {
        deleted_threshold: 0.9,
        vacuum_min_vector_number: 1000,
        default_segment_number: 2,
        max_segment_size: None,
        #[expect(deprecated)]
        memmap_threshold: None,
        indexing_threshold: Some(50_000),
        flush_interval_sec: 30,
        max_optimization_threads: Some(2),
        prevent_unoptimized: None,
    };

    async fn new_shard_replica_set(collection_dir: &TempDir) -> ShardReplicaSet {
        let update_runtime = Handle::current();
        let search_runtime = AdaptiveSearchHandle::current_for_tests();

        let wal_config = WalConfig {
            wal_capacity_mb: 1,
            wal_segments_ahead: 0,
            wal_retain_closed: 1,
        };

        let collection_params = CollectionParams {
            vectors: VectorsConfig::Single(VectorParamsBuilder::new(4, Distance::Dot).build()),
            shard_number: NonZeroU32::new(4).unwrap(),
            replication_factor: NonZeroU32::new(3).unwrap(),
            write_consistency_factor: NonZeroU32::new(2).unwrap(),
            ..CollectionParams::empty()
        };

        let config = CollectionConfigInternal {
            params: collection_params,
            optimizer_config: TEST_OPTIMIZERS_CONFIG.clone(),
            wal_config,
            hnsw_config: Default::default(),
            quantization_config: None,
            strict_mode_config: None,
            uuid: None,
            metadata: None,
        };

        let payload_index_schema_dir = Builder::new().prefix("qdrant-test").tempdir().unwrap();
        let payload_index_schema_file = payload_index_schema_dir.path().join("payload-schema.json");
        let payload_index_schema =
            Arc::new(SaveOnDisk::load_or_init_default(payload_index_schema_file).unwrap());

        let shared_config = Arc::new(RwLock::new(config.clone()));
        let remotes = HashSet::from([2, 3, 4, 5]);
        ShardReplicaSet::build(
            1,
            None,
            "test_collection".to_string(),
            1,
            false,
            remotes,
            dummy_on_replica_failure(),
            dummy_abort_shard_transfer(),
            collection_dir.path(),
            shared_config,
            config.optimizer_config.clone(),
            Default::default(),
            payload_index_schema,
            Default::default(),
            update_runtime,
            search_runtime,
            ResourceBudget::default(),
            None,
        )
        .await
        .unwrap()
    }

    fn dummy_on_replica_failure() -> ChangePeerFromState {
        Arc::new(move |_peer_id, _shard_id, _from_state| {})
    }

    fn dummy_abort_shard_transfer() -> AbortShardTransfer {
        Arc::new(|_shard_transfer, _reason| {})
    }
