use crate::shards::shard_config::ShardConfig;
use crate::shards::shard_holder::recovery_guard::{
    ActiveRecoveries, RecoveryProgressHandle, ShardRecoveryGuard,
};
use crate::shards::transfer::{ShardTransfer, ShardTransferKey};
use crate::shards::{CollectionId, check_shard_path, shard_initializing_flag_path};

const SHARD_TRANSFERS_FILE: &str = "shard_transfers";
const RESHARDING_STATE_FILE: &str = "resharding_state.json";
pub const SHARD_KEY_MAPPING_FILE: &str = "shard_key_mapping.json";

/// Abort a streamed snapshot if its consumer reads no data for this long.
///
/// The streaming write holds a read lock on the shard's segment holder and
/// occupies a blocking thread, so a stalled consumer must not be allowed to
/// block it forever. See [`TimeoutWriter`].
const SNAPSHOT_STREAM_WRITE_IDLE_TIMEOUT: Duration = Duration::from_secs(5 * 60);

pub struct ShardHolder {
    /// `BTreeMap` for deterministic iteration order by `ShardId` — iteration is externally
    /// observable (fan-out, telemetry, consensus state apply).
    ///
    /// Values are `Arc` so consumers can clone a handle, drop the outer
    /// `ShardHolder` lock, and still operate on the shard. This matters
    /// especially for searches: holding the `ShardHolder` read lock across
    /// every `core_search` await would block writers (e.g. shard creation)
    /// for the duration of the search.
    shards: BTreeMap<ShardId, Arc<ShardReplicaSet>>,
    pub(crate) shard_transfers: SaveOnDisk<HashSet<ShardTransfer>>,
    pub(crate) shard_transfer_changes: broadcast::Sender<ShardTransferChange>,
    pub(crate) resharding_state: SaveOnDisk<Option<ReshardState>>,
    /// Hash rings per shard key
    ///
    /// In case of auto sharding, this only hash a `None` hash ring. In case of custom sharding,
    /// this only has hash rings for defined shard keys excluding `None`.
    pub(crate) rings: HashMap<Option<ShardKey>, HashRingRouter>,
    key_mapping: SaveOnDisk<ShardKeyMapping>,
    // Duplicates the information from `key_mapping` for faster access, does not use locking
    shard_id_to_key_mapping: AHashMap<ShardId, ShardKey>,
    sharding_method: ShardingMethod,
    /// Active snapshot recoveries on this peer (destination side of transfers).
    /// Tracks progress of downloading, unpacking, and restoring snapshots.
    /// Entries are added and removed via [`ShardRecoveryGuard`].
    active_recoveries: ActiveRecoveries,
}

impl ShardHolder {
    pub async fn trigger_optimizers(&self) {
        for shard in self.shards.values() {
            shard.trigger_optimizers().await;
        }
    }

    pub fn new(collection_path: &Path, sharding_method: ShardingMethod) -> CollectionResult<Self> {
        let shard_transfers =
            SaveOnDisk::load_or_init_default(collection_path.join(SHARD_TRANSFERS_FILE))?;
        let resharding_state: SaveOnDisk<Option<ReshardState>> =
            SaveOnDisk::load_or_init_default(collection_path.join(RESHARDING_STATE_FILE))?;

        let key_mapping: SaveOnDisk<ShardKeyMapping> =
            SaveOnDisk::load_or_init_default(collection_path.join(SHARD_KEY_MAPPING_FILE))?;

        let mut shard_id_to_key_mapping = AHashMap::new();

        for (shard_key, shard_ids) in key_mapping.read().iter() {
            for shard_id in shard_ids {
                shard_id_to_key_mapping.insert(*shard_id, shard_key.clone());
            }
        }

        let rings = match sharding_method {
            ShardingMethod::Auto => HashMap::from([(None, HashRingRouter::single())]),
            ShardingMethod::Custom => HashMap::new(),
        };

        let (shard_transfer_changes, _) = broadcast::channel(64);

        Ok(Self {
            shards: BTreeMap::new(),
            shard_transfers,
            shard_transfer_changes,
            resharding_state,
            rings,
            key_mapping,
            shard_id_to_key_mapping,
            sharding_method,
            active_recoveries: ActiveRecoveries::default(),
        })
    }

    pub async fn stop_gracefully(&mut self) {
        let futures = std::mem::take(&mut self.shards)
            .into_values()
            .map(|shard| async move { shard.stop_gracefully().await });
        futures::future::join_all(futures).await;
    }

    pub async fn save_key_mapping_to_tar(
        &self,
        tar: &common::tar_ext::BuilderExt,
    ) -> CollectionResult<()> {
        self.key_mapping
            .save_to_tar(tar, Path::new(SHARD_KEY_MAPPING_FILE))
            .await?;
        Ok(())
    }

    pub fn get_shard_id_to_key_mapping(&self) -> &AHashMap<ShardId, ShardKey> {
        &self.shard_id_to_key_mapping
    }

    pub fn get_shard_key_to_ids_mapping(&self) -> ShardKeyMapping {
        self.key_mapping.read().clone()
    }

    pub fn get_sharding_method(&self) -> ShardingMethod {
        self.sharding_method
    }

    /// Set the shard key mappings
    ///
    /// # Warning
    ///
    /// This does not update the shard key inside replica sets. If the shard key mapping changes
    /// and we have existing replica sets, they must be updated as well to reflect the changed
    /// mappings.
    pub fn set_shard_key_mappings(
        &mut self,
        shard_key_mapping: ShardKeyMapping,
    ) -> CollectionResult<()> {
        let shard_id_to_key_mapping = shard_key_mapping.shard_id_to_shard_key();

        self.key_mapping
            .write_optional(move |_| Some(shard_key_mapping))?;

        self.shard_id_to_key_mapping = shard_id_to_key_mapping;

        Ok(())
    }

    pub async fn drop_and_remove_shard(&mut self, shard_id: ShardId) -> CollectionResult<()> {
        if let Some(replica_set) = self.shards.remove(&shard_id) {
            let shard_path = replica_set.shard_path.clone();
            replica_set.stop_gracefully().await;

            // Explicitly drop shard config file first
            // If removing all shard files at once, it may be possible for the shard configuration
            // file to be left behind if the process is killed in the middle. We must avoid this so
            // we don't attempt to load this shard anymore on restart.
            let shard_config_path = ShardConfig::get_config_path(&shard_path);
            if let Err(err) = tokio_fs::remove_file(&shard_config_path).await {
                log::error!(
                    "Failed to remove shard config file before removing the rest of the files: {err}",
                );
            }
            sync_parent_dir_async(&shard_config_path).await?;

            tokio_fs::remove_dir_all(shard_path).await?;
        }
        Ok(())
    }

    pub fn remove_shard_from_key_mapping(
        &mut self,
        shard_id: ShardId,
        shard_key: &ShardKey,
    ) -> CollectionResult<()> {
        // Idempotent: only rewrite the mapping if the shard id is actually
        // present under this key. A replay after a successful removal finds
        // nothing to remove and skips the unnecessary disk write.
        self.key_mapping.write_optional(|key_mapping| {
            let shard_ids = key_mapping.get(shard_key)?;
            if !shard_ids.contains(&shard_id) {
                return None;
            }

            let mut key_mapping = key_mapping.clone();
            key_mapping.get_mut(shard_key).unwrap().remove(&shard_id);
            Some(key_mapping)
        })?;
        self.shard_id_to_key_mapping.remove(&shard_id);

        Ok(())
    }

    /// ## Cancel safety
    ///
    /// This function is **not** cancel safe.
    pub async fn add_shard(
        &mut self,
        shard_id: ShardId,
        shard: ShardReplicaSet,
        shard_key: Option<ShardKey>,
    ) -> CollectionResult<()> {
        let evicted = self.shards.insert(shard_id, Arc::new(shard));
        if let Some(evicted) = evicted {
            debug_assert!(false, "Overwriting existing shard id {shard_id}");
            evicted.stop_gracefully().await;
        }

        self.rings
            .entry(shard_key.clone())
            .or_insert_with(HashRingRouter::single)
            .add(shard_id);

        if let Some(shard_key) = shard_key {
            self.key_mapping.write_optional(|key_mapping| {
                let has_id = key_mapping
                    .get(&shard_key)
                    .map(|shard_ids| shard_ids.contains(&shard_id))
                    .unwrap_or(false);

                if has_id {
                    return None;
                }
                let mut copy_of_mapping = key_mapping.clone();
                let shard_ids = copy_of_mapping.entry(shard_key.clone()).or_default();
                shard_ids.insert(shard_id);
                Some(copy_of_mapping)
            })?;
            self.shard_id_to_key_mapping.insert(shard_id, shard_key);
        }
        Ok(())
    }

    pub async fn remove_shard_key(&mut self, shard_key: &ShardKey) -> CollectionResult<()> {
        let mut remove_shard_ids = Vec::new();

        self.key_mapping.write_optional(|key_mapping| {
            if key_mapping.contains_key(shard_key) {
                let mut new_key_mapping = key_mapping.clone();
                if let Some(shard_ids) = new_key_mapping.remove(shard_key) {
                    for shard_id in shard_ids {
                        remove_shard_ids.push(shard_id);
                    }
                }
                Some(new_key_mapping)
            } else {
                None
            }
        })?;

        self.rings.remove(&shard_key.clone().into());
        for shard_id in remove_shard_ids {
            self.drop_and_remove_shard(shard_id).await?;
            self.shard_id_to_key_mapping.remove(&shard_id);
        }
        Ok(())
    }

    fn rebuild_rings(&mut self) {
        let mut rings = match self.sharding_method {
            // With auto sharding, we have a single hash ring
            ShardingMethod::Auto => HashMap::from([(None, HashRingRouter::single())]),
            // With custom sharding, we have a hash ring per shard key
            ShardingMethod::Custom => HashMap::new(),
        };

        // Add shards and shard keys
        let ids_to_key = self.get_shard_id_to_key_mapping();
        for shard_id in self.shards.keys() {
            let shard_key = ids_to_key.get(shard_id).cloned();
            debug_assert!(
                matches!(
                    (self.sharding_method, &shard_key),
                    (ShardingMethod::Auto, None) | (ShardingMethod::Custom, Some(_)),
                ),
                "auto sharding cannot have shard key, custom sharding must have shard key ({:?}, {shard_key:?})",
                self.sharding_method,
            );
            rings
                .entry(shard_key)
                .or_insert_with(HashRingRouter::single)
                .add(*shard_id);
        }

        // Restore resharding hash ring if resharding is active and haven't reached
        // `WriteHashRingCommitted` stage yet
        if let Some(state) = self.resharding_state.read().deref() {
            let ring = rings
                .get_mut(&state.shard_key)
                .expect("must have hash ring for current resharding shard key");

            ring.start_resharding(state.shard_id, state.direction);

            if state.stage >= ReshardingStage::WriteHashRingCommitted {
                ring.commit_resharding();
            }
        }

        self.rings = rings;
    }

    pub async fn apply_shards_state(
        &mut self,
        shard_ids: HashSet<ShardId>,
        shard_key_mapping: ShardKeyMapping,
        extra_shards: AHashMap<ShardId, ShardReplicaSet>,
    ) -> CollectionResult<()> {
        for (extra_shard_id, extra_shard) in extra_shards {
            let evicted = self.shards.insert(extra_shard_id, Arc::new(extra_shard));
            if let Some(evicted) = evicted {
                evicted.stop_gracefully().await;
            }
        }

        let all_shard_ids: Vec<ShardId> = self.shards.keys().copied().collect();

        self.set_shard_key_mappings(shard_key_mapping)?;

        for shard_id in all_shard_ids {
            if !shard_ids.contains(&shard_id) {
                self.drop_and_remove_shard(shard_id).await?;
            }
        }

        self.rebuild_rings();

        Ok(())
    }

    pub fn contains_shard(&self, shard_id: ShardId) -> bool {
        self.shards.contains_key(&shard_id)
    }

    pub fn get_shard(&self, shard_id: ShardId) -> Option<&Arc<ShardReplicaSet>> {
        self.shards.get(&shard_id)
    }

    pub fn get_shards(&self) -> impl Iterator<Item = (ShardId, &Arc<ShardReplicaSet>)> {
        self.shards.iter().map(|(id, shard)| (*id, shard))
    }

    pub fn all_shards(&self) -> impl Iterator<Item = &Arc<ShardReplicaSet>> {
        self.shards.values()
    }

    pub fn split_by_shard<O: SplitByShard + Clone>(
        &self,
        operation: O,
        shard_keys_selection: &Option<ShardKey>,
    ) -> CollectionResult<Vec<(&Arc<ShardReplicaSet>, O)>> {
        let Some(hashring) = self.rings.get(&shard_keys_selection.clone()) else {
            return if let Some(shard_key) = shard_keys_selection {
                Err(CollectionError::bad_input(format!(
                    "Shard key {shard_key} not found"
                )))
            } else {
                Err(CollectionError::bad_input(
                    "Shard key not specified".to_string(),
                ))
            };
        };

        if hashring.is_empty() {
            return Err(CollectionError::bad_input(
                "No shards found for shard key".to_string(),
            ));
        }

        let operation_to_shard = operation.split_by_shard(hashring);
        let shard_ops: Vec<_> = match operation_to_shard {
            OperationToShard::ByShard(by_shard) => by_shard
                .into_iter()
                .map(|(shard_id, operation)| (self.shards.get(&shard_id).unwrap(), operation))
                .collect(),
            OperationToShard::ToAll(operation) => {
                if let Some(shard_key) = shard_keys_selection {
                    let shard_ids = self
                        .key_mapping
                        .read()
                        .get(shard_key)
                        .cloned()
                        .unwrap_or_default();
                    shard_ids
                        .into_iter()
                        .map(|shard_id| (self.shards.get(&shard_id).unwrap(), operation.clone()))
                        .collect()
                } else {
                    self.all_shards()
                        .map(|shard| (shard, operation.clone()))
                        .collect()
                }
            }
        };
        Ok(shard_ops)
    }

    pub fn register_start_shard_transfer(&self, transfer: ShardTransfer) -> CollectionResult<bool> {
        let changed = self
            .shard_transfers
            .write(|transfers| transfers.insert(transfer.clone()))?;
        let _ = self
            .shard_transfer_changes
            .send(ShardTransferChange::Start(transfer));
        Ok(changed)
    }

    pub fn register_finish_transfer(&self, key: &ShardTransferKey) -> CollectionResult<bool> {
        let any_removed = self
            .shard_transfers
            .write(|transfers| transfers.extract_if(|transfer| key.check(transfer)).count() > 0)?;
        let _ = self
            .shard_transfer_changes
            .send(ShardTransferChange::Finish(*key));
        Ok(any_removed)
    }

    pub fn register_abort_transfer(&self, key: &ShardTransferKey) -> CollectionResult<bool> {
        let any_removed = self
            .shard_transfers
            .write(|transfers| transfers.extract_if(|transfer| key.check(transfer)).count() > 0)?;
        let _ = self
            .shard_transfer_changes
            .send(ShardTransferChange::Abort(*key));
        Ok(any_removed)
    }

    /// The count of incoming and outgoing shard transfers on the given peer
    ///
    /// This only includes shard transfers that are in consensus for the current collection. A
    /// shard transfer that has just been proposed may not be included yet.
    pub fn count_shard_transfer_io(&self, peer_id: PeerId) -> (usize, usize) {
        let (mut incoming, mut outgoing) = (0, 0);

        for transfer in self.shard_transfers.read().iter() {
            incoming += usize::from(transfer.to == peer_id);
            outgoing += usize::from(transfer.from == peer_id);
        }

        (incoming, outgoing)
    }

    /// Start tracking recovery progress for a shard (destination side).
    ///
    /// Returns a [`ShardRecoveryGuard`] that must be held for the duration of the
    /// recovery. Dropping the guard - on success, error, or cancellation - stops
    /// tracking and removes the progress entry.
    pub fn start_shard_recovery(&self, shard_id: ShardId) -> ShardRecoveryGuard {
        self.active_recoveries.start(shard_id)
    }

    pub fn get_shard_transfer_info(
        &self,
        tasks_pool: &TransferTasksPool,
    ) -> Vec<ShardTransferInfo> {
        let mut shard_transfers = vec![];
        for shard_transfer in self.shard_transfers.read().iter() {
            let shard_id = shard_transfer.shard_id;
            let to_shard_id = shard_transfer.to_shard_id;
            let to = shard_transfer.to;
            let from = shard_transfer.from;
            let sync = shard_transfer.sync;
            let method = shard_transfer.method;

            // Check for active recovery on destination shard first, then sender task status
            let target_shard = to_shard_id.unwrap_or(shard_id);
            let comment = self.active_recoveries.comment(target_shard).or_else(|| {
                tasks_pool
                    .get_task_status(&shard_transfer.key())
                    .map(|p| p.comment)
            });

            shard_transfers.push(ShardTransferInfo {
                shard_id,
                to_shard_id,
                from,
                to,
                sync,
                method,
                comment,
            })
        }
        shard_transfers.sort_by_key(|k| k.shard_id);
        shard_transfers
    }

    pub fn get_resharding_operations_info(&self) -> Option<Vec<ReshardingInfo>> {
        let mut resharding_operations = vec![];

        // We eventually expect to extend this to multiple concurrent operations, which is why
        // we're using a list here
        let Some(resharding_state) = &*self.resharding_state.read() else {
            return None;
        };

        resharding_operations.push(ReshardingInfo {
            uuid: resharding_state.uuid,
            shard_id: resharding_state.shard_id,
            peer_id: resharding_state.peer_id,
            direction: resharding_state.direction,
            shard_key: resharding_state.shard_key.clone(),
            stage: resharding_state.stage,
        });

        resharding_operations.sort_by_key(|k| k.shard_id);
        Some(resharding_operations)
    }

    /// Get all transfers related to the given peer and shard ID pair
    pub fn get_related_transfers(&self, peer_id: PeerId, shard_id: ShardId) -> Vec<ShardTransfer> {
        self.get_transfers(|transfer| transfer.is_source_or_target(peer_id, shard_id))
    }

    pub fn get_shard_ids_by_key(&self, shard_key: &ShardKey) -> CollectionResult<HashSet<ShardId>> {
        match self.key_mapping.read().get(shard_key).cloned() {
            None => Err(CollectionError::bad_request(format!(
                "Shard key {shard_key} not found"
            ))),
            Some(ids) => Ok(ids),
        }
    }

    pub fn select_shards<'a>(
        &'a self,
        shard_selector: &'a ShardSelectorInternal,
    ) -> CollectionResult<Vec<(&'a Arc<ShardReplicaSet>, Option<&'a ShardKey>)>> {
        let mut res = Vec::new();

        let filter_resharding = match shard_selector {
            ShardSelectorInternal::Empty => {
                debug_assert!(false, "Do not expect empty shard selector");
                false
            }
            ShardSelectorInternal::All => {
                let is_custom_sharding = match self.sharding_method {
                    ShardingMethod::Auto => false,
                    ShardingMethod::Custom => true,
                };

                for (&shard_id, shard) in self.shards.iter() {
                    // Technically, we could skip inactive shards regardless of sharding method,
                    // as we do not expect that shard id can even become inactive on all replicas.
                    // (if it happens, means there is a bug)
                    // But for earlier detection of such issues, we only do this check for custom sharding,
                    // where this situation is expected for the case of tenant promotion.
                    if is_custom_sharding && !shard.shard_is_active() {
                        continue;
                    }

                    let shard_key = self.shard_id_to_key_mapping.get(&shard_id);
                    res.push((shard, shard_key));
                }

                true
            }
            ShardSelectorInternal::ShardKey(shard_key) => {
                for shard_id in self.get_shard_ids_by_key(shard_key)? {
                    if let Some(replica_set) = self.shards.get(&shard_id) {
                        res.push((replica_set, Some(shard_key)));
                    } else {
                        debug_assert!(false, "Shard id {shard_id} not found")
                    }
                }

                true
            }
            ShardSelectorInternal::ShardKeys(shard_keys) => {
                for shard_key in shard_keys {
                    for shard_id in self.get_shard_ids_by_key(shard_key)? {
                        if let Some(replica_set) = self.shards.get(&shard_id) {
                            res.push((replica_set, Some(shard_key)));
                        } else {
                            debug_assert!(false, "Shard id {shard_id} not found")
                        }
                    }
                }

                true
            }
            ShardSelectorInternal::ShardKeyWithFallback(key) => {
                let (shard_ids_to_query, used_shard_key) =
                    self.route_with_fallback_for_read(key)?;

                log::trace!("Search routing with fallback: {used_shard_key:?}");

                for shard_id in shard_ids_to_query {
                    if let Some(replica_set) = self.shards.get(&shard_id) {
                        res.push((replica_set, Some(used_shard_key)));
                    } else {
                        debug_assert!(false, "Shard id {shard_id} not found")
                    }
                }

                true
            }
            ShardSelectorInternal::ShardId(shard_id) => {
                if let Some(replica_set) = self.shards.get(shard_id) {
                    res.push((replica_set, self.shard_id_to_key_mapping.get(shard_id)));
                } else {
                    return Err(shard_not_found_error(*shard_id));
                }

                // Exempt from resharding filter. This selector is used by internal per-shard
                // operations, such as the resharding driver reading back migrated points from the
                // new shard, which must be able to reach the shard before it becomes visible to
                // user-facing selectors
                false
            }
        };

        // Filter out shards that must not be queried while resharding, regardless of how they
        // were selected above
        if filter_resharding && let Some(state) = self.resharding_state.read().as_ref() {
            res.retain(|(shard, _)| {
                if state.shard_id != shard.shard_id {
                    return true;
                }

                // Ignore a new resharding shard until it completed point migration
                // The shard will be marked as active at the end of the migration stage
                let resharding_migrating_up = state.direction == ReshardingDirection::Up
                    && state.stage < ReshardingStage::ReadHashRingCommitted;

                // Skip shard being removed by resharding down once the write
                // hash ring is committed. The shard is logically gone at this
                // point; querying it on a remote peer that already applied
                // `finish_resharding` would return a "shard not found" error.
                let resharding_removing_down = state.direction == ReshardingDirection::Down
                    && state.stage >= ReshardingStage::WriteHashRingCommitted;

                !resharding_migrating_up && !resharding_removing_down
            });
        }

        Ok(res)
    }

    /// Common routing logic for reads when using ShardKeyWithFallback
    ///
    /// Example routing:
    ///
    /// request: {"target": "key1", "fallback": "default"}
    ///
    /// Situation 1:
    /// /// - key1 -> shard_ids {1, 2} (both active)
    /// Request is routed to shard_ids {1, 2} of target key1
    ///
    /// Situation 2:
    /// /// - key1 -> no shards found
    /// Request is routed to shard_ids of fallback key "default"
    ///
    /// Situation 3:
    /// /// - key1 -> shard_ids {1} and it is in Partial state (no active replicas)
    /// Request is routed to shard_ids of fallback key "default"
    ///
    /// Situation 4:
    /// /// - key1 -> shard_ids {1, 2} (shard 1 active, shard 2 partial)
    /// Request is routed to shard_ids of fallback key "default"
    ///
    ///
    /// If at least one of target shards is Active, use target shard. If not, redirect to fallback shard
    pub fn route_with_fallback_for_read<'a>(
        &self,
        key: &'a ShardKeyWithFallback,
    ) -> CollectionResult<(HashSet<ShardId>, &'a ShardKey)> {
        let mut shard_key_to_ids_mapping = self.get_shard_key_to_ids_mapping();

        let target_shard_ids = shard_key_to_ids_mapping.remove(&key.target);
        let fallback_shard_ids = shard_key_to_ids_mapping.remove(&key.fallback);

        if let Some(target_shard_ids) = target_shard_ids {
            let target_replicas = target_shard_ids
                .iter()
                .filter_map(|shard_id| self.shards.get(shard_id))
                .collect::<Vec<_>>();

            let target_shards_active = target_replicas
                .iter()
                .all(|replica_set| !replica_set.readable_shards().is_empty());

            if !target_replicas.is_empty() && target_shards_active {
                // 1st condition is required to handle empty shard keys (2nd one returns true)
                Ok((target_shard_ids, &key.target))
            } else if let Some(fallback_shard_ids) = fallback_shard_ids {
                Ok((fallback_shard_ids, &key.fallback))
            } else {
                Err(CollectionError::shard_unavailable(format!(
                    "Neither target shard key {} nor fallback shard key {} have active replicas",
                    key.target, key.fallback
                )))
            }
        } else if let Some(fallback_shard_ids) = fallback_shard_ids {
            Ok((fallback_shard_ids, &key.fallback))
        } else {
            Err(CollectionError::not_found(format!(
                "Neither target shard key {} nor fallback shard key {} exist",
                key.target, key.fallback
            )))
        }
    }

    /// Common routing logic for writes when using ShardKeyWithFallback
    ///
    /// Similar to read routing, but in case if target shard exists, but is in Partial state, we still want
    /// to route to both target and fallback shards to ensure data consistency.
    pub fn route_with_fallback_for_write(
        &self,
        key: ShardKeyWithFallback,
    ) -> CollectionResult<Vec<(HashSet<ShardId>, ShardKey)>> {
        let ShardKeyWithFallback { target, fallback } = key;

        let mut shard_key_to_ids_mapping = self.get_shard_key_to_ids_mapping();

        let target_shard_ids = shard_key_to_ids_mapping.remove(&target);
        let fallback_shard_ids = shard_key_to_ids_mapping.remove(&fallback);

        if let Some(target_shard_ids) = target_shard_ids {
            let target_replicas = target_shard_ids
                .iter()
                .filter_map(|shard_id| self.shards.get(shard_id))
                .collect::<Vec<_>>();

            // Check that at least one active replica per shard exists
            let target_shards_active = target_replicas
                .iter()
                .all(|replica_set| !replica_set.active_shards(false).is_empty());

            if target_replicas.is_empty() {
                return if let Some(fallback_shard_ids) = fallback_shard_ids {
                    Ok(vec![(fallback_shard_ids, fallback)])
                } else {
                    Err(CollectionError::not_found(format!(
                        "Neither target shard key {target} nor fallback shard key {fallback} exist",
                    )))
                };
            }

            if target_shards_active {
                // 1st condition is required to handle empty shard keys (2nd one returns true)
                Ok(vec![(target_shard_ids, target)])
            } else if let Some(fallback_shard_ids) = fallback_shard_ids {
                // target is not active, but it can be in Partial state, so we need extra check

                // Target:
                // Shard_id 1 -> replicas: A (Partial)
                // Shard_id 2 -> replicas: B (Active)
                // In this case target is still receiving updates. We need to fallback.

                // Target:
                // Shard_id 1 -> replicas: A (ActiveRead)
                // Shard_id 2 -> replicas: B (Active)
                // We need to send to both target and fallback to ensure consistency.

                // Target:
                // Shard_id 1 -> replicas: A (Partial) B (Active)
                // This is not possible, as we checked for active shards above

                // Target:
                // Shard_id 1 -> replicas: A (Partial) B (Dead)
                // This is not possible, as we never deactivate last active replica

                // Target:
                // Shard_id 1 -> replicas: A (ActiveRead) B (Dead)
                // This is not possible, as we never deactivate last active replica

                // Target:
                // Shard_id 1 -> replicas: A (ActiveRead)
                // We need to send to both target and fallback to ensure consistency.

                // Target:
                // Shard_id 1 -> replicas: A (Dead)
                // Can be, if transfer failed. We just fallback.

                let is_all_replicas_in_read_active = target_replicas.iter().any(|replica_set| {
                    replica_set.check_peers_state_all(|state| state == ReplicaState::ActiveRead)
                });
                if is_all_replicas_in_read_active {
                    Ok(vec![
                        (target_shard_ids, target),
                        (fallback_shard_ids, fallback),
                    ])
                } else {
                    Ok(vec![(fallback_shard_ids, fallback)])
                }
            } else {
                Err(CollectionError::shard_unavailable(format!(
                    "Neither target shard key {target} nor fallback shard key {fallback} have active replicas",
                )))
            }
        } else if let Some(fallback_shard_ids) = fallback_shard_ids {
            Ok(vec![(fallback_shard_ids, fallback)])
        } else {
            Err(CollectionError::not_found(format!(
                "Neither target shard key {target} nor fallback shard key {fallback} exist",
            )))
        }
    }

    pub fn len(&self) -> usize {
        self.shards.len()
    }

    pub fn is_empty(&self) -> bool {
        self.shards.is_empty()
    }

    #[allow(clippy::too_many_arguments)]
    pub async fn load_shards(
        &mut self,
        collection_path: &Path,
        collection_id: &CollectionId,
        collection_config: Arc<RwLock<CollectionConfigInternal>>,
        effective_optimizers_config: OptimizersConfig,
        shared_storage_config: Arc<SharedStorageConfig>,
        payload_index_schema: Arc<SaveOnDisk<PayloadIndexSchema>>,
        channel_service: ChannelService,
        on_peer_failure: ChangePeerFromState,
        abort_shard_transfer: AbortShardTransfer,
        this_peer_id: PeerId,
        update_runtime: Handle,
        search_runtime: AdaptiveSearchHandle,
        optimizer_resource_budget: ResourceBudget,
    ) {
        let shard_number = collection_config.read().await.params.shard_number.get();

        let (shard_ids_list, shard_id_to_key_mapping) = match self.sharding_method {
            ShardingMethod::Auto => {
                let ids_list = (0..shard_number).collect::<Vec<_>>();
                let shard_id_to_key_mapping = AHashMap::new();
                (ids_list, shard_id_to_key_mapping)
            }
            ShardingMethod::Custom => {
                let shard_id_to_key_mapping = self.get_shard_id_to_key_mapping();
                let ids_list = shard_id_to_key_mapping
                    .keys()
                    .cloned()
                    .sorted()
                    .collect::<Vec<_>>();
                (ids_list, shard_id_to_key_mapping.clone())
            }
        };

        // Concurrently load all shards.
        let shard_id_to_key_mapping_clone = shard_id_to_key_mapping.clone();
        let shard_futures = shard_ids_list.into_iter().map(|shard_id| {
            // Check if shard is fully initialized on disk
            // The initialization flag should be absent for a well-formed replica set
            let initializing_flag = shard_initializing_flag_path(collection_path, shard_id).clone();
            let collection_id = collection_id.clone();
            let collection_config = collection_config.clone();
            let effective_optimizers_config = effective_optimizers_config.clone();
            let shared_storage_config = shared_storage_config.clone();
            let payload_index_schema = payload_index_schema.clone();
            let channel_service = channel_service.clone();
            let on_peer_failure = on_peer_failure.clone();
            let abort_shard_transfer = abort_shard_transfer.clone();
            let update_runtime = update_runtime.clone();
            let search_runtime = search_runtime.clone();
            let shard_key = shard_id_to_key_mapping_clone.get(&shard_id).cloned();
            let optimizer_resource_budget = optimizer_resource_budget.clone();
            async move {
                let shard_key_for_add = shard_key.clone();

                // Check if shard is fully initialized on disk
                let is_dirty_shard = tokio_fs::try_exists(&initializing_flag)
                    .await
                    .unwrap_or(false);

                // Validate that shard exists on disk
                let shard_path = check_shard_path(collection_path, shard_id)
                    .await
                    .expect("Failed to check shard path");

                // Load replica set
                let replica_set = ShardReplicaSet::load(
                    shard_id,
                    shard_key,
                    collection_id,
                    &shard_path,
                    is_dirty_shard,
                    collection_config,
                    effective_optimizers_config,
                    shared_storage_config,
                    payload_index_schema,
                    channel_service,
                    on_peer_failure,
                    abort_shard_transfer,
                    this_peer_id,
                    update_runtime,
                    search_runtime,
                    optimizer_resource_budget,
                )
                .await;

                (replica_set, shard_key_for_add)
            }
        });
        let mut shard_stream = stream::iter(shard_futures).buffer_unordered(
            shared_storage_config
                .load_concurrency_config
                .get_concurrent_shards()
                .get(),
        );
        while let Some((replica_set, shard_key)) = shard_stream.next().await {
            // Change local shards stuck in Initializing state to Active
            let local_peer_id = replica_set.this_peer_id();
            let not_distributed = !shared_storage_config.is_distributed;
            let is_local =
                replica_set.this_peer_id() == local_peer_id && replica_set.is_local().await;
            let is_initializing =
                replica_set.peer_state(local_peer_id) == Some(ReplicaState::Initializing);
            if not_distributed && is_local && is_initializing {
                log::warn!(
                    "Local shard {collection_id}:{} stuck in Initializing state, changing to Active",
                    replica_set.shard_id,
                );
                replica_set
                    .set_replica_state(local_peer_id, ReplicaState::Active)
                    .await
                    .expect("Failed to set local shard state");
            }
            self.add_shard(replica_set.shard_id, replica_set, shard_key)
                .await
                .unwrap();
        }

        // If resharding, rebuild the hash rings because they'll be messed up
        if self.resharding_state.read().is_some() {
            self.rebuild_rings();
        }
    }

    pub fn assert_shard_exists(&self, shard_id: ShardId) -> CollectionResult<()> {
        match self.get_shard(shard_id) {
            Some(_) => Ok(()),
            None => Err(shard_not_found_error(shard_id)),
        }
    }

    async fn assert_shard_is_local(&self, shard_id: ShardId) -> CollectionResult<()> {
        let is_local_shard = self
            .is_shard_local(shard_id)
            .await
            .ok_or_else(|| shard_not_found_error(shard_id))?;

        if is_local_shard {
            Ok(())
        } else {
            Err(CollectionError::bad_input(format!(
                "Shard {shard_id} is not a local shard"
            )))
        }
    }

    async fn assert_shard_is_local_or_queue_proxy(
        &self,
        shard_id: ShardId,
    ) -> CollectionResult<()> {
        let is_local_shard = self
            .is_shard_local_or_queue_proxy(shard_id)
            .await
            .ok_or_else(|| shard_not_found_error(shard_id))?;

        if is_local_shard {
            Ok(())
        } else {
            Err(CollectionError::bad_input(format!(
                "Shard {shard_id} is not a local or queue proxy shard"
            )))
        }
    }

    /// Returns true if shard is explicitly local, false otherwise.
    pub async fn is_shard_local(&self, shard_id: ShardId) -> Option<bool> {
        match self.get_shard(shard_id) {
            Some(shard) => Some(shard.is_local().await),
            None => None,
        }
    }

    /// Returns true if shard is explicitly local or is queue proxy shard, false otherwise.
    pub async fn is_shard_local_or_queue_proxy(&self, shard_id: ShardId) -> Option<bool> {
        match self.get_shard(shard_id) {
            Some(shard) => Some(shard.is_local().await || shard.is_queue_proxy().await),
            None => None,
        }
    }

    /// Return a list of local shards, present on this peer
    pub async fn get_local_shards(&self) -> Vec<ShardId> {
        let mut res = Vec::with_capacity(1);
        for (shard_id, replica_set) in self.get_shards() {
            if replica_set.has_local_shard().await {
                res.push(shard_id);
            }
        }
        res
    }

    pub fn check_transfer_exists(&self, transfer_key: &ShardTransferKey) -> bool {
        self.shard_transfers
            .read()
            .iter()
            .any(|transfer| transfer_key.check(transfer))
    }

    pub fn get_transfer(&self, transfer_key: &ShardTransferKey) -> Option<ShardTransfer> {
        self.shard_transfers
            .read()
            .iter()
            .find(|transfer| transfer_key.check(transfer))
            .cloned()
    }

    pub fn get_transfers<F>(&self, mut predicate: F) -> Vec<ShardTransfer>
    where
        F: FnMut(&ShardTransfer) -> bool,
    {
        self.shard_transfers
            .read()
            .iter()
            .filter(|&transfer| predicate(transfer))
            .cloned()
            .collect()
    }

    pub fn get_outgoing_transfers(&self, current_peer_id: PeerId) -> Vec<ShardTransfer> {
        self.get_transfers(|transfer| transfer.from == current_peer_id)
    }

    /// # Cancel safety
    ///
    /// This method is cancel safe.
    pub async fn list_shard_snapshots(
        &self,
        snapshots_path: &Path,
        shard_id: ShardId,
    ) -> CollectionResult<Vec<SnapshotDescription>> {
        self.assert_shard_is_local(shard_id).await?;

        let snapshots_path = Self::snapshots_path_for_shard_unchecked(snapshots_path, shard_id);

        let shard = self
            .get_shard(shard_id)
            .ok_or_else(|| shard_not_found_error(shard_id))?;
        let snapshot_manager = shard.get_snapshots_storage_manager()?;
        snapshot_manager.list_snapshots(&snapshots_path).await
    }

    /// # Cancel safety
    ///
    /// This method is cancel safe.
    pub async fn create_shard_snapshot(
        &self,
        snapshots_path: &Path,
        collection_name: &str,
        shard_id: ShardId,
        temp_dir: &Path,
    ) -> CollectionResult<impl Future<Output = CollectionResult<SnapshotDescription>> + use<>> {
        // - `snapshot_temp_dir` and `temp_file` are handled by `tempfile`
        //   and would be deleted, if future is canceled

        let shard = self
            .get_shard(shard_id)
            .ok_or_else(|| shard_not_found_error(shard_id))?;

        if !shard.is_local().await && !shard.is_queue_proxy().await {
            return Err(CollectionError::bad_input(format!(
                "Shard {shard_id} is not a local or queue proxy shard"
            )));
        }

        let snapshot_file_name = format!(
            "{collection_name}-shard-{shard_id}-{}.snapshot",
            chrono::Utc::now().format("%Y-%m-%d-%H-%M-%S"),
        );

        let snapshot_temp_dir = tempfile::Builder::new()
            .prefix(&format!("{snapshot_file_name}-temp-"))
            .tempdir_in(temp_dir)?;

        let temp_file = tempfile::Builder::new()
            .prefix(&format!("{snapshot_file_name}-"))
            .suffix(".tar")
            .tempfile_in(temp_dir)?;

        let snapshots_path = snapshots_path.to_path_buf();
        let snapshot_manager = shard.get_snapshots_storage_manager()?;

        let tar = BuilderExt::new_seekable_owned(File::create(temp_file.path())?);

        let snapshot_creator = shard
            .create_snapshot(
                snapshot_temp_dir.path(),
                tar.clone(),
                SnapshotFormat::Regular,
                None,
                false,
            )
            .await?;

        let future = async move {
            snapshot_creator.await?;

            let snapshot_temp_dir_path = snapshot_temp_dir.path().to_path_buf();
            if let Err(err) = snapshot_temp_dir.close() {
                log::error!(
                    "Failed to remove temporary directory {}: {err}",
                    snapshot_temp_dir_path.display(),
                );
            }

            tar.finish().await?;

            let snapshot_path =
                Self::shard_snapshot_path_unchecked(&snapshots_path, shard_id, snapshot_file_name)?;

            let snapshot_description = snapshot_manager
                .store_file(temp_file.path(), &snapshot_path)
                .await;
            if snapshot_description.is_ok() {
                let _ = temp_file.keep();
            }
            snapshot_description
        };

        Ok(future)
    }

    /// # Cancel safety
    ///
    /// This method is cancel safe.
    pub async fn stream_shard_snapshot(
        shard: OwnedRwLockReadGuard<ShardHolder, Arc<ShardReplicaSet>>,
        collection_name: &str,
        shard_id: ShardId,
        manifest: Option<SnapshotManifest>,
        temp_dir: &Path,
    ) -> CollectionResult<SnapshotStream> {
        // - `snapshot_temp_dir` and `temp_file` are handled by `tempfile`
        //   and would be deleted, if future is cancelled

        if !shard.is_local().await && !shard.is_queue_proxy().await {
            return Err(CollectionError::bad_input(format!(
                "Shard {shard_id} is not a local or queue proxy shard"
            )));
        }

        let snapshot_file_name = format!(
            "{collection_name}-shard-{shard_id}-{}.snapshot",
            chrono::Utc::now().format("%Y-%m-%d-%H-%M-%S"),
        );

        let snapshot_temp_dir = tempfile::Builder::new()
            .prefix(&format!("{snapshot_file_name}-temp-"))
            .tempdir_in(temp_dir)?;

        let (read_half, write_half) = tokio::io::duplex(4096);

        // Abort the snapshot if the consumer stops draining the stream. This
        // write holds a read lock on the shard's segment holder and occupies a
        // blocking thread; without a timeout, a stalled consumer (e.g. a slow or
        // hung client) would block the segment holder and leak the thread
        // indefinitely, wedging the whole shard.
        let write_half = TimeoutWriter::new(write_half, SNAPSHOT_STREAM_WRITE_IDLE_TIMEOUT);

        let tar = BuilderExt::new_streaming_owned(SyncIoBridge::new(write_half));

        let snapshot_creator = shard
            .create_snapshot(
                snapshot_temp_dir.path(),
                tar.clone(),
                SnapshotFormat::Streamable,
                manifest,
                false,
            )
            .await?;

        drop(shard);

        let future = async move {
            snapshot_creator.await?;

            let snapshot_temp_dir_path = snapshot_temp_dir.path().to_path_buf();
            if let Err(err) = snapshot_temp_dir.close() {
                log::error!(
                    "Failed to remove temporary directory {}: {err}",
                    snapshot_temp_dir_path.display(),
                );
            }

            tar.finish().await?;

            CollectionResult::Ok(())
        };

        tokio::spawn(async move {
            if let Err(err) = future.await {
                log::error!("Failed to stream shard snapshot: {err}");
            }
        });

        Ok(SnapshotStream::new_stream(
            FramedRead::new(read_half, BytesCodec::new()).map_ok(|bytes| bytes.freeze()),
            Some(snapshot_file_name),
        ))
    }

    /// # Cancel safety
    ///
    /// This method is *not* cancel safe.
    #[allow(clippy::too_many_arguments)]
    pub async fn restore_shard_snapshot(
        &self,
        snapshot_data: SnapshotData,
        recovery_type: RecoveryType,
        collection_path: &Path,
        collection_name: &str,
        shard_id: ShardId,
        this_peer_id: PeerId,
        is_distributed: bool,
        temp_dir: &Path,
        recovery_progress: Option<RecoveryProgressHandle>,
        cancel: cancel::CancellationToken,
    ) -> CollectionResult<()> {
        if !self.contains_shard(shard_id) {
            return Err(shard_not_found_error(shard_id));
        }

        if !temp_dir.exists() {
            fs::create_dir_all(temp_dir)?;
        }

        let snapshot_temp_dir = tempfile::Builder::new()
            .prefix(&format!("{collection_name}-shard-{shard_id}"))
            .tempdir_in(temp_dir)?;

        // Set unpacking stage
        if let Some(recovery_progress) = &recovery_progress {
            recovery_progress.lock().set_stage(RecoveryStage::Unpacking);
        }

        let extract = {
            let snapshot_temp_dir = snapshot_temp_dir.path().to_path_buf();

            cancel::blocking::spawn_cancel_on_token(
                cancel.child_token(),
                move |cancel| -> CollectionResult<_> {
                    match snapshot_data {
                        SnapshotData::Packed(snapshot_path) => {
                            if cancel.is_cancelled() {
                                return Err(cancel::Error::Cancelled.into());
                            }
                            tar_unpack_file(&snapshot_path, &snapshot_temp_dir)?;
                            snapshot_path.close()?;
                        }
                        SnapshotData::Unpacked(snapshot_dir) => {
                            move_all(snapshot_dir.path(), &snapshot_temp_dir)?;
                        }
                    }

                    if cancel.is_cancelled() {
                        return Err(cancel::Error::Cancelled.into());
                    }

                    ShardReplicaSet::restore_snapshot(
                        &snapshot_temp_dir,
                        this_peer_id,
                        is_distributed,
                    )?;
                    common::fs::bulk_sync_dir(&snapshot_temp_dir)?;

                    Ok(())
                },
            )
        };

        extract.await??;

        // Set restoring stage
        if let Some(recovery_progress) = &recovery_progress {
            recovery_progress.lock().set_stage(RecoveryStage::Restoring);
        }

        // `ShardHolder::recover_local_shard_from` is *not* cancel safe
        // (see `ShardReplicaSet::restore_local_replica_from`)
        let recovered = self
            .recover_local_shard_from(
                snapshot_temp_dir.path(),
                recovery_type,
                collection_path,
                shard_id,
                cancel,
            )
            .await?;

        if !recovered {
            return Err(CollectionError::bad_request("Invalid snapshot"));
        }

        if recovery_type.is_partial() {
            self.update_payload_index_schema().await.map_err(|err| {
                CollectionError::service_error(format!(
                    "failed to update payload index schema after recovering partial snapshot: {err}"
                ))
            })?;
        }

        Ok(())
    }

    /// # Cancel safety
    ///
    /// This method is *not* cancel safe.
    pub async fn recover_local_shard_from(
        &self,
        snapshot_shard_path: &Path,
        recovery_type: RecoveryType,
        collection_path: &Path,
        shard_id: ShardId,
        cancel: cancel::CancellationToken,
    ) -> CollectionResult<bool> {
        // TODO:
        //   Check that shard snapshot is compatible with the collection
        //   (see `VectorsConfig::check_compatible_with_segment_config`)

        let replica_set = self
            .get_shard(shard_id)
            .ok_or_else(|| shard_not_found_error(shard_id))?;

        // `ShardReplicaSet::restore_local_replica_from` is *not* cancel safe
        let res = replica_set
            .restore_local_replica_from(snapshot_shard_path, recovery_type, collection_path, cancel)
            .await?;

        Ok(res)
    }

    pub async fn update_payload_index_schema(&self) -> CollectionResult<()> {
        let payload_index_schema = self
            .all_shards()
            .next()
            .map(|shard| shard.payload_index_schema());

        let Some(payload_index_schema) = payload_index_schema else {
            // Shard holder contains no shards
            return Ok(());
        };

        let schema = self.common_payload_index_schema().await?;

        payload_index_schema.write(|payload_index_schema| {
            *payload_index_schema = PayloadIndexSchema { schema };
        })?;

        Ok(())
    }

    async fn common_payload_index_schema(
        &self,
    ) -> CollectionResult<HashMap<JsonPath, PayloadFieldSchema>> {
        let mut schema = HashMap::new();

        for (shard_idx, shard) in self.all_shards().enumerate() {
            let shard_schema: HashMap<_, _> = shard
                .info(true)
                .await?
                .payload_schema
                .into_iter()
                .filter_map(|(field, info)| {
                    let schema = match PayloadFieldSchema::try_from(info) {
                        Ok(schema) => schema,
                        Err(err) => {
                            log::warn!(
                                "Failed to extract payload index schema from payload index info: \
                                 {err}"
                            );

                            return None;
                        }
                    };

                    Some((field, schema))
                })
                .collect();

            if shard_idx == 0 {
                schema = shard_schema;
            } else {
                schema.retain(|field, schema| {
                    let Some(shard_schema) = shard_schema.get(field) else {
                        return false;
                    };

                    schema == shard_schema
                });
            }

            if schema.is_empty() {
                break;
            }
        }

        Ok(schema)
    }

    pub fn try_take_partial_snapshot_recovery_lock(
        &self,
        shard_id: ShardId,
        recovery_type: RecoveryType,
    ) -> CollectionResult<Option<tokio::sync::OwnedRwLockWriteGuard<()>>> {
        match recovery_type {
            RecoveryType::Full => Ok(None),
            RecoveryType::Partial => {
                let lock = self
                    .get_shard(shard_id)
                    .ok_or_else(|| shard_not_found_error(shard_id))?
                    .try_take_partial_snapshot_recovery_lock()?;

                Ok(Some(lock))
            }
        }
    }

    /// # Cancel safety
    ///
    /// This method is cancel safe.
    pub async fn get_shard_snapshot_path(
        &self,
        snapshots_path: &Path,
        shard_id: ShardId,
        snapshot_file_name: impl AsRef<Path>,
    ) -> CollectionResult<PathBuf> {
        self.assert_shard_is_local_or_queue_proxy(shard_id).await?;
        Self::shard_snapshot_path_unchecked(snapshots_path, shard_id, snapshot_file_name)
    }

    fn snapshots_path_for_shard_unchecked(snapshots_path: &Path, shard_id: ShardId) -> PathBuf {
        snapshots_path.join(format!("shards/{shard_id}"))
    }

    fn shard_snapshot_path_unchecked(
        snapshots_path: &Path,
        shard_id: ShardId,
        snapshot_file_name: impl AsRef<Path>,
    ) -> CollectionResult<PathBuf> {
        let snapshots_path = Self::snapshots_path_for_shard_unchecked(snapshots_path, shard_id);

        let snapshot_file_name = snapshot_file_name.as_ref();

        if snapshot_file_name.file_name() != Some(snapshot_file_name.as_os_str()) {
            return Err(CollectionError::not_found(format!(
                "Snapshot {}",
                snapshot_file_name.display(),
            )));
        }

        let snapshot_path = snapshots_path.join(snapshot_file_name);

        Ok(snapshot_path)
    }

    pub async fn remove_shards_at_peer(&self, peer_id: PeerId) -> CollectionResult<()> {
        for (_shard_id, replica_set) in self.get_shards() {
            replica_set.remove_peer(peer_id).await?;
        }
        Ok(())
    }

    /// Estimates the collections size based on local shard data. Returns `None` if no shard for the collection was found locally.
    pub async fn estimate_collection_size_stats(
        &self,
    ) -> CollectionResult<Option<CollectionSizeStats>> {
        if self.is_distributed().await {
            // In distributed, we estimate the whole collection size by using a single local shard and multiply by amount of shards in the collection.
            for shard in self.shards.iter() {
                if let Some(shard_stats) = shard.1.calculate_local_shard_stats().await? {
                    // TODO(resharding) take into account the ongoing resharding and exclude shards that are being filled from multiplication.
                    // Project the single shards size to the full collection.
                    let collection_estimate = shard_stats.multiplied_with(self.shards.len());
                    return Ok(Some(collection_estimate));
                }
            }

            return Ok(None);
        }

        // Local mode: return collection size estimations using all shards.
        let mut stats = CollectionSizeStats::default();
        for shard in self.shards.iter() {
            if let Some(shard_stats) = shard.1.calculate_local_shard_stats().await? {
                stats.accumulate_metrics_from(&shard_stats);
            }
        }

        Ok(Some(stats))
    }

    /// Returns `true` if the collection is distributed across multiple nodes.
    async fn is_distributed(&self) -> bool {
        stream::iter(self.shards.iter())
            .any(|i| async { i.1.has_remote_shard().await })
            .await
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) enum ShardTransferChange {
    Start(ShardTransfer),
    Finish(ShardTransferKey),
    Abort(ShardTransferKey),
}

pub fn shard_not_found_error(shard_id: ShardId) -> CollectionError {
    CollectionError::not_found(format!("shard {shard_id}"))
}use std::collections::HashMap;
use std::sync::Arc;

use parking_lot::Mutex;

use crate::shards::shard::ShardId;
use crate::shards::transfer::RecoveryStage;
use crate::shards::transfer::transfer_tasks_pool::RecoveryProgress;

/// Shared handle to a single recovery's progress.
///
/// Obtained from a [`ShardRecoveryGuard`] via [`ShardRecoveryGuard::progress_handle`]
/// and threaded into the recovery sub-steps so they update *this* recovery's progress
/// directly, rather than re-resolving the current map entry by shard id (which a newer
/// recovery for the same shard may have already replaced).
pub type RecoveryProgressHandle = Arc<Mutex<RecoveryProgress>>;

/// Tracks active snapshot recoveries on a peer (destination side of transfers),
/// keyed by shard id.
///
/// This is a cheaply cloneable handle around a shared map. Recoveries are started
/// via [`ActiveRecoveries::start`], which returns a [`ShardRecoveryGuard`] that
/// removes the entry again on drop.
#[derive(Clone, Default)]
pub struct ActiveRecoveries {
    recoveries: Arc<Mutex<HashMap<ShardId, RecoveryProgressHandle>>>,
}

impl ActiveRecoveries {
    /// Start tracking a recovery for `shard_id`, returning a guard that stops
    /// tracking on drop.
    pub fn start(&self, shard_id: ShardId) -> ShardRecoveryGuard {
        let progress = Arc::new(Mutex::new(RecoveryProgress::new()));
        self.recoveries
            .lock()
            .insert(shard_id, Arc::clone(&progress));
        ShardRecoveryGuard {
            active_recoveries: self.clone(),
            shard_id,
            progress,
        }
    }

    /// Format the recovery progress comment for `shard_id`, if a recovery is active.
    pub fn comment(&self, shard_id: ShardId) -> Option<String> {
        self.recoveries
            .lock()
            .get(&shard_id)
            .and_then(|progress| progress.lock().format_comment())
    }

    /// Remove the entry for `shard_id`, but only if it still points at `progress`,
    /// so a newer recovery for the same shard is never clobbered.
    fn remove(&self, shard_id: ShardId, progress: &RecoveryProgressHandle) {
        let mut recoveries = self.recoveries.lock();
        if let Some(current) = recoveries.get(&shard_id)
            && Arc::ptr_eq(current, progress)
        {
            recoveries.remove(&shard_id);
        }
    }
}

/// RAII guard for tracking an active snapshot recovery on the destination side.
///
/// While held, the recovery progress is registered in [`ActiveRecoveries`] so it can
/// be reported in the transfer status. On drop - including early returns, errors, and
/// cancellation - the entry is removed again, ensuring that stale recovery comments
/// are never reported for subsequent transfers.
pub struct ShardRecoveryGuard {
    active_recoveries: ActiveRecoveries,
    shard_id: ShardId,
    progress: RecoveryProgressHandle,
}

impl ShardRecoveryGuard {
    /// Update the recovery stage of *this* recovery.
    pub fn set_stage(&self, stage: RecoveryStage) {
        self.progress.lock().set_stage(stage);
    }

    /// A shared handle to this recovery's progress, for threading into recovery
    /// sub-steps that need to update the stage. Bound to this guard's own entry, so
    /// updates never leak into a newer recovery for the same shard.
    pub fn progress_handle(&self) -> RecoveryProgressHandle {
        Arc::clone(&self.progress)
    }
}

impl Drop for ShardRecoveryGuard {
    fn drop(&mut self) {
        self.active_recoveries.remove(self.shard_id, &self.progress);
    }
}use std::collections::{HashMap, HashSet};
use std::fmt;
use std::ops::Deref as _;
use std::sync::Arc;

use common::counter::hardware_accumulator::HwMeasurementAcc;
use common::types::DeferredBehavior;
use segment::types::{Condition, CustomIdCheckerCondition as _, Filter, ShardKey};
use shard::operations::point_ops::UpdateMode;

use super::ShardHolder;
use crate::config::ShardingMethod;
use crate::hash_ring::{self, HashRingRouter};
use crate::operations::CollectionUpdateOperations;
use crate::operations::cluster_ops::ReshardingDirection;
use crate::operations::point_ops::{ConditionalInsertOperationInternal, PointOperations};
use crate::operations::types::{CollectionError, CollectionResult};
use crate::shards::replica_set::ShardReplicaSet;
use crate::shards::replica_set::replica_set_state::ReplicaState;
use crate::shards::resharding::{ReshardKey, ReshardState, ReshardingStage};
use crate::shards::shard::ShardId;

impl ShardHolder {
    pub fn resharding_state(&self) -> Option<ReshardState> {
        self.resharding_state.read().clone()
    }

    pub fn check_start_resharding(&mut self, resharding_key: &ReshardKey) -> CollectionResult<()> {
        let ReshardKey {
            uuid: _,
            direction,
            peer_id: _,
            shard_id,
            shard_key,
        } = resharding_key;

        // Additional shard key check
        // For auto sharding no shard key must be provided, with custom sharding it must be provided
        match self.sharding_method {
            ShardingMethod::Auto => {
                if shard_key.is_some() {
                    return Err(CollectionError::bad_request(format!(
                        "cannot specify shard key {} on collection with auto sharding",
                        shard_key_fmt(shard_key),
                    )));
                }
            }
            ShardingMethod::Custom => {
                if shard_key.is_none() {
                    return Err(CollectionError::bad_request(
                        "must specify shard key on collection with custom sharding",
                    ));
                }
            }
        }

        let ring = get_ring(&mut self.rings, shard_key)?;

        {
            let state = self.resharding_state.read();
            assert_resharding_state_consistency(&state, ring, shard_key);

            if let Some(state) = state.deref() {
                // Idempotent: a matching state means start_resharding was
                // already applied on this peer. Caller falls through each
                // step to reconcile any partially-applied state, so we must
                // not short-circuit with an error that would be silently
                // swallowed by apply_entries and cause divergence.
                return if state.matches(resharding_key) {
                    Ok(())
                } else {
                    Err(CollectionError::bad_request(format!(
                        "another resharding is in progress:\n{state:#?}"
                    )))
                };
            }
        }

        // Don't remove the last shard if resharding down
        if matches!(direction, ReshardingDirection::Down) {
            let shard_count = match shard_key {
                Some(shard_key) => self
                    .get_shard_key_to_ids_mapping()
                    .get(shard_key)
                    .map_or(0, |shards| shards.len()),
                None => self.shards.len(),
            };
            if shard_count <= 1 {
                return Err(CollectionError::bad_request(format!(
                    "cannot remove shard {shard_id} by resharding down, it is the last shard",
                )));
            }
        }

        let has_shard = self.shards.contains_key(shard_id);
        match resharding_key.direction {
            ReshardingDirection::Up => {
                if has_shard {
                    // Idempotent: the replica set may already exist as a
                    // leftover from a previous partial apply or as the result
                    // of an earlier successful apply we are replaying. The
                    // caller skips create_replica_set in that case and falls
                    // through; we must not block on this condition.
                    log::warn!(
                        "Shard {shard_id} already exists during resharding start, \
                         treating as idempotent re-apply and reusing existing replica set",
                    );
                }
            }
            ReshardingDirection::Down => {
                if !has_shard {
                    return Err(CollectionError::bad_request(format!(
                        "shard holder does not contain shard {shard_id} replica set",
                    )));
                }
            }
        }

        // TODO(resharding): Check that peer exists!?

        Ok(())
    }

    // TODO: do not leave broken intermediate state if this fails midway?
    /// ## Cancel safety
    ///
    /// This function is **not** cancel safe.
    pub async fn start_resharding_unchecked(
        &mut self,
        resharding_key: ReshardKey,
        new_shard: Option<ShardReplicaSet>,
    ) -> CollectionResult<()> {
        let ReshardKey {
            uuid,
            direction,
            peer_id,
            shard_id,
            shard_key,
        } = resharding_key;

        // TODO(resharding): Delete shard on error!?

        let ring_res = get_ring(&mut self.rings, &shard_key);
        let ring = match ring_res {
            Ok(ring) => ring,
            Err(err) => {
                if let Some(new_shard) = new_shard {
                    new_shard.stop_gracefully().await;
                }
                return Err(err);
            }
        };
        ring.start_resharding(shard_id, direction);

        // Add new shard if resharding up
        if let Some(new_shard) = new_shard {
            debug_assert_eq!(direction, ReshardingDirection::Up);
            self.add_shard(shard_id, new_shard, shard_key.clone())
                .await?;
        }

        // Idempotent: if matching state is already persisted (replay after a
        // successful apply), leave it alone. Only write if missing or stale.
        self.resharding_state.write_optional(|state| {
            let new_state =
                ReshardState::new(uuid, direction, peer_id, shard_id, shard_key.clone());
            match state {
                Some(existing) if *existing == new_state => None,
                _ => Some(Some(new_state)),
            }
        })?;

        Ok(())
    }

    pub fn commit_read_hashring(&mut self, resharding_key: &ReshardKey) -> CollectionResult<()> {
        // Idempotent: if no resharding is active, or the stage is already at/past
        // ReadHashRingCommitted, this entry was already applied. Return Ok to
        // prevent silent state divergence via apply_entries error swallowing.
        match self.resharding_state.read().deref() {
            None => {
                log::warn!(
                    "commit_read_hashring: no resharding in progress for {resharding_key}, treating as already committed",
                );
                return Ok(());
            }
            Some(state)
                if state.matches(resharding_key)
                    && state.stage >= ReshardingStage::ReadHashRingCommitted =>
            {
                log::warn!(
                    "commit_read_hashring: read hashring already committed for {resharding_key}, skipping",
                );
                return Ok(());
            }
            _ => {}
        }

        self.check_resharding(
            resharding_key,
            check_stage(ReshardingStage::MigratingPoints),
        )?;

        self.resharding_state.write(|state| {
            let Some(state) = state else {
                unreachable!();
            };

            state.stage = ReshardingStage::ReadHashRingCommitted;
        })?;

        Ok(())
    }

    pub fn commit_write_hashring(&mut self, resharding_key: &ReshardKey) -> CollectionResult<()> {
        // Idempotent: if no resharding is active, or the stage is already at/past
        // WriteHashRingCommitted, this entry was already applied.
        match self.resharding_state.read().deref() {
            None => {
                log::warn!(
                    "commit_write_hashring: no resharding in progress for {resharding_key}, treating as already committed",
                );
                return Ok(());
            }
            Some(state)
                if state.matches(resharding_key)
                    && state.stage >= ReshardingStage::WriteHashRingCommitted =>
            {
                log::warn!(
                    "commit_write_hashring: write hashring already committed for {resharding_key}, skipping",
                );
                return Ok(());
            }
            _ => {}
        }

        self.check_resharding(
            resharding_key,
            check_stage(ReshardingStage::ReadHashRingCommitted),
        )?;

        let ring = get_ring(&mut self.rings, &resharding_key.shard_key)?;
        ring.commit_resharding();

        self.resharding_state.write(|state| {
            let Some(state) = state else {
                unreachable!();
            };

            state.stage = ReshardingStage::WriteHashRingCommitted;
        })?;

        Ok(())
    }

    pub fn check_finish_resharding(&mut self, resharding_key: &ReshardKey) -> CollectionResult<()> {
        // Idempotent: if no resharding is active, finish was already applied.
        if self.resharding_state.read().is_none() {
            log::warn!(
                "check_finish_resharding: no resharding in progress for {resharding_key}, treating as already finished",
            );
            return Ok(());
        }

        self.check_resharding(
            resharding_key,
            check_stage(ReshardingStage::WriteHashRingCommitted),
        )?;

        Ok(())
    }

    pub fn finish_resharding_unchecked(&mut self, _: &ReshardKey) -> CollectionResult<()> {
        // Idempotent: if state is already cleared (replay after a successful
        // finish/abort), leave it alone so we don't spuriously touch the file.
        self.resharding_state.write_optional(
            |state| {
                if state.is_some() { Some(None) } else { None }
            },
        )?;

        Ok(())
    }

    fn check_resharding(
        &mut self,
        resharding_key: &ReshardKey,
        check_state: impl Fn(&ReshardState) -> CollectionResult<()>,
    ) -> CollectionResult<()> {
        let ReshardKey {
            shard_id,
            shard_key,
            ..
        } = resharding_key;

        let ring = get_ring(&mut self.rings, shard_key)?;

        let state = self.resharding_state.read();
        assert_resharding_state_consistency(&state, ring, &resharding_key.shard_key);

        match state.deref() {
            Some(state) if state.matches(resharding_key) => {
                check_state(state)?;
            }

            Some(state) => {
                return Err(CollectionError::bad_request(format!(
                    "another resharding is in progress:\n{state:#?}"
                )));
            }

            None => {
                return Err(CollectionError::bad_request(
                    "resharding is not in progress",
                ));
            }
        }

        debug_assert!(
            self.shards.contains_key(shard_id),
            "shard holder does not contain shard {shard_id} replica set"
        );

        // TODO(resharding): Assert that peer exists!?

        Ok(())
    }

    pub fn check_abort_resharding(&self, resharding_key: &ReshardKey) -> CollectionResult<()> {
        let state = self.resharding_state.read();

        let Some(state) = state.deref() else {
            // Idempotent: no resharding in progress means the abort (or finish)
            // was already applied, or the start was never applied on this node.
            // Returning an error here would be silently swallowed by apply_entries,
            // causing permanent state divergence between peers.
            log::warn!(
                "check_abort_resharding: no resharding in progress for {resharding_key}, treating as already aborted",
            );
            return Ok(());
        };

        if !state.matches(resharding_key) {
            // Idempotent: a different resharding is active, so the one we're
            // trying to abort was already handled. Same reasoning as above.
            log::warn!(
                "check_abort_resharding: resharding {resharding_key} not found, current resharding has key {}, treating as already aborted",
                state.key(),
            );
            return Ok(());
        }

        if state.stage < ReshardingStage::ReadHashRingCommitted {
            return Ok(());
        }

        Err(CollectionError::bad_request(format!(
            "can't abort resharding {resharding_key}, \
             because read hash ring has been committed already, \
             resharding must be completed",
        )))
    }

    pub async fn abort_resharding(
        &mut self,
        resharding_key: ReshardKey,
        force: bool,
    ) -> CollectionResult<()> {
        log::warn!("Aborting resharding {resharding_key} (force: {force})");

        let ReshardKey {
            uuid: _,
            direction,
            peer_id: _,
            shard_id,
            ref shard_key,
        } = resharding_key;

        // Cleanup existing shards if resharding down
        if direction == ReshardingDirection::Down {
            for (&id, shard) in self.shards.iter() {
                // Skip shards that does not belong to resharding shard key
                if self.shard_id_to_key_mapping.get(&id) != shard_key.as_ref() {
                    continue;
                }

                // Skip target shard
                if id == shard_id {
                    continue;
                }

                // Revert replicas in `Resharding` state back into `Active` state
                for (peer, state) in shard.peers() {
                    if state.is_resharding() {
                        shard.set_replica_state(peer, ReplicaState::Active).await?;
                    }
                }

                // We only cleanup local shards
                if !shard.is_local().await {
                    continue;
                }

                // Remove any points that might have been transferred from target shard
                // Replica may be dead, so we force the delete operation
                let filter = self.hash_ring_filter(id).expect("hash ring filter");
                let filter = Filter::new_must_not(Condition::new_custom(Arc::new(filter)));
                shard
                    .delete_local_points(
                        filter,
                        // Internal operation, no performance tracking needed
                        HwMeasurementAcc::disposable(),
                        true,
                        DeferredBehavior::IncludeAll,
                    )
                    .await?;
            }
        }

        if let Some(ring) = self.rings.get_mut(shard_key) {
            log::debug!("reverting resharding hashring for shard {shard_id}");
            ring.abort_resharding(shard_id, direction);
        } else {
            log::warn!(
                "aborting resharding {resharding_key}, \
                 but {shard_key:?} hashring does not exist"
            );
        }

        // Remove new shard if resharding up
        if direction == ReshardingDirection::Up {
            if let Some(shard) = self.get_shard(shard_id) {
                // Remove all replicas from shard
                for (peer_id, replica_state) in shard.peers() {
                    log::debug!(
                        "removing peer {peer_id} with state {replica_state:?} from replica set {shard_id}",
                    );
                    shard.remove_peer(peer_id).await?;
                }

                debug_assert!(
                    shard.peers().is_empty(),
                    "replica set {shard_id} must be empty after removing all peers",
                );

                log::debug!("removing replica set {shard_id}");

                // Drop the shard
                if let Some(shard_key) = shard_key {
                    // Idempotent: only rewrite the mapping if the shard id is
                    // actually present under this key. A replay after a
                    // successful abort finds nothing to remove and skips the
                    // unnecessary disk write.
                    self.key_mapping.write_optional(|key_mapping| {
                        let shard_ids = key_mapping.get(shard_key)?;
                        if !shard_ids.contains(&shard_id) {
                            return None;
                        }

                        let mut key_mapping = key_mapping.clone();
                        key_mapping.get_mut(shard_key).unwrap().remove(&shard_id);

                        Some(key_mapping)
                    })?;
                }

                self.drop_and_remove_shard(shard_id).await?;
                self.shard_id_to_key_mapping.remove(&shard_id);
            } else {
                log::warn!(
                    "aborting resharding {resharding_key}, \
                     but shard holder does not contain {shard_id} replica set",
                );
            }
        }

        // Idempotent: if state is already cleared, or holds a different
        // resharding (already superseded), leave it alone. Only clear a state
        // that matches the resharding_key we are aborting.
        self.resharding_state.write_optional(|state| match state {
            Some(state) if state.matches(&resharding_key) => Some(None),
            _ => None,
        })?;

        Ok(())
    }

    /// Split collection update operation by "update mode":
    /// - update all:
    ///   - "regular" operation
    ///   - `upsert` inserts new points and updates existing ones
    ///   - other update operations return error, if a point does not exist in collection
    /// - update existing:
    ///   - `upsert` does *not* insert new points, only updates existing ones
    ///   - other update operations ignore points that do not exist in collection
    ///
    /// Depends on the current resharding state. If resharding is not active operations are not split.
    pub fn split_by_mode(
        &self,
        shard_id: ShardId,
        operation: CollectionUpdateOperations,
    ) -> OperationsByMode {
        let Some(state) = self.resharding_state() else {
            return OperationsByMode::from(operation);
        };

        // Resharding *UP*
        // ┌────────────┐   ┌──────────┐
        // │            │   │          │
        // │ Shard 1    │   │ Shard 2  │
        // │ Non-Target ├──►│ Target   │
        // │ Sender     │   │ Receiver │
        // │            │   │          │
        // └────────────┘   └──────────┘
        //
        // Resharding *DOWN*
        // ┌────────────┐   ┌──────────┐
        // │            │   │          │
        // │ Shard 1    │   │ Shard 2  │
        // │ Non-Target │◄──┤ Target   │
        // │ Receiver   │   │ Sender   │
        // │            │   │          │
        // └────────────┘   └──────────┘

        // Target shard of the resharding operation. This is the shard that:
        //
        // - *created* during resharding *up*
        // - *deleted* during resharding *down*
        let is_target_shard = shard_id == state.shard_id;

        // Shard that will be *receiving* migrated points during resharding:
        //
        // - *target* shard during resharding *up*
        // - *non* target shards during resharding *down*
        let is_receiver_shard = match state.direction {
            ReshardingDirection::Up => is_target_shard,
            ReshardingDirection::Down => !is_target_shard,
        };

        // Shard that will be *sending* migrated points during resharding:
        //
        // - *non* target shards during resharding *up*
        // - *target* shard during resharding *down*
        let is_sender_shard = !is_receiver_shard;

        // We split update operations:
        //
        // - on *receiver* shards during `MigratingPoints` stage (for all operations except `upsert`)
        // - and on *sender* shards during `ReadHashRingCommitted` stage when resharding *up*

        let should_split_receiver = is_receiver_shard
            && state.stage == ReshardingStage::MigratingPoints
            && !operation.is_upsert_points();

        let should_split_sender = is_sender_shard
            && state.stage >= ReshardingStage::ReadHashRingCommitted
            && state.direction == ReshardingDirection::Up;

        if !should_split_receiver && !should_split_sender {
            return OperationsByMode::from(operation);
        }

        // There's no point splitting delete operations
        if operation.is_delete_points() {
            return OperationsByMode::from(operation);
        }

        let Some(filter) = self.resharding_filter() else {
            return OperationsByMode::from(operation);
        };

        let point_ids = match operation.point_ids() {
            Some(ids) if !ids.is_empty() => ids,
            Some(_) | None => return OperationsByMode::from(operation),
        };

        let target_point_ids: HashSet<_> = point_ids
            .iter()
            .copied()
            .filter(|&point_id| filter.check(point_id))
            .collect();

        if target_point_ids.is_empty() {
            OperationsByMode::from(operation)
        } else if target_point_ids.len() == point_ids.len() {
            OperationsByMode::default().with_update_only_existing(operation)
        } else {
            let mut update_all = operation.clone();
            update_all.retain_point_ids(|point_id| !target_point_ids.contains(point_id));

            let mut update_only_existing = operation;
            update_only_existing.retain_point_ids(|point_id| target_point_ids.contains(point_id));

            OperationsByMode::from(update_all).with_update_only_existing(update_only_existing)
        }
    }

    pub fn resharding_filter(&self) -> Option<hash_ring::HashRingFilter> {
        let shard_id = self.resharding_state.read().as_ref()?.shard_id;
        self.hash_ring_filter(shard_id)
    }

    pub fn hash_ring_router(&self, shard_id: ShardId) -> Option<&HashRingRouter> {
        if !self.contains_shard(shard_id) {
            return None;
        }

        let shard_key = self.shard_id_to_key_mapping.get(&shard_id).cloned();
        let router = self.rings.get(&shard_key).expect("hashring exists");
        Some(router)
    }

    pub fn hash_ring_filter(&self, shard_id: ShardId) -> Option<hash_ring::HashRingFilter> {
        let router = self.hash_ring_router(shard_id)?;
        let ring = match router {
            HashRingRouter::Single(ring) => ring,
            HashRingRouter::Resharding { old, new } => {
                if new.len() > old.len() {
                    new
                } else {
                    old
                }
            }
        };

        Some(hash_ring::HashRingFilter::new(ring.clone(), shard_id))
    }
}

#[derive(Clone, Debug, Default)]
pub struct OperationsByMode {
    pub update_all: Vec<CollectionUpdateOperations>,
    pub update_only_existing: Vec<CollectionUpdateOperations>,
}

impl OperationsByMode {
    pub fn with_update_only_existing(mut self, operation: CollectionUpdateOperations) -> Self {
        self.update_only_existing = match operation {
            CollectionUpdateOperations::PointOperation(point_operation) => match point_operation {
                PointOperations::UpsertPoints(operation) => {
                    vec![CollectionUpdateOperations::PointOperation(
                        PointOperations::UpsertPointsConditional(
                            ConditionalInsertOperationInternal {
                                points_op: operation,
                                condition: Filter::new(), // Always true condition
                                update_mode: Some(UpdateMode::UpdateOnly),
                            },
                        ),
                    )]
                }
                PointOperations::UpsertPointsConditional(operation) => {
                    vec![CollectionUpdateOperations::PointOperation(
                        PointOperations::UpsertPointsConditional(
                            ConditionalInsertOperationInternal {
                                points_op: operation.points_op,
                                condition: operation.condition,
                                update_mode: Some(UpdateMode::UpdateOnly),
                            },
                        ),
                    )]
                }

                PointOperations::DeletePoints { ids } => {
                    vec![CollectionUpdateOperations::PointOperation(
                        PointOperations::DeletePoints { ids },
                    )]
                }
                PointOperations::DeletePointsByFilter(op) => {
                    vec![CollectionUpdateOperations::PointOperation(
                        PointOperations::DeletePointsByFilter(op),
                    )]
                }
                PointOperations::SyncPoints(op) => {
                    vec![CollectionUpdateOperations::PointOperation(
                        PointOperations::SyncPoints(op),
                    )]
                }
            },
            CollectionUpdateOperations::VectorOperation(_)
            | CollectionUpdateOperations::PayloadOperation(_)
            | CollectionUpdateOperations::FieldIndexOperation(_)
            | CollectionUpdateOperations::VectorNameOperation(_) => {
                vec![operation]
            }
            #[cfg(feature = "staging")]
            CollectionUpdateOperations::StagingOperation(_) => {
                vec![operation]
            }
        };

        self
    }
}

impl From<CollectionUpdateOperations> for OperationsByMode {
    fn from(operation: CollectionUpdateOperations) -> Self {
        Self {
            update_all: vec![operation],
            update_only_existing: Vec::new(),
        }
    }
}

fn get_ring<'a>(
    rings: &'a mut HashMap<Option<ShardKey>, HashRingRouter>,
    shard_key: &'_ Option<ShardKey>,
) -> CollectionResult<&'a mut HashRingRouter> {
    rings.get_mut(shard_key).ok_or_else(|| {
        CollectionError::bad_request(format!(
            "{} hashring does not exist",
            shard_key_fmt(shard_key)
        ))
    })
}

fn assert_resharding_state_consistency(
    state: &Option<ReshardState>,
    ring: &HashRingRouter,
    shard_key: &Option<ShardKey>,
) {
    match state.as_ref().map(|state| state.stage) {
        Some(ReshardingStage::MigratingPoints | ReshardingStage::ReadHashRingCommitted) => {
            debug_assert!(
                ring.is_resharding(),
                "resharding is in progress, \
                 but {shard_key:?} hashring is not a resharding hashring:\n\
                 {state:#?}"
            );
        }

        Some(ReshardingStage::WriteHashRingCommitted) => {
            debug_assert!(
                !ring.is_resharding(),
                "resharding is in progress, \
                 and write hashring has already been committed, \
                 but {shard_key:?} hashring is a resharding hashring:\n\
                 {state:#?}"
            );
        }

        None => {
            debug_assert!(
                !ring.is_resharding(),
                "resharding is not in progress, \
                 but {shard_key:?} hashring is a resharding hashring"
            );
        }
    }
}

fn check_stage(stage: ReshardingStage) -> impl Fn(&ReshardState) -> CollectionResult<()> {
    move |state| {
        if state.stage == stage {
            Ok(())
        } else {
            Err(CollectionError::bad_request(format!(
                "expected resharding stage {stage:?}, but resharding is at stage {:?}",
                state.stage,
            )))
        }
    }
}

fn shard_key_fmt(key: &Option<ShardKey>) -> &dyn fmt::Display {
    match key {
        Some(key) => key,
        None => &"default",
    }
}

/// Resharding consensus operations must be idempotent.
///
/// The consensus apply loop (`apply_entries` in `consensus_manager.rs`) silently
/// swallows all non-`ServiceError` results and marks the entry as applied. Since
/// resharding check functions return `bad_request` (`StorageError::BadRequest`,
/// not `ServiceError`), any validation failure is silently swallowed.
///
/// If local state on a peer diverges for any reason (crash during partial apply,
/// prior swallowed error), the same committed Raft entry produces different
/// outcomes on different peers — succeeding on some, silently swallowed on
/// others — causing permanent resharding state divergence despite identical
/// consensus term and commit.
///
/// These tests verify that resharding operations return `Ok` when the desired
/// post-condition is already met or the operation is inapplicable, rather than
/// returning `bad_request` errors that get silently swallowed.
#[cfg(test)]
mod tests {
    use uuid::Uuid;

    use super::*;

    fn make_reshard_key(shard_id: ShardId) -> ReshardKey {
        ReshardKey {
            uuid: Uuid::new_v4(),
            direction: ReshardingDirection::Up,
            peer_id: 1,
            shard_id,
            shard_key: None,
        }
    }

    fn make_holder() -> (tempfile::TempDir, ShardHolder) {
        let dir = tempfile::tempdir().unwrap();
        let holder = ShardHolder::new(dir.path(), ShardingMethod::Auto).unwrap();
        (dir, holder)
    }

    // ------------------------------------------------------------------
    // check_abort_resharding idempotency
    // ------------------------------------------------------------------

    #[test]
    fn test_abort_check_idempotent_when_no_resharding_active() {
        let (_dir, holder) = make_holder();
        let key = make_reshard_key(1);

        // No resharding is in progress. This happens when:
        // - The abort was already applied on this node (crash recovery replay)
        // - The start was never applied on this node (prior swallowed error)
        //
        // Returning bad_request here causes silent state divergence: the error
        // is swallowed by apply_entries, the entry is marked as applied, but
        // resharding state is not cleared on this peer while it IS cleared on
        // peers where the operation succeeded.
        let result = holder.check_abort_resharding(&key);
        assert!(
            result.is_ok(),
            "check_abort_resharding must return Ok when no resharding is active \
             (idempotent: already aborted or never started), got error: {result:?}",
        );
    }

    #[test]
    fn test_abort_check_idempotent_when_different_resharding_active() {
        let (_dir, holder) = make_holder();

        // Set up resharding state for shard 1
        let active_key = make_reshard_key(1);
        holder
            .resharding_state
            .write(|state| {
                *state = Some(ReshardState::new(
                    active_key.uuid,
                    active_key.direction,
                    active_key.peer_id,
                    active_key.shard_id,
                    active_key.shard_key.clone(),
                ));
            })
            .unwrap();

        // Try to abort a DIFFERENT resharding (shard 2). This can happen when
        // the original resharding was already aborted and a new one was started.
        let other_key = make_reshard_key(2);
        let result = holder.check_abort_resharding(&other_key);
        assert!(
            result.is_ok(),
            "check_abort_resharding must return Ok when a different resharding is active \
             (the one we're aborting was already handled), got error: {result:?}"
        );
    }

    // ------------------------------------------------------------------
    // commit_read_hashring idempotency
    // ------------------------------------------------------------------

    #[test]
    fn test_commit_read_idempotent_when_no_resharding_active() {
        let (_dir, mut holder) = make_holder();
        let key = make_reshard_key(1);

        // No resharding is in progress. commit_read should be a no-op, not an
        // error that gets silently swallowed causing state divergence.
        let result = holder.commit_read_hashring(&key);
        assert!(
            result.is_ok(),
            "commit_read_hashring must return Ok when no resharding is active, got error: {result:?}",
        );
    }

    // ------------------------------------------------------------------
    // commit_write_hashring idempotency
    // ------------------------------------------------------------------

    #[test]
    fn test_commit_write_idempotent_when_no_resharding_active() {
        let (_dir, mut holder) = make_holder();
        let key = make_reshard_key(1);

        let result = holder.commit_write_hashring(&key);
        assert!(
            result.is_ok(),
            "commit_write_hashring must return Ok when no resharding is active, got error: {result:?}",
        );
    }

    // ------------------------------------------------------------------
    // check_finish_resharding idempotency
    // ------------------------------------------------------------------

    #[test]
    fn test_finish_check_idempotent_when_no_resharding_active() {
        let (_dir, mut holder) = make_holder();
        let key = make_reshard_key(1);

        let result = holder.check_finish_resharding(&key);
        assert!(
            result.is_ok(),
            "check_finish_resharding must return Ok when no resharding is active (idempotent: already finished), got error: {result:?}",
        );
    }

    // ------------------------------------------------------------------
    // check_start_resharding idempotency
    // ------------------------------------------------------------------

    #[test]
    fn test_start_check_idempotent_when_matching_resharding_active() {
        let (_dir, mut holder) = make_holder();
        let key = make_reshard_key(1);

        // Set up ring and resharding state as they would look after a
        // successful `start_resharding` had been applied on this peer.
        holder
            .rings
            .get_mut(&None)
            .unwrap()
            .start_resharding(key.shard_id, key.direction);
        holder
            .resharding_state
            .write(|state| {
                *state = Some(ReshardState::new(
                    key.uuid,
                    key.direction,
                    key.peer_id,
                    key.shard_id,
                    key.shard_key.clone(),
                ));
            })
            .unwrap();

        // Re-applying start for the same key must not fail. Otherwise the
        // replay would be silently swallowed and the subsequent idempotent
        // steps in `Collection::start_resharding` would be skipped — leaving
        // half-applied state unreconciled on this peer.
        let result = holder.check_start_resharding(&key);
        assert!(
            result.is_ok(),
            "check_start_resharding must return Ok when the same resharding is already active (idempotent re-apply), got error: {result:?}",
        );
    }

    // ------------------------------------------------------------------
    // finish_resharding_unchecked idempotency
    // ------------------------------------------------------------------

    #[test]
    fn test_finish_unchecked_idempotent_when_no_resharding_active() {
        let (_dir, mut holder) = make_holder();
        let key = make_reshard_key(1);

        // Replay `finish` after the resharding state has already been cleared
        // (partial apply between the state write and a subsequent step).
        // The unchecked helper must not panic or error in this case.
        let result = holder.finish_resharding_unchecked(&key);
        assert!(
            result.is_ok(),
            "finish_resharding_unchecked must return Ok when no resharding state is present, got error: {result:?}",
        );
        assert!(
            holder.resharding_state.read().is_none(),
            "state must remain cleared after idempotent finish",
        );
    }

    // ------------------------------------------------------------------
    // start_resharding_unchecked idempotency
    // ------------------------------------------------------------------

    #[tokio::test]
    async fn test_start_unchecked_idempotent_when_matching_state_present() {
        let (_dir, mut holder) = make_holder();
        let key = make_reshard_key(1);

        let expected_state = ReshardState::new(
            key.uuid,
            key.direction,
            key.peer_id,
            key.shard_id,
            key.shard_key.clone(),
        );

        // Pre-seed matching state to simulate a replay after a successful
        // start had already persisted the resharding state.
        holder
            .resharding_state
            .write(|state| {
                *state = Some(expected_state.clone());
            })
            .unwrap();

        // Re-apply. `new_shard = None` matches the caller's behavior when it
        // has detected that the replica set already exists.
        holder
            .start_resharding_unchecked(key.clone(), None)
            .await
            .expect("start_resharding_unchecked must be idempotent on replay");

        assert_eq!(
            holder.resharding_state.read().clone(),
            Some(expected_state),
            "matching state must be preserved verbatim across a replay",
        );
    }

    // ------------------------------------------------------------------
    // Divergence scenario: proves the bug end-to-end
    // ------------------------------------------------------------------

    /// Simulates two peers processing the same sequence of committed Raft
    /// entries, where peer B missed the initial "start" due to a silently
    /// swallowed error. Every subsequent operation must succeed on BOTH peers
    /// to prevent permanent resharding state divergence.
    #[test]
    fn test_resharding_ops_do_not_cause_divergence_between_peers() {
        let (_dir_a, holder_a) = make_holder();
        let (_dir_b, holder_b) = make_holder();
        let key = make_reshard_key(1);

        // Simulate: "start resharding" was applied on peer A but silently
        // swallowed on peer B (e.g. due to shard already existing from a
        // crashed previous attempt).
        holder_a
            .resharding_state
            .write(|state| {
                *state = Some(ReshardState::new(
                    key.uuid,
                    key.direction,
                    key.peer_id,
                    key.shard_id,
                    key.shard_key.clone(),
                ));
            })
            .unwrap();
        // peer B has no resharding state (start was swallowed)

        // Now an "abort resharding" consensus entry is committed.
        // Both peers must return Ok. If peer B returns bad_request, the error
        // is silently swallowed, state is not modified, and peer A clears its
        // resharding state while peer B remains without it — but a future
        // resharding start would diverge because peer A is clean while peer B
        // might have leftover state from other operations.
        let result_a = holder_a.check_abort_resharding(&key);
        let result_b = holder_b.check_abort_resharding(&key);

        assert!(
            result_a.is_ok(),
            "Peer A (has resharding state) must succeed: {result_a:?}"
        );
        assert!(
            result_b.is_ok(),
            "Peer B (no resharding state) must also succeed to prevent divergence: {result_b:?}"
        );
    }
}use std::collections::{HashMap, HashSet};
use std::ops;

use ahash::AHashMap;
use itertools::Itertools;
use segment::types::ShardKey;
use serde::{Deserialize, Serialize};

use crate::shards::shard::ShardId;

/// Shard key mapping type
#[derive(Clone, Debug, Default, Eq, PartialEq, Deserialize, Serialize)]
#[serde(from = "SerdeHelper", into = "SerdeHelper")]
pub struct ShardKeyMapping {
    shard_key_to_shard_ids: HashMap<ShardKey, HashSet<ShardId>>,
}

impl ops::Deref for ShardKeyMapping {
    type Target = HashMap<ShardKey, HashSet<ShardId>>;

    fn deref(&self) -> &Self::Target {
        &self.shard_key_to_shard_ids
    }
}

impl ops::DerefMut for ShardKeyMapping {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.shard_key_to_shard_ids
    }
}

impl ShardKeyMapping {
    /// Get an inverse mapping, all shard IDs and their key
    pub fn shard_id_to_shard_key(&self) -> AHashMap<ShardId, ShardKey> {
        self.shard_key_to_shard_ids
            .iter()
            .flat_map(|(shard_key, shard_ids)| {
                shard_ids
                    .iter()
                    .map(|shard_id| (*shard_id, shard_key.clone()))
            })
            .collect()
    }

    /// Return all shard IDs from the mappings
    pub fn shard_ids(&self) -> Vec<ShardId> {
        let ids = self.iter_shard_ids().collect::<Vec<_>>();

        debug_assert!(
            ids.iter().all_unique(),
            "shard mapping contains duplicate shard IDs",
        );

        ids
    }

    /// Iterate over all shard IDs from the mappings
    pub fn iter_shard_ids(&self) -> impl Iterator<Item = ShardId> {
        self.shard_key_to_shard_ids
            .values()
            .flat_map(|shard_ids| shard_ids.iter().copied())
    }

    /// Iterate over all shard keys
    pub fn iter_shard_keys(&self) -> impl Iterator<Item = &ShardKey> {
        self.shard_key_to_shard_ids.keys()
    }

    /// Get the shard key for a given shard ID
    ///
    /// `None` is returned if the shard ID has no key, or if the shard ID is unknown
    pub fn shard_key(&self, shard_id: ShardId) -> Option<ShardKey> {
        self.shard_key_to_shard_ids
            .iter()
            .find(|(_, shard_ids)| shard_ids.contains(&shard_id))
            .map(|(key, _)| key.clone())
    }
}

impl From<SerdeHelper> for ShardKeyMapping {
    fn from(helper: SerdeHelper) -> Self {
        Self {
            shard_key_to_shard_ids: helper.0.into_iter().map(KeyIdsPair::into_parts).collect(),
        }
    }
}

/// Helper structure for persisting shard key mapping in safe format
///
/// Bug: <https://github.com/qdrant/qdrant/pull/5838>
#[derive(Deserialize, Serialize)]
struct SerdeHelper(Vec<KeyIdsPair>);

impl From<ShardKeyMapping> for SerdeHelper {
    fn from(mapping: ShardKeyMapping) -> Self {
        let key_ids_pairs = mapping
            .shard_key_to_shard_ids
            .into_iter()
            .map(KeyIdsPair::from)
            .collect();
        Self(key_ids_pairs)
    }
}

#[derive(Clone, Debug, Deserialize, Serialize)]
struct KeyIdsPair {
    /// Shard key
    ///
    /// The key is persisted as untagged variant. The JSON value gives us enough information
    /// however to distinguish between a shard key number and string.
    key: ShardKey,
    /// Associalted shard IDs.
    shard_ids: HashSet<ShardId>,
}

impl KeyIdsPair {
    fn into_parts(self) -> (ShardKey, HashSet<ShardId>) {
        let Self { key, shard_ids } = self;
        (key, shard_ids)
    }
}

impl From<(ShardKey, HashSet<ShardId>)> for KeyIdsPair {
    fn from((key, shard_ids): (ShardKey, HashSet<ShardId>)) -> Self {
        Self { key, shard_ids }
    }
}use std::sync::{Arc, Weak};

use tokio::sync;

use super::ShardHolder;

#[derive(Clone)]
pub struct SharedShardHolder(Arc<sync::RwLock<ShardHolder>>);

impl SharedShardHolder {
    pub fn new(shard_holder: ShardHolder) -> Self {
        Self(Arc::new(sync::RwLock::new(shard_holder)))
    }

    pub async fn read(&self) -> sync::RwLockReadGuard<'_, ShardHolder> {
        self.0.read().await
    }

    pub async fn read_owned(self) -> sync::OwnedRwLockReadGuard<ShardHolder> {
        self.0.read_owned().await
    }

    pub async fn write(&self) -> sync::RwLockWriteGuard<'_, ShardHolder> {
        self.0.write().await
    }

    pub async fn write_owned(self) -> sync::OwnedRwLockWriteGuard<ShardHolder> {
        self.0.write_owned().await
    }

    pub fn downgrade(&self) -> WeakShardHolder {
        WeakShardHolder(Arc::downgrade(&self.0))
    }
}

#[derive(Clone)]
pub struct WeakShardHolder(Weak<sync::RwLock<ShardHolder>>);

impl WeakShardHolder {
    pub fn upgrade(&self) -> Option<SharedShardHolder> {
        self.0.upgrade().map(SharedShardHolder)
    }
