    async fn restart_shard_transfer(
        &self,
        transfer_config: ShardTransfer,
        collection_id: CollectionId,
        default_method: ShardTransferMethod,
    ) -> CollectionResult<()>;

    /// Propose to restart a shard transfer with a different given configuration
