/// Timeout for transferring and recovering a shard snapshot on a remote peer.
const SHARD_SNAPSHOT_TRANSFER_RECOVER_TIMEOUT: Duration = MAX_GRPC_CHANNEL_TIMEOUT;

/// RemoteShard
///
/// Remote Shard is a representation of a shard that is located on a remote peer.
#[derive(Clone)]
pub struct RemoteShard {
    pub(crate) id: ShardId,
    pub(crate) collection_id: CollectionId,
    pub peer_id: PeerId,
    pub channel_service: ChannelService,
    telemetry_search_durations: Arc<Mutex<OperationDurationsAggregator>>,
    telemetry_update_durations: Arc<Mutex<OperationDurationsAggregator>>,
}

impl RemoteShard {
    /// Instantiate a new remote shard in memory
    pub fn new(
        id: ShardId,
        collection_id: CollectionId,
        peer_id: PeerId,
        channel_service: ChannelService,
    ) -> Self {
        Self {
            id,
            collection_id,
            peer_id,
            channel_service,
            telemetry_search_durations: OperationDurationsAggregator::new(),
            telemetry_update_durations: OperationDurationsAggregator::new(),
        }
    }

    /// Checks that remote shard is at least at the given version
    /// - Returns `true` if we know that the peer is at least at the given version
    /// - Returns `false` if we know that the peer not at the given version or version is unknown
    pub fn check_version(&self, version: &Version) -> bool {
        self.channel_service
            .peer_is_at_version(self.peer_id, version)
    }

    pub fn restore_snapshot(_snapshot_path: &Path) {
        // NO extra actions needed for remote shards
    }

    fn current_address(&self) -> CollectionResult<Uri> {
        let guard_peer_address = self.channel_service.id_to_address.read();
        let peer_address = guard_peer_address.get(&self.peer_id).cloned();
        match peer_address {
            None => Err(CollectionError::service_error(format!(
                "no address found for peer {}",
                self.peer_id
            ))),
            Some(peer_address) => Ok(peer_address),
        }
    }

    async fn with_points_client<T, O: Future<Output = Result<T, Status>>>(
        &self,
        f: impl Fn(PointsInternalClient<InterceptedService<Channel, PoolInterceptor>>) -> O,
    ) -> CollectionResult<T> {
        let current_address = self.current_address()?;
        self.channel_service
            .channel_pool
            .with_channel(&current_address, |channel| {
                let client = PointsInternalClient::new(channel);
                let client = client.max_decoding_message_size(usize::MAX);
                f(client)
            })
            .await
            .map_err(|err| err.into())
    }

    async fn with_collections_client<T, O: Future<Output = Result<T, Status>>>(
        &self,
        f: impl Fn(CollectionsInternalClient<InterceptedService<Channel, PoolInterceptor>>) -> O,
    ) -> CollectionResult<T> {
        let current_address = self.current_address()?;
        self.channel_service
            .channel_pool
            .with_channel(&current_address, |channel| {
                let client = CollectionsInternalClient::new(channel);
                let client = client.max_decoding_message_size(usize::MAX);
                f(client)
            })
            .await
            .map_err(|err| err.into())
    }

    async fn with_shard_snapshots_client_timeout<T, O: Future<Output = Result<T, Status>>>(
        &self,
        f: impl Fn(ShardSnapshotsClient<InterceptedService<Channel, PoolInterceptor>>) -> O,
        timeout: Option<Duration>,
        retries: usize,
    ) -> CollectionResult<T> {
        let current_address = self.current_address()?;
        self.channel_service
            .channel_pool
            .with_channel_timeout(
                &current_address,
                |channel| {
                    let client = ShardSnapshotsClient::new(channel);
                    let client = client.max_decoding_message_size(usize::MAX);
                    f(client)
                },
                timeout,
                retries,
            )
            .await
            .map_err(|err| err.into())
    }

    async fn with_qdrant_client<T, Fut: Future<Output = Result<T, Status>>>(
        &self,
        f: impl Fn(QdrantClient<InterceptedService<Channel, PoolInterceptor>>) -> Fut,
    ) -> CollectionResult<T> {
        let current_address = self.current_address()?;
        self.channel_service
            .channel_pool
            .with_channel(&current_address, |channel| {
                let client = QdrantClient::new(channel);
                f(client)
            })
            .await
            .map_err(|err| err.into())
    }

    pub fn get_telemetry_data(&self, detail: TelemetryDetail) -> RemoteShardTelemetry {
        RemoteShardTelemetry {
            shard_id: self.id,
            peer_id: self.peer_id,
            searches: Some(
                self.telemetry_search_durations
                    .lock()
                    .get_statistics(detail),
            ),
            updates: Some(
                self.telemetry_update_durations
                    .lock()
                    .get_statistics(detail),
            ),
        }
    }

    pub async fn initiate_transfer(&self) -> CollectionResult<CollectionOperationResponse> {
        let res = self
            .with_collections_client(|mut client| async move {
                client
                    .initiate(InitiateShardTransferRequest {
                        collection_name: self.collection_id.clone(),
                        shard_id: self.id,
                    })
                    .await
            })
            .await?
            .into_inner();
        Ok(res)
    }

    pub async fn forward_update_batch(
        &self,
        operations: Vec<OperationWithClockTag>,
        wait: WaitUntil,
        timeout: Option<Duration>,
        ordering: WriteOrdering,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<UpdateResult> {
        let mut updates = Vec::with_capacity(operations.len());

        let shard_id = Some(self.id);
        let collection_name = &self.collection_id;
        let ordering = Some(ordering);
        let timeout = timeout.map(|t| t.as_secs());

        for operation in operations {
            let update_op = match operation.operation {
                CollectionUpdateOperations::PointOperation(point_ops) => match point_ops {
                    PointOperations::UpsertPoints(point_insert_operations) => {
                        let request = internal_upsert_points(
                            shard_id,
                            operation.clock_tag,
                            collection_name.clone(),
                            point_insert_operations,
                            wait,
                            timeout,
                            ordering,
                        )?;

                        Update::Upsert(request)
                    }
                    PointOperations::UpsertPointsConditional(conditional_upsert) => {
                        let request = internal_conditional_upsert_points(
                            shard_id,
                            operation.clock_tag,
                            collection_name.clone(),
                            conditional_upsert,
                            wait,
                            timeout,
                            ordering,
                        )?;
                        Update::Upsert(request)
                    }
                    PointOperations::DeletePoints { ids } => {
                        let request = internal_delete_points(
                            shard_id,
                            operation.clock_tag,
                            collection_name.clone(),
                            ids,
                            wait,
                            timeout,
                            ordering,
                        );
                        Update::Delete(request)
                    }
                    PointOperations::DeletePointsByFilter(filter) => {
                        let request = internal_delete_points_by_filter(
                            shard_id,
                            operation.clock_tag,
                            collection_name.clone(),
                            filter,
                            wait,
                            timeout,
                            ordering,
                        );
                        Update::Delete(request)
                    }
                    PointOperations::SyncPoints(operation) => {
                        let request = internal_sync_points(
                            shard_id,
                            None, // TODO!?
                            collection_name.clone(),
                            operation,
                            wait,
                            timeout,
                            ordering,
                        )?;
                        Update::Sync(request)
                    }
                },
                CollectionUpdateOperations::VectorOperation(vector_ops) => match vector_ops {
                    VectorOperations::UpdateVectors(update_operation) => {
                        let request = internal_update_vectors(
                            shard_id,
                            operation.clock_tag,
                            collection_name.clone(),
                            update_operation,
                            wait,
                            timeout,
                            ordering,
                        )?;
                        Update::UpdateVectors(request)
                    }
                    VectorOperations::DeleteVectors(ids, vector_names) => {
                        let request = internal_delete_vectors(
                            shard_id,
                            operation.clock_tag,
                            collection_name.clone(),
                            ids.points,
                            vector_names.clone(),
                            wait,
                            timeout,
                            ordering,
                        );
                        Update::DeleteVectors(request)
                    }
                    VectorOperations::DeleteVectorsByFilter(filter, vector_names) => {
                        let request = internal_delete_vectors_by_filter(
                            shard_id,
                            operation.clock_tag,
                            collection_name.clone(),
                            filter,
                            vector_names.clone(),
                            wait,
                            timeout,
                            ordering,
                        );
                        Update::DeleteVectors(request)
                    }
                },
                CollectionUpdateOperations::PayloadOperation(payload_ops) => match payload_ops {
                    PayloadOps::SetPayload(set_payload) => {
                        let request = internal_set_payload(
                            shard_id,
                            operation.clock_tag,
                            collection_name.clone(),
                            set_payload,
                            wait,
                            timeout,
                            ordering,
                        );
                        Update::SetPayload(request)
                    }
                    PayloadOps::DeletePayload(delete_payload) => {
                        let request = internal_delete_payload(
                            shard_id,
                            operation.clock_tag,
                            collection_name.clone(),
                            delete_payload,
                            wait,
                            timeout,
                            ordering,
                        );
                        Update::DeletePayload(request)
                    }
                    PayloadOps::ClearPayload { points } => {
                        let request = internal_clear_payload(
                            shard_id,
                            operation.clock_tag,
                            collection_name.clone(),
                            points,
                            wait,
                            timeout,
                            ordering,
                        );
                        Update::ClearPayload(request)
                    }
                    PayloadOps::ClearPayloadByFilter(filter) => {
                        let request = internal_clear_payload_by_filter(
                            shard_id,
                            operation.clock_tag,
                            collection_name.clone(),
                            filter,
                            wait,
                            timeout,
                            ordering,
                        );
                        Update::ClearPayload(request)
                    }
                    PayloadOps::OverwritePayload(set_payload) => {
                        let request = internal_set_payload(
                            shard_id,
                            operation.clock_tag,
                            collection_name.clone(),
                            set_payload,
                            wait,
                            timeout,
                            ordering,
                        );
                        Update::OverwritePayload(request)
                    }
                },
                CollectionUpdateOperations::FieldIndexOperation(field_index_op) => {
                    match field_index_op {
                        FieldIndexOperations::CreateIndex(create_index) => {
                            let request = internal_create_index(
                                shard_id,
                                operation.clock_tag,
                                collection_name.clone(),
                                create_index,
                                wait,
                                timeout,
                                ordering,
                            );
                            Update::CreateFieldIndex(request)
                        }
                        FieldIndexOperations::DeleteIndex(delete_index) => {
                            let request = internal_delete_index(
                                shard_id,
                                operation.clock_tag,
                                collection_name.clone(),
                                delete_index,
                                wait,
                                timeout,
                                ordering,
                            );
                            Update::DeleteFieldIndex(request)
                        }
                    }
                }
                CollectionUpdateOperations::VectorNameOperation(vector_name_op) => {
                    match vector_name_op {
                        VectorNameOperations::CreateVectorName(create) => {
                            let request = internal_create_vector_name(
                                shard_id,
                                operation.clock_tag,
                                collection_name.clone(),
                                create,
                                wait,
                                timeout,
                                ordering,
                            );
                            Update::CreateVectorName(request)
                        }
                        VectorNameOperations::DeleteVectorName(delete) => {
                            let request = internal_delete_vector_name(
                                shard_id,
                                operation.clock_tag,
                                collection_name.clone(),
                                delete,
                                wait,
                                timeout,
                                ordering,
                            );
                            Update::DeleteVectorName(request)
                        }
                    }
                }
                #[cfg(feature = "staging")]
                CollectionUpdateOperations::StagingOperation(_) => {
                    // Staging operations should not be forwarded to remote shards
                    continue;
                }
            };
            updates.push(UpdateOperation {
                update: Some(update_op),
            });
        }

        let batch_request = &UpdateBatchInternal {
            operations: updates,
            wait_override: wait_override_to_proto(wait),
        };

        let point_operation_response = self
            .with_points_client(|mut client| async move {
                client
                    .update_batch(tonic::Request::new(batch_request.clone()))
                    .await
            })
            .await?
            .into_inner();

        if let Some(hw_usage) = point_operation_response.hardware_usage {
            hw_measurement_acc.accumulate_request(hw_usage);
        }

        match point_operation_response.result {
            None => Err(CollectionError::service_error(
                "Malformed UpdateResult type".to_string(),
            )),
            Some(update_result) => update_result.try_into().map_err(|e: Status| e.into()),
        }
    }

    /// # Cancel safety
    ///
    /// This method is cancel safe.
    pub async fn forward_update(
        &self,
        operation: OperationWithClockTag,
        wait: WaitUntil,
        timeout: Option<Duration>,
        ordering: WriteOrdering,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<UpdateResult> {
        // `RemoteShard::execute_update_operation` is cancel safe, so this method is cancel safe.

        self.execute_update_operation(
            Some(self.id),
            self.collection_id.clone(),
            operation,
            wait,
            timeout,
            Some(ordering),
            hw_measurement_acc,
        )
        .await
    }

    /// # Cancel safety
    ///
    /// This method is cancel safe.
    #[allow(clippy::too_many_arguments)]
    pub async fn execute_update_operation(
        &self,
        shard_id: Option<ShardId>,
        collection_name: String,
        operation: OperationWithClockTag,
        wait: WaitUntil,
        timeout: Option<Duration>,
        ordering: Option<WriteOrdering>,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<UpdateResult> {
        // Cancelling remote request should always be safe on the client side and update API
        // *should be* cancel safe on the server side, so this method is cancel safe.

        let mut timer = ScopeDurationMeasurer::new(&self.telemetry_update_durations);
        timer.set_success(false);

        let default_timeout = self.channel_service.request_timeout();

        // We want to know if operation wrote into WAL before re break connection on client side
        // So, we always want to propagate explicit timeout to the remote side
        let timeout = Some(timeout.unwrap_or(default_timeout).as_secs());

        let point_operation_response = match operation.operation {
            CollectionUpdateOperations::PointOperation(point_ops) => match point_ops {
                PointOperations::UpsertPoints(point_insert_operations) => {
                    let request = &internal_upsert_points(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        point_insert_operations,
                        wait,
                        timeout,
                        ordering,
                    )?;
                    self.with_points_client(|mut client| async move {
                        client.upsert(tonic::Request::new(request.clone())).await
                    })
                    .await?
                    .into_inner()
                }
                PointOperations::UpsertPointsConditional(conditional_upsert) => {
                    let request = &internal_conditional_upsert_points(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        conditional_upsert,
                        wait,
                        timeout,
                        ordering,
                    )?;
                    self.with_points_client(|mut client| async move {
                        client.upsert(tonic::Request::new(request.clone())).await
                    })
                    .await?
                    .into_inner()
                }
                PointOperations::DeletePoints { ids } => {
                    let request = &internal_delete_points(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        ids,
                        wait,
                        timeout,
                        ordering,
                    );
                    self.with_points_client(|mut client| async move {
                        client.delete(tonic::Request::new(request.clone())).await
                    })
                    .await?
                    .into_inner()
                }
                PointOperations::DeletePointsByFilter(filter) => {
                    let request = &internal_delete_points_by_filter(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        filter,
                        wait,
                        timeout,
                        ordering,
                    );
                    self.with_points_client(|mut client| async move {
                        client.delete(tonic::Request::new(request.clone())).await
                    })
                    .await?
                    .into_inner()
                }
                PointOperations::SyncPoints(operation) => {
                    let request = &internal_sync_points(
                        shard_id,
                        None, // TODO!?
                        collection_name,
                        operation,
                        wait,
                        timeout,
                        ordering,
                    )?;
                    self.with_points_client(|mut client| async move {
                        client.sync(tonic::Request::new(request.clone())).await
                    })
                    .await?
                    .into_inner()
                }
            },
            CollectionUpdateOperations::VectorOperation(vector_ops) => match vector_ops {
                VectorOperations::UpdateVectors(update_operation) => {
                    let request = &internal_update_vectors(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        update_operation,
                        wait,
                        timeout,
                        ordering,
                    )?;
                    self.with_points_client(|mut client| async move {
                        client
                            .update_vectors(tonic::Request::new(request.clone()))
                            .await
                    })
                    .await?
                    .into_inner()
                }
                VectorOperations::DeleteVectors(ids, vector_names) => {
                    let request = &internal_delete_vectors(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        ids.points,
                        vector_names.clone(),
                        wait,
                        timeout,
                        ordering,
                    );
                    self.with_points_client(|mut client| async move {
                        client
                            .delete_vectors(tonic::Request::new(request.clone()))
                            .await
                    })
                    .await?
                    .into_inner()
                }
                VectorOperations::DeleteVectorsByFilter(filter, vector_names) => {
                    let request = &internal_delete_vectors_by_filter(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        filter,
                        vector_names.clone(),
                        wait,
                        timeout,
                        ordering,
                    );
                    self.with_points_client(|mut client| async move {
                        client
                            .delete_vectors(tonic::Request::new(request.clone()))
                            .await
                    })
                    .await?
                    .into_inner()
                }
            },
            CollectionUpdateOperations::PayloadOperation(payload_ops) => match payload_ops {
                PayloadOps::SetPayload(set_payload) => {
                    let request = &internal_set_payload(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        set_payload,
                        wait,
                        timeout,
                        ordering,
                    );
                    self.with_points_client(|mut client| async move {
                        client
                            .set_payload(tonic::Request::new(request.clone()))
                            .await
                    })
                    .await?
                    .into_inner()
                }
                PayloadOps::DeletePayload(delete_payload) => {
                    let request = &internal_delete_payload(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        delete_payload,
                        wait,
                        timeout,
                        ordering,
                    );
                    self.with_points_client(|mut client| async move {
                        client
                            .delete_payload(tonic::Request::new(request.clone()))
                            .await
                    })
                    .await?
                    .into_inner()
                }
                PayloadOps::ClearPayload { points } => {
                    let request = &internal_clear_payload(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        points,
                        wait,
                        timeout,
                        ordering,
                    );
                    self.with_points_client(|mut client| async move {
                        client
                            .clear_payload(tonic::Request::new(request.clone()))
                            .await
                    })
                    .await?
                    .into_inner()
                }
                PayloadOps::ClearPayloadByFilter(filter) => {
                    let request = &internal_clear_payload_by_filter(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        filter,
                        wait,
                        timeout,
                        ordering,
                    );
                    self.with_points_client(|mut client| async move {
                        client
                            .clear_payload(tonic::Request::new(request.clone()))
                            .await
                    })
                    .await?
                    .into_inner()
                }
                PayloadOps::OverwritePayload(set_payload) => {
                    let request = &internal_set_payload(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        set_payload,
                        wait,
                        timeout,
                        ordering,
                    );
                    self.with_points_client(|mut client| async move {
                        client
                            .overwrite_payload(tonic::Request::new(request.clone()))
                            .await
                    })
                    .await?
                    .into_inner()
                }
            },
            CollectionUpdateOperations::FieldIndexOperation(field_index_op) => match field_index_op
            {
                FieldIndexOperations::CreateIndex(create_index) => {
                    let request = &internal_create_index(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        create_index,
                        wait,
                        timeout,
                        ordering,
                    );
                    self.with_points_client(|mut client| async move {
                        client
                            .create_field_index(tonic::Request::new(request.clone()))
                            .await
                    })
                    .await?
                    .into_inner()
                }
                FieldIndexOperations::DeleteIndex(delete_index) => {
                    let request = &internal_delete_index(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        delete_index,
                        wait,
                        timeout,
                        ordering,
                    );
                    self.with_points_client(|mut client| async move {
                        client
                            .delete_field_index(tonic::Request::new(request.clone()))
                            .await
                    })
                    .await?
                    .into_inner()
                }
            },
            CollectionUpdateOperations::VectorNameOperation(vector_name_op) => match vector_name_op
            {
                VectorNameOperations::CreateVectorName(create) => {
                    let request = &internal_create_vector_name(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        create,
                        wait,
                        timeout,
                        ordering,
                    );
                    self.with_points_client(|mut client| async move {
                        client
                            .create_vector_name(tonic::Request::new(request.clone()))
                            .await
                    })
                    .await?
                    .into_inner()
                }
                VectorNameOperations::DeleteVectorName(delete) => {
                    let request = &internal_delete_vector_name(
                        shard_id,
                        operation.clock_tag,
                        collection_name,
                        delete,
                        wait,
                        timeout,
                        ordering,
                    );
                    self.with_points_client(|mut client| async move {
                        client
                            .delete_vector_name(tonic::Request::new(request.clone()))
                            .await
                    })
                    .await?
                    .into_inner()
                }
            },
            #[cfg(feature = "staging")]
            CollectionUpdateOperations::StagingOperation(staging_op) => {
                // TODO: Add gRPC support to forward staging operations to remote shards
                // For now, staging operations only execute on local shards
                match staging_op {
                    shard::operations::staging::StagingOperations::Delay(delay_op) => {
                        let delay =
                            std::time::Duration::from_secs_f64(delay_op.duration_sec.into_inner());
                        log::debug!(
                            "StagingOperation::Delay: skipping remote shard {} (duration: {delay:?})",
                            self.id
                        );
                    }
                }
                timer.set_success(true);
                return Ok(UpdateResult {
                    operation_id: None,
                    status: crate::operations::types::UpdateStatus::Completed,
                    clock_tag: operation.clock_tag,
                });
            }
        };

        if let Some(hw_usage) = point_operation_response.hardware_usage {
            hw_measurement_acc.accumulate_request(hw_usage);
        }

        match point_operation_response.result {
            None => Err(CollectionError::service_error(
                "Malformed UpdateResult type".to_string(),
            )),
            Some(update_result) => update_result.try_into().map_err(|e: Status| e.into()),
        }
    }

    /// Recover a shard at the remote from the given public `url`.
    ///
    /// # Warning
    ///
    /// This method specifies a timeout of 24 hours.
    ///
    /// Setting an API key may leak when requesting a snapshot file from a malicious server.
    /// This is potentially dangerous if a user has control over what URL is accessed.
    ///
    /// # Cancel safety
    ///
    /// This method is cancel safe.
    pub async fn recover_shard_snapshot_from_url(
        &self,
        collection_name: &str,
        shard_id: ShardId,
        url: &Url,
        snapshot_priority: SnapshotPriority,
        api_key: Option<&str>,
    ) -> CollectionResult<RecoverSnapshotResponse> {
        let res = self
            .with_shard_snapshots_client_timeout(
                |mut client| async move {
                    client
                        .recover(RecoverShardSnapshotRequest {
                            collection_name: collection_name.into(),
                            shard_id,
                            snapshot_location: Some(ShardSnapshotLocation {
                                location: Some(Location::Url(url.to_string())),
                            }),
                            snapshot_priority: api::grpc::qdrant::ShardSnapshotPriority::from(
                                snapshot_priority,
                            ) as i32,
                            checksum: None,
                            api_key: api_key.map(Into::into),
                        })
                        .await
                },
                Some(SHARD_SNAPSHOT_TRANSFER_RECOVER_TIMEOUT),
                api::grpc::transport_channel_pool::DEFAULT_RETRIES,
            )
            .await?
            .into_inner();
        Ok(res)
    }

    /// Wait for a local shard on the remote to get into a certain state
    pub async fn wait_for_shard_state(
        &self,
        collection_name: &str,
        shard_id: ShardId,
        state: ReplicaState,
        timeout: Duration,
    ) -> CollectionResult<CollectionOperationResponse> {
        let res = self
            .with_collections_client(|mut client| async move {
                let mut wait_for_shard_request = tonic::Request::new(WaitForShardStateRequest {
                    collection_name: collection_name.into(),
                    shard_id,
                    state: api::grpc::qdrant::ReplicaState::from(state) as i32,
                    timeout: timeout.as_secs_f32().ceil() as u64,
                });
                wait_for_shard_request.set_timeout(timeout);
                client.wait_for_shard_state(wait_for_shard_request).await
            })
            .await?
            .into_inner();
        Ok(res)
    }

    /// Request the recovery point on the remote shard
    pub async fn shard_recovery_point(
        &self,
        collection_name: &str,
        shard_id: ShardId,
    ) -> CollectionResult<RecoveryPoint> {
        let res = self
            .with_collections_client(|mut client| async move {
                client
                    .get_shard_recovery_point(GetShardRecoveryPointRequest {
                        collection_name: collection_name.into(),
                        shard_id,
                    })
                    .await
            })
            .await?
            .into_inner();

        let Some(recovery_point) = res.recovery_point else {
            return Err(CollectionError::service_error(
                "Recovery point data is missing in recovery point response",
            ));
        };

        Ok(recovery_point.try_into()?)
    }

    /// Update the shard cutoff point on the remote shard
    pub async fn update_shard_cutoff_point(
        &self,
        collection_name: &str,
        shard_id: ShardId,
        cutoff: &RecoveryPoint,
    ) -> CollectionResult<()> {
        self.with_collections_client(|mut client| async move {
            client
                .update_shard_cutoff_point(UpdateShardCutoffPointRequest {
                    collection_name: collection_name.into(),
                    shard_id,
                    cutoff: Some(cutoff.into()),
                })
                .await
        })
        .await?;
        Ok(())
    }

    /// Get optimizations info from the remote shard via gRPC.
    pub async fn optimizations(
        &self,
        options: OptimizationsRequestOptions,
    ) -> CollectionResult<OptimizationsResponse> {
        let res = self
            .with_collections_client(|mut client| async move {
                client
                    .get_shard_optimizations(GetShardOptimizationsRequest {
                        collection_name: self.collection_id.clone(),
                        shard_id: self.id,
                        with_queued: options.queued,
                        completed_limit: options.completed_limit.map(|l| l as u32),
                        with_idle_segments: options.idle_segments,
                    })
                    .await
            })
            .await?
            .into_inner();

        let response: OptimizationsResponse = serde_json::from_slice(&res.optimizations_json)
            .map_err(|err| {
                CollectionError::service_error(format!(
                    "Failed to deserialize optimizations response from remote shard: {err}"
                ))
            })?;

        Ok(response)
    }

    pub async fn memory_report(
        &self,
    ) -> CollectionResult<crate::common::memory_reporter::CollectionMemoryReport> {
        let res = self
            .with_collections_client(|mut client| async move {
                client
                    .get_shard_memory_report(api::grpc::qdrant::GetShardMemoryReportRequest {
                        collection_name: self.collection_id.clone(),
                        shard_id: self.id,
                    })
                    .await
            })
            .await?
            .into_inner();

        let report: crate::common::memory_reporter::CollectionMemoryReport =
            serde_json::from_slice(&res.memory_report_json).map_err(|err| {
                CollectionError::service_error(format!(
                    "Failed to deserialize memory report from remote shard: {err}"
                ))
            })?;

        Ok(report)
    }

    pub async fn health_check(&self) -> CollectionResult<()> {
        let _ = self
            .with_qdrant_client(|mut client| async move {
                client.health_check(HealthCheckRequest {}).await
            })
            .await?
            .into_inner();

        Ok(())
    }

    /// Validate timeout before making a read operation.
    /// - detect elapsed timeouts early to avoid unnecessary traffic
    /// - round up to the nearest second to well with our internal timeout handling
    ///
    /// Returns a new timeout value if the input is valid, otherwise an error.
    pub fn process_read_timeout(
        timeout: Option<Duration>,
        operation: &str,
    ) -> CollectionResult<Option<Duration>> {
        match timeout {
            None => Ok(timeout),
            Some(t) if t.is_zero() => Err(CollectionError::timeout(Duration::ZERO, operation)),
            Some(t) => {
                // round up to avoid losing completely timeouts that are under 1 second
                let timeout_secs = t.as_secs_f32().ceil() as u64;
                Ok(Some(Duration::from_secs(timeout_secs)))
            }
        }
    }
}

// New-type to own the type in the crate for conversions via From
pub struct CollectionCoreSearchRequest<'a>(pub(crate) (CollectionId, &'a CoreSearchRequest));

#[async_trait]
impl ShardOperation for RemoteShard {
    /// # Cancel safety
    ///
    /// This method is cancel safe.
    async fn update(
        &self,
        operation: OperationWithClockTag,
        wait: WaitUntil,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<UpdateResult> {
        // `RemoteShard::execute_update_operation` is cancel safe, so this method is cancel safe.

        // targets the shard explicitly
        let shard_id = Some(self.id);
        self.execute_update_operation(
            shard_id,
            self.collection_id.clone(),
            operation,
            wait,
            timeout,
            None,
            hw_measurement_acc,
        )
        .await
    }

    async fn scroll_by(
        &self,
        request: Arc<ScrollRequestInternal>,
        _search_runtime_handle: &AdaptiveSearchHandle,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<Vec<RecordInternal>> {
        let processed_timeout = Self::process_read_timeout(timeout, "scroll")?;
        let ScrollRequestInternal {
            filter,
            offset,
            limit,
            with_payload,
            with_vector,
            order_by,
        } = request.as_ref();

        let with_payload = with_payload
            .as_ref()
            .cloned()
            .unwrap_or_else(ScrollRequestInternal::default_with_payload);

        let is_payload_required = with_payload.is_required();
        let order_by = order_by.clone().map(OrderBy::from);
        let filter = filter.clone();

        let scroll_points = ScrollPoints {
            collection_name: self.collection_id.clone(),
            filter: filter.map(api::grpc::qdrant::Filter::from),
            offset: offset.map(ExtendedPointId::into),
            limit: limit.map(|x| x as u32),
            with_payload: Some(WithPayloadSelector::from(with_payload)),
            with_vectors: Some(with_vector.clone().into()),
            read_consistency: None,
            shard_key_selector: None,
            order_by: order_by.map(api::grpc::qdrant::OrderBy::from),
            timeout: processed_timeout.map(|t| t.as_secs()),
        };
        let scroll_request = &ScrollPointsInternal {
            scroll_points: Some(scroll_points),
            shard_id: Some(self.id),
        };

        let scroll_response = self
            .with_points_client(|mut client| async move {
                let mut request = tonic::Request::new(scroll_request.clone());
                if let Some(timeout) = processed_timeout {
                    request.set_timeout(timeout);
                }
                client.scroll(request).await
            })
            .await?
            .into_inner();

        if let Some(hw_usage) = scroll_response.usage.unwrap_or_default().hardware {
            hw_measurement_acc.accumulate_request(hw_usage);
        }

        let result: Result<Vec<RecordInternal>, Status> = scroll_response
            .result
            .into_iter()
            .map(|point| try_record_from_grpc(point, is_payload_required))
            .collect();

        result.map_err(|e| e.into())
    }

    async fn local_scroll_by_id(
        &self,
        _offset: Option<ExtendedPointId>,
        _limit: usize,
        _with_payload_interface: &WithPayloadInterface,
        _with_vector: &WithVector,
        _filter: Option<&Filter>,
        _search_runtime_handle: &AdaptiveSearchHandle,
        _timeout: Option<Duration>,
        _hw_measurement_acc: HwMeasurementAcc,
        _overwrite_deferred: DeferredBehavior,
    ) -> CollectionResult<Vec<RecordInternal>> {
        debug_assert!(false, "RemoteShard does not support local_scroll_by_id");
        Err(CollectionError::service_error(
            "RemoteShard does not support local_scroll_by_id".to_string(),
        ))
    }

    async fn info(&self) -> CollectionResult<CollectionInfo> {
        let get_collection_info_request = GetCollectionInfoRequest {
            collection_name: self.collection_id.clone(),
        };
        let request = &GetCollectionInfoRequestInternal {
            get_collection_info_request: Some(get_collection_info_request),
            shard_id: self.id,
        };
        let get_collection_response = self
            .with_collections_client(|mut client| async move {
                client.get(tonic::Request::new(request.clone())).await
            })
            .await?
            .into_inner();

        let result: Result<CollectionInfo, Status> = get_collection_response.try_into();
        result.map_err(|e| e.into())
    }

    async fn core_search(
        &self,
        batch_request: Arc<CoreSearchRequestBatch>,
        _search_runtime_handle: &AdaptiveSearchHandle,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<Vec<Vec<ScoredPoint>>> {
        let processed_timeout = Self::process_read_timeout(timeout, "search")?;
        let mut timer = ScopeDurationMeasurer::new(&self.telemetry_search_durations);
        timer.set_success(false);

        let search_points = batch_request
            .searches
            .iter()
            .map(|s| CollectionCoreSearchRequest((self.collection_id.clone(), s)).into())
            .collect();

        let request = &CoreSearchBatchPointsInternal {
            collection_name: self.collection_id.clone(),
            search_points,
            shard_id: Some(self.id),
            timeout: processed_timeout.map(|t| t.as_secs()),
        };
        let search_batch_response = self
            .with_points_client(|mut client| async move {
                let mut request = tonic::Request::new(request.clone());

                if let Some(timeout) = processed_timeout {
                    request.set_timeout(timeout);
                }

                client.core_search_batch(request).await
            })
            .await?
            .into_inner();

        let SearchBatchResponse {
            result,
            time: _,
            usage,
        } = search_batch_response;

        if let Some(hw_usage) = usage.unwrap_or_default().hardware {
            hw_measurement_acc.accumulate_request(hw_usage);
        }

        let result: Result<Vec<Vec<ScoredPoint>>, Status> = result
            .into_iter()
            .zip(batch_request.searches.iter())
            .map(|(batch_result, request)| {
                let is_payload_required = request
                    .with_payload
                    .as_ref()
                    .is_some_and(|with_payload| with_payload.is_required());

                batch_result
                    .result
                    .into_iter()
                    .map(|point| try_scored_point_from_grpc(point, is_payload_required))
                    .collect()
            })
            .collect();
        let result = result.map_err(|e| e.into());
        if result.is_ok() {
            timer.set_success(true);
        }
        result
    }

    async fn count(
        &self,
        request: Arc<CountRequestInternal>,
        _search_runtime_handle: &AdaptiveSearchHandle,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
        // TODO(deferred): Find a solution for this parameter, and don't` simply ignore it. E.g. we might call `count` directly and remove the parameter from the trait signature.
        _deferred_behavior: DeferredBehavior,
    ) -> CollectionResult<CountResult> {
        let processed_timeout = Self::process_read_timeout(timeout, "count")?;
        let count_points = CountPoints {
            collection_name: self.collection_id.clone(),
            filter: request.filter.clone().map(Filter::into),
            exact: Some(request.exact),
            read_consistency: None,
            shard_key_selector: None,
            timeout: processed_timeout.map(|t| t.as_secs()),
        };

        let count_request = &CountPointsInternal {
            count_points: Some(count_points),
            shard_id: Some(self.id),
        };
        let count_response = self
            .with_points_client(|mut client| async move {
                let mut request = tonic::Request::new(count_request.clone());
                if let Some(timeout) = processed_timeout {
                    request.set_timeout(timeout);
                }
                client.count(request).await
            })
            .await?
            .into_inner();

        let CountResponse {
            result,
            time: _,
            usage,
        } = count_response;

        if let Some(hw_usage) = usage.unwrap_or_default().hardware {
            hw_measurement_acc.accumulate_request(hw_usage);
        }

        result.map_or_else(
            || {
                Err(CollectionError::service_error(
                    "Unexpected empty CountResult".to_string(),
                ))
            },
            |count_result| Ok(count_result.into()),
        )
    }

    async fn retrieve(
        &self,
        request: Arc<PointRequestInternal>,
        with_payload: &WithPayload,
        with_vector: &WithVector,
        _search_runtime_handle: &AdaptiveSearchHandle,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
        // TODO(deferred): Find a solution for this parameter, and don't simply ignore it.
        _deferred_behavior: DeferredBehavior,
    ) -> CollectionResult<Vec<RecordInternal>> {
        let processed_timeout = Self::process_read_timeout(timeout, "retrieve")?;
        let get_points = GetPoints {
            collection_name: self.collection_id.clone(),
            ids: request
                .ids
                .iter()
                .copied()
                .map(ExtendedPointId::into)
                .collect(),
            with_payload: request.with_payload.clone().map(WithPayloadInterface::into),
            with_vectors: Some(with_vector.clone().into()),
            read_consistency: None,
            shard_key_selector: None,
            timeout: processed_timeout.map(|t| t.as_secs()),
        };
        let get_request = &GetPointsInternal {
            get_points: Some(get_points),
            shard_id: Some(self.id),
        };

        let get_response = self
            .with_points_client(|mut client| async move {
                let mut request = tonic::Request::new(get_request.clone());
                if let Some(timeout) = processed_timeout {
                    request.set_timeout(timeout);
                }
                client.get(request).await
            })
            .await?
            .into_inner();

        if let Some(hw_usage) = get_response.usage.unwrap_or_default().hardware {
            hw_measurement_acc.accumulate_request(hw_usage);
        }

        let result: Result<Vec<RecordInternal>, Status> = get_response
            .result
            .into_iter()
            .map(|point| try_record_from_grpc(point, with_payload.enable))
            .collect();

        result.map_err(|e| e.into())
    }

    async fn query_batch(
        &self,
        requests: Arc<Vec<ShardQueryRequest>>,
        _search_runtime_handle: &AdaptiveSearchHandle,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<Vec<ShardQueryResponse>> {
        let processed_timeout = Self::process_read_timeout(timeout, "query_batch")?;
        let mut timer = ScopeDurationMeasurer::new(&self.telemetry_search_durations);
        timer.set_success(false);

        let requests = requests.as_ref();

        let batch_response = self
            .with_points_client(|mut client| async move {
                let query_points = requests
                    .iter()
                    .map(|request| QueryShardPoints::from(request.clone()))
                    .collect();

                let request = &QueryBatchPointsInternal {
                    collection_name: self.collection_id.clone(),
                    query_points,
                    shard_id: Some(self.id),
                    timeout: processed_timeout.map(|t| t.as_secs()),
                };

                let mut request = tonic::Request::new(request.clone());

                if let Some(timeout) = processed_timeout {
                    request.set_timeout(timeout);
                }

                client.query_batch(request).await
            })
            .await?
            .into_inner();

        let QueryBatchResponseInternal {
            results,
            time: _,
            hardware_usage,
            inference_usage: _, // Remote shards don't have inference usage, so we can ignore it
        } = batch_response;

        if let Some(hw_usage) = hardware_usage {
            hw_measurement_acc.accumulate_request(hw_usage);
        }

        let result = results
            .into_iter()
            .zip(requests.iter())
            .map(|(query_result, request)| {
                let is_payload_required = request.with_payload.is_required();

                query_result
                    .intermediate_results
                    .into_iter()
                    .map(|intermediate| {
                        intermediate
                            .result
                            .into_iter()
                            .map(|point| try_scored_point_from_grpc(point, is_payload_required))
                            .collect()
                    })
                    .collect()
            })
            .try_collect()?;

        timer.set_success(true);

        Ok(result)
    }

    async fn facet(
        &self,
        request: Arc<FacetParams>,
        _search_runtime_handle: &AdaptiveSearchHandle,
        timeout: Option<Duration>,
        hw_measurement_acc: HwMeasurementAcc,
    ) -> CollectionResult<FacetResponse> {
        let processed_timeout = Self::process_read_timeout(timeout, "facet")?;
        let mut timer = ScopeDurationMeasurer::new(&self.telemetry_search_durations);
        timer.set_success(false);

        let FacetParams {
            key,
            limit,
            filter,
            exact,
        } = request.as_ref();

        let response = self
            .with_points_client(|mut client| async move {
                let request = &FacetCountsInternal {
                    collection_name: self.collection_id.clone(),
                    key: key.to_string(),
                    filter: filter.clone().map(api::grpc::qdrant::Filter::from),
                    limit: *limit as u64,
                    exact: *exact,
                    shard_id: self.id,
                    timeout: processed_timeout.map(|t| t.as_secs()),
                };

                let mut request = tonic::Request::new(request.clone());

                if let Some(timeout) = timeout {
                    request.set_timeout(timeout);
                }

                client.facet(request).await
            })
            .await?
            .into_inner();

        if let Some(hw_usage) = response.usage {
            hw_measurement_acc.accumulate_request(hw_usage);
        }

        let hits = response
            .hits
            .into_iter()
            .map(FacetValueHit::try_from)
            .try_collect()?;

        let result = FacetResponse { hits };

        timer.set_success(true);

        Ok(result)
    }

    async fn stop_gracefully(self) {
        // No background operations to stop on RemoteShard
    }
}use std::fmt;

use schemars::JsonSchema;
use segment::types::ShardKey;
use serde::{Deserialize, Serialize};
use uuid::Uuid;

use super::shard::{PeerId, ShardId};
use crate::operations::cluster_ops::ReshardingDirection;

#[derive(Clone, Debug, Eq, PartialEq, Deserialize, Serialize)]
pub struct ReshardState {
    pub uuid: Uuid,
    pub peer_id: PeerId,
    pub shard_id: ShardId,
    pub shard_key: Option<ShardKey>,
    pub direction: ReshardingDirection,
    pub stage: ReshardingStage,
}

impl ReshardState {
    pub fn new(
        uuid: Uuid,
        direction: ReshardingDirection,
        peer_id: PeerId,
        shard_id: ShardId,
        shard_key: Option<ShardKey>,
    ) -> Self {
        Self {
            uuid,
            direction,
            peer_id,
            shard_id,
            shard_key,
            stage: ReshardingStage::MigratingPoints,
        }
    }

    pub fn matches(&self, key: &ReshardKey) -> bool {
        let ReshardKey {
            uuid,
            direction,
            peer_id,
            shard_id,
            shard_key,
        } = key;

        self.uuid == *uuid
            && self.direction == *direction
            && self.peer_id == *peer_id
            && self.shard_id == *shard_id
            && self.shard_key == *shard_key
    }

    pub fn key(&self) -> ReshardKey {
        let ReshardState {
            uuid,
            peer_id,
            shard_id,
            shard_key,
            direction,
            stage: _,
        } = self;

        ReshardKey {
            uuid: *uuid,
            direction: *direction,
            peer_id: *peer_id,
            shard_id: *shard_id,
            shard_key: shard_key.clone(),
        }
    }
}

/// Resharding stages
///
/// # Warning
///
/// This enum is ordered!
#[derive(Copy, Clone, Debug, Default, Eq, PartialEq, Ord, PartialOrd, Deserialize, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum ReshardingStage {
    #[default]
    MigratingPoints,
    ReadHashRingCommitted,
    WriteHashRingCommitted,
}

/// Unique identifier of a resharding task
#[derive(Clone, Debug, Eq, PartialEq, Hash, Deserialize, Serialize, JsonSchema)]
pub struct ReshardKey {
    #[schemars(skip)]
    pub uuid: Uuid,
    #[serde(default)]
    pub direction: ReshardingDirection,
    pub peer_id: PeerId,
    pub shard_id: ShardId,
    pub shard_key: Option<ShardKey>,
}

impl ReshardKey {
    /// Pin the auto-sharding invariant that resharding always targets the
    /// last shard id. `shard_number` must equal `shard_id` or `shard_id + 1`;
    /// any other value would silently corrupt the count via the id-derived
    /// `shard_number` update.
    pub(crate) fn debug_assert_targets_last_shard(&self, shard_number: u32) {
        let shard_id = self.shard_id;
        debug_assert!(
            shard_id
                .checked_add(1)
                .is_some_and(|next| shard_number == shard_id || shard_number == next),
            "auto-sharding resharding must target the last shard id; \
             shard_number={shard_number} shard_id={shard_id}",
        );
    }
}

impl fmt::Display for ReshardKey {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}/{}/{:?}", self.peer_id, self.shard_id, self.shard_key)
    }
}use std::collections::{HashMap, HashSet};
use std::hash;
use std::iter::Peekable;
use std::rc::Rc;

use itertools::Itertools;
use segment::data_types::facets::{FacetResponse, FacetValue};
use segment::types::{Payload, ScoredPoint};
use shard::retrieve::record_internal::RecordInternal;
use tinyvec::TinyVec;

use crate::common::transpose_iterator::transposed_iter;
use crate::operations::types::CountResult;
use crate::operations::universal_query::shard_query::ShardQueryResponse;

#[derive(Copy, Clone, Debug, Eq, PartialEq)]
pub enum ResolveCondition {
    All,
    Majority,
}

impl ResolveCondition {
    fn resolution_count(&self, num_replicas: usize) -> usize {
        match self {
            Self::All => num_replicas,
            Self::Majority => num_replicas / 2 + 1,
        }
    }
}

pub trait Resolve: Default + Sized {
    fn resolve(responses: Vec<Self>, condition: ResolveCondition) -> Self;
}

impl Resolve for CountResult {
    fn resolve(records: Vec<Self>, condition: ResolveCondition) -> Self {
        match condition {
            ResolveCondition::All => Self {
                count: records
                    .iter()
                    .map(|result| result.count)
                    .min()
                    .unwrap_or_default(),
            },
            ResolveCondition::Majority => {
                let mut counts = records
                    .iter()
                    .map(|result| result.count)
                    .collect::<Vec<_>>();
                counts.sort_unstable();
                let middle = counts.len() / 2;
                Self {
                    count: counts.get(middle).copied().unwrap_or_default(),
                }
            }
        }
    }
}

impl Resolve for FacetResponse {
    /// Resolve the counts for each value using the CountResult implementation
    fn resolve(responses: Vec<Self>, condition: ResolveCondition) -> Self {
        let num_replicas = responses.len();
        let resolution_count = condition.resolution_count(num_replicas);

        // Example responses:
        // [
        //   {
        //     hits: [
        //       { value: "a", count: 20 },
        //       { value: "b": count: 15 }
        //     ]
        //   },
        //   {
        //     hits: [
        //       { value: "a", count: 21 },
        //       { value: "b": count: 13 }
        //     ]
        //   },
        // ]

        let resolved_counts: HashMap<_, _> = responses
            .iter()
            .flat_map(|FacetResponse { hits }| hits)
            // Collect all hits into a Hashmap of {value -> Vec<CountResult>}
            .fold(
                HashMap::new(),
                |mut map: HashMap<FacetValue, Vec<CountResult>>, hit| {
                    if let Some(counts) = map.get_mut(&hit.value) {
                        counts.push(CountResult { count: hit.count });
                    } else {
                        map.entry(hit.value.clone())
                            .or_insert(Vec::with_capacity(num_replicas))
                            .push(CountResult { count: hit.count });
                    };
                    map
                },
            )
            .into_iter()
            // Filter out values that don't appear in enough replicas
            .filter(|(_, counts)| counts.len() >= resolution_count)
            // Resolve the counts with the CountResult implementation
            .map(|(value, counts)| {
                let count = CountResult::resolve(counts, condition).count;

                (value, count)
            })
            .collect();

        let filtered_iters = responses.into_iter().map(|FacetResponse { hits }| {
            hits.into_iter().filter_map(|mut hit| {
                resolved_counts.get(&hit.value).map(|&count| {
                    // Use the resolved count
                    hit.count = count;
                    hit
                })
            })
        });

        // Retain the original order of the hits (instead of always sorting in the same direction).
        let resolved_hits =
            MergeInOrder::new(filtered_iters, |hit| hit.value.clone(), resolution_count).collect();

        // resolved_hits for ResolveCondition::All:
        // [
        //  { value: "a", count: 20 },
        //  { value: "b", count: 13 }
        // ]

        FacetResponse {
            hits: resolved_hits,
        }
    }
}

impl Resolve for Vec<RecordInternal> {
    fn resolve(records: Vec<Self>, condition: ResolveCondition) -> Self {
        Resolver::resolve(records, |record| record.id, record_eq, condition)
    }
}

impl Resolve for Vec<Vec<ScoredPoint>> {
    fn resolve(batches: Vec<Self>, condition: ResolveCondition) -> Self {
        // batches: <replica_id, <batch_id, ScoredPoints>>
        // transpose to <batch_id, <replica_id, ScoredPoints>>

        let batches = transposed_iter(batches);

        batches
            .map(|points| Resolver::resolve(points, |point| point.id, scored_point_eq, condition))
            .collect()
    }
}

impl Resolve for Vec<ShardQueryResponse> {
    fn resolve(batches: Vec<Self>, condition: ResolveCondition) -> Self {
        // batches: <replica_id, <batch_id, ShardQueryResponse>>
        // transpose to <batch_id, <replica_id, ShardQueryResponse>>

        let batches = transposed_iter(batches);

        batches
            .into_iter()
            .map(|shard_responses| Resolve::resolve(shard_responses, condition))
            .collect()
    }
}

fn record_eq(this: &RecordInternal, other: &RecordInternal) -> bool {
    this.id == other.id
        && this.order_value == other.order_value
        && this.vector == other.vector
        && payload_eq(&this.payload, &other.payload)
}

fn scored_point_eq(this: &ScoredPoint, other: &ScoredPoint) -> bool {
    this.id == other.id
        && this.score == other.score
        && this.order_value == other.order_value
        && this.vector == other.vector
        && payload_eq(&this.payload, &other.payload)
}

fn payload_eq(this: &Option<Payload>, other: &Option<Payload>) -> bool {
    match (this, other) {
        (Some(payload), None) | (None, Some(payload)) => payload.is_empty(),
        (this, other) => this == other,
    }
}

/// Expected number of replicas
const EXPECTED_REPLICAS: usize = 5;

type ResolverRecords<'a, Item> = TinyVec<[ResolverRecord<'a, Item>; EXPECTED_REPLICAS]>;

struct Resolver<'a, Item, Id, Ident, Cmp> {
    items: HashMap<Id, ResolverRecords<'a, Item>>,
    identify: Ident,
    compare: Cmp,
}

impl<'a, Item, Id, Ident, Cmp> Resolver<'a, Item, Id, Ident, Cmp>
where
    Id: Eq + hash::Hash,
    Ident: Fn(&Item) -> Id + Copy,
    Cmp: Fn(&Item, &Item) -> bool,
{
    pub fn resolve(
        items: Vec<Vec<Item>>,
        identify: Ident,
        compare: Cmp,
        condition: ResolveCondition,
    ) -> Vec<Item> {
        let resolution_count = condition.resolution_count(items.len());

        // Items:
        //  [
        //      [
        //          { id: 10, item: A, score: 0.9 },
        //          { id: 3, item: B, score: 0.8 },
        //          { id: 4, item: C, score: 0.7 }
        //      ],
        //      [
        //          { id: 10, item: A, score: 0.9 },
        //          { id: 3, item: B, score: 0.8 },
        //          { id: 4, item: C, score: 0.7 }
        //      ],
        //      [
        //          { id: 10, item: A, score: 0.9 },
        //          { id: 4, item: C, score: 0.7 },
        //          { id: 2, item: D, score: 0.6 }
        //      ]
        //  ]
        let mut resolver = Resolver::new(items.first().map_or(0, Vec::len), identify, compare);
        resolver.add_all(&items);

        // resolver items:
        // {
        //     10: [ { item: A, count: 3, coordinates: [(0, 0), (1, 0), (2, 0)] } ],
        //     3:  [ { item: B, count: 2, coordinates: [(0, 1), (1, 1)] } ],
        //     4:  [ { item: C, count: 3, coordinates: [(0, 2), (1, 2), (2, 1)] } ],
        //     2:  [ { item: D, count: 1, coordinates: [(2, 2)] } ]
        // }

        // For majority, we need resolution_count = 2

        // Select coordinates of accepted items, avoiding copying
        let resolved_coords: HashSet<_> = resolver
            .items
            .into_values()
            .filter_map(|points| {
                points
                    .into_iter()
                    .find(|point| point.count >= resolution_count)
                    .map(|point| point.coordinates.into_iter())
            })
            .flatten()
            .collect();

        // resolved coords:
        // [
        //     (0, 0), (1, 0), (2, 0),
        //     (0, 1), (1, 1),
        //     (0, 2), (1, 2), (2, 1)
        // ]

        // Shortcut if everything is consistent: return first items, avoiding filtering
        let all_items_len = items.iter().map(Vec::len).sum::<usize>();
        let is_consistent = resolved_coords.len() == all_items_len;

        if is_consistent {
            // Return the first replica result as everything is consistent
            return items.into_iter().next().unwrap_or_default();
        }

        // Items:
        //  [
        //      [
        //          { id: 3, item: B, score: 0.8 },
        //          { id: 4, item: C, score: 0.7 }
        //      ],
        //      [
        //          { id: 3, item: B, score: 0.8 },
        //          { id: 4, item: C, score: 0.7 }
        //      ],
        //      [
        //          { id: 4, item: C, score: 0.7 },
        //      ]
        //  ]
        let resolved_coords = Rc::new(resolved_coords);

        let resolved_iters = items
            .into_iter()
            .enumerate()
            .map(|(replica_id, replica_response)| {
                // replica_response:
                //  [
                //      { id: 10, item: A, score: 0.9 },
                //      { id: 4, item: C, score: 0.7 },
                //      { id: 2, item: D, score: 0.6 }
                //  ]

                let resolved_coords = resolved_coords.clone();
                replica_response
                    .into_iter()
                    .enumerate()
                    .filter_map(move |(index, item)| {
                        resolved_coords
                            .contains(&(replica_id, index))
                            .then_some(item)
                    })

                // Iterator of filtered items:
                //  Iter<
                //      { id: 10, item: A, score: 0.9 },
                //      { id: 4, item: C, score: 0.7 },
                //  >
            });

        MergeInOrder::new(resolved_iters, identify, resolution_count).collect_vec()
    }

    fn new(capacity: usize, identify: Ident, compare: Cmp) -> Self {
        Self {
            items: HashMap::with_capacity(capacity),
            identify,
            compare,
        }
    }

    fn add_all<I>(&mut self, items: I)
    where
        I: IntoIterator,
        I::Item: IntoIterator<Item = &'a Item>,
    {
        for (row, items) in items.into_iter().enumerate() {
            for (index, item) in items.into_iter().enumerate() {
                self.add((self.identify)(item), item, row, index);
            }
        }
    }

    fn add(&mut self, id: Id, item: &'a Item, row: RowId, index: ColumnId) {
        let points = self.items.entry(id).or_default();

        for point in points.iter_mut() {
            if (self.compare)(item, point.item.unwrap()) {
                point.count += 1;
                point.coordinates.push((row, index));
                return;
            }
        }

        points.push(ResolverRecord::new(item, row, index));
    }
}

type RowId = usize;
type ColumnId = usize;

#[derive(Debug, Clone)]
struct ResolverRecord<'a, T> {
    item: Option<&'a T>,
    /// Store all coordinates of equal items in `(row, index)` tuples
    coordinates: TinyVec<[(RowId, ColumnId); EXPECTED_REPLICAS]>,
    /// Keeps track of the amount of times we see this same item
    count: usize,
}

impl<T> Default for ResolverRecord<'_, T> {
    fn default() -> Self {
        Self {
            item: None,
            coordinates: Default::default(),
            count: 0,
        }
    }
}

impl<'a, T> ResolverRecord<'a, T> {
    fn new(item: &'a T, row: RowId, index: ColumnId) -> Self {
        let mut coordinates = TinyVec::new();
        coordinates.push((row, index));

        Self {
            item: Some(item),
            coordinates,
            count: 1,
        }
    }
}

/// Resolves multiple list of items by reading heads of all iterators on each step
/// and accepting the most common occurrence as the next resolved item.
///
/// [
///    [A, F, B, C],
///    [A, B, C],
///    [F, B, C],
/// ]
///
///   1   2   3   4
///  [A,  F,  B,  C]
///  [A,      B,  C]
///  [    F,  B,  C]
struct MergeInOrder<I: Iterator, Ident> {
    /// One iterator per set of results, which outputs items that comply with resolution count, in their original order
    resolved_iters: Vec<Peekable<I>>,
    /// Closure which retrieves the item's ID
    ident: Ident,

    /// Only used to debug_assert correctness
    resolution_count: usize,
}

impl<Iter, Ident, Id, Item> MergeInOrder<Iter, Ident>
where
    Id: Eq + hash::Hash,
    Ident: Fn(&Item) -> Id,
    Iter: Iterator<Item = Item>,
{
    fn new(
        resolved_iters: impl Iterator<Item = Iter>,
        identify: Ident,
        resolution_count: usize,
    ) -> Self {
        let resolved_iters = resolved_iters.map(|iter| iter.peekable()).collect();

        Self {
            resolved_iters,
            ident: identify,
            resolution_count,
        }
    }

    /// An iterator over all current heads of the resolved iterators
    fn peek_heads(&mut self) -> impl Iterator<Item = (RowId, Id)> + '_ {
        self.resolved_iters
            .iter_mut()
            .enumerate()
            .filter_map(|(row, iter)| iter.peek().map(|peeked| (row, (self.ident)(peeked))))
    }

    /// Peeks each row, then maps IDs to the peeked rows in which each ID appears
    ///
    /// Example:
    ///
    /// ```text
    /// resolved_iters = [
    ///     <- (10, A) <- (4, B) <- (3, C)
    ///     <- (10, A) <- (4, B) <- (3, C)
    ///     <- (4, B) <- (3, C)
    /// ]
    /// ```
    ///
    /// output:
    /// ```text
    /// {
    ///     10: [0, 1],
    ///     4:  [2],
    /// }
    /// ```
    fn heads_map(&mut self) -> HashMap<Id, TinyVec<[RowId; EXPECTED_REPLICAS]>> {
        let capacity = self.resolved_iters.len();
        self.peek_heads()
            .fold(HashMap::with_capacity(capacity), |mut map, (row, id)| {
                let entry = map.entry(id).or_default();
                entry.push(row);
                map
            })
    }

    /// Advances the rows and returns the item in the first of them
    ///
    /// Minimum len of `row_ids` should be the resolution count.
    fn advance_rows(&mut self, row_ids: &[RowId]) -> Option<Item> {
        debug_assert!(row_ids.len() >= self.resolution_count);

        let mut merged_item = None;
        for row_id in row_ids {
            merged_item = self.resolved_iters[*row_id].next();
        }

        merged_item
    }
}

impl<Iter, Ident, Id, Item> Iterator for MergeInOrder<Iter, Ident>
where
    Id: Eq + hash::Hash,
    Ident: Fn(&Item) -> Id,
    Iter: Iterator<Item = Item>,
{
    type Item = Item;

    fn next(&mut self) -> Option<Self::Item> {
        // Choose the item that appears the most times in the heads

        // heads_map: (id to source row_ids)
        // {
        //     10: [0, 1],
        //     4:  [2],
        // }
        let heads_map = self.heads_map();

        // Most frequent row IDs - Assume most frequent item is the one to be resolved next
        // [0, 1]
        let chosen_rows = heads_map.into_values().max_by_key(|kv| kv.len())?;

        // Pull the item from the chosen rows (return only one of them)
        self.advance_rows(&chosen_rows)
    }
}

#[cfg(test)]
mod test {
    use std::fmt;

    use common::types::ScoreType;

    use super::*;

    #[rustfmt::skip]
    fn resolve_scored_points_batch_4_data() -> [Vec<ScoredPoint>; 3] {
        [
            vec![
                point(14, 0.0), point(17, 0.1), point(15, 0.1),
                point(13, 0.2), point(11, 0.2), point(12, 0.3),
                point(18, 0.3), point(16, 0.4), point(10, 0.5),
            ],
            vec![
                point(23, 0.0), point(21, 0.1), point(25, 0.2),
                point(22, 0.2), point(20, 0.3), point(24, 0.3),
            ],
            vec![
                point(30, 0.1), point(31, 0.1), point(32, 0.1),
                point(33, 0.2), point(34, 0.2), point(35, 0.3),
            ],
        ]
    }

    fn point(id: u64, score: ScoreType) -> ScoredPoint {
        ScoredPoint {
            id: id.into(),
            version: 1,
            score,
            payload: None,
            vector: None,
            shard_key: None,
            order_value: None,
        }
    }

    #[rustfmt::skip]
    fn resolve_scored_points_batch_4_input() -> Vec<Vec<Vec<ScoredPoint>>> {
        let [batch1, batch2, batch3] = resolve_scored_points_batch_4_data();

        vec![
            vec![
                batch(&batch1, [remove(2), remove(3)]),
                batch(&batch2, [remove(0), remove(3)]),
                batch(&batch3, [remove(4), remove(5)]),
            ],

            vec![
                batch(&batch1, [remove(1), modify(3)]),
                batch(&batch2, [modify(0), remove(2)]),
                batch(&batch3, [remove(3), modify(5)]),
            ],

            vec![
                batch(&batch1, [remove(1), modify(4)]),
                batch(&batch2, [modify(3), remove(5)]),
                batch(&batch3, [remove(2), modify(5)]),
            ],

            vec![
                batch1,
                batch2,
                batch3,
            ],
        ]
    }

    fn batch<const N: usize>(batch: &[ScoredPoint], mut actions: [Action; N]) -> Vec<ScoredPoint> {
        let mut batch = batch.to_owned();

        actions.sort_unstable_by_key(|action| action.index());

        let mut removed = Vec::new();

        for action in actions {
            let offset = removed
                .iter()
                .filter(|&&removed| removed <= action.index())
                .count();

            match action {
                Action::Remove(index) => {
                    batch.remove(index - offset);
                    removed.push(index);
                }

                Action::Modify(index) => {
                    batch[index - offset].score += 1.0;
                }
            }
        }

        batch
    }

    #[derive(Copy, Clone, Debug)]
    enum Action {
        Remove(usize),
        Modify(usize),
    }

    impl Action {
        pub fn index(self) -> usize {
            match self {
                Self::Remove(index) => index,
                Self::Modify(index) => index,
            }
        }
    }

    fn remove(index: usize) -> Action {
        Action::Remove(index)
    }

    fn modify(index: usize) -> Action {
        Action::Modify(index)
    }

    #[test]
    fn resolve_scored_points_batch_4_all() {
        let [mut batch1, mut batch2, mut batch3] = resolve_scored_points_batch_4_data();

        batch1.remove(4);
        batch1.remove(3);
        batch1.remove(2);
        batch1.remove(1);

        batch2.remove(5);
        batch2.remove(3);
        batch2.remove(2);
        batch2.remove(0);

        batch3.remove(5);
        batch3.remove(4);
        batch3.remove(3);
        batch3.remove(2);

        test_resolve(
            resolve_scored_points_batch_4_input(),
            [batch1, batch2, batch3],
            ResolveCondition::All,
        );
    }

    #[test]
    fn resolve_scored_points_batch_4_majority() {
        let [mut batch1, mut batch2, mut batch3] = resolve_scored_points_batch_4_data();

        batch1.remove(3);
        batch1.remove(1);

        batch2.remove(3);
        batch2.remove(0);

        batch3.remove(5);

        test_resolve(
            resolve_scored_points_batch_4_input(),
            [batch1, batch2, batch3],
            ResolveCondition::Majority,
        );
    }

    fn data_simple() -> [i32; 9] {
        [1, 2, 3, 4, 5, 6, 7, 8, 9]
    }

    #[rustfmt::skip]
    fn input_2() -> [Vec<i32>; 2] {
        [
            vec![1, 2, 3,       6, 7,    9,     11, 12, 13],
            vec![      3, 4, 5, 6,    8,    10, 11,       ],
        ]
    }

    fn expected_2() -> [i32; 3] {
        [3, 6, 11]
    }

    #[rustfmt::skip]
    fn input_3() -> [Vec<i32>; 3] {
        [
            vec![1, 2,          6, 7, 8,       11,      13, 14, 15,       ],
            vec![   2, 3, 4,       7,    9, 10,         13, 14,     16,   ],
            vec![         4, 5, 6, 7,    9,    11, 12,      14,         17],
        ]
    }

    fn expected_3_all() -> [i32; 2] {
        [7, 14]
    }

    fn expected_3_majority() -> [i32; 8] {
        [2, 4, 6, 7, 9, 11, 13, 14]
    }

    #[rustfmt::skip]
    fn input_4() -> [Vec<i32>; 4] {
        [
            vec![1, 2, 3,                9,     11, 12, 13, 14,     16,         19,     21, 22,     24,     27,     29],
            vec![   2, 3, 4, 5, 6,                  12, 13,     15,     17,     19,         22,     24, 26, 27, 28,   ],
            vec![      3,    5, 6, 7, 8, 9,             13,     15, 16,     18,     20,     22,         26, 27, 28,   ],
            vec![               6,    8, 9, 10, 11, 12, 13,         16,     18, 19,     21,     23,     26, 27,     29],
        ]
    }

    fn expected_4_all() -> [i32; 2] {
        [13, 27]
    }

    fn expected_4_majority() -> [i32; 10] {
        [3, 6, 9, 12, 13, 16, 19, 22, 26, 27]
    }

    #[rustfmt::skip]
    fn input_5() -> [Vec<i32>; 3] {
        [
            vec![1, 2, 3, 4, 5, 6, 7],
            vec![               6, 7],
            vec![1, 2, 3, 4         ],
        ]
    }

    fn expected_5_majority() -> [i32; 6] {
        [1, 2, 3, 4, 6, 7]
    }

    fn expected_5_all() -> [i32; 0] {
        []
    }

    #[test]
    fn resolve_0_all() {
        resolve_0(ResolveCondition::All);
    }

    #[test]
    fn resolve_0_majority() {
        resolve_0(ResolveCondition::Majority);
    }

    fn resolve_0(condition: ResolveCondition) {
        test_resolve_simple(Vec::<Vec<i32>>::new(), Vec::new(), condition);
    }

    #[test]
    fn resolve_simple_all() {
        for replicas in 1..=5 {
            resolve_simple(replicas, ResolveCondition::All);
        }
    }

    #[test]
    fn resolve_simple_majority() {
        for replicas in 1..=5 {
            resolve_simple(replicas, ResolveCondition::All);
        }
    }

    fn resolve_simple(replicas: usize, condition: ResolveCondition) {
        let input: Vec<_> = (0..replicas).map(|_| data_simple()).collect();
        let expected = data_simple();

        test_resolve_simple(input, expected, condition)
    }

    #[test]
    fn resolve_2_all() {
        test_resolve_simple(input_2(), expected_2(), ResolveCondition::All);
    }

    #[test]
    fn resolve_2_majority() {
        test_resolve_simple(input_2(), expected_2(), ResolveCondition::Majority);
    }

    #[test]
    fn resolve_3_all() {
        test_resolve_simple(input_3(), expected_3_all(), ResolveCondition::All);
    }

    #[test]
    fn resolve_3_majority() {
        test_resolve_simple(input_3(), expected_3_majority(), ResolveCondition::Majority);
    }

    #[test]
    fn resolve_4_all() {
        test_resolve_simple(input_4(), expected_4_all(), ResolveCondition::All);
    }

    #[test]
    fn resolve_4_majority() {
        test_resolve_simple(input_4(), expected_4_majority(), ResolveCondition::Majority);
    }

    #[test]
    fn resolve_5_majority() {
        test_resolve_simple(input_5(), expected_5_majority(), ResolveCondition::Majority);
    }

    #[test]
    fn resolve_5_all() {
        test_resolve_simple(input_5(), expected_5_all(), ResolveCondition::All);
    }

    fn test_resolve<T, E>(input: Vec<T>, expected: E, condition: ResolveCondition)
    where
        T: Resolve + Clone + PartialEq<E> + fmt::Debug,
        E: fmt::Debug,
    {
        assert_eq!(T::resolve(input, condition), expected);
    }

    fn test_resolve_simple<I, E>(input: I, expected: E, condition: ResolveCondition)
    where
        I: IntoIterator,
        I::Item: IntoIterator<Item = i32>,
        E: IntoIterator<Item = i32>,
    {
        test_resolve(simple_input(input), simple_expected(expected), condition);
    }

    fn simple_input<I>(input: I) -> Vec<Vec<Val>>
    where
        I: IntoIterator,
        I::Item: IntoIterator<Item = i32>,
    {
        input
            .into_iter()
            .map(|items| items.into_iter().map(Val).collect())
            .collect()
    }

    fn simple_expected<E>(expected: E) -> Vec<Val>
    where
        E: IntoIterator<Item = i32>,
    {
        expected.into_iter().map(Val).collect()
    }

    #[derive(Copy, Clone, Debug, Eq, PartialEq, Ord, PartialOrd)]
    struct Val(i32);

    impl Resolve for Vec<Val> {
        fn resolve(values: Vec<Self>, condition: ResolveCondition) -> Self {
            Resolver::resolve(values, |val| val.0, PartialEq::eq, condition)
        }
    }
}use std::path::{Path, PathBuf};

use common::fs::{atomic_save_json, read_json};
use common::tar_ext;
use serde::{Deserialize, Serialize};

use crate::operations::types::CollectionResult;
use crate::shards::shard::PeerId;

pub const SHARD_CONFIG_FILE: &str = "shard_config.json";

#[derive(Debug, Deserialize, Serialize, Clone, PartialEq, Eq)]
pub enum ShardType {
    Local,                      // Deprecated
    Remote { peer_id: PeerId }, // Deprecated
    Temporary,                  // Deprecated
    ReplicaSet,
}

#[derive(Debug, Deserialize, Serialize, Clone, PartialEq, Eq)]
pub struct ShardConfig {
    pub r#type: ShardType,
}

impl ShardConfig {
    pub fn get_config_path(shard_path: &Path) -> PathBuf {
        shard_path.join(SHARD_CONFIG_FILE)
    }

    pub fn new_replica_set() -> Self {
        Self {
            r#type: ShardType::ReplicaSet,
        }
    }

    pub fn load(shard_path: &Path) -> CollectionResult<Option<Self>> {
        let config_path = Self::get_config_path(shard_path);
        if !config_path.exists() {
            log::info!("Detected missing shard config file in {shard_path:?}");
            return Ok(None);
        }
        Ok(Some(read_json(&config_path)?))
    }

    pub fn save(&self, shard_path: &Path) -> CollectionResult<()> {
        let config_path = Self::get_config_path(shard_path);
        Ok(atomic_save_json(&config_path, self)?)
    }

    pub async fn save_to_tar(&self, tar: &tar_ext::BuilderExt) -> CollectionResult<()> {
        let bytes = serde_json::to_vec(self)?;
        tar.append_data(bytes, Path::new(SHARD_CONFIG_FILE)).await?;
        Ok(())
    }
