                .read_all(true)
                .map(|e| e.map(|(op_num, op)| (op_num, op.clock_tag))),
            recovery_point,
            newest_clocks,
            oldest_clocks,
        );
        assert_eq!(resolve_result.unwrap_err(), WalDeltaError::Cutoff);
    }

