#[derive(Serialize, Clone, Debug, JsonSchema, Anonymize)]
pub struct ClusterTelemetry {
    pub enabled: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub status: Option<ClusterStatusTelemetry>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub config: Option<ClusterConfigTelemetry>,
    #[serde(skip_serializing_if = "Option::is_none")]
    #[anonymize(with = anonymize_collection_values_opt)]
    pub peers: Option<HashMap<PeerId, PeerInfo>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    #[anonymize(false)]
    pub peer_metadata: Option<HashMap<PeerId, PeerMetadata>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub metadata: Option<HashMap<String, serde_json::Value>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub resharding_enabled: Option<bool>,
}

impl ClusterTelemetry {
    pub fn collect(
        auth: &Auth,
        detail: TelemetryDetail,
        dispatcher: &Dispatcher,
        settings: &Settings,
    ) -> Option<ClusterTelemetry> {
        let global_access = AccessRequirements::new();
        if auth
            .unlogged_access()
            .check_global_access(global_access)
            .is_err()
        {
            return None;
        }

        Some(ClusterTelemetry {
            enabled: settings.cluster.enabled,
            status: (detail.level >= DetailsLevel::Level1)
                .then(|| match dispatcher.cluster_status() {
                    ClusterStatus::Disabled => None,
                    ClusterStatus::Enabled(cluster_info) => Some(ClusterStatusTelemetry {
                        number_of_peers: cluster_info.peers.len(),
                        term: cluster_info.raft_info.term,
                        commit: cluster_info.raft_info.commit,
                        pending_operations: cluster_info.raft_info.pending_operations,
                        role: cluster_info.raft_info.role,
                        is_voter: cluster_info.raft_info.is_voter,
                        peer_id: Some(cluster_info.peer_id),
                        consensus_thread_status: cluster_info.consensus_thread_status,
                    }),
                })
                .flatten(),
            config: (detail.level >= DetailsLevel::Level2)
                .then(|| ClusterConfigTelemetry::from(settings)),
            peers: (detail.level >= DetailsLevel::Level2)
                .then(|| match dispatcher.cluster_status() {
                    ClusterStatus::Disabled => None,
                    ClusterStatus::Enabled(cluster_info) => Some(cluster_info.peers),
                })
                .flatten(),
            peer_metadata: (detail.level >= DetailsLevel::Level3)
                .then(|| {
                    dispatcher
                        .consensus_state()
                        .map(|state| state.persistent.read().peer_metadata_by_id())
                })
                .flatten(),
            metadata: (detail.level >= DetailsLevel::Level1)
                .then(|| {
                    dispatcher
                        .consensus_state()
                        .map(|state| state.persistent.read().cluster_metadata.clone())
                        .filter(|metadata| !metadata.is_empty())
                })
                .flatten(),
            resharding_enabled: Some(settings.cluster.resharding_enabled),
        })
    }

    pub fn this_peer_id(&self) -> Option<PeerId> {
        self.enabled
            .then(|| self.status.as_ref().and_then(|j| j.peer_id))
            .flatten()
    }
}use std::sync::atomic::AtomicBool;
use std::time::Duration;

use ahash::HashSet;
use collection::operations::types::CollectionResult;
use collection::telemetry::{
    CollectionSnapshotTelemetry, CollectionTelemetry, CollectionsAggregatedTelemetry,
};
use common::types::{DetailsLevel, TelemetryDetail};
use schemars::JsonSchema;
use segment::common::anonymize::Anonymize;
use serde::Serialize;
use storage::content_manager::toc::TableOfContent;
use storage::rbac::Access;

#[derive(Serialize, Clone, Debug, JsonSchema, Anonymize)]
#[serde(untagged)]
pub enum CollectionTelemetryEnum {
    Full(Box<CollectionTelemetry>),
    Aggregated(Box<CollectionsAggregatedTelemetry>),
}

#[derive(Serialize, Clone, Debug, JsonSchema, Anonymize, Default)]
pub struct CollectionsTelemetry {
    #[anonymize(false)]
    pub number_of_collections: usize,
    #[anonymize(false)]
    #[serde(skip_serializing_if = "Option::is_none")]
    pub max_collections: Option<usize>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub collections: Option<Vec<CollectionTelemetryEnum>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub snapshots: Option<Vec<CollectionSnapshotTelemetry>>,
}

impl CollectionsTelemetry {
    pub async fn collect(
        detail: TelemetryDetail,
        access: &Access,
        only_collections: Option<HashSet<String>>,
        toc: &TableOfContent,
        timeout: Duration,
        is_stopped: &AtomicBool,
    ) -> CollectionResult<Self> {
        let number_of_collections = toc.all_collections(access).await.len();
        let (collections, snapshots) = if detail.level >= DetailsLevel::Level1 {
            let telemetry_data = if detail.level >= DetailsLevel::Level2 {
                let toc_telemetry = toc
                    .get_telemetry_data(detail, access, only_collections, timeout, is_stopped)
                    .await?;

                let collections: Vec<_> = toc_telemetry
                    .collection_telemetry
                    .into_iter()
                    .map(|t| CollectionTelemetryEnum::Full(Box::new(t)))
                    .collect();

                (collections, toc_telemetry.snapshot_telemetry)
            } else {
                let collections = toc
                    .get_aggregated_telemetry_data(access, timeout, is_stopped)
                    .await?
                    .into_iter()
                    .map(|t| CollectionTelemetryEnum::Aggregated(Box::new(t)))
                    .collect();
                (collections, vec![])
            };

            (Some(telemetry_data.0), Some(telemetry_data.1))
        } else {
            (None, None)
        };

        let max_collections = toc.max_collections();

        Ok(CollectionsTelemetry {
            number_of_collections,
            max_collections,
            collections,
            snapshots,
        })
    }
}use std::collections::HashMap;

use api::grpc::qdrant as grpc;
use chrono::DateTime;
use storage::types::{ConsensusThreadStatus, PeerInfo, StateRole};
use tonic::Status;

use super::cluster_telemetry::ClusterStatusTelemetry;
use crate::common::telemetry_ops::app_telemetry::AppBuildTelemetry;
use crate::common::telemetry_ops::cluster_telemetry::ClusterTelemetry;

fn try_convert_opt_role_from_grpc(role: Option<i32>) -> Result<Option<StateRole>, Status> {
    role.map(|role| {
        Result::<_, Status>::Ok(StateRole::from(grpc::StateRole::try_from(role).map_err(
            |err| Status::invalid_argument(format!("Invalid state role: {err}")),
        )?))
    })
    .transpose()
}

impl TryFrom<grpc::AppTelemetry> for AppBuildTelemetry {
    type Error = Status;

    fn try_from(value: grpc::AppTelemetry) -> Result<Self, Self::Error> {
        let grpc::AppTelemetry {
            name,
            version,
            startup,
        } = value;

        Ok(Self {
            name,
            version,
            features: None,
            runtime_features: None,
            low_memory_mode: None,
            hnsw_global_config: None,
            system: None,
            jwt_rbac: None,
            hide_jwt_dashboard: None,
            audit: None,
            startup: DateTime::from_timestamp_secs(startup)
                .ok_or_else(|| Status::internal("startup time is out-of-range"))?,
        })
    }
}

impl From<AppBuildTelemetry> for grpc::AppTelemetry {
    fn from(value: AppBuildTelemetry) -> Self {
        let AppBuildTelemetry {
            name,
            version,
            features: _,
            runtime_features: _,
            low_memory_mode: _,
            hnsw_global_config: _,
            system: _,
            jwt_rbac: _,
            hide_jwt_dashboard: _,
            audit: _,
            startup,
        } = value;

        Self {
            name,
            version,
            startup: startup.timestamp(),
        }
    }
}

impl TryFrom<grpc::ClusterStatusTelemetry> for ClusterStatusTelemetry {
    type Error = Status;

    fn try_from(value: grpc::ClusterStatusTelemetry) -> Result<Self, Self::Error> {
        let grpc::ClusterStatusTelemetry {
            num_peers,
            term,
            commit,
            pending_operations,
            role,
            is_voter,
            peer_id,
            consensus_thread_status,
        } = value;

        let consensus_thread_status = ConsensusThreadStatus::try_from(
            consensus_thread_status
                .ok_or_else(|| Status::invalid_argument("Consensus thread status is missing"))?,
        )?;

        let role = try_convert_opt_role_from_grpc(role)?;

        Ok(ClusterStatusTelemetry {
            number_of_peers: num_peers as usize,
            term,
            commit,
            pending_operations: pending_operations as usize,
            role,
            is_voter,
            peer_id,
            consensus_thread_status,
        })
    }
}

impl From<ClusterStatusTelemetry> for grpc::ClusterStatusTelemetry {
    fn from(value: ClusterStatusTelemetry) -> Self {
        let ClusterStatusTelemetry {
            number_of_peers,
            term,
            commit,
            pending_operations,
            role,
            is_voter,
            peer_id,
            consensus_thread_status,
        } = value;

        grpc::ClusterStatusTelemetry {
            consensus_thread_status: Some(grpc::ConsensusThreadStatus::from(
                consensus_thread_status,
            )),
            role: role.map(|r| grpc::StateRole::from(r) as i32),
            num_peers: number_of_peers as u32,
            term,
            commit,
            pending_operations: pending_operations as u64,
            is_voter,
            peer_id,
        }
    }
}

impl TryFrom<grpc::ClusterTelemetry> for ClusterTelemetry {
    type Error = Status;

    fn try_from(value: grpc::ClusterTelemetry) -> Result<Self, Self::Error> {
        let grpc::ClusterTelemetry { status, peers } = value;

        let peers = peers
            .into_iter()
            .map(|(peer_id, grpc::PeerInfo { uri })| (peer_id, PeerInfo { uri }))
            .collect::<HashMap<_, _>>();

        Ok(ClusterTelemetry {
            enabled: true, // Not provided in gRPC, default to true if we have telemetry
            status: status.map(ClusterStatusTelemetry::try_from).transpose()?,
            config: None, // Not provided in gRPC
            peers: (!peers.is_empty()).then_some(peers),
            peer_metadata: None,      // Not provided in gRPC
            metadata: None,           // Not provided in gRPC
            resharding_enabled: None, // Not provided in gRPC
        })
    }
}

impl From<ClusterTelemetry> for grpc::ClusterTelemetry {
    fn from(value: ClusterTelemetry) -> Self {
        let ClusterTelemetry {
            enabled: _,
            status,
            config: _,
            peers,
            peer_metadata: _,
            metadata: _,
            resharding_enabled: _,
        } = value;

        let peers = peers
            .unwrap_or_default()
            .into_iter()
            .map(|(peer_id, PeerInfo { uri })| (peer_id, grpc::PeerInfo { uri }))
            .collect();

        grpc::ClusterTelemetry {
            status: status.map(grpc::ClusterStatusTelemetry::from),
            peers,
        }
    }
