        temp_path: None,
        on_disk_payload: false,
        optimizers: OptimizersConfig {
            deleted_threshold: 0.5,
            vacuum_min_vector_number: 100,
            default_segment_number: 2,
            max_segment_size: None,
            #[expect(deprecated)]
            memmap_threshold: Some(100),
            indexing_threshold: Some(100),
            flush_interval_sec: 2,
            max_optimization_threads: Some(2),
            prevent_unoptimized: None,
        },
        optimizers_overwrite: None,
        wal: WalConfig::default(),
        performance: PerformanceConfig {
            max_search_threads: 1,
            max_optimization_runtime_threads: 1,
            update_rate_limit: None,
            search_timeout_sec: None,
            optimizer_cpu_budget: 0,
            optimizer_io_budget: 0,
            incoming_shard_transfers_limit: Some(1),
            outgoing_shard_transfers_limit: Some(1),
            async_scorer: None,
            load_concurrency: LoadConcurrencyConfig::default(),
        },
        hnsw_index: HnswConfig::default(),
        hnsw_global_config: HnswGlobalConfig::default(),
        mmap_advice: mmap::Advice::Random,
        low_memory_mode: Default::default(),
        node_type: Default::default(),
        update_queue_size: Default::default(),
        handle_collection_load_errors: false,
        recovery_mode: None,
        update_concurrency: Some(NonZeroUsize::new(2).unwrap()),
        shard_transfer_method: None,
        collection: None,
        max_collections: None,
    }
}

/// Create service on a blocking thread to avoid nested-runtime panics.
/// `TableOfContent::new` internally calls `block_on`, and dropping the
/// `Runtime` instances it owns also requires a non-async context.
async fn create_service_async() -> (StorageReadService<MmapFile>, TempDir, PathBuf) {
    tokio::task::spawn_blocking(create_service).await.unwrap()
}

/// Drop service (and its `TempDir`) on a blocking thread so the `Runtime`
/// instances inside `TableOfContent` are not dropped from async context.
async fn drop_service(service: StorageReadService<MmapFile>, storage_dir: TempDir) {
    tokio::task::spawn_blocking(move || drop((service, storage_dir)))
        .await
        .unwrap();
}

/// Returns the shard directory for `TEST_SHARD_ID` inside the test collection.
fn create_service() -> (StorageReadService<MmapFile>, TempDir, PathBuf) {
    let storage_dir = tempfile::tempdir().unwrap();
    let config = test_storage_config(storage_dir.path());
    let toc = Arc::new(
        TableOfContent::new(
            &config,
            ResourceBudget::default(),
            ChannelService::new(6333, false, None, None),
            0,
            None,
        )
        .unwrap(),
    );
    let shard_dir = storage_dir
        .path()
        .join(COLLECTIONS_DIR)
        .join(TEST_COLLECTION_NAME)
        .join(TEST_SHARD_ID.to_string());
    fs_err::create_dir_all(&shard_dir).unwrap();

    let dispatcher = Arc::new(Dispatcher::new(toc));
    let service = StorageReadService::new(dispatcher).unwrap();

    (service, storage_dir, shard_dir)
}

/// Create a request with auth restricted to a single collection.
fn request_with_access<T>(inner: T, allowed_collection: &str) -> Request<T> {
    #[expect(deprecated)]
    let access = Access::Collection(CollectionAccessList(vec![CollectionAccess {
        collection: allowed_collection.to_string(),
        access: CollectionAccessMode::Read,
        payload: None,
    }]));
    let auth = Auth::new(access, None, None, AuthType::None, None);
    let mut req = Request::new(inner);
    req.extensions_mut().insert(auth);
    req
}

fn write_shard_file(shard_dir: &Path, relative_path: &str, contents: &[u8]) -> PathBuf {
    let path = shard_dir.join(relative_path);
    fs_err::create_dir_all(path.parent().unwrap()).unwrap();
    fs_err::write(&path, contents).unwrap();
    path
}

#[tokio::test]
async fn file_exists_rejects_path_traversal() {
    let (service, storage_dir, _shard_dir) = create_service_async().await;

    let err = service
        .file_exists(Request::new(FileExistsRequest {
            collection_name: TEST_COLLECTION_NAME.to_string(),
            shard_id: TEST_SHARD_ID,
            path: "nested/../secret.bin".to_string(),
        }))
        .await
        .unwrap_err();

    assert_eq!(err.code(), Code::InvalidArgument);
    assert!(
        err.message().contains("Invalid path component"),
        "unexpected error message: {}",
        err.message()
    );

    drop_service(service, storage_dir).await;
}

