        let auth = extract_auth(&mut request);

        // Nothing to verify here.
        let pass = new_unchecked_verification_pass();

        get(
            self.dispatcher.toc(&auth, &pass),
            request.into_inner(),
            &auth,
            None,
        )
        .await
    }

    async fn list(
        &self,
