use std::task::{Context, Poll};

use futures::future::BoxFuture;
use storage::audit::{audit_trust_forwarded_headers, extract_tracing_id};
use storage::rbac::Access;
use tonic::Status;
use tower::{Layer, Service};

use super::forwarded;
use crate::common::auth::{Auth, AuthError, AuthKeys, AuthType, log_denied_auth};
use crate::common::inference::api_keys::InferenceToken;

type Request<Body> = http::Request<Body>;
type Response<Body> = http::Response<Body>;

#[derive(Clone)]
pub struct AuthMiddleware<S> {
    auth_keys: Arc<AuthKeys>,
    service: S,
}

async fn check<Body>(
    auth_keys: Arc<AuthKeys>,
    mut req: Request<Body>,
) -> Result<Request<Body>, Status>
where
    Body: Send + 'static,
{
    // When the audit logger trusts forwarded headers, prefer the raw
    // `X-Forwarded-For` value so audit entries record the real client address
    // rather than the proxy address.  Fall back to the TCP peer address.
    let remote = if audit_trust_forwarded_headers() {
        forwarded::forwarded_for(&req)
    } else {
        None
    }
    .or_else(|| {
        req.extensions()
            .get::<tonic::transport::server::TcpConnectInfo>()
            .and_then(|info| info.remote_addr())
            .map(|addr| addr.ip().to_string())
    });

    let tracing_id = extract_tracing_id(|h| {
        req.headers()
            .get(h)
            .and_then(|val| val.to_str().ok())
            .map(str::to_string)
    });

    // Allow health check endpoints to bypass authentication
    let path = req.uri().path();
    if path == "/qdrant.Qdrant/HealthCheck" || path == "/grpc.health.v1.Health/Check" {
        // Set default full access for health check endpoints
        let auth = Auth::new(
            Access::full("Health check endpoints have full access without authentication"),
            None,
            remote,
            AuthType::None,
            tracing_id,
        );
        let inference_token = InferenceToken(None);

        req.extensions_mut().insert(auth);
        req.extensions_mut().insert(inference_token);

        return Ok(req);
    }

    let headers = req.headers();
    let (access, inference_token, auth_type, subject) = auth_keys
        .validate_request(move |key| headers.get(key).and_then(|val| val.to_str().ok()))
        .await
        .map_err(|e| {
            log_denied_auth(path, remote.clone(), tracing_id.clone(), &e);
            match e {
                AuthError::Unauthorized(e) => Status::unauthenticated(e),
                AuthError::Forbidden(e) => Status::permission_denied(e),
                AuthError::StorageError(e) => Status::from(e),
            }
        })?;

    let auth = Auth::new(access, subject, remote, auth_type, tracing_id).with_api(path.to_string());

    let previous = req.extensions_mut().insert(auth);

    debug_assert!(
        previous.is_none(),
        "Previous auth object should not exist in the request"
    );

    let previous_token = req.extensions_mut().insert(inference_token);

    debug_assert!(
        previous_token.is_none(),
        "Previous inference token should not exist in the request"
    );

    Ok(req)
}

impl<S, ReqBody, RespBody> Service<Request<ReqBody>> for AuthMiddleware<S>
where
    S: Service<Request<ReqBody>, Response = Response<RespBody>> + Clone + Send + 'static,
    S::Future: Send + 'static,
    ReqBody: Send + 'static,
    RespBody: Default,
{
    type Response = S::Response;
    type Error = S::Error;
    type Future = BoxFuture<'static, Result<Self::Response, S::Error>>;

    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.service.poll_ready(cx)
    }

    fn call(&mut self, request: Request<ReqBody>) -> Self::Future {
        let auth_keys = self.auth_keys.clone();
        let mut service = self.service.clone();

        Box::pin(async move {
            match check(auth_keys, request).await {
                Ok(req) => service.call(req).await,
                Err(e) => Ok(e.into_http()),
            }
        })
    }
}

#[derive(Clone)]
pub struct AuthLayer {
    auth_keys: Arc<AuthKeys>,
}

impl AuthLayer {
    pub fn new(auth_keys: AuthKeys) -> Self {
        Self {
            auth_keys: Arc::new(auth_keys),
        }
    }
}

impl<S> Layer<S> for AuthLayer {
    type Service = AuthMiddleware<S>;

    fn layer(&self, service: S) -> Self::Service {
        Self::Service {
            auth_keys: self.auth_keys.clone(),
            service,
        }
    }
}

/// Extract the per-request [`Auth`] context from a tonic request.
///
/// When no authentication middleware is configured, a default `Auth` with full
/// access is returned.
pub fn extract_auth<R>(req: &mut tonic::Request<R>) -> Auth {
    req.extensions_mut().remove::<Auth>().unwrap_or_else(|| {
        Auth::new(
            Access::full("All requests have full by default access when API key is not configured"),
            None,
            None,
            AuthType::None,
            extract_tracing_id(|h| {
                req.metadata()
                    .get(h)
                    .and_then(|val| val.to_str().ok())
                    .map(str::to_string)
            }),
        )
    })
}static X_FORWARDED_FOR: http::HeaderName = http::HeaderName::from_static("x-forwarded-for");

/// Extract the raw forwarded-for header value from a tonic/http request.
///
/// Checks the standard RFC 7239 `Forwarded` header first, then falls back to
/// the legacy `X-Forwarded-For` header.  The value is returned **as-is** – no
/// parsing or validation is performed.
///
/// Returns `None` when neither header is present or the value is not valid UTF-8.
pub fn forwarded_for<Body>(req: &http::Request<Body>) -> Option<String> {
    let headers = req.headers();

    // Try standard Forwarded header first (RFC 7239)
    if let Some(forwarded) = headers
        .get(http::header::FORWARDED)
        .and_then(|v| v.to_str().ok())
    {
        return Some(forwarded.to_string());
    }

    // Fallback to legacy X-Forwarded-For header
    headers
        .get(&X_FORWARDED_FOR)
        .and_then(|v| v.to_str().ok())
        .map(|s| s.to_string())
}use std::task::{Context, Poll};

use futures_util::future::BoxFuture;
use tonic::Code;
use tower::Service;
use tower_layer::Layer;

#[derive(Clone)]
pub struct LoggingMiddleware<T> {
    inner: T,
}

#[derive(Clone)]
pub struct LoggingMiddlewareLayer;

impl LoggingMiddlewareLayer {
    pub fn new() -> Self {
        Self
    }
}

impl<S, ReqBody, RespBody> Service<http::Request<ReqBody>> for LoggingMiddleware<S>
where
    S: Service<http::Request<ReqBody>, Response = http::Response<RespBody>> + Clone,
    S::Future: Send + 'static,
    ReqBody: Send + 'static,
{
    type Response = S::Response;
    type Error = S::Error;
    type Future = BoxFuture<'static, Result<S::Response, S::Error>>;

    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.inner.poll_ready(cx)
    }

    fn call(&mut self, request: http::Request<ReqBody>) -> Self::Future {
        let clone = self.inner.clone();
        let mut inner = std::mem::replace(&mut self.inner, clone);

        let method_name = request.uri().path().to_string();
        let instant = std::time::Instant::now();
        let future = inner.call(request);
        Box::pin(async move {
            let response = future.await;
            let elapsed_sec = instant.elapsed().as_secs_f32();
            match response {
                Err(error) => {
                    log::error!("gRPC request error {method_name}");
                    Err(error)
                }
                Ok(response_tonic) => {
                    let grpc_status = tonic::Status::from_header_map(response_tonic.headers());
                    if let Some(grpc_status) = grpc_status {
                        match grpc_status.code() {
                            Code::Ok => {
                                log::trace!("gRPC {method_name} Ok {elapsed_sec:.6}");
                            }
                            Code::Cancelled => {
                                // cluster mode generates a large amount of `stream error received: stream no longer needed`
                                log::trace!("gRPC cancelled {method_name} {elapsed_sec:.6}");
                            }
                            Code::DeadlineExceeded
                            | Code::Aborted
                            | Code::OutOfRange
                            | Code::ResourceExhausted
                            | Code::NotFound
                            | Code::InvalidArgument
                            | Code::AlreadyExists
                            | Code::FailedPrecondition
                            | Code::PermissionDenied
                            | Code::Unauthenticated => {
                                log::info!(
                                    "gRPC {} failed with {} {:?} {:.6}",
                                    method_name,
                                    grpc_status.code(),
                                    grpc_status.message(),
                                    elapsed_sec,
                                );
                            }
                            Code::Internal
                            | Code::Unimplemented
                            | Code::Unavailable
                            | Code::DataLoss
                            | Code::Unknown => log::error!(
                                "gRPC {} unexpectedly failed with {} {:?} {:.6}",
                                method_name,
                                grpc_status.code(),
                                grpc_status.message(),
                                elapsed_sec,
                            ),
                        };
                    } else {
                        // Fallback to response's `status_code` if no `grpc-status` header found.
                        match response_tonic.status().as_u16() {
                            100..=199 => {
                                log::trace!(
                                    "gRPC information {} {} {:.6}",
                                    method_name,
                                    response_tonic.status(),
                                    elapsed_sec,
                                );
                            }
                            200..=299 => {
                                log::trace!(
                                    "gRPC success {} {} {:.6}",
                                    method_name,
                                    response_tonic.status(),
                                    elapsed_sec,
                                );
                            }
                            300..=399 => {
                                log::debug!(
                                    "gRPC redirection {} {} {:.6}",
                                    method_name,
                                    response_tonic.status(),
                                    elapsed_sec,
                                );
                            }
                            400..=499 => {
                                log::info!(
                                    "gRPC client error {} {} {:.6}",
                                    method_name,
                                    response_tonic.status(),
                                    elapsed_sec,
                                );
                            }
                            500..=599 => {
                                log::error!(
                                    "gRPC server error {} {} {:.6}",
                                    method_name,
                                    response_tonic.status(),
                                    elapsed_sec,
                                );
                            }
                            _ => {
                                log::warn!(
                                    "gRPC {} unknown status code {} {:.6}",
                                    method_name,
                                    response_tonic.status(),
                                    elapsed_sec,
                                );
                            }
                        };
                    }
                    Ok(response_tonic)
                }
            }
        })
    }
}

impl<S> Layer<S> for LoggingMiddlewareLayer {
    type Service = LoggingMiddleware<S>;

    fn layer(&self, service: S) -> Self::Service {
        LoggingMiddleware { inner: service }
    }
